# Load the library
library(tidyverse)
library(readxl)
library(scales)
library(paletteer)
library(treemapify)
library(ggpmisc)
library(gridExtra)
library(openxlsx)
library(olsrr)
library(jmv)
library(gtsummary)
library(MASS)
source("RO_Census_functions.R")

# Load from RO Census 2021
RO_Census_df <- read_excel("./Ro_Census_2021.xlsx", sheet = 1)
RO_Census_rank<- RO_Census_df %>% 
  left_join(RO_Census_df %>% group_by(Judet_Name) %>% 
              summarize(Total_Pop = sum(Population))) %>%
  arrange(Judet_Name, desc(Population)) %>% group_by(Judet_Name) %>% 
  mutate(Rank = row_number(), Pop_Freq = Population/Total_Pop) %>%
  ungroup()
View(RO_Census_rank)

# I. Alba

# 1. OLS
RO_Census_Alba <- RO_Census_rank %>% filter(Judet_Name == "ALBA")
#View(RO_Census_Alba)

# a) Power Law
AB_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Alba)
summary(AB_pw_lm_ols)
AB_pred_pw_lm_ols <- exp(predict(AB_pw_lm_ols, newdata = RO_Census_Alba, 
                             interval = "prediction", level = 0.95))
AB_pw_out_ols <- RO_Census_Alba %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(AB_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Alba), 
         DFFIT = dffits(AB_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(AB_pw_lm_ols$coefficients) / nrow(RO_Census_Alba)), 
         Rezid_Std = rstudent(AB_pw_lm_ols), Leverage = hatvalues(AB_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(AB_pw_lm_ols)), 
         DFBETA = dfbetas(AB_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Alba)))

# b) Zipf_Mandelbrot Law
AB_ZM_prm_ols <- get_ZM_Param("RO_Census_Alba", "Population", "Rank")
AB_ZM_m_ols <- AB_ZM_prm_ols$m
AB_ZM_alpha_ols <- AB_ZM_prm_ols$alpha_ZM
AB_ZM_cst_ols <- AB_ZM_prm_ols$constant_ZM
AB_ZM_lm_ols <- lm(log(RO_Census_Alba$Population) ~ log(RO_Census_Alba$Rank + AB_ZM_m_ols))
summary(AB_ZM_lm_ols)
AB_pred_ZM_lm_ols <- exp(predict(AB_ZM_lm_ols, newdata = RO_Census_Alba, 
                             interval = "prediction", level = 0.95))
AB_ZM_out_ols <- RO_Census_Alba %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(AB_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Alba), 
         DFFIT = dffits(AB_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(AB_ZM_lm_ols$coefficients) / nrow(RO_Census_Alba)), 
         Rezid_Std = rstudent(AB_ZM_lm_ols), Leverage = hatvalues(AB_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(AB_ZM_lm_ols)), 
         DFBETA = dfbetas(AB_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Alba)))

# c) Exponential Law
AB_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Alba)
summary(AB_exp_lm_ols)
AB_pred_exp_lm_ols <- exp(predict(AB_exp_lm_ols, newdata = RO_Census_Alba, 
                              interval = "prediction", level = 0.95))
AB_exp_out_ols <- RO_Census_Alba %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(AB_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Alba), 
         DFFIT = dffits(AB_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(AB_exp_lm_ols$coefficients) / nrow(RO_Census_Alba)), 
         Rezid_Std = rstudent(AB_exp_lm_ols), Leverage = hatvalues(AB_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(AB_exp_lm_ols)), 
         DFBETA = dfbetas(AB_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Alba)))

# d) Lavalette Function
RO_Census_Alba <- RO_Census_Alba %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Alba) - Rank + 1))
)
AB_lav_lm_ols <- lm(log(RO_Census_Alba$Population) ~ RO_Census_Alba$Lav_exp)
summary(AB_lav_lm_ols)
AB_lav_kst_ols <- exp(signif(AB_lav_lm_ols$coef[[1]], 4))
AB_lav_chi_ols <- signif(AB_lav_lm_ols$coef[[2]], 4)
AB_pred_lav_lm_ols <- exp(predict(AB_lav_lm_ols, newdata = RO_Census_Alba, 
                              interval = "prediction", level = 0.95))
AB_lav_out_ols <- RO_Census_Alba %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(AB_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Alba), 
         DFFIT = dffits(AB_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(AB_lav_lm_ols$coefficients) / nrow(RO_Census_Alba)), 
         Rezid_Std = rstudent(AB_lav_lm_ols), Leverage = hatvalues(AB_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(AB_lav_lm_ols)), 
         DFBETA = dfbetas(AB_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Alba)))

# e) Data Distributions
RO_Census_Alba %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Alba$Rank, 
                              Population = AB_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(AB_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(AB_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(AB_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Alba$Rank, 
                              Population = AB_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(AB_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(AB_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(AB_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Alba$Rank, 
                              Population = AB_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(AB_ZM_cst_ols, 4), "%.%", "(",
                           signif(AB_ZM_m_ols, 4), "+ x)^", signif(AB_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(summary(AB_ZM_lm_ols)$r.squared, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Alba$Rank, 
                              Population = AB_pred_lav_lm_ols[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(AB_lav_kst_ols, 4), "%.%", "x^",
                           -signif(AB_lav_chi_ols, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(summary(AB_lav_lm_ols)$r.squared, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Alba judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# Linear Regressions
grid.arrange(
  (RO_Census_Alba %>%
     ggplot(aes(x = log(Rank), y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = "#ED3F39FF") +
     labs(x = "Rank", y = "Population") +
     ggtitle("Power Linear Regression on Alba judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  (RO_Census_Alba %>%
     ggplot(aes(x = Rank, y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = "#088BBEFF") +
     labs(x = "Rank", y = "Population") +
     ggtitle("Exponential Linear Regression on Alba judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  (RO_Census_Alba %>%
     ggplot(aes(x = log(Rank + AB_ZM_m_ols), y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = '#1B7837FF') +
     labs(x = "Rank", y = "Population") +
     ggtitle("Zipf-Mandelbrot Linear Regression on Alba judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  (RO_Census_Alba %>%
     ggplot(aes(x = Lav_exp, y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = '#F8A02EFF') +
     labs(x = "Rank", y = "Population") +
     ggtitle("Lavalette Linear Regression on Alba judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  ncol = 2, nrow = 2)

# f) Extract Outliers
Alba_Outliers <- bind_rows(
  (AB_pw_out_ols %>% mutate(Function_Name = "Power")),
  (AB_ZM_out_ols %>% mutate(Function_Name = "Zipf-Mandelbrot")),
  (AB_exp_out_ols %>% mutate(Function_Name = "Exponential")),
  (AB_lav_out_ols %>% mutate(Function_Name = "Lavalette"))
) %>% mutate(DFBETA_intercept = round(DFBETA[,1], 8), 
             DFBETA_var_x = round(DFBETA[,2], 8)) %>% dplyr::select(-DFBETA)

AB_out <- get_outliers(Alba_Outliers, RO_Census_Alba)

AB_out_ols <- RO_Census_Alba %>% inner_join(
  bind_rows(
    (AB_out$PW %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>% 
       dplyr::select(Rank) %>% distinct()),
    (AB_out$ZM %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (AB_out$LAV %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (AB_out$EXP %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct())
  ) %>% count(Rank) %>% arrange(desc(n)) %>% filter(n >= mean(n))) %>% 
  dplyr::select(-n)

# g) Extract regression metrics
AB_regmet_ols <- as.data.frame(list(Judet_Name = "ALBA",
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  R_Squared = c(signif(summary(AB_pw_lm_ols)$r.squared, 4), 
                signif(summary(AB_exp_lm_ols)$r.squared, 4),
                signif(summary(AB_ZM_lm_ols)$r.squared, 4),
                signif(summary(AB_lav_lm_ols)$r.squared, 4)),
  Adj_R_Squared = c(signif(summary(AB_pw_lm_ols)$adj.r.squared, 4), 
                    signif(summary(AB_exp_lm_ols)$adj.r.squared, 4),
                    signif(summary(AB_ZM_lm_ols)$adj.r.squared, 4),
                    signif(summary(AB_lav_lm_ols)$adj.r.squared, 4)),
  AIC = c(signif(AIC(AB_pw_lm_ols), 4), signif(AIC(AB_exp_lm_ols), 4), 
          signif(AIC(AB_ZM_lm_ols), 4), signif(AIC(AB_lav_lm_ols), 4)),
  BIC = c(signif(BIC(AB_pw_lm_ols), 4), signif(BIC(AB_exp_lm_ols), 4), 
          signif(BIC(AB_ZM_lm_ols), 4), signif(BIC(AB_lav_lm_ols), 4)),
  MAE = c(signif(mean(abs((log(RO_Census_Alba$Population) - 
                      (predict(AB_pw_lm_ols, newdata = RO_Census_Alba, 
                               interval = "prediction", level = 0.95))))), 4), 
          signif(mean(abs((log(RO_Census_Alba$Population) - 
                       (predict(AB_exp_lm_ols, newdata = RO_Census_Alba, 
                                interval = "prediction", level = 0.95))))), 4),
          signif(mean(abs((log(RO_Census_Alba$Population) - 
                       (predict(AB_ZM_lm_ols, newdata = RO_Census_Alba, 
                                interval = "prediction", level = 0.95))))), 4),
          signif(mean(abs((log(RO_Census_Alba$Population) - 
                       (predict(AB_lav_lm_ols, newdata = RO_Census_Alba, 
                                interval = "prediction", level = 0.95))))), 4)),
  RMSE = c(signif(sqrt(mean(((log(RO_Census_Alba$Population)) - 
                        (predict(AB_pw_lm_ols, newdata = RO_Census_Alba, 
                                 interval = "prediction", level = 0.95))) ^ 2)), 4),
           signif(sqrt(mean(((log(RO_Census_Alba$Population)) - 
                        (predict(AB_exp_lm_ols, newdata = RO_Census_Alba, 
                                 interval = "prediction", level = 0.95))) ^ 2)), 4),
           signif(sqrt(mean(((log(RO_Census_Alba$Population)) - 
                        (predict(AB_ZM_lm_ols, newdata = RO_Census_Alba, 
                                 interval = "prediction", level = 0.95))) ^ 2)), 4),
           signif(sqrt(mean(((log(RO_Census_Alba$Population)) - 
                        (predict(AB_lav_lm_ols, newdata = RO_Census_Alba, 
                                 interval = "prediction", level = 0.95))) ^ 2)), 4))
))

# h) Extract MAE/RMSE on head, body, tail
RO_Census_Alba_ols <- RO_Census_Alba %>% 
  mutate(PW_Y_Pred = (predict(AB_pw_lm_ols, newdata = RO_Census_Alba, 
                              interval = "prediction", level = 0.95))[,1], 
         ZM_Y_Pred = (predict(AB_ZM_lm_ols, newdata = RO_Census_Alba, 
                              interval = "prediction", level = 0.95))[,1],
         EXP_Y_Pred = (predict(AB_exp_lm_ols, newdata = RO_Census_Alba, 
                               interval = "prediction", level = 0.95))[,1], 
         LAV_Y_Pred = (predict(AB_lav_lm_ols, newdata = RO_Census_Alba, 
                               interval = "prediction", level = 0.95))[,1])

# Head
AB_ols_hd <- RO_Census_Alba_ols %>% filter(Rank <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(AB_ols_hd$Population) - AB_ols_hd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(AB_ols_hd$Population) - AB_ols_hd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(AB_ols_hd$Population) - AB_ols_hd$ZM_Y_Pred))), 4),
          signif(mean(abs((log(AB_ols_hd$Population) - AB_ols_hd$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(AB_ols_hd$Population)) - AB_ols_hd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(AB_ols_hd$Population)) - AB_ols_hd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(AB_ols_hd$Population)) - AB_ols_hd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(AB_ols_hd$Population)) - AB_ols_hd$LAV_Y_Pred) ^ 2)), 4))
))

# Tail
AB_ols_tl <- RO_Census_Alba_ols %>% arrange(desc(Rank)) %>% 
  filter(row_number() <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(AB_ols_tl$Population) - AB_ols_tl$PW_Y_Pred))), 4), 
          signif(mean(abs((log(AB_ols_tl$Population) - AB_ols_tl$EXP_Y_Pred))), 4),
          signif(mean(abs((log(AB_ols_tl$Population) - AB_ols_tl$ZM_Y_Pred))), 4),
          signif(mean(abs((log(AB_ols_tl$Population) - AB_ols_tl$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(AB_ols_tl$Population)) - AB_ols_tl$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(AB_ols_tl$Population)) - AB_ols_tl$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(AB_ols_tl$Population)) - AB_ols_tl$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(AB_ols_tl$Population)) - AB_ols_tl$LAV_Y_Pred) ^ 2)), 4))
))

# Body
AB_ols_bd <- RO_Census_Alba_ols %>% anti_join(AB_ols_hd) %>% anti_join(AB_ols_tl)

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(AB_ols_bd$Population) - AB_ols_bd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(AB_ols_bd$Population) - AB_ols_bd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(AB_ols_bd$Population) - AB_ols_bd$ZM_Y_Pred))), 4),
          signif(mean(abs((log(AB_ols_bd$Population) - AB_ols_bd$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(AB_ols_bd$Population)) - AB_ols_bd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(AB_ols_bd$Population)) - AB_ols_bd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(AB_ols_bd$Population)) - AB_ols_bd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(AB_ols_bd$Population)) - AB_ols_bd$LAV_Y_Pred) ^ 2)), 4))
))

# Final
AB_res_ols <- as.data.frame(bind_rows(
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(AB_ols_hd$Population) - AB_ols_hd$PW_Y_Pred))), 4), 
            signif(mean(abs((log(AB_ols_hd$Population) - AB_ols_hd$EXP_Y_Pred))), 4),
            signif(mean(abs((log(AB_ols_hd$Population) - AB_ols_hd$ZM_Y_Pred))), 4),
            signif(mean(abs((log(AB_ols_hd$Population) - AB_ols_hd$LAV_Y_Pred))), 4)),
    RMSE = c(signif(sqrt(mean(((log(AB_ols_hd$Population)) - AB_ols_hd$PW_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(AB_ols_hd$Population)) - AB_ols_hd$EXP_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(AB_ols_hd$Population)) - AB_ols_hd$ZM_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(AB_ols_hd$Population)) - AB_ols_hd$LAV_Y_Pred) ^ 2)), 4)),
    Data_Part = "Head"
  )),
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(AB_ols_tl$Population) - AB_ols_tl$PW_Y_Pred))), 4), 
            signif(mean(abs((log(AB_ols_tl$Population) - AB_ols_tl$EXP_Y_Pred))), 4),
            signif(mean(abs((log(AB_ols_tl$Population) - AB_ols_tl$ZM_Y_Pred))), 4),
            signif(mean(abs((log(AB_ols_tl$Population) - AB_ols_tl$LAV_Y_Pred))), 4)),
    RMSE = c(signif(sqrt(mean(((log(AB_ols_tl$Population)) - AB_ols_tl$PW_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(AB_ols_tl$Population)) - AB_ols_tl$EXP_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(AB_ols_tl$Population)) - AB_ols_tl$ZM_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(AB_ols_tl$Population)) - AB_ols_tl$LAV_Y_Pred) ^ 2)), 4)),
    Data_Part = "Tail"
  )),
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(AB_ols_bd$Population) - AB_ols_bd$PW_Y_Pred))), 4), 
            signif(mean(abs((log(AB_ols_bd$Population) - AB_ols_bd$EXP_Y_Pred))), 4),
            signif(mean(abs((log(AB_ols_bd$Population) - AB_ols_bd$ZM_Y_Pred))), 4),
            signif(mean(abs((log(AB_ols_bd$Population) - AB_ols_bd$LAV_Y_Pred))), 4)),
    RMSE = c(signif(sqrt(mean(((log(AB_ols_bd$Population)) - AB_ols_bd$PW_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(AB_ols_bd$Population)) - AB_ols_bd$EXP_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(AB_ols_bd$Population)) - AB_ols_bd$ZM_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(AB_ols_bd$Population)) - AB_ols_bd$LAV_Y_Pred) ^ 2)), 4)),
    Data_Part = "Body"
  )),
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(RO_Census_Alba$Population) - 
                               (predict(AB_pw_lm_ols, newdata = RO_Census_Alba, 
                                        interval = "prediction", level = 0.95))))), 4), 
            signif(mean(abs((log(RO_Census_Alba$Population) - 
                               (predict(AB_exp_lm_ols, newdata = RO_Census_Alba, 
                                        interval = "prediction", level = 0.95))))), 4),
            signif(mean(abs((log(RO_Census_Alba$Population) - 
                               (predict(AB_ZM_lm_ols, newdata = RO_Census_Alba, 
                                        interval = "prediction", level = 0.95))))), 4),
            signif(mean(abs((log(RO_Census_Alba$Population) - 
                               (predict(AB_lav_lm_ols, newdata = RO_Census_Alba, 
                                        interval = "prediction", level = 0.95))))), 4)),
    RMSE = c(signif(sqrt(mean(((log(RO_Census_Alba$Population)) - 
                                 (predict(AB_pw_lm_ols, newdata = RO_Census_Alba, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Alba$Population)) - 
                                 (predict(AB_exp_lm_ols, newdata = RO_Census_Alba, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Alba$Population)) - 
                                 (predict(AB_ZM_lm_ols, newdata = RO_Census_Alba, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Alba$Population)) - 
                                 (predict(AB_lav_lm_ols, newdata = RO_Census_Alba, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4)),
    Data_Part = "Full"
  ))
)) %>% mutate(Regression_Type = "OLS", Judet_Name = "ALBA")

# 2. Robust

# a) Power Law
AB_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Alba)
summary(AB_pw_lm_rob)
AB_pred_pw_lm_rob <- exp(predict(AB_pw_lm_rob, newdata = RO_Census_Alba, 
                                 interval = "prediction", level = 0.95))
AB_RSquared_pw_rob <- 1 - sum((log(RO_Census_Alba$Population) - fitted(AB_pw_lm_rob))^2) / 
  sum((log(RO_Census_Alba$Population) - mean(log(RO_Census_Alba$Population)))^2)

# b) Zipf_Mandelbrot Law
AB_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Alba, "Population", "Rank")
AB_ZM_m_rob <- AB_ZM_prm_rob$m
AB_ZM_alpha_rob <- AB_ZM_prm_rob$alpha_ZM
AB_ZM_cst_rob <- AB_ZM_prm_rob$constant_ZM
AB_ZM_lm_rob <- rlm(log(RO_Census_Alba$Population) ~ log(RO_Census_Alba$Rank + AB_ZM_m_rob))
summary(AB_ZM_lm_rob)
AB_pred_ZM_lm_rob <- exp(predict(AB_ZM_lm_rob, newdata = RO_Census_Alba, 
                                 interval = "prediction", level = 0.95))
AB_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Alba$Population) - fitted(AB_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Alba$Population) - mean(log(RO_Census_Alba$Population)))^2)

# c) Exponential Law
AB_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Alba)
summary(AB_exp_lm_rob)
AB_pred_exp_lm_rob <- exp(predict(AB_exp_lm_rob, newdata = RO_Census_Alba, 
                                  interval = "prediction", level = 0.95))
AB_RSquared_exp_rob <- 1 - sum((log(RO_Census_Alba$Population) - fitted(AB_exp_lm_rob))^2) / 
  sum((log(RO_Census_Alba$Population) - mean(log(RO_Census_Alba$Population)))^2)

# d) Lavalette Function
RO_Census_Alba <- RO_Census_Alba %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Alba) - Rank + 1))
)
AB_lav_lm_rob <- rlm(log(RO_Census_Alba$Population) ~ RO_Census_Alba$Lav_exp)
summary(AB_lav_lm_rob)
AB_lav_kst_rob <- exp(signif(AB_lav_lm_rob$coef[[1]], 4))
AB_lav_chi_rob <- signif(AB_lav_lm_rob$coef[[2]], 4)
AB_pred_lav_lm_rob <- exp(predict(AB_lav_lm_rob, newdata = RO_Census_Alba, 
                                  interval = "prediction", level = 0.95))
AB_RSquared_lav_rob <- 1 - sum((log(RO_Census_Alba$Population) - fitted(AB_lav_lm_rob))^2) / 
  sum((log(RO_Census_Alba$Population) - mean(log(RO_Census_Alba$Population)))^2)

# e) Data Distributions
RO_Census_Alba %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Alba$Rank, 
                              Population = AB_pred_pw_lm_rob[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(AB_pw_lm_rob$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(AB_pw_lm_rob$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(AB_RSquared_pw_rob, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Alba$Rank, 
                              Population = AB_pred_exp_lm_rob[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(AB_exp_lm_rob$coefficients[[1]]), 4), "%.%", 
                           signif(exp(AB_exp_lm_rob$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(AB_RSquared_exp_rob, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Alba$Rank, 
                              Population = AB_pred_ZM_lm_rob[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(AB_ZM_cst_rob, 4), "%.%", "(",
                           signif(AB_ZM_m_rob, 4), "+ x)^", signif(AB_ZM_alpha_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(AB_RSquared_ZM_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Alba$Rank, 
                              Population = AB_pred_lav_lm_rob[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(AB_lav_kst_rob, 4), "%.%", "x^",
                           -signif(AB_lav_chi_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(AB_RSquared_lav_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Alba judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# f) Extract regression metrics
AB_regmet_rob <- as.data.frame(list(Judet_Name = "ALBA",
