# II. Arad

# 1. OLS
RO_Census_Arad <- RO_Census_rank %>% filter(Judet_Name == "ARAD")
#View(RO_Census_Arad)

# a) Power Law
AR_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Arad)
summary(AR_pw_lm_ols)
AR_pred_pw_lm_ols <- exp(predict(AR_pw_lm_ols, newdata = RO_Census_Arad, 
                                 interval = "prediction", level = 0.95))
AR_pw_out_ols <- RO_Census_Arad %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(AR_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Arad), 
         DFFIT = dffits(AR_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(AR_pw_lm_ols$coefficients) / nrow(RO_Census_Arad)), 
         Rezid_Std = rstudent(AR_pw_lm_ols), Leverage = hatvalues(AR_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(AR_pw_lm_ols)), 
         DFBETA = dfbetas(AR_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Arad)))

# b) Zipf_Mandelbrot Law
AR_ZM_prm_ols <- get_ZM_Param("RO_Census_Arad", "Population", "Rank")
AR_ZM_m_ols <- AR_ZM_prm_ols$m
AR_ZM_alpha_ols <- AR_ZM_prm_ols$alpha_ZM
AR_ZM_cst_ols <- AR_ZM_prm_ols$constant_ZM
AR_ZM_lm_ols <- lm(log(RO_Census_Arad$Population) ~ log(RO_Census_Arad$Rank + AR_ZM_m_ols))
summary(AR_ZM_lm_ols)
AR_pred_ZM_lm_ols <- exp(predict(AR_ZM_lm_ols, newdata = RO_Census_Arad, 
                                 interval = "prediction", level = 0.95))
AR_ZM_out_ols <- RO_Census_Arad %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(AR_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Arad), 
         DFFIT = dffits(AR_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(AR_ZM_lm_ols$coefficients) / nrow(RO_Census_Arad)), 
         Rezid_Std = rstudent(AR_ZM_lm_ols), Leverage = hatvalues(AR_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(AR_ZM_lm_ols)), 
         DFBETA = dfbetas(AR_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Arad)))

# c) Exponential Law
AR_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Arad)
summary(AR_exp_lm_ols)
AR_pred_exp_lm_ols <- exp(predict(AR_exp_lm_ols, newdata = RO_Census_Arad, 
                                  interval = "prediction", level = 0.95))
AR_exp_out_ols <- RO_Census_Arad %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(AR_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Arad), 
         DFFIT = dffits(AR_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(AR_exp_lm_ols$coefficients) / nrow(RO_Census_Arad)), 
         Rezid_Std = rstudent(AR_exp_lm_ols), Leverage = hatvalues(AR_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(AR_exp_lm_ols)), 
         DFBETA = dfbetas(AR_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Arad)))

# d) Lavalette Function
RO_Census_Arad <- RO_Census_Arad %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Arad) - Rank + 1))
)
AR_lav_lm_ols <- lm(log(RO_Census_Arad$Population) ~ RO_Census_Arad$Lav_exp)
summary(AR_lav_lm_ols)
AR_lav_kst_ols <- exp(signif(AR_lav_lm_ols$coef[[1]], 4))
AR_lav_chi_ols <- signif(AR_lav_lm_ols$coef[[2]], 4)
AR_pred_lav_lm_ols <- exp(predict(AR_lav_lm_ols, newdata = RO_Census_Arad, 
                                  interval = "prediction", level = 0.95))
AR_lav_out_ols <- RO_Census_Arad %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(AR_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Arad), 
         DFFIT = dffits(AR_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(AR_lav_lm_ols$coefficients) / nrow(RO_Census_Arad)), 
         Rezid_Std = rstudent(AR_lav_lm_ols), Leverage = hatvalues(AR_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(AR_lav_lm_ols)), 
         DFBETA = dfbetas(AR_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Arad)))

