# 2. Robust

# a) Power Law
AR_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Arad)
summary(AR_pw_lm_rob)
AR_pred_pw_lm_rob <- exp(predict(AR_pw_lm_rob, newdata = RO_Census_Arad, 
                                 interval = "prediction", level = 0.95))
AR_RSquared_pw_rob <- 1 - sum((log(RO_Census_Arad$Population) - fitted(AR_pw_lm_rob))^2) / 
  sum((log(RO_Census_Arad$Population) - mean(log(RO_Census_Arad$Population)))^2)

# b) Zipf_Mandelbrot Law
AR_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Arad, "Population", "Rank")
AR_ZM_m_rob <- AR_ZM_prm_rob$m
AR_ZM_alpha_rob <- AR_ZM_prm_rob$alpha_ZM
AR_ZM_cst_rob <- AR_ZM_prm_rob$constant_ZM
AR_ZM_lm_rob <- rlm(log(RO_Census_Arad$Population) ~ log(RO_Census_Arad$Rank + AR_ZM_m_rob))
summary(AR_ZM_lm_rob)
AR_pred_ZM_lm_rob <- exp(predict(AR_ZM_lm_rob, newdata = RO_Census_Arad, 
                                 interval = "prediction", level = 0.95))
AR_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Arad$Population) - fitted(AR_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Arad$Population) - mean(log(RO_Census_Arad$Population)))^2)

# c) Exponential Law
AR_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Arad)
summary(AR_exp_lm_rob)
AR_pred_exp_lm_rob <- exp(predict(AR_exp_lm_rob, newdata = RO_Census_Arad, 
                                  interval = "prediction", level = 0.95))
AR_RSquared_exp_rob <- 1 - sum((log(RO_Census_Arad$Population) - fitted(AR_exp_lm_rob))^2) / 
  sum((log(RO_Census_Arad$Population) - mean(log(RO_Census_Arad$Population)))^2)

# d) Lavalette Function
RO_Census_Arad <- RO_Census_Arad %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Arad) - Rank + 1))
)
AR_lav_lm_rob <- rlm(log(RO_Census_Arad$Population) ~ RO_Census_Arad$Lav_exp)
summary(AR_lav_lm_rob)
AR_lav_kst_rob <- exp(signif(AR_lav_lm_rob$coef[[1]], 4))
AR_lav_chi_rob <- signif(AR_lav_lm_rob$coef[[2]], 4)
AR_pred_lav_lm_rob <- exp(predict(AR_lav_lm_rob, newdata = RO_Census_Arad, 
                                  interval = "prediction", level = 0.95))
AR_RSquared_lav_rob <- 1 - sum((log(RO_Census_Arad$Population) - fitted(AR_lav_lm_rob))^2) / 
  sum((log(RO_Census_Arad$Population) - mean(log(RO_Census_Arad$Population)))^2)

# e) Data Distributions
RO_Census_Arad %>%
  ggplot(aes(x = Rank, y = Population)) +
