# g) Extract MAE/RMSE on head, body, tail
RO_Census_Arad_rob <- RO_Census_Arad %>% 
  mutate(PW_Y_Pred = (predict(AR_pw_lm_rob, newdata = RO_Census_Arad, 
                              interval = "prediction", level = 0.95))[,1], 
