         LAV_Y_Pred = (predict(AR_lav_lm_rob, newdata = RO_Census_Arad, 
                               interval = "prediction", level = 0.95))[,1])

# Head
AR_rob_hd <- RO_Census_Arad_rob %>% filter(Rank <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(AR_rob_hd$Population) - AR_rob_hd$PW_Y_Pred))), 4), 
