# III. Arges

# 1. OLS
RO_Census_Arges <- RO_Census_rank %>% filter(Judet_Name == "ARGES")
#View(RO_Census_Arges)

# a) Power Law
AG_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Arges)
summary(AG_pw_lm_ols)
AG_pred_pw_lm_ols <- exp(predict(AG_pw_lm_ols, newdata = RO_Census_Arges, 
                                 interval = "prediction", level = 0.95))
AG_pw_out_ols <- RO_Census_Arges %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(AG_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Arges), 
         DFFIT = dffits(AG_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(AG_pw_lm_ols$coefficients) / nrow(RO_Census_Arges)), 
         Rezid_Std = rstudent(AG_pw_lm_ols), Leverage = hatvalues(AG_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(AG_pw_lm_ols)), 
         DFBETA = dfbetas(AG_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Arges)))

# b) Zipf_Mandelbrot Law
AG_ZM_prm_ols <- get_ZM_Param("RO_Census_Arges", "Population", "Rank")
AG_ZM_m_ols <- AG_ZM_prm_ols$m
AG_ZM_alpha_ols <- AG_ZM_prm_ols$alpha_ZM
AG_ZM_cst_ols <- AG_ZM_prm_ols$constant_ZM
AG_ZM_lm_ols <- lm(log(RO_Census_Arges$Population) ~ log(RO_Census_Arges$Rank + AG_ZM_m_ols))
summary(AG_ZM_lm_ols)
AG_pred_ZM_lm_ols <- exp(predict(AG_ZM_lm_ols, newdata = RO_Census_Arges, 
                                 interval = "prediction", level = 0.95))
AG_ZM_out_ols <- RO_Census_Arges %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(AG_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Arges), 
         DFFIT = dffits(AG_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(AG_ZM_lm_ols$coefficients) / nrow(RO_Census_Arges)), 
         Rezid_Std = rstudent(AG_ZM_lm_ols), Leverage = hatvalues(AG_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(AG_ZM_lm_ols)), 
         DFBETA = dfbetas(AG_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Arges)))

# c) Exponential Law
AG_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Arges)
summary(AG_exp_lm_ols)
AG_pred_exp_lm_ols <- exp(predict(AG_exp_lm_ols, newdata = RO_Census_Arges, 
                                  interval = "prediction", level = 0.95))
AG_exp_out_ols <- RO_Census_Arges %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(AG_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Arges), 
         DFFIT = dffits(AG_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(AG_exp_lm_ols$coefficients) / nrow(RO_Census_Arges)), 
         Rezid_Std = rstudent(AG_exp_lm_ols), Leverage = hatvalues(AG_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(AG_exp_lm_ols)), 
         DFBETA = dfbetas(AG_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Arges)))

# d) Lavalette Function
RO_Census_Arges <- RO_Census_Arges %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Arges) - Rank + 1))
)
AG_lav_lm_ols <- lm(log(RO_Census_Arges$Population) ~ RO_Census_Arges$Lav_exp)
summary(AG_lav_lm_ols)
AG_lav_kst_ols <- exp(signif(AG_lav_lm_ols$coef[[1]], 4))
AG_lav_chi_ols <- signif(AG_lav_lm_ols$coef[[2]], 4)
AG_pred_lav_lm_ols <- exp(predict(AG_lav_lm_ols, newdata = RO_Census_Arges, 
                                  interval = "prediction", level = 0.95))
AG_lav_out_ols <- RO_Census_Arges %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(AG_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Arges), 
         DFFIT = dffits(AG_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(AG_lav_lm_ols$coefficients) / nrow(RO_Census_Arges)), 
         Rezid_Std = rstudent(AG_lav_lm_ols), Leverage = hatvalues(AG_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(AG_lav_lm_ols)), 
         DFBETA = dfbetas(AG_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Arges)))

