# 2. Robust

# a) Power Law
AG_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Arges)
summary(AG_pw_lm_rob)
AG_pred_pw_lm_rob <- exp(predict(AG_pw_lm_rob, newdata = RO_Census_Arges, 
                                 interval = "prediction", level = 0.95))
AG_RSquared_pw_rob <- 1 - sum((log(RO_Census_Arges$Population) - fitted(AG_pw_lm_rob))^2) / 
  sum((log(RO_Census_Arges$Population) - mean(log(RO_Census_Arges$Population)))^2)

# b) Zipf_Mandelbrot Law
AG_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Arges, "Population", "Rank")
AG_ZM_m_rob <- AG_ZM_prm_rob$m
AG_ZM_alpha_rob <- AG_ZM_prm_rob$alpha_ZM
AG_ZM_cst_rob <- AG_ZM_prm_rob$constant_ZM
AG_ZM_lm_rob <- rlm(log(RO_Census_Arges$Population) ~ log(RO_Census_Arges$Rank + AG_ZM_m_rob))
summary(AG_ZM_lm_rob)
AG_pred_ZM_lm_rob <- exp(predict(AG_ZM_lm_rob, newdata = RO_Census_Arges, 
                                 interval = "prediction", level = 0.95))
AG_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Arges$Population) - fitted(AG_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Arges$Population) - mean(log(RO_Census_Arges$Population)))^2)

# c) Exponential Law
AG_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Arges)
summary(AG_exp_lm_rob)
AG_pred_exp_lm_rob <- exp(predict(AG_exp_lm_rob, newdata = RO_Census_Arges, 
                                  interval = "prediction", level = 0.95))
AG_RSquared_exp_rob <- 1 - sum((log(RO_Census_Arges$Population) - fitted(AG_exp_lm_rob))^2) / 
  sum((log(RO_Census_Arges$Population) - mean(log(RO_Census_Arges$Population)))^2)

# d) Lavalette Function
RO_Census_Arges <- RO_Census_Arges %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Arges) - Rank + 1))
)
AG_lav_lm_rob <- rlm(log(RO_Census_Arges$Population) ~ RO_Census_Arges$Lav_exp)
summary(AG_lav_lm_rob)
AG_lav_kst_rob <- exp(signif(AG_lav_lm_rob$coef[[1]], 4))
AG_lav_chi_rob <- signif(AG_lav_lm_rob$coef[[2]], 4)
AG_pred_lav_lm_rob <- exp(predict(AG_lav_lm_rob, newdata = RO_Census_Arges, 
                                  interval = "prediction", level = 0.95))
AG_RSquared_lav_rob <- 1 - sum((log(RO_Census_Arges$Population) - fitted(AG_lav_lm_rob))^2) / 
  sum((log(RO_Census_Arges$Population) - mean(log(RO_Census_Arges$Population)))^2)

# e) Data Distributions
RO_Census_Arges %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Arges$Rank, 
                              Population = AG_pred_pw_lm_rob[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(AG_pw_lm_rob$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(AG_pw_lm_rob$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(AG_RSquared_pw_rob, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Arges$Rank, 
                              Population = AG_pred_exp_lm_rob[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(AG_exp_lm_rob$coefficients[[1]]), 4), "%.%", 
                           signif(exp(AG_exp_lm_rob$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(AG_RSquared_exp_rob, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Arges$Rank, 
                              Population = AG_pred_ZM_lm_rob[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(AG_ZM_cst_rob, 4), "%.%", "(",
                           signif(AG_ZM_m_rob, 4), "+ x)^", signif(AG_ZM_alpha_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(AG_RSquared_ZM_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Arges$Rank, 
                              Population = AG_pred_lav_lm_rob[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(AG_lav_kst_rob, 4), "%.%", "x^",
                           -signif(AG_lav_chi_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(AG_RSquared_lav_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
