# IV. Bacau

# 1. OLS
RO_Census_Bacau <- RO_Census_rank %>% filter(Judet_Name == "BACAU")
#View(RO_Census_Bacau)

# a) Power Law
BC_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Bacau)
summary(BC_pw_lm_ols)
BC_pred_pw_lm_ols <- exp(predict(BC_pw_lm_ols, newdata = RO_Census_Bacau, 
                                 interval = "prediction", level = 0.95))
BC_pw_out_ols <- RO_Census_Bacau %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BC_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Bacau), 
         DFFIT = dffits(BC_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BC_pw_lm_ols$coefficients) / nrow(RO_Census_Bacau)), 
         Rezid_Std = rstudent(BC_pw_lm_ols), Leverage = hatvalues(BC_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BC_pw_lm_ols)), 
         DFBETA = dfbetas(BC_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Bacau)))

# b) Zipf_Mandelbrot Law
BC_ZM_prm_ols <- get_ZM_Param("RO_Census_Bacau", "Population", "Rank")
BC_ZM_m_ols <- BC_ZM_prm_ols$m
BC_ZM_alpha_ols <- BC_ZM_prm_ols$alpha_ZM
BC_ZM_cst_ols <- BC_ZM_prm_ols$constant_ZM
BC_ZM_lm_ols <- lm(log(RO_Census_Bacau$Population) ~ log(RO_Census_Bacau$Rank + BC_ZM_m_ols))
summary(BC_ZM_lm_ols)
BC_pred_ZM_lm_ols <- exp(predict(BC_ZM_lm_ols, newdata = RO_Census_Bacau, 
                                 interval = "prediction", level = 0.95))
BC_ZM_out_ols <- RO_Census_Bacau %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BC_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Bacau), 
         DFFIT = dffits(BC_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BC_ZM_lm_ols$coefficients) / nrow(RO_Census_Bacau)), 
         Rezid_Std = rstudent(BC_ZM_lm_ols), Leverage = hatvalues(BC_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BC_ZM_lm_ols)), 
         DFBETA = dfbetas(BC_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Bacau)))

# c) Exponential Law
BC_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Bacau)
summary(BC_exp_lm_ols)
BC_pred_exp_lm_ols <- exp(predict(BC_exp_lm_ols, newdata = RO_Census_Bacau, 
                                  interval = "prediction", level = 0.95))
BC_exp_out_ols <- RO_Census_Bacau %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BC_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Bacau), 
         DFFIT = dffits(BC_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BC_exp_lm_ols$coefficients) / nrow(RO_Census_Bacau)), 
         Rezid_Std = rstudent(BC_exp_lm_ols), Leverage = hatvalues(BC_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BC_exp_lm_ols)), 
         DFBETA = dfbetas(BC_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Bacau)))

# d) Lavalette Function
RO_Census_Bacau <- RO_Census_Bacau %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Bacau) - Rank + 1))
)
BC_lav_lm_ols <- lm(log(RO_Census_Bacau$Population) ~ RO_Census_Bacau$Lav_exp)
summary(BC_lav_lm_ols)
BC_lav_kst_ols <- exp(signif(BC_lav_lm_ols$coef[[1]], 4))
BC_lav_chi_ols <- signif(BC_lav_lm_ols$coef[[2]], 4)
BC_pred_lav_lm_ols <- exp(predict(BC_lav_lm_ols, newdata = RO_Census_Bacau, 
                                  interval = "prediction", level = 0.95))
BC_lav_out_ols <- RO_Census_Bacau %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BC_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Bacau), 
         DFFIT = dffits(BC_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BC_lav_lm_ols$coefficients) / nrow(RO_Census_Bacau)), 
         Rezid_Std = rstudent(BC_lav_lm_ols), Leverage = hatvalues(BC_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BC_lav_lm_ols)), 
         DFBETA = dfbetas(BC_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Bacau)))

# e) Data Distributions
RO_Census_Bacau %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Bacau$Rank, 
