            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(BC_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Bacau$Rank, 
                              Population = BC_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(BC_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(BC_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(BC_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Bacau$Rank, 
                              Population = BC_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(BC_ZM_cst_ols, 4), "%.%", "(",
                           signif(BC_ZM_m_ols, 4), "+ x)^", signif(BC_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
