# 2. Robust

# a) Power Law
BC_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Bacau)
summary(BC_pw_lm_rob)
BC_pred_pw_lm_rob <- exp(predict(BC_pw_lm_rob, newdata = RO_Census_Bacau, 
                                 interval = "prediction", level = 0.95))
BC_RSquared_pw_rob <- 1 - sum((log(RO_Census_Bacau$Population) - fitted(BC_pw_lm_rob))^2) / 
  sum((log(RO_Census_Bacau$Population) - mean(log(RO_Census_Bacau$Population)))^2)

# b) Zipf_Mandelbrot Law
BC_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Bacau, "Population", "Rank")
BC_ZM_m_rob <- BC_ZM_prm_rob$m
BC_ZM_alpha_rob <- BC_ZM_prm_rob$alpha_ZM
BC_ZM_cst_rob <- BC_ZM_prm_rob$constant_ZM
BC_ZM_lm_rob <- rlm(log(RO_Census_Bacau$Population) ~ log(RO_Census_Bacau$Rank + BC_ZM_m_rob))
summary(BC_ZM_lm_rob)
BC_pred_ZM_lm_rob <- exp(predict(BC_ZM_lm_rob, newdata = RO_Census_Bacau, 
                                 interval = "prediction", level = 0.95))
BC_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Bacau$Population) - fitted(BC_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Bacau$Population) - mean(log(RO_Census_Bacau$Population)))^2)

# c) Exponential Law
BC_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Bacau)
summary(BC_exp_lm_rob)
BC_pred_exp_lm_rob <- exp(predict(BC_exp_lm_rob, newdata = RO_Census_Bacau, 
                                  interval = "prediction", level = 0.95))
BC_RSquared_exp_rob <- 1 - sum((log(RO_Census_Bacau$Population) - fitted(BC_exp_lm_rob))^2) / 
  sum((log(RO_Census_Bacau$Population) - mean(log(RO_Census_Bacau$Population)))^2)

# d) Lavalette Function
RO_Census_Bacau <- RO_Census_Bacau %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Bacau) - Rank + 1))
)
BC_lav_lm_rob <- rlm(log(RO_Census_Bacau$Population) ~ RO_Census_Bacau$Lav_exp)
summary(BC_lav_lm_rob)
BC_lav_kst_rob <- exp(signif(BC_lav_lm_rob$coef[[1]], 4))
BC_lav_chi_rob <- signif(BC_lav_lm_rob$coef[[2]], 4)
BC_pred_lav_lm_rob <- exp(predict(BC_lav_lm_rob, newdata = RO_Census_Bacau, 
                                  interval = "prediction", level = 0.95))
BC_RSquared_lav_rob <- 1 - sum((log(RO_Census_Bacau$Population) - fitted(BC_lav_lm_rob))^2) / 
  sum((log(RO_Census_Bacau$Population) - mean(log(RO_Census_Bacau$Population)))^2)

