                           signif(exp(BC_exp_lm_rob$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(BC_RSquared_exp_rob, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Bacau$Rank, 
                              Population = BC_pred_ZM_lm_rob[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(BC_ZM_cst_rob, 4), "%.%", "(",
                           signif(BC_ZM_m_rob, 4), "+ x)^", signif(BC_ZM_alpha_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(BC_RSquared_ZM_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Bacau$Rank, 
                              Population = BC_pred_lav_lm_rob[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(BC_lav_kst_rob, 4), "%.%", "x^",
                           -signif(BC_lav_chi_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(BC_RSquared_lav_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Bacau judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# f) Extract regression metrics
BC_regmet_rob <- as.data.frame(list(Judet_Name = "BACAU",
                                    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
                                    R_Squared = c(signif(BC_RSquared_pw_rob, 4), 
                                                  signif(BC_RSquared_exp_rob, 4),
                                                  signif(BC_RSquared_ZM_rob, 4),
                                                  signif(BC_RSquared_lav_rob, 4)),
                                    AIC = c(signif(AIC(BC_pw_lm_rob), 4), signif(AIC(BC_exp_lm_rob), 4), 
                                            signif(AIC(BC_ZM_lm_rob), 4), signif(AIC(BC_lav_lm_rob), 4)),
                                    BIC = c(signif(BIC(BC_pw_lm_rob), 4), signif(BIC(BC_exp_lm_rob), 4), 
                                            signif(BIC(BC_ZM_lm_rob), 4), signif(BIC(BC_lav_lm_rob), 4)),
                                    MAE = c(signif(mean(abs((log(RO_Census_Bacau$Population) - 
                                                               (predict(BC_pw_lm_rob, newdata = RO_Census_Bacau, 
                                                                        interval = "prediction", level = 0.95))))), 4), 
                                            signif(mean(abs((log(RO_Census_Bacau$Population) - 
                                                               (predict(BC_exp_lm_rob, newdata = RO_Census_Bacau, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Bacau$Population) - 
                                                               (predict(BC_ZM_lm_rob, newdata = RO_Census_Bacau, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Bacau$Population) - 
                                                               (predict(BC_lav_lm_rob, newdata = RO_Census_Bacau, 
                                                                        interval = "prediction", level = 0.95))))), 4)),
                                    RMSE = c(signif(sqrt(mean(((log(RO_Census_Bacau$Population)) - 
                                                                 (predict(BC_pw_lm_rob, newdata = RO_Census_Bacau, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Bacau$Population)) - 
                                                                 (predict(BC_exp_lm_rob, newdata = RO_Census_Bacau, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
