# Extract weight
BC_out_weights <- bind_rows(
  (RO_Census_Bacau %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>% 
     mutate(Robust_Weight = BC_pw_lm_rob$w, Function_Name = "Power")),
  (RO_Census_Bacau %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = BC_ZM_lm_rob$w, Function_Name = "Zipf-Mandelbrot")),
  (RO_Census_Bacau %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = BC_exp_lm_rob$w, Function_Name = "Exponential")),
  (RO_Census_Bacau %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = BC_lav_lm_rob$w, Function_Name = "Lavalette"))) %>% 
  inner_join(BC_out_ols) %>% 
  dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank, Robust_Weight, Function_Name) %>%
  mutate(Judet_Name = "BACAU")

# g) Extract MAE/RMSE on head, body, tail
RO_Census_Bacau_rob <- RO_Census_Bacau %>% 
  mutate(PW_Y_Pred = (predict(BC_pw_lm_rob, newdata = RO_Census_Bacau, 
                              interval = "prediction", level = 0.95))[,1], 
