         EXP_Y_Pred = (predict(BC_exp_lm_rob, newdata = RO_Census_Bacau, 
                               interval = "prediction", level = 0.95))[,1], 
         LAV_Y_Pred = (predict(BC_lav_lm_rob, newdata = RO_Census_Bacau, 
                               interval = "prediction", level = 0.95))[,1])

# Head
BC_rob_hd <- RO_Census_Bacau_rob %>% filter(Rank <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(BC_rob_hd$Population) - BC_rob_hd$PW_Y_Pred))), 4), 
