           signif(sqrt(mean(((log(BC_rob_tl$Population)) - BC_rob_tl$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BC_rob_tl$Population)) - BC_rob_tl$LAV_Y_Pred) ^ 2)), 4))
