# 3. Compare OLS with Robust
BC_regg_res <- bind_rows(BC_res_ols, BC_res_rob)

# RMSE
BC_regg_res %>% ggplot(aes(Data_Part, RMSE, color = Function_Name, 
                           group = Function_Name)) +
  geom_line(linewidth = 1) + geom_point(size = 3) + 
