# V. Bihor

# 1. OLS
RO_Census_Bihor <- RO_Census_rank %>% filter(Judet_Name == "BIHOR")
#View(RO_Census_Bihor)

# a) Power Law
BH_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Bihor)
summary(BH_pw_lm_ols)
BH_pred_pw_lm_ols <- exp(predict(BH_pw_lm_ols, newdata = RO_Census_Bihor, 
                                 interval = "prediction", level = 0.95))
BH_pw_out_ols <- RO_Census_Bihor %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BH_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Bihor), 
         DFFIT = dffits(BH_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BH_pw_lm_ols$coefficients) / nrow(RO_Census_Bihor)), 
         Rezid_Std = rstudent(BH_pw_lm_ols), Leverage = hatvalues(BH_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BH_pw_lm_ols)), 
         DFBETA = dfbetas(BH_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Bihor)))

# b) Zipf_Mandelbrot Law
BH_ZM_prm_ols <- get_ZM_Param("RO_Census_Bihor", "Population", "Rank")
BH_ZM_m_ols <- BH_ZM_prm_ols$m
BH_ZM_alpha_ols <- BH_ZM_prm_ols$alpha_ZM
BH_ZM_cst_ols <- BH_ZM_prm_ols$constant_ZM
BH_ZM_lm_ols <- lm(log(RO_Census_Bihor$Population) ~ log(RO_Census_Bihor$Rank + BH_ZM_m_ols))
summary(BH_ZM_lm_ols)
BH_pred_ZM_lm_ols <- exp(predict(BH_ZM_lm_ols, newdata = RO_Census_Bihor, 
                                 interval = "prediction", level = 0.95))
BH_ZM_out_ols <- RO_Census_Bihor %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BH_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Bihor), 
         DFFIT = dffits(BH_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BH_ZM_lm_ols$coefficients) / nrow(RO_Census_Bihor)), 
         Rezid_Std = rstudent(BH_ZM_lm_ols), Leverage = hatvalues(BH_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BH_ZM_lm_ols)), 
         DFBETA = dfbetas(BH_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Bihor)))

# c) Exponential Law
BH_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Bihor)
summary(BH_exp_lm_ols)
BH_pred_exp_lm_ols <- exp(predict(BH_exp_lm_ols, newdata = RO_Census_Bihor, 
                                  interval = "prediction", level = 0.95))
BH_exp_out_ols <- RO_Census_Bihor %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BH_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Bihor), 
         DFFIT = dffits(BH_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BH_exp_lm_ols$coefficients) / nrow(RO_Census_Bihor)), 
         Rezid_Std = rstudent(BH_exp_lm_ols), Leverage = hatvalues(BH_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BH_exp_lm_ols)), 
         DFBETA = dfbetas(BH_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Bihor)))

# d) Lavalette Function
RO_Census_Bihor <- RO_Census_Bihor %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Bihor) - Rank + 1))
)
BH_lav_lm_ols <- lm(log(RO_Census_Bihor$Population) ~ RO_Census_Bihor$Lav_exp)
summary(BH_lav_lm_ols)
BH_lav_kst_ols <- exp(signif(BH_lav_lm_ols$coef[[1]], 4))
BH_lav_chi_ols <- signif(BH_lav_lm_ols$coef[[2]], 4)
BH_pred_lav_lm_ols <- exp(predict(BH_lav_lm_ols, newdata = RO_Census_Bihor, 
                                  interval = "prediction", level = 0.95))
BH_lav_out_ols <- RO_Census_Bihor %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BH_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Bihor), 
         DFFIT = dffits(BH_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BH_lav_lm_ols$coefficients) / nrow(RO_Census_Bihor)), 
         Rezid_Std = rstudent(BH_lav_lm_ols), Leverage = hatvalues(BH_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BH_lav_lm_ols)), 
         DFBETA = dfbetas(BH_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Bihor)))

# e) Data Distributions
RO_Census_Bihor %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Bihor$Rank, 
                              Population = BH_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(BH_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(BH_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(BH_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Bihor$Rank, 
                              Population = BH_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(BH_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(BH_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(BH_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Bihor$Rank, 
                              Population = BH_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(BH_ZM_cst_ols, 4), "%.%", "(",
                           signif(BH_ZM_m_ols, 4), "+ x)^", signif(BH_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(summary(BH_ZM_lm_ols)$r.squared, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Bihor$Rank, 
                              Population = BH_pred_lav_lm_ols[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(BH_lav_kst_ols, 4), "%.%", "x^",
                           -signif(BH_lav_chi_ols, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(summary(BH_lav_lm_ols)$r.squared, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Bihor judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# Linear Regressions
grid.arrange(
  (RO_Census_Bihor %>%
     ggplot(aes(x = log(Rank), y = log(Population))) +
