# 2. Robust

# a) Power Law
BH_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Bihor)
summary(BH_pw_lm_rob)
BH_pred_pw_lm_rob <- exp(predict(BH_pw_lm_rob, newdata = RO_Census_Bihor, 
                                 interval = "prediction", level = 0.95))
BH_RSquared_pw_rob <- 1 - sum((log(RO_Census_Bihor$Population) - fitted(BH_pw_lm_rob))^2) / 
  sum((log(RO_Census_Bihor$Population) - mean(log(RO_Census_Bihor$Population)))^2)

# b) Zipf_Mandelbrot Law
BH_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Bihor, "Population", "Rank")
BH_ZM_m_rob <- BH_ZM_prm_rob$m
BH_ZM_alpha_rob <- BH_ZM_prm_rob$alpha_ZM
BH_ZM_cst_rob <- BH_ZM_prm_rob$constant_ZM
BH_ZM_lm_rob <- rlm(log(RO_Census_Bihor$Population) ~ log(RO_Census_Bihor$Rank + BH_ZM_m_rob))
summary(BH_ZM_lm_rob)
BH_pred_ZM_lm_rob <- exp(predict(BH_ZM_lm_rob, newdata = RO_Census_Bihor, 
                                 interval = "prediction", level = 0.95))
BH_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Bihor$Population) - fitted(BH_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Bihor$Population) - mean(log(RO_Census_Bihor$Population)))^2)

# c) Exponential Law
BH_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Bihor)
summary(BH_exp_lm_rob)
BH_pred_exp_lm_rob <- exp(predict(BH_exp_lm_rob, newdata = RO_Census_Bihor, 
                                  interval = "prediction", level = 0.95))
BH_RSquared_exp_rob <- 1 - sum((log(RO_Census_Bihor$Population) - fitted(BH_exp_lm_rob))^2) / 
  sum((log(RO_Census_Bihor$Population) - mean(log(RO_Census_Bihor$Population)))^2)

# d) Lavalette Function
RO_Census_Bihor <- RO_Census_Bihor %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Bihor) - Rank + 1))
)
BH_lav_lm_rob <- rlm(log(RO_Census_Bihor$Population) ~ RO_Census_Bihor$Lav_exp)
summary(BH_lav_lm_rob)
BH_lav_kst_rob <- exp(signif(BH_lav_lm_rob$coef[[1]], 4))
BH_lav_chi_rob <- signif(BH_lav_lm_rob$coef[[2]], 4)
BH_pred_lav_lm_rob <- exp(predict(BH_lav_lm_rob, newdata = RO_Census_Bihor, 
                                  interval = "prediction", level = 0.95))
BH_RSquared_lav_rob <- 1 - sum((log(RO_Census_Bihor$Population) - fitted(BH_lav_lm_rob))^2) / 
  sum((log(RO_Census_Bihor$Population) - mean(log(RO_Census_Bihor$Population)))^2)

