# Extract weight
BH_out_weights <- bind_rows(
  (RO_Census_Bihor %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>% 
     mutate(Robust_Weight = BH_pw_lm_rob$w, Function_Name = "Power")),
  (RO_Census_Bihor %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = BH_ZM_lm_rob$w, Function_Name = "Zipf-Mandelbrot")),
  (RO_Census_Bihor %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = BH_exp_lm_rob$w, Function_Name = "Exponential")),
  (RO_Census_Bihor %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = BH_lav_lm_rob$w, Function_Name = "Lavalette"))) %>% 
  inner_join(BH_out_ols) %>% 
  dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank, Robust_Weight, Function_Name) %>%
  mutate(Judet_Name = "BIHOR")

# g) Extract MAE/RMSE on head, body, tail
RO_Census_Bihor_rob <- RO_Census_Bihor %>% 
  mutate(PW_Y_Pred = (predict(BH_pw_lm_rob, newdata = RO_Census_Bihor, 
                              interval = "prediction", level = 0.95))[,1], 
         ZM_Y_Pred = (predict(BH_ZM_lm_rob, newdata = RO_Census_Bihor, 
                              interval = "prediction", level = 0.95))[,1],
         EXP_Y_Pred = (predict(BH_exp_lm_rob, newdata = RO_Census_Bihor, 
                               interval = "prediction", level = 0.95))[,1], 
         LAV_Y_Pred = (predict(BH_lav_lm_rob, newdata = RO_Census_Bihor, 
                               interval = "prediction", level = 0.95))[,1])

# Head
BH_rob_hd <- RO_Census_Bihor_rob %>% filter(Rank <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(BH_rob_hd$Population) - BH_rob_hd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(BH_rob_hd$Population) - BH_rob_hd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(BH_rob_hd$Population) - BH_rob_hd$ZM_Y_Pred))), 4),
          signif(mean(abs((log(BH_rob_hd$Population) - BH_rob_hd$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(BH_rob_hd$Population)) - BH_rob_hd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BH_rob_hd$Population)) - BH_rob_hd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BH_rob_hd$Population)) - BH_rob_hd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BH_rob_hd$Population)) - BH_rob_hd$LAV_Y_Pred) ^ 2)), 4))
))

# Tail
BH_rob_tl <- RO_Census_Bihor_rob %>% arrange(desc(Rank)) %>% 
  filter(row_number() <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(BH_rob_tl$Population) - BH_rob_tl$PW_Y_Pred))), 4), 
          signif(mean(abs((log(BH_rob_tl$Population) - BH_rob_tl$EXP_Y_Pred))), 4),
          signif(mean(abs((log(BH_rob_tl$Population) - BH_rob_tl$ZM_Y_Pred))), 4),
          signif(mean(abs((log(BH_rob_tl$Population) - BH_rob_tl$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(BH_rob_tl$Population)) - BH_rob_tl$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BH_rob_tl$Population)) - BH_rob_tl$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BH_rob_tl$Population)) - BH_rob_tl$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BH_rob_tl$Population)) - BH_rob_tl$LAV_Y_Pred) ^ 2)), 4))
))

# Body
BH_rob_bd <- RO_Census_Bihor_rob %>% anti_join(BH_rob_hd) %>% anti_join(BH_rob_tl)

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(BH_rob_bd$Population) - BH_rob_bd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(BH_rob_bd$Population) - BH_rob_bd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(BH_rob_bd$Population) - BH_rob_bd$ZM_Y_Pred))), 4),
          signif(mean(abs((log(BH_rob_bd$Population) - BH_rob_bd$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(BH_rob_bd$Population)) - BH_rob_bd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BH_rob_bd$Population)) - BH_rob_bd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BH_rob_bd$Population)) - BH_rob_bd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BH_rob_bd$Population)) - BH_rob_bd$LAV_Y_Pred) ^ 2)), 4))
))

# Final
BH_res_rob <- as.data.frame(bind_rows(
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(BH_rob_hd$Population) - BH_rob_hd$PW_Y_Pred))), 4), 
            signif(mean(abs((log(BH_rob_hd$Population) - BH_rob_hd$EXP_Y_Pred))), 4),
            signif(mean(abs((log(BH_rob_hd$Population) - BH_rob_hd$ZM_Y_Pred))), 4),
            signif(mean(abs((log(BH_rob_hd$Population) - BH_rob_hd$LAV_Y_Pred))), 4)),
    RMSE = c(signif(sqrt(mean(((log(BH_rob_hd$Population)) - BH_rob_hd$PW_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(BH_rob_hd$Population)) - BH_rob_hd$EXP_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(BH_rob_hd$Population)) - BH_rob_hd$ZM_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(BH_rob_hd$Population)) - BH_rob_hd$LAV_Y_Pred) ^ 2)), 4)),
    Data_Part = "Head"
  )),
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(BH_rob_tl$Population) - BH_rob_tl$PW_Y_Pred))), 4), 
            signif(mean(abs((log(BH_rob_tl$Population) - BH_rob_tl$EXP_Y_Pred))), 4),
            signif(mean(abs((log(BH_rob_tl$Population) - BH_rob_tl$ZM_Y_Pred))), 4),
            signif(mean(abs((log(BH_rob_tl$Population) - BH_rob_tl$LAV_Y_Pred))), 4)),
    RMSE = c(signif(sqrt(mean(((log(BH_rob_tl$Population)) - BH_rob_tl$PW_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(BH_rob_tl$Population)) - BH_rob_tl$EXP_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(BH_rob_tl$Population)) - BH_rob_tl$ZM_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(BH_rob_tl$Population)) - BH_rob_tl$LAV_Y_Pred) ^ 2)), 4)),
    Data_Part = "Tail"
  )),
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(BH_rob_bd$Population) - BH_rob_bd$PW_Y_Pred))), 4), 
            signif(mean(abs((log(BH_rob_bd$Population) - BH_rob_bd$EXP_Y_Pred))), 4),
            signif(mean(abs((log(BH_rob_bd$Population) - BH_rob_bd$ZM_Y_Pred))), 4),
            signif(mean(abs((log(BH_rob_bd$Population) - BH_rob_bd$LAV_Y_Pred))), 4)),
    RMSE = c(signif(sqrt(mean(((log(BH_rob_bd$Population)) - BH_rob_bd$PW_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(BH_rob_bd$Population)) - BH_rob_bd$EXP_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(BH_rob_bd$Population)) - BH_rob_bd$ZM_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(BH_rob_bd$Population)) - BH_rob_bd$LAV_Y_Pred) ^ 2)), 4)),
    Data_Part = "Body"
  )),
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(RO_Census_Bihor$Population) - 
                               (predict(BH_pw_lm_rob, newdata = RO_Census_Bihor, 
                                        interval = "prediction", level = 0.95))))), 4), 
            signif(mean(abs((log(RO_Census_Bihor$Population) - 
                               (predict(BH_exp_lm_rob, newdata = RO_Census_Bihor, 
                                        interval = "prediction", level = 0.95))))), 4),
            signif(mean(abs((log(RO_Census_Bihor$Population) - 
                               (predict(BH_ZM_lm_rob, newdata = RO_Census_Bihor, 
                                        interval = "prediction", level = 0.95))))), 4),
            signif(mean(abs((log(RO_Census_Bihor$Population) - 
                               (predict(BH_lav_lm_rob, newdata = RO_Census_Bihor, 
                                        interval = "prediction", level = 0.95))))), 4)),
    RMSE = c(signif(sqrt(mean(((log(RO_Census_Bihor$Population)) - 
                                 (predict(BH_pw_lm_rob, newdata = RO_Census_Bihor, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Bihor$Population)) - 
                                 (predict(BH_exp_lm_rob, newdata = RO_Census_Bihor, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Bihor$Population)) - 
                                 (predict(BH_ZM_lm_rob, newdata = RO_Census_Bihor, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Bihor$Population)) - 
                                 (predict(BH_lav_lm_rob, newdata = RO_Census_Bihor, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4)),
    Data_Part = "Full"
  ))
)) %>% mutate(Regression_Type = "Robust", Judet_Name = "BIHOR")

