# VI. Bistrita-Nasaud

# 1. OLS
RO_Census_BistNsd <- RO_Census_rank %>% filter(Judet_Name == "BISTRITA-NASAUD")
#View(RO_Census_BistNsd)

# a) Power Law
BN_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_BistNsd)
summary(BN_pw_lm_ols)
BN_pred_pw_lm_ols <- exp(predict(BN_pw_lm_ols, newdata = RO_Census_BistNsd, 
                                 interval = "prediction", level = 0.95))
BN_pw_out_ols <- RO_Census_BistNsd %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BN_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_BistNsd), 
         DFFIT = dffits(BN_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BN_pw_lm_ols$coefficients) / nrow(RO_Census_BistNsd)), 
         Rezid_Std = rstudent(BN_pw_lm_ols), Leverage = hatvalues(BN_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BN_pw_lm_ols)), 
         DFBETA = dfbetas(BN_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_BistNsd)))

# b) Zipf_Mandelbrot Law
BN_ZM_prm_ols <- get_ZM_Param("RO_Census_BistNsd", "Population", "Rank")
BN_ZM_m_ols <- BN_ZM_prm_ols$m
BN_ZM_alpha_ols <- BN_ZM_prm_ols$alpha_ZM
BN_ZM_cst_ols <- BN_ZM_prm_ols$constant_ZM
BN_ZM_lm_ols <- lm(log(RO_Census_BistNsd$Population) ~ log(RO_Census_BistNsd$Rank + BN_ZM_m_ols))
summary(BN_ZM_lm_ols)
BN_pred_ZM_lm_ols <- exp(predict(BN_ZM_lm_ols, newdata = RO_Census_BistNsd, 
                                 interval = "prediction", level = 0.95))
BN_ZM_out_ols <- RO_Census_BistNsd %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BN_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_BistNsd), 
         DFFIT = dffits(BN_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BN_ZM_lm_ols$coefficients) / nrow(RO_Census_BistNsd)), 
         Rezid_Std = rstudent(BN_ZM_lm_ols), Leverage = hatvalues(BN_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BN_ZM_lm_ols)), 
         DFBETA = dfbetas(BN_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_BistNsd)))

# c) Exponential Law
BN_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_BistNsd)
summary(BN_exp_lm_ols)
BN_pred_exp_lm_ols <- exp(predict(BN_exp_lm_ols, newdata = RO_Census_BistNsd, 
                                  interval = "prediction", level = 0.95))
BN_exp_out_ols <- RO_Census_BistNsd %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BN_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_BistNsd), 
         DFFIT = dffits(BN_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BN_exp_lm_ols$coefficients) / nrow(RO_Census_BistNsd)), 
         Rezid_Std = rstudent(BN_exp_lm_ols), Leverage = hatvalues(BN_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BN_exp_lm_ols)), 
         DFBETA = dfbetas(BN_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_BistNsd)))

# d) Lavalette Function
RO_Census_BistNsd <- RO_Census_BistNsd %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_BistNsd) - Rank + 1))
)
BN_lav_lm_ols <- lm(log(RO_Census_BistNsd$Population) ~ RO_Census_BistNsd$Lav_exp)
summary(BN_lav_lm_ols)
BN_lav_kst_ols <- exp(signif(BN_lav_lm_ols$coef[[1]], 4))
BN_lav_chi_ols <- signif(BN_lav_lm_ols$coef[[2]], 4)
BN_pred_lav_lm_ols <- exp(predict(BN_lav_lm_ols, newdata = RO_Census_BistNsd, 
                                  interval = "prediction", level = 0.95))
BN_lav_out_ols <- RO_Census_BistNsd %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BN_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_BistNsd), 
         DFFIT = dffits(BN_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BN_lav_lm_ols$coefficients) / nrow(RO_Census_BistNsd)), 
         Rezid_Std = rstudent(BN_lav_lm_ols), Leverage = hatvalues(BN_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BN_lav_lm_ols)), 
         DFBETA = dfbetas(BN_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_BistNsd)))

# e) Data Distributions
RO_Census_BistNsd %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_BistNsd$Rank, 
                              Population = BN_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(BN_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(BN_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(BN_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_BistNsd$Rank, 
                              Population = BN_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(BN_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(BN_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(BN_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_BistNsd$Rank, 
                              Population = BN_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(BN_ZM_cst_ols, 4), "%.%", "(",
                           signif(BN_ZM_m_ols, 4), "+ x)^", signif(BN_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(summary(BN_ZM_lm_ols)$r.squared, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_BistNsd$Rank, 
                              Population = BN_pred_lav_lm_ols[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(BN_lav_kst_ols, 4), "%.%", "x^",
                           -signif(BN_lav_chi_ols, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(summary(BN_lav_lm_ols)$r.squared, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on BistNsd judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# Linear Regressions
grid.arrange(
  (RO_Census_BistNsd %>%
     ggplot(aes(x = log(Rank), y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = "#ED3F39FF") +
     labs(x = "Rank", y = "Population") +
     ggtitle("Power Linear Regression on BistNsd judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  (RO_Census_BistNsd %>%
     ggplot(aes(x = Rank, y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = "#088BBEFF") +
     labs(x = "Rank", y = "Population") +
     ggtitle("Exponential Linear Regression on BistNsd judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  (RO_Census_BistNsd %>%
     ggplot(aes(x = log(Rank + BN_ZM_m_ols), y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = '#1B7837FF') +
     labs(x = "Rank", y = "Population") +
     ggtitle("Zipf-Mandelbrot Linear Regression on BistNsd judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  (RO_Census_BistNsd %>%
     ggplot(aes(x = Lav_exp, y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = '#F8A02EFF') +
     labs(x = "Rank", y = "Population") +
     ggtitle("Lavalette Linear Regression on BistNsd judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  ncol = 2, nrow = 2)

# f) Extract Outliers
BistNsd_Outliers <- bind_rows(
  (BN_pw_out_ols %>% mutate(Function_Name = "Power")),
  (BN_ZM_out_ols %>% mutate(Function_Name = "Zipf-Mandelbrot")),
  (BN_exp_out_ols %>% mutate(Function_Name = "Exponential")),
  (BN_lav_out_ols %>% mutate(Function_Name = "Lavalette"))
) %>% mutate(DFBETA_intercept = round(DFBETA[,1], 8), 
             DFBETA_var_x = round(DFBETA[,2], 8)) %>% dplyr::select(-DFBETA)

BN_out <- get_outliers(BistNsd_Outliers, RO_Census_BistNsd)

BN_out_ols <- RO_Census_BistNsd %>% inner_join(
  bind_rows(
    (BN_out$PW %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>% 
       dplyr::select(Rank) %>% distinct()),
    (BN_out$ZM %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (BN_out$LAV %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (BN_out$EXP %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct())
  ) %>% count(Rank) %>% arrange(desc(n)) %>% filter(n >= mean(n))) %>% 
  dplyr::select(-n)

# g) Extract regression metrics
BN_regmet_ols <- as.data.frame(list(Judet_Name = "BISTRITA-NASAUD",
