# 2. Robust

# a) Power Law
BN_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_BistNsd)
summary(BN_pw_lm_rob)
BN_pred_pw_lm_rob <- exp(predict(BN_pw_lm_rob, newdata = RO_Census_BistNsd, 
                                 interval = "prediction", level = 0.95))
BN_RSquared_pw_rob <- 1 - sum((log(RO_Census_BistNsd$Population) - fitted(BN_pw_lm_rob))^2) / 
  sum((log(RO_Census_BistNsd$Population) - mean(log(RO_Census_BistNsd$Population)))^2)

# b) Zipf_Mandelbrot Law
BN_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_BistNsd, "Population", "Rank")
BN_ZM_m_rob <- BN_ZM_prm_rob$m
BN_ZM_alpha_rob <- BN_ZM_prm_rob$alpha_ZM
BN_ZM_cst_rob <- BN_ZM_prm_rob$constant_ZM
BN_ZM_lm_rob <- rlm(log(RO_Census_BistNsd$Population) ~ log(RO_Census_BistNsd$Rank + BN_ZM_m_rob))
summary(BN_ZM_lm_rob)
BN_pred_ZM_lm_rob <- exp(predict(BN_ZM_lm_rob, newdata = RO_Census_BistNsd, 
                                 interval = "prediction", level = 0.95))
BN_RSquared_ZM_rob <- 1 - sum((log(RO_Census_BistNsd$Population) - fitted(BN_ZM_lm_rob))^2) / 
  sum((log(RO_Census_BistNsd$Population) - mean(log(RO_Census_BistNsd$Population)))^2)

# c) Exponential Law
BN_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_BistNsd)
summary(BN_exp_lm_rob)
BN_pred_exp_lm_rob <- exp(predict(BN_exp_lm_rob, newdata = RO_Census_BistNsd, 
                                  interval = "prediction", level = 0.95))
BN_RSquared_exp_rob <- 1 - sum((log(RO_Census_BistNsd$Population) - fitted(BN_exp_lm_rob))^2) / 
  sum((log(RO_Census_BistNsd$Population) - mean(log(RO_Census_BistNsd$Population)))^2)

# d) Lavalette Function
RO_Census_BistNsd <- RO_Census_BistNsd %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_BistNsd) - Rank + 1))
)
BN_lav_lm_rob <- rlm(log(RO_Census_BistNsd$Population) ~ RO_Census_BistNsd$Lav_exp)
summary(BN_lav_lm_rob)
BN_lav_kst_rob <- exp(signif(BN_lav_lm_rob$coef[[1]], 4))
BN_lav_chi_rob <- signif(BN_lav_lm_rob$coef[[2]], 4)
BN_pred_lav_lm_rob <- exp(predict(BN_lav_lm_rob, newdata = RO_Census_BistNsd, 
                                  interval = "prediction", level = 0.95))
BN_RSquared_lav_rob <- 1 - sum((log(RO_Census_BistNsd$Population) - fitted(BN_lav_lm_rob))^2) / 
  sum((log(RO_Census_BistNsd$Population) - mean(log(RO_Census_BistNsd$Population)))^2)

# e) Data Distributions
RO_Census_BistNsd %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_BistNsd$Rank, 
                              Population = BN_pred_pw_lm_rob[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(BN_pw_lm_rob$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(BN_pw_lm_rob$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(BN_RSquared_pw_rob, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_BistNsd$Rank, 
                              Population = BN_pred_exp_lm_rob[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(BN_exp_lm_rob$coefficients[[1]]), 4), "%.%", 
                           signif(exp(BN_exp_lm_rob$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(BN_RSquared_exp_rob, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_BistNsd$Rank, 
                              Population = BN_pred_ZM_lm_rob[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(BN_ZM_cst_rob, 4), "%.%", "(",
                           signif(BN_ZM_m_rob, 4), "+ x)^", signif(BN_ZM_alpha_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(BN_RSquared_ZM_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_BistNsd$Rank, 
                              Population = BN_pred_lav_lm_rob[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(BN_lav_kst_rob, 4), "%.%", "x^",
                           -signif(BN_lav_chi_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(BN_RSquared_lav_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on BistNsd judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

