BN_rob_hd <- RO_Census_BistNsd_rob %>% filter(Rank <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(BN_rob_hd$Population) - BN_rob_hd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(BN_rob_hd$Population) - BN_rob_hd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(BN_rob_hd$Population) - BN_rob_hd$ZM_Y_Pred))), 4),
