          signif(mean(abs((log(BN_rob_tl$Population) - BN_rob_tl$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(BN_rob_tl$Population)) - BN_rob_tl$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BN_rob_tl$Population)) - BN_rob_tl$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BN_rob_tl$Population)) - BN_rob_tl$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BN_rob_tl$Population)) - BN_rob_tl$LAV_Y_Pred) ^ 2)), 4))
))

# Body
BN_rob_bd <- RO_Census_BistNsd_rob %>% anti_join(BN_rob_hd) %>% anti_join(BN_rob_tl)

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(BN_rob_bd$Population) - BN_rob_bd$PW_Y_Pred))), 4), 
