          signif(mean(abs((log(BN_rob_bd$Population) - BN_rob_bd$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(BN_rob_bd$Population)) - BN_rob_bd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BN_rob_bd$Population)) - BN_rob_bd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BN_rob_bd$Population)) - BN_rob_bd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BN_rob_bd$Population)) - BN_rob_bd$LAV_Y_Pred) ^ 2)), 4))
))

# Final
