# VII. Botosani

# 1. OLS
RO_Census_Botosani <- RO_Census_rank %>% filter(Judet_Name == "BOTOSANI")
#View(RO_Census_Botosani)

# a) Power Law
BT_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Botosani)
summary(BT_pw_lm_ols)
BT_pred_pw_lm_ols <- exp(predict(BT_pw_lm_ols, newdata = RO_Census_Botosani, 
                                 interval = "prediction", level = 0.95))
BT_pw_out_ols <- RO_Census_Botosani %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BT_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Botosani), 
         DFFIT = dffits(BT_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BT_pw_lm_ols$coefficients) / nrow(RO_Census_Botosani)), 
         Rezid_Std = rstudent(BT_pw_lm_ols), Leverage = hatvalues(BT_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BT_pw_lm_ols)), 
         DFBETA = dfbetas(BT_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Botosani)))

# b) Zipf_Mandelbrot Law
BT_ZM_prm_ols <- get_ZM_Param("RO_Census_Botosani", "Population", "Rank")
BT_ZM_m_ols <- BT_ZM_prm_ols$m
BT_ZM_alpha_ols <- BT_ZM_prm_ols$alpha_ZM
BT_ZM_cst_ols <- BT_ZM_prm_ols$constant_ZM
BT_ZM_lm_ols <- lm(log(RO_Census_Botosani$Population) ~ log(RO_Census_Botosani$Rank + BT_ZM_m_ols))
summary(BT_ZM_lm_ols)
BT_pred_ZM_lm_ols <- exp(predict(BT_ZM_lm_ols, newdata = RO_Census_Botosani, 
                                 interval = "prediction", level = 0.95))
BT_ZM_out_ols <- RO_Census_Botosani %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BT_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Botosani), 
         DFFIT = dffits(BT_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BT_ZM_lm_ols$coefficients) / nrow(RO_Census_Botosani)), 
         Rezid_Std = rstudent(BT_ZM_lm_ols), Leverage = hatvalues(BT_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BT_ZM_lm_ols)), 
         DFBETA = dfbetas(BT_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Botosani)))

# c) Exponential Law
BT_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Botosani)
summary(BT_exp_lm_ols)
BT_pred_exp_lm_ols <- exp(predict(BT_exp_lm_ols, newdata = RO_Census_Botosani, 
                                  interval = "prediction", level = 0.95))
BT_exp_out_ols <- RO_Census_Botosani %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BT_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Botosani), 
         DFFIT = dffits(BT_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BT_exp_lm_ols$coefficients) / nrow(RO_Census_Botosani)), 
         Rezid_Std = rstudent(BT_exp_lm_ols), Leverage = hatvalues(BT_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BT_exp_lm_ols)), 
         DFBETA = dfbetas(BT_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Botosani)))

# d) Lavalette Function
RO_Census_Botosani <- RO_Census_Botosani %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Botosani) - Rank + 1))
)
BT_lav_lm_ols <- lm(log(RO_Census_Botosani$Population) ~ RO_Census_Botosani$Lav_exp)
summary(BT_lav_lm_ols)
BT_lav_kst_ols <- exp(signif(BT_lav_lm_ols$coef[[1]], 4))
BT_lav_chi_ols <- signif(BT_lav_lm_ols$coef[[2]], 4)
BT_pred_lav_lm_ols <- exp(predict(BT_lav_lm_ols, newdata = RO_Census_Botosani, 
                                  interval = "prediction", level = 0.95))
BT_lav_out_ols <- RO_Census_Botosani %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BT_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Botosani), 
         DFFIT = dffits(BT_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BT_lav_lm_ols$coefficients) / nrow(RO_Census_Botosani)), 
         Rezid_Std = rstudent(BT_lav_lm_ols), Leverage = hatvalues(BT_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BT_lav_lm_ols)), 
         DFBETA = dfbetas(BT_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Botosani)))

# e) Data Distributions
RO_Census_Botosani %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Botosani$Rank, 
                              Population = BT_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(BT_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(BT_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(BT_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Botosani$Rank, 
                              Population = BT_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(BT_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(BT_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(BT_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Botosani$Rank, 
                              Population = BT_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(BT_ZM_cst_ols, 4), "%.%", "(",
                           signif(BT_ZM_m_ols, 4), "+ x)^", signif(BT_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(summary(BT_ZM_lm_ols)$r.squared, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Botosani$Rank, 
                              Population = BT_pred_lav_lm_ols[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(BT_lav_kst_ols, 4), "%.%", "x^",
                           -signif(BT_lav_chi_ols, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(summary(BT_lav_lm_ols)$r.squared, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Botosani judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# Linear Regressions
grid.arrange(
  (RO_Census_Botosani %>%
     ggplot(aes(x = log(Rank), y = log(Population))) +
