     ggtitle("Lavalette Linear Regression on Botosani judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  ncol = 2, nrow = 2)

# f) Extract Outliers
Botosani_Outliers <- bind_rows(
  (BT_pw_out_ols %>% mutate(Function_Name = "Power")),
  (BT_ZM_out_ols %>% mutate(Function_Name = "Zipf-Mandelbrot")),
  (BT_exp_out_ols %>% mutate(Function_Name = "Exponential")),
  (BT_lav_out_ols %>% mutate(Function_Name = "Lavalette"))
) %>% mutate(DFBETA_intercept = round(DFBETA[,1], 8), 
             DFBETA_var_x = round(DFBETA[,2], 8)) %>% dplyr::select(-DFBETA)

BT_out <- get_outliers(Botosani_Outliers, RO_Census_Botosani)

BT_out_ols <- RO_Census_Botosani %>% inner_join(
  bind_rows(
    (BT_out$PW %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>% 
       dplyr::select(Rank) %>% distinct()),
    (BT_out$ZM %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (BT_out$LAV %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (BT_out$EXP %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct())
  ) %>% count(Rank) %>% arrange(desc(n)) %>% filter(n == max(n))) %>% 
  dplyr::select(-n)

# g) Extract regression metrics
BT_regmet_ols <- as.data.frame(list(Judet_Name = "BOTOSANI",
                                    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
                                    R_Squared = c(signif(summary(BT_pw_lm_ols)$r.squared, 4), 
                                                  signif(summary(BT_exp_lm_ols)$r.squared, 4),
                                                  signif(summary(BT_ZM_lm_ols)$r.squared, 4),
                                                  signif(summary(BT_lav_lm_ols)$r.squared, 4)),
                                    Adj_R_Squared = c(signif(summary(BT_pw_lm_ols)$adj.r.squared, 4), 
                                                      signif(summary(BT_exp_lm_ols)$adj.r.squared, 4),
                                                      signif(summary(BT_ZM_lm_ols)$adj.r.squared, 4),
                                                      signif(summary(BT_lav_lm_ols)$adj.r.squared, 4)),
                                    AIC = c(signif(AIC(BT_pw_lm_ols), 4), signif(AIC(BT_exp_lm_ols), 4), 
                                            signif(AIC(BT_ZM_lm_ols), 4), signif(AIC(BT_lav_lm_ols), 4)),
                                    BIC = c(signif(BIC(BT_pw_lm_ols), 4), signif(BIC(BT_exp_lm_ols), 4), 
                                            signif(BIC(BT_ZM_lm_ols), 4), signif(BIC(BT_lav_lm_ols), 4)),
                                    MAE = c(signif(mean(abs((log(RO_Census_Botosani$Population) - 
                                                               (predict(BT_pw_lm_ols, newdata = RO_Census_Botosani, 
                                                                        interval = "prediction", level = 0.95))))), 4), 
                                            signif(mean(abs((log(RO_Census_Botosani$Population) - 
                                                               (predict(BT_exp_lm_ols, newdata = RO_Census_Botosani, 
