# VIII. Braila

# 1. OLS
RO_Census_Braila <- RO_Census_rank %>% filter(Judet_Name == "BRAILA")
#View(RO_Census_Braila)

# a) Power Law
BR_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Braila)
summary(BR_pw_lm_ols)
BR_pred_pw_lm_ols <- exp(predict(BR_pw_lm_ols, newdata = RO_Census_Braila, 
                                 interval = "prediction", level = 0.95))
BR_pw_out_ols <- RO_Census_Braila %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BR_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Braila), 
         DFFIT = dffits(BR_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BR_pw_lm_ols$coefficients) / nrow(RO_Census_Braila)), 
         Rezid_Std = rstudent(BR_pw_lm_ols), Leverage = hatvalues(BR_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BR_pw_lm_ols)), 
         DFBETA = dfbetas(BR_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Braila)))

# b) Zipf_Mandelbrot Law
BR_ZM_prm_ols <- get_ZM_Param("RO_Census_Braila", "Population", "Rank")
BR_ZM_m_ols <- BR_ZM_prm_ols$m
BR_ZM_alpha_ols <- BR_ZM_prm_ols$alpha_ZM
BR_ZM_cst_ols <- BR_ZM_prm_ols$constant_ZM
BR_ZM_lm_ols <- lm(log(RO_Census_Braila$Population) ~ log(RO_Census_Braila$Rank + BR_ZM_m_ols))
summary(BR_ZM_lm_ols)
BR_pred_ZM_lm_ols <- exp(predict(BR_ZM_lm_ols, newdata = RO_Census_Braila, 
                                 interval = "prediction", level = 0.95))
BR_ZM_out_ols <- RO_Census_Braila %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BR_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Braila), 
         DFFIT = dffits(BR_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BR_ZM_lm_ols$coefficients) / nrow(RO_Census_Braila)), 
         Rezid_Std = rstudent(BR_ZM_lm_ols), Leverage = hatvalues(BR_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BR_ZM_lm_ols)), 
         DFBETA = dfbetas(BR_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Braila)))

# c) Exponential Law
BR_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Braila)
summary(BR_exp_lm_ols)
BR_pred_exp_lm_ols <- exp(predict(BR_exp_lm_ols, newdata = RO_Census_Braila, 
                                  interval = "prediction", level = 0.95))
BR_exp_out_ols <- RO_Census_Braila %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BR_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Braila), 
         DFFIT = dffits(BR_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BR_exp_lm_ols$coefficients) / nrow(RO_Census_Braila)), 
         Rezid_Std = rstudent(BR_exp_lm_ols), Leverage = hatvalues(BR_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BR_exp_lm_ols)), 
         DFBETA = dfbetas(BR_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Braila)))

# d) Lavalette Function
RO_Census_Braila <- RO_Census_Braila %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Braila) - Rank + 1))
)
BR_lav_lm_ols <- lm(log(RO_Census_Braila$Population) ~ RO_Census_Braila$Lav_exp)
summary(BR_lav_lm_ols)
BR_lav_kst_ols <- exp(signif(BR_lav_lm_ols$coef[[1]], 4))
BR_lav_chi_ols <- signif(BR_lav_lm_ols$coef[[2]], 4)
BR_pred_lav_lm_ols <- exp(predict(BR_lav_lm_ols, newdata = RO_Census_Braila, 
                                  interval = "prediction", level = 0.95))
BR_lav_out_ols <- RO_Census_Braila %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BR_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Braila), 
         DFFIT = dffits(BR_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BR_lav_lm_ols$coefficients) / nrow(RO_Census_Braila)), 
         Rezid_Std = rstudent(BR_lav_lm_ols), Leverage = hatvalues(BR_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BR_lav_lm_ols)), 
         DFBETA = dfbetas(BR_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Braila)))

# e) Data Distributions
RO_Census_Braila %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Braila$Rank, 
                              Population = BR_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(BR_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(BR_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(BR_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Braila$Rank, 
                              Population = BR_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(BR_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(BR_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(BR_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Braila$Rank, 
                              Population = BR_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(BR_ZM_cst_ols, 4), "%.%", "(",
                           signif(BR_ZM_m_ols, 4), "+ x)^", signif(BR_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(summary(BR_ZM_lm_ols)$r.squared, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Braila$Rank, 
                              Population = BR_pred_lav_lm_ols[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(BR_lav_kst_ols, 4), "%.%", "x^",
                           -signif(BR_lav_chi_ols, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(summary(BR_lav_lm_ols)$r.squared, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Braila judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# Linear Regressions
