# 2. Robust

# a) Power Law
BR_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Braila)
summary(BR_pw_lm_rob)
BR_pred_pw_lm_rob <- exp(predict(BR_pw_lm_rob, newdata = RO_Census_Braila, 
                                 interval = "prediction", level = 0.95))
BR_RSquared_pw_rob <- 1 - sum((log(RO_Census_Braila$Population) - fitted(BR_pw_lm_rob))^2) / 
  sum((log(RO_Census_Braila$Population) - mean(log(RO_Census_Braila$Population)))^2)

# b) Zipf_Mandelbrot Law
BR_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Braila, "Population", "Rank")
BR_ZM_m_rob <- BR_ZM_prm_rob$m
BR_ZM_alpha_rob <- BR_ZM_prm_rob$alpha_ZM
BR_ZM_cst_rob <- BR_ZM_prm_rob$constant_ZM
BR_ZM_lm_rob <- rlm(log(RO_Census_Braila$Population) ~ log(RO_Census_Braila$Rank + BR_ZM_m_rob))
summary(BR_ZM_lm_rob)
BR_pred_ZM_lm_rob <- exp(predict(BR_ZM_lm_rob, newdata = RO_Census_Braila, 
                                 interval = "prediction", level = 0.95))
BR_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Braila$Population) - fitted(BR_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Braila$Population) - mean(log(RO_Census_Braila$Population)))^2)

# c) Exponential Law
BR_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Braila)
summary(BR_exp_lm_rob)
BR_pred_exp_lm_rob <- exp(predict(BR_exp_lm_rob, newdata = RO_Census_Braila, 
                                  interval = "prediction", level = 0.95))
BR_RSquared_exp_rob <- 1 - sum((log(RO_Census_Braila$Population) - fitted(BR_exp_lm_rob))^2) / 
  sum((log(RO_Census_Braila$Population) - mean(log(RO_Census_Braila$Population)))^2)

# d) Lavalette Function
RO_Census_Braila <- RO_Census_Braila %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Braila) - Rank + 1))
)
BR_lav_lm_rob <- rlm(log(RO_Census_Braila$Population) ~ RO_Census_Braila$Lav_exp)
summary(BR_lav_lm_rob)
BR_lav_kst_rob <- exp(signif(BR_lav_lm_rob$coef[[1]], 4))
BR_lav_chi_rob <- signif(BR_lav_lm_rob$coef[[2]], 4)
BR_pred_lav_lm_rob <- exp(predict(BR_lav_lm_rob, newdata = RO_Census_Braila, 
                                  interval = "prediction", level = 0.95))
BR_RSquared_lav_rob <- 1 - sum((log(RO_Census_Braila$Population) - fitted(BR_lav_lm_rob))^2) / 
  sum((log(RO_Census_Braila$Population) - mean(log(RO_Census_Braila$Population)))^2)

# e) Data Distributions
RO_Census_Braila %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Braila$Rank, 
                              Population = BR_pred_pw_lm_rob[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 15, y = 120000,
            label = paste0("y", "==", signif(exp(BR_pw_lm_rob$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(BR_pw_lm_rob$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 25, y = 120000,
            label = paste0("R^2 ==", signif(BR_RSquared_pw_rob, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Braila$Rank, 
                              Population = BR_pred_exp_lm_rob[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 15, y = 100000,
            label = paste0("y", "==", signif(exp(BR_exp_lm_rob$coefficients[[1]]), 4), "%.%", 
                           signif(exp(BR_exp_lm_rob$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 25, y = 100000,
            label = paste0("R^2 ==", signif(BR_RSquared_exp_rob, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Braila$Rank, 
                              Population = BR_pred_ZM_lm_rob[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 15, y = 80000,
            label = paste0("y", "==", signif(BR_ZM_cst_rob, 4), "%.%", "(",
                           signif(BR_ZM_m_rob, 4), "+ x)^", signif(BR_ZM_alpha_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 25, y = 80000,
            label = paste0("R^2 ==", signif(BR_RSquared_ZM_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Braila$Rank, 
                              Population = BR_pred_lav_lm_rob[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 15, y = 60000,
            label = paste0("y", "==", signif(BR_lav_kst_rob, 4), "%.%", "x^",
                           -signif(BR_lav_chi_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 25, y = 60000,
            label = paste0("R^2 ==", signif(BR_RSquared_lav_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_y_continuous(labels = scales::label_number(
    big.mark = ",", decimal.mark = ".")) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Braila judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

