             signif(sqrt(mean(((log(BR_rob_hd$Population)) - BR_rob_hd$LAV_Y_Pred) ^ 2)), 4)),
    Data_Part = "Head"
  )),
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(BR_rob_tl$Population) - BR_rob_tl$PW_Y_Pred))), 4), 
            signif(mean(abs((log(BR_rob_tl$Population) - BR_rob_tl$EXP_Y_Pred))), 4),
            signif(mean(abs((log(BR_rob_tl$Population) - BR_rob_tl$ZM_Y_Pred))), 4),
            signif(mean(abs((log(BR_rob_tl$Population) - BR_rob_tl$LAV_Y_Pred))), 4)),
    RMSE = c(signif(sqrt(mean(((log(BR_rob_tl$Population)) - BR_rob_tl$PW_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(BR_rob_tl$Population)) - BR_rob_tl$EXP_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(BR_rob_tl$Population)) - BR_rob_tl$ZM_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(BR_rob_tl$Population)) - BR_rob_tl$LAV_Y_Pred) ^ 2)), 4)),
    Data_Part = "Tail"
  )),
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(BR_rob_bd$Population) - BR_rob_bd$PW_Y_Pred))), 4), 
            signif(mean(abs((log(BR_rob_bd$Population) - BR_rob_bd$EXP_Y_Pred))), 4),
            signif(mean(abs((log(BR_rob_bd$Population) - BR_rob_bd$ZM_Y_Pred))), 4),
            signif(mean(abs((log(BR_rob_bd$Population) - BR_rob_bd$LAV_Y_Pred))), 4)),
    RMSE = c(signif(sqrt(mean(((log(BR_rob_bd$Population)) - BR_rob_bd$PW_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(BR_rob_bd$Population)) - BR_rob_bd$EXP_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(BR_rob_bd$Population)) - BR_rob_bd$ZM_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(BR_rob_bd$Population)) - BR_rob_bd$LAV_Y_Pred) ^ 2)), 4)),
    Data_Part = "Body"
  )),
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(RO_Census_Braila$Population) - 
                               (predict(BR_pw_lm_rob, newdata = RO_Census_Braila, 
                                        interval = "prediction", level = 0.95))))), 4), 
            signif(mean(abs((log(RO_Census_Braila$Population) - 
                               (predict(BR_exp_lm_rob, newdata = RO_Census_Braila, 
                                        interval = "prediction", level = 0.95))))), 4),
            signif(mean(abs((log(RO_Census_Braila$Population) - 
                               (predict(BR_ZM_lm_rob, newdata = RO_Census_Braila, 
                                        interval = "prediction", level = 0.95))))), 4),
            signif(mean(abs((log(RO_Census_Braila$Population) - 
                               (predict(BR_lav_lm_rob, newdata = RO_Census_Braila, 
                                        interval = "prediction", level = 0.95))))), 4)),
    RMSE = c(signif(sqrt(mean(((log(RO_Census_Braila$Population)) - 
                                 (predict(BR_pw_lm_rob, newdata = RO_Census_Braila, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Braila$Population)) - 
                                 (predict(BR_exp_lm_rob, newdata = RO_Census_Braila, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Braila$Population)) - 
                                 (predict(BR_ZM_lm_rob, newdata = RO_Census_Braila, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Braila$Population)) - 
                                 (predict(BR_lav_lm_rob, newdata = RO_Census_Braila, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4)),
    Data_Part = "Full"
  ))
)) %>% mutate(Regression_Type = "Robust", Judet_Name = "BRAILA")

# 3. Compare OLS with Robust
BR_regg_res <- bind_rows(BR_res_ols, BR_res_rob)

# RMSE
BR_regg_res %>% ggplot(aes(Data_Part, RMSE, color = Function_Name, 
                           group = Function_Name)) +
  geom_line(linewidth = 1) + geom_point(size = 3) + 
  facet_wrap(~ Regression_Type) + scale_y_log10() +
  scale_color_manual(
    values = c("Power" = "#ED3F39FF", "Exponential" = "#088BBEFF", 
               "Zipf-Mandelbrot" = "#1B7837FF", "Lavalette" = "#F8A02EFF")) +
  labs(x = "Data Region", y = "RMSE (log scale)") +
  theme(plot.title = element_text(hjust = 0.5))

# MAE
BR_regg_res %>% ggplot(aes(Data_Part, MAE, color = Function_Name, 
                           group = Function_Name)) +
  geom_line(linewidth = 1) + geom_point(size = 3) + 
  facet_wrap(~ Regression_Type) + scale_y_log10() +
  scale_color_manual(
    values = c("Power" = "#ED3F39FF", "Exponential" = "#088BBEFF", 
               "Zipf-Mandelbrot" = "#1B7837FF", "Lavalette" = "#F8A02EFF")) +
  labs(x = "Data Region", y = "MAE (log scale)") +
  theme(plot.title = element_text(hjust = 0.5))

# IX. Brasov

# 1. OLS
RO_Census_Brasov <- RO_Census_rank %>% filter(Judet_Name == "BRASOV")
#View(RO_Census_Brasov)

# a) Power Law
BV_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Brasov)
summary(BV_pw_lm_ols)
BV_pred_pw_lm_ols <- exp(predict(BV_pw_lm_ols, newdata = RO_Census_Brasov, 
                                 interval = "prediction", level = 0.95))
BV_pw_out_ols <- RO_Census_Brasov %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BV_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Brasov), 
         DFFIT = dffits(BV_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BV_pw_lm_ols$coefficients) / nrow(RO_Census_Brasov)), 
         Rezid_Std = rstudent(BV_pw_lm_ols), Leverage = hatvalues(BV_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BV_pw_lm_ols)), 
         DFBETA = dfbetas(BV_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Brasov)))

# b) Zipf_Mandelbrot Law
BV_ZM_prm_ols <- get_ZM_Param("RO_Census_Brasov", "Population", "Rank")
BV_ZM_m_ols <- BV_ZM_prm_ols$m
BV_ZM_alpha_ols <- BV_ZM_prm_ols$alpha_ZM
BV_ZM_cst_ols <- BV_ZM_prm_ols$constant_ZM
BV_ZM_lm_ols <- lm(log(RO_Census_Brasov$Population) ~ log(RO_Census_Brasov$Rank + BV_ZM_m_ols))
summary(BV_ZM_lm_ols)
BV_pred_ZM_lm_ols <- exp(predict(BV_ZM_lm_ols, newdata = RO_Census_Brasov, 
                                 interval = "prediction", level = 0.95))
BV_ZM_out_ols <- RO_Census_Brasov %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BV_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Brasov), 
         DFFIT = dffits(BV_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BV_ZM_lm_ols$coefficients) / nrow(RO_Census_Brasov)), 
         Rezid_Std = rstudent(BV_ZM_lm_ols), Leverage = hatvalues(BV_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BV_ZM_lm_ols)), 
         DFBETA = dfbetas(BV_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Brasov)))

# c) Exponential Law
BV_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Brasov)
summary(BV_exp_lm_ols)
BV_pred_exp_lm_ols <- exp(predict(BV_exp_lm_ols, newdata = RO_Census_Brasov, 
                                  interval = "prediction", level = 0.95))
BV_exp_out_ols <- RO_Census_Brasov %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BV_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Brasov), 
         DFFIT = dffits(BV_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BV_exp_lm_ols$coefficients) / nrow(RO_Census_Brasov)), 
         Rezid_Std = rstudent(BV_exp_lm_ols), Leverage = hatvalues(BV_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BV_exp_lm_ols)), 
         DFBETA = dfbetas(BV_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Brasov)))

# d) Lavalette Function
RO_Census_Brasov <- RO_Census_Brasov %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Brasov) - Rank + 1))
)
BV_lav_lm_ols <- lm(log(RO_Census_Brasov$Population) ~ RO_Census_Brasov$Lav_exp)
summary(BV_lav_lm_ols)
BV_lav_kst_ols <- exp(signif(BV_lav_lm_ols$coef[[1]], 4))
BV_lav_chi_ols <- signif(BV_lav_lm_ols$coef[[2]], 4)
BV_pred_lav_lm_ols <- exp(predict(BV_lav_lm_ols, newdata = RO_Census_Brasov, 
                                  interval = "prediction", level = 0.95))
BV_lav_out_ols <- RO_Census_Brasov %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BV_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Brasov), 
         DFFIT = dffits(BV_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BV_lav_lm_ols$coefficients) / nrow(RO_Census_Brasov)), 
         Rezid_Std = rstudent(BV_lav_lm_ols), Leverage = hatvalues(BV_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BV_lav_lm_ols)), 
         DFBETA = dfbetas(BV_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Brasov)))

# e) Data Distributions
RO_Census_Brasov %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Brasov$Rank, 
                              Population = BV_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(BV_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(BV_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(BV_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Brasov$Rank, 
                              Population = BV_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(BV_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(BV_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(BV_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Brasov$Rank, 
                              Population = BV_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(BV_ZM_cst_ols, 4), "%.%", "(",
                           signif(BV_ZM_m_ols, 4), "+ x)^", signif(BV_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(summary(BV_ZM_lm_ols)$r.squared, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Brasov$Rank, 
                              Population = BV_pred_lav_lm_ols[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(BV_lav_kst_ols, 4), "%.%", "x^",
                           -signif(BV_lav_chi_ols, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(summary(BV_lav_lm_ols)$r.squared, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Brasov judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# Linear Regressions
grid.arrange(
  (RO_Census_Brasov %>%
     ggplot(aes(x = log(Rank), y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = "#ED3F39FF") +
     labs(x = "Rank", y = "Population") +
     ggtitle("Power Linear Regression on Brasov judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  (RO_Census_Brasov %>%
     ggplot(aes(x = Rank, y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = "#088BBEFF") +
     labs(x = "Rank", y = "Population") +
     ggtitle("Exponential Linear Regression on Brasov judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  (RO_Census_Brasov %>%
     ggplot(aes(x = log(Rank + BV_ZM_m_ols), y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = '#1B7837FF') +
     labs(x = "Rank", y = "Population") +
     ggtitle("Zipf-Mandelbrot Linear Regression on Brasov judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  (RO_Census_Brasov %>%
     ggplot(aes(x = Lav_exp, y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = '#F8A02EFF') +
     labs(x = "Rank", y = "Population") +
     ggtitle("Lavalette Linear Regression on Brasov judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  ncol = 2, nrow = 2)

# f) Extract Outliers
Brasov_Outliers <- bind_rows(
  (BV_pw_out_ols %>% mutate(Function_Name = "Power")),
  (BV_ZM_out_ols %>% mutate(Function_Name = "Zipf-Mandelbrot")),
  (BV_exp_out_ols %>% mutate(Function_Name = "Exponential")),
  (BV_lav_out_ols %>% mutate(Function_Name = "Lavalette"))
) %>% mutate(DFBETA_intercept = round(DFBETA[,1], 8), 
             DFBETA_var_x = round(DFBETA[,2], 8)) %>% dplyr::select(-DFBETA)

BV_out <- get_outliers(Brasov_Outliers, RO_Census_Brasov)

BV_out_ols <- RO_Census_Brasov %>% inner_join(
  bind_rows(
    (BV_out$PW %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>% 
       dplyr::select(Rank) %>% distinct()),
    (BV_out$ZM %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (BV_out$LAV %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (BV_out$EXP %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct())
  ) %>% count(Rank) %>% arrange(desc(n)) %>% filter(n >= mean(n))) %>% 
  dplyr::select(-n)

# g) Extract regression metrics
BV_regmet_ols <- as.data.frame(list(Judet_Name = "BRASOV",
                                    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
                                    R_Squared = c(signif(summary(BV_pw_lm_ols)$r.squared, 4), 
                                                  signif(summary(BV_exp_lm_ols)$r.squared, 4),
                                                  signif(summary(BV_ZM_lm_ols)$r.squared, 4),
                                                  signif(summary(BV_lav_lm_ols)$r.squared, 4)),
                                    Adj_R_Squared = c(signif(summary(BV_pw_lm_ols)$adj.r.squared, 4), 
                                                      signif(summary(BV_exp_lm_ols)$adj.r.squared, 4),
                                                      signif(summary(BV_ZM_lm_ols)$adj.r.squared, 4),
                                                      signif(summary(BV_lav_lm_ols)$adj.r.squared, 4)),
                                    AIC = c(signif(AIC(BV_pw_lm_ols), 4), signif(AIC(BV_exp_lm_ols), 4), 
                                            signif(AIC(BV_ZM_lm_ols), 4), signif(AIC(BV_lav_lm_ols), 4)),
                                    BIC = c(signif(BIC(BV_pw_lm_ols), 4), signif(BIC(BV_exp_lm_ols), 4), 
                                            signif(BIC(BV_ZM_lm_ols), 4), signif(BIC(BV_lav_lm_ols), 4)),
                                    MAE = c(signif(mean(abs((log(RO_Census_Brasov$Population) - 
                                                               (predict(BV_pw_lm_ols, newdata = RO_Census_Brasov, 
                                                                        interval = "prediction", level = 0.95))))), 4), 
                                            signif(mean(abs((log(RO_Census_Brasov$Population) - 
                                                               (predict(BV_exp_lm_ols, newdata = RO_Census_Brasov, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Brasov$Population) - 
                                                               (predict(BV_ZM_lm_ols, newdata = RO_Census_Brasov, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Brasov$Population) - 
                                                               (predict(BV_lav_lm_ols, newdata = RO_Census_Brasov, 
                                                                        interval = "prediction", level = 0.95))))), 4)),
                                    RMSE = c(signif(sqrt(mean(((log(RO_Census_Brasov$Population)) - 
                                                                 (predict(BV_pw_lm_ols, newdata = RO_Census_Brasov, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Brasov$Population)) - 
                                                                 (predict(BV_exp_lm_ols, newdata = RO_Census_Brasov, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Brasov$Population)) - 
                                                                 (predict(BV_ZM_lm_ols, newdata = RO_Census_Brasov, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Brasov$Population)) - 
                                                                 (predict(BV_lav_lm_ols, newdata = RO_Census_Brasov, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4))
))

# h) Extract MAE/RMSE on head, body, tail
RO_Census_Brasov_ols <- RO_Census_Brasov %>% 
  mutate(PW_Y_Pred = (predict(BV_pw_lm_ols, newdata = RO_Census_Brasov, 
                              interval = "prediction", level = 0.95))[,1], 
         ZM_Y_Pred = (predict(BV_ZM_lm_ols, newdata = RO_Census_Brasov, 
                              interval = "prediction", level = 0.95))[,1],
         EXP_Y_Pred = (predict(BV_exp_lm_ols, newdata = RO_Census_Brasov, 
                               interval = "prediction", level = 0.95))[,1], 
         LAV_Y_Pred = (predict(BV_lav_lm_ols, newdata = RO_Census_Brasov, 
                               interval = "prediction", level = 0.95))[,1])

# Head
BV_ols_hd <- RO_Census_Brasov_ols %>% filter(Rank <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(BV_ols_hd$Population) - BV_ols_hd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(BV_ols_hd$Population) - BV_ols_hd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(BV_ols_hd$Population) - BV_ols_hd$ZM_Y_Pred))), 4),
          signif(mean(abs((log(BV_ols_hd$Population) - BV_ols_hd$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(BV_ols_hd$Population)) - BV_ols_hd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BV_ols_hd$Population)) - BV_ols_hd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BV_ols_hd$Population)) - BV_ols_hd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BV_ols_hd$Population)) - BV_ols_hd$LAV_Y_Pred) ^ 2)), 4))
))

# Tail
BV_ols_tl <- RO_Census_Brasov_ols %>% arrange(desc(Rank)) %>% 
  filter(row_number() <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(BV_ols_tl$Population) - BV_ols_tl$PW_Y_Pred))), 4), 
          signif(mean(abs((log(BV_ols_tl$Population) - BV_ols_tl$EXP_Y_Pred))), 4),
