             signif(sqrt(mean(((log(BV_rob_bd$Population)) - BV_rob_bd$LAV_Y_Pred) ^ 2)), 4)),
    Data_Part = "Body"
  )),
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(RO_Census_Brasov$Population) - 
                               (predict(BV_pw_lm_rob, newdata = RO_Census_Brasov, 
                                        interval = "prediction", level = 0.95))))), 4), 
            signif(mean(abs((log(RO_Census_Brasov$Population) - 
                               (predict(BV_exp_lm_rob, newdata = RO_Census_Brasov, 
                                        interval = "prediction", level = 0.95))))), 4),
            signif(mean(abs((log(RO_Census_Brasov$Population) - 
                               (predict(BV_ZM_lm_rob, newdata = RO_Census_Brasov, 
                                        interval = "prediction", level = 0.95))))), 4),
            signif(mean(abs((log(RO_Census_Brasov$Population) - 
                               (predict(BV_lav_lm_rob, newdata = RO_Census_Brasov, 
                                        interval = "prediction", level = 0.95))))), 4)),
    RMSE = c(signif(sqrt(mean(((log(RO_Census_Brasov$Population)) - 
                                 (predict(BV_pw_lm_rob, newdata = RO_Census_Brasov, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Brasov$Population)) - 
                                 (predict(BV_exp_lm_rob, newdata = RO_Census_Brasov, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Brasov$Population)) - 
                                 (predict(BV_ZM_lm_rob, newdata = RO_Census_Brasov, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Brasov$Population)) - 
                                 (predict(BV_lav_lm_rob, newdata = RO_Census_Brasov, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4)),
    Data_Part = "Full"
  ))
)) %>% mutate(Regression_Type = "Robust", Judet_Name = "BRASOV")

# 3. Compare OLS with Robust
BV_regg_res <- bind_rows(BV_res_ols, BV_res_rob)

# RMSE
BV_regg_res %>% ggplot(aes(Data_Part, RMSE, color = Function_Name, 
