# MAE
BV_regg_res %>% ggplot(aes(Data_Part, MAE, color = Function_Name, 
                           group = Function_Name)) +
  geom_line(linewidth = 1) + geom_point(size = 3) + 
  facet_wrap(~ Regression_Type) + scale_y_log10() +
  scale_color_manual(
    values = c("Power" = "#ED3F39FF", "Exponential" = "#088BBEFF", 
