# X. Buzau

# 1. OLS
RO_Census_Buzau <- RO_Census_rank %>% filter(Judet_Name == "BUZAU")
#View(RO_Census_Buzau)

# a) Power Law
BZ_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Buzau)
summary(BZ_pw_lm_ols)
BZ_pred_pw_lm_ols <- exp(predict(BZ_pw_lm_ols, newdata = RO_Census_Buzau, 
                                 interval = "prediction", level = 0.95))
BZ_pw_out_ols <- RO_Census_Buzau %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BZ_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Buzau), 
         DFFIT = dffits(BZ_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BZ_pw_lm_ols$coefficients) / nrow(RO_Census_Buzau)), 
         Rezid_Std = rstudent(BZ_pw_lm_ols), Leverage = hatvalues(BZ_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BZ_pw_lm_ols)), 
         DFBETA = dfbetas(BZ_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Buzau)))

# b) Zipf_Mandelbrot Law
BZ_ZM_prm_ols <- get_ZM_Param("RO_Census_Buzau", "Population", "Rank")
BZ_ZM_m_ols <- BZ_ZM_prm_ols$m
BZ_ZM_alpha_ols <- BZ_ZM_prm_ols$alpha_ZM
BZ_ZM_cst_ols <- BZ_ZM_prm_ols$constant_ZM
BZ_ZM_lm_ols <- lm(log(RO_Census_Buzau$Population) ~ log(RO_Census_Buzau$Rank + BZ_ZM_m_ols))
summary(BZ_ZM_lm_ols)
BZ_pred_ZM_lm_ols <- exp(predict(BZ_ZM_lm_ols, newdata = RO_Census_Buzau, 
                                 interval = "prediction", level = 0.95))
BZ_ZM_out_ols <- RO_Census_Buzau %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BZ_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Buzau), 
         DFFIT = dffits(BZ_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BZ_ZM_lm_ols$coefficients) / nrow(RO_Census_Buzau)), 
         Rezid_Std = rstudent(BZ_ZM_lm_ols), Leverage = hatvalues(BZ_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BZ_ZM_lm_ols)), 
         DFBETA = dfbetas(BZ_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Buzau)))

# c) Exponential Law
BZ_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Buzau)
summary(BZ_exp_lm_ols)
BZ_pred_exp_lm_ols <- exp(predict(BZ_exp_lm_ols, newdata = RO_Census_Buzau, 
                                  interval = "prediction", level = 0.95))
BZ_exp_out_ols <- RO_Census_Buzau %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BZ_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Buzau), 
         DFFIT = dffits(BZ_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BZ_exp_lm_ols$coefficients) / nrow(RO_Census_Buzau)), 
         Rezid_Std = rstudent(BZ_exp_lm_ols), Leverage = hatvalues(BZ_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BZ_exp_lm_ols)), 
         DFBETA = dfbetas(BZ_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Buzau)))

# d) Lavalette Function
RO_Census_Buzau <- RO_Census_Buzau %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Buzau) - Rank + 1))
)
BZ_lav_lm_ols <- lm(log(RO_Census_Buzau$Population) ~ RO_Census_Buzau$Lav_exp)
summary(BZ_lav_lm_ols)
BZ_lav_kst_ols <- exp(signif(BZ_lav_lm_ols$coef[[1]], 4))
BZ_lav_chi_ols <- signif(BZ_lav_lm_ols$coef[[2]], 4)
BZ_pred_lav_lm_ols <- exp(predict(BZ_lav_lm_ols, newdata = RO_Census_Buzau, 
                                  interval = "prediction", level = 0.95))
BZ_lav_out_ols <- RO_Census_Buzau %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(BZ_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Buzau), 
         DFFIT = dffits(BZ_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(BZ_lav_lm_ols$coefficients) / nrow(RO_Census_Buzau)), 
         Rezid_Std = rstudent(BZ_lav_lm_ols), Leverage = hatvalues(BZ_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(BZ_lav_lm_ols)), 
         DFBETA = dfbetas(BZ_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Buzau)))

# e) Data Distributions
RO_Census_Buzau %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Buzau$Rank, 
                              Population = BZ_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(BZ_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(BZ_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(BZ_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Buzau$Rank, 
                              Population = BZ_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(BZ_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(BZ_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(BZ_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Buzau$Rank, 
                              Population = BZ_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(BZ_ZM_cst_ols, 4), "%.%", "(",
                           signif(BZ_ZM_m_ols, 4), "+ x)^", signif(BZ_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(summary(BZ_ZM_lm_ols)$r.squared, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Buzau$Rank, 
                              Population = BZ_pred_lav_lm_ols[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(BZ_lav_kst_ols, 4), "%.%", "x^",
                           -signif(BZ_lav_chi_ols, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(summary(BZ_lav_lm_ols)$r.squared, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Buzau judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# Linear Regressions
grid.arrange(
  (RO_Census_Buzau %>%
     ggplot(aes(x = log(Rank), y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
