  ncol = 2, nrow = 2)

# f) Extract Outliers
Buzau_Outliers <- bind_rows(
  (BZ_pw_out_ols %>% mutate(Function_Name = "Power")),
  (BZ_ZM_out_ols %>% mutate(Function_Name = "Zipf-Mandelbrot")),
  (BZ_exp_out_ols %>% mutate(Function_Name = "Exponential")),
  (BZ_lav_out_ols %>% mutate(Function_Name = "Lavalette"))
) %>% mutate(DFBETA_intercept = round(DFBETA[,1], 8), 
             DFBETA_var_x = round(DFBETA[,2], 8)) %>% dplyr::select(-DFBETA)

BZ_out <- get_outliers(Buzau_Outliers, RO_Census_Buzau)

BZ_out_ols <- RO_Census_Buzau %>% inner_join(
  bind_rows(
    (BZ_out$PW %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>% 
       dplyr::select(Rank) %>% distinct()),
    (BZ_out$ZM %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (BZ_out$LAV %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (BZ_out$EXP %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct())
  ) %>% count(Rank) %>% arrange(desc(n)) %>% filter(n >= mean(n))) %>% 
  dplyr::select(-n)

# g) Extract regression metrics
BZ_regmet_ols <- as.data.frame(list(Judet_Name = "BUZAU",
                                    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
