                                                  signif(summary(BZ_ZM_lm_ols)$r.squared, 4),
                                                  signif(summary(BZ_lav_lm_ols)$r.squared, 4)),
                                    Adj_R_Squared = c(signif(summary(BZ_pw_lm_ols)$adj.r.squared, 4), 
                                                      signif(summary(BZ_exp_lm_ols)$adj.r.squared, 4),
                                                      signif(summary(BZ_ZM_lm_ols)$adj.r.squared, 4),
                                                      signif(summary(BZ_lav_lm_ols)$adj.r.squared, 4)),
                                    AIC = c(signif(AIC(BZ_pw_lm_ols), 4), signif(AIC(BZ_exp_lm_ols), 4), 
                                            signif(AIC(BZ_ZM_lm_ols), 4), signif(AIC(BZ_lav_lm_ols), 4)),
