                                            signif(BIC(BZ_ZM_lm_ols), 4), signif(BIC(BZ_lav_lm_ols), 4)),
                                    MAE = c(signif(mean(abs((log(RO_Census_Buzau$Population) - 
                                                               (predict(BZ_pw_lm_ols, newdata = RO_Census_Buzau, 
                                                                        interval = "prediction", level = 0.95))))), 4), 
                                            signif(mean(abs((log(RO_Census_Buzau$Population) - 
                                                               (predict(BZ_exp_lm_ols, newdata = RO_Census_Buzau, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Buzau$Population) - 
                                                               (predict(BZ_ZM_lm_ols, newdata = RO_Census_Buzau, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Buzau$Population) - 
                                                               (predict(BZ_lav_lm_ols, newdata = RO_Census_Buzau, 
                                                                        interval = "prediction", level = 0.95))))), 4)),
                                    RMSE = c(signif(sqrt(mean(((log(RO_Census_Buzau$Population)) - 
                                                                 (predict(BZ_pw_lm_ols, newdata = RO_Census_Buzau, 
