                                             signif(sqrt(mean(((log(RO_Census_Buzau$Population)) - 
                                                                 (predict(BZ_exp_lm_ols, newdata = RO_Census_Buzau, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
