                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4))
))

# h) Extract MAE/RMSE on head, body, tail
RO_Census_Buzau_ols <- RO_Census_Buzau %>% 
  mutate(PW_Y_Pred = (predict(BZ_pw_lm_ols, newdata = RO_Census_Buzau, 
                              interval = "prediction", level = 0.95))[,1], 
         ZM_Y_Pred = (predict(BZ_ZM_lm_ols, newdata = RO_Census_Buzau, 
                              interval = "prediction", level = 0.95))[,1],
         EXP_Y_Pred = (predict(BZ_exp_lm_ols, newdata = RO_Census_Buzau, 
                               interval = "prediction", level = 0.95))[,1], 
         LAV_Y_Pred = (predict(BZ_lav_lm_ols, newdata = RO_Census_Buzau, 
                               interval = "prediction", level = 0.95))[,1])

# Head
BZ_ols_hd <- RO_Census_Buzau_ols %>% filter(Rank <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(BZ_ols_hd$Population) - BZ_ols_hd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(BZ_ols_hd$Population) - BZ_ols_hd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(BZ_ols_hd$Population) - BZ_ols_hd$ZM_Y_Pred))), 4),
          signif(mean(abs((log(BZ_ols_hd$Population) - BZ_ols_hd$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(BZ_ols_hd$Population)) - BZ_ols_hd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BZ_ols_hd$Population)) - BZ_ols_hd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BZ_ols_hd$Population)) - BZ_ols_hd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BZ_ols_hd$Population)) - BZ_ols_hd$LAV_Y_Pred) ^ 2)), 4))
))

# Tail
BZ_ols_tl <- RO_Census_Buzau_ols %>% arrange(desc(Rank)) %>% 
  filter(row_number() <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(BZ_ols_tl$Population) - BZ_ols_tl$PW_Y_Pred))), 4), 
          signif(mean(abs((log(BZ_ols_tl$Population) - BZ_ols_tl$EXP_Y_Pred))), 4),
          signif(mean(abs((log(BZ_ols_tl$Population) - BZ_ols_tl$ZM_Y_Pred))), 4),
          signif(mean(abs((log(BZ_ols_tl$Population) - BZ_ols_tl$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(BZ_ols_tl$Population)) - BZ_ols_tl$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BZ_ols_tl$Population)) - BZ_ols_tl$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BZ_ols_tl$Population)) - BZ_ols_tl$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BZ_ols_tl$Population)) - BZ_ols_tl$LAV_Y_Pred) ^ 2)), 4))
))

# Body
BZ_ols_bd <- RO_Census_Buzau_ols %>% anti_join(BZ_ols_hd) %>% anti_join(BZ_ols_tl)

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(BZ_ols_bd$Population) - BZ_ols_bd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(BZ_ols_bd$Population) - BZ_ols_bd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(BZ_ols_bd$Population) - BZ_ols_bd$ZM_Y_Pred))), 4),
          signif(mean(abs((log(BZ_ols_bd$Population) - BZ_ols_bd$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(BZ_ols_bd$Population)) - BZ_ols_bd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BZ_ols_bd$Population)) - BZ_ols_bd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BZ_ols_bd$Population)) - BZ_ols_bd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(BZ_ols_bd$Population)) - BZ_ols_bd$LAV_Y_Pred) ^ 2)), 4))
))

# Final
BZ_res_ols <- as.data.frame(bind_rows(
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
