# 2. Robust

# a) Power Law
BZ_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Buzau)
summary(BZ_pw_lm_rob)
BZ_pred_pw_lm_rob <- exp(predict(BZ_pw_lm_rob, newdata = RO_Census_Buzau, 
                                 interval = "prediction", level = 0.95))
BZ_RSquared_pw_rob <- 1 - sum((log(RO_Census_Buzau$Population) - fitted(BZ_pw_lm_rob))^2) / 
  sum((log(RO_Census_Buzau$Population) - mean(log(RO_Census_Buzau$Population)))^2)

# b) Zipf_Mandelbrot Law
BZ_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Buzau, "Population", "Rank")
BZ_ZM_m_rob <- BZ_ZM_prm_rob$m
BZ_ZM_alpha_rob <- BZ_ZM_prm_rob$alpha_ZM
BZ_ZM_cst_rob <- BZ_ZM_prm_rob$constant_ZM
BZ_ZM_lm_rob <- rlm(log(RO_Census_Buzau$Population) ~ log(RO_Census_Buzau$Rank + BZ_ZM_m_rob))
summary(BZ_ZM_lm_rob)
BZ_pred_ZM_lm_rob <- exp(predict(BZ_ZM_lm_rob, newdata = RO_Census_Buzau, 
                                 interval = "prediction", level = 0.95))
BZ_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Buzau$Population) - fitted(BZ_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Buzau$Population) - mean(log(RO_Census_Buzau$Population)))^2)

# c) Exponential Law
BZ_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Buzau)
summary(BZ_exp_lm_rob)
BZ_pred_exp_lm_rob <- exp(predict(BZ_exp_lm_rob, newdata = RO_Census_Buzau, 
                                  interval = "prediction", level = 0.95))
BZ_RSquared_exp_rob <- 1 - sum((log(RO_Census_Buzau$Population) - fitted(BZ_exp_lm_rob))^2) / 
  sum((log(RO_Census_Buzau$Population) - mean(log(RO_Census_Buzau$Population)))^2)

# d) Lavalette Function
RO_Census_Buzau <- RO_Census_Buzau %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Buzau) - Rank + 1))
)
BZ_lav_lm_rob <- rlm(log(RO_Census_Buzau$Population) ~ RO_Census_Buzau$Lav_exp)
summary(BZ_lav_lm_rob)
BZ_lav_kst_rob <- exp(signif(BZ_lav_lm_rob$coef[[1]], 4))
BZ_lav_chi_rob <- signif(BZ_lav_lm_rob$coef[[2]], 4)
BZ_pred_lav_lm_rob <- exp(predict(BZ_lav_lm_rob, newdata = RO_Census_Buzau, 
                                  interval = "prediction", level = 0.95))
BZ_RSquared_lav_rob <- 1 - sum((log(RO_Census_Buzau$Population) - fitted(BZ_lav_lm_rob))^2) / 
  sum((log(RO_Census_Buzau$Population) - mean(log(RO_Census_Buzau$Population)))^2)

# e) Data Distributions
RO_Census_Buzau %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Buzau$Rank, 
                              Population = BZ_pred_pw_lm_rob[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(BZ_pw_lm_rob$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(BZ_pw_lm_rob$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(BZ_RSquared_pw_rob, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Buzau$Rank, 
                              Population = BZ_pred_exp_lm_rob[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(BZ_exp_lm_rob$coefficients[[1]]), 4), "%.%", 
                           signif(exp(BZ_exp_lm_rob$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(BZ_RSquared_exp_rob, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Buzau$Rank, 
                              Population = BZ_pred_ZM_lm_rob[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(BZ_ZM_cst_rob, 4), "%.%", "(",
                           signif(BZ_ZM_m_rob, 4), "+ x)^", signif(BZ_ZM_alpha_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(BZ_RSquared_ZM_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Buzau$Rank, 
                              Population = BZ_pred_lav_lm_rob[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(BZ_lav_kst_rob, 4), "%.%", "x^",
                           -signif(BZ_lav_chi_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(BZ_RSquared_lav_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Buzau judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# f) Extract regression metrics
BZ_regmet_rob <- as.data.frame(list(Judet_Name = "BUZAU",
                                    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
