# Extract weight
BZ_out_weights <- bind_rows(
  (RO_Census_Buzau %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>% 
     mutate(Robust_Weight = BZ_pw_lm_rob$w, Function_Name = "Power")),
  (RO_Census_Buzau %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = BZ_ZM_lm_rob$w, Function_Name = "Zipf-Mandelbrot")),
  (RO_Census_Buzau %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = BZ_exp_lm_rob$w, Function_Name = "Exponential")),
  (RO_Census_Buzau %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = BZ_lav_lm_rob$w, Function_Name = "Lavalette"))) %>% 
  inner_join(BZ_out_ols) %>% 
  dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank, Robust_Weight, Function_Name) %>%
  mutate(Judet_Name = "BUZAU")

# g) Extract MAE/RMSE on head, body, tail
RO_Census_Buzau_rob <- RO_Census_Buzau %>% 
  mutate(PW_Y_Pred = (predict(BZ_pw_lm_rob, newdata = RO_Census_Buzau, 
                              interval = "prediction", level = 0.95))[,1], 
