# XI. Caras-Severin

# 1. OLS
RO_Census_CarSev <- RO_Census_rank %>% filter(Judet_Name == "CARAS-SEVERIN")
#View(RO_Census_CarSev)

# a) Power Law
CS_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_CarSev)
summary(CS_pw_lm_ols)
CS_pred_pw_lm_ols <- exp(predict(CS_pw_lm_ols, newdata = RO_Census_CarSev, 
                                 interval = "prediction", level = 0.95))
CS_pw_out_ols <- RO_Census_CarSev %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(CS_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_CarSev), 
         DFFIT = dffits(CS_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(CS_pw_lm_ols$coefficients) / nrow(RO_Census_CarSev)), 
         Rezid_Std = rstudent(CS_pw_lm_ols), Leverage = hatvalues(CS_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(CS_pw_lm_ols)), 
         DFBETA = dfbetas(CS_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_CarSev)))

# b) Zipf_Mandelbrot Law
CS_ZM_prm_ols <- get_ZM_Param("RO_Census_CarSev", "Population", "Rank")
CS_ZM_m_ols <- CS_ZM_prm_ols$m
CS_ZM_alpha_ols <- CS_ZM_prm_ols$alpha_ZM
CS_ZM_cst_ols <- CS_ZM_prm_ols$constant_ZM
CS_ZM_lm_ols <- lm(log(RO_Census_CarSev$Population) ~ log(RO_Census_CarSev$Rank + CS_ZM_m_ols))
summary(CS_ZM_lm_ols)
CS_pred_ZM_lm_ols <- exp(predict(CS_ZM_lm_ols, newdata = RO_Census_CarSev, 
                                 interval = "prediction", level = 0.95))
CS_ZM_out_ols <- RO_Census_CarSev %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(CS_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_CarSev), 
         DFFIT = dffits(CS_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(CS_ZM_lm_ols$coefficients) / nrow(RO_Census_CarSev)), 
         Rezid_Std = rstudent(CS_ZM_lm_ols), Leverage = hatvalues(CS_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(CS_ZM_lm_ols)), 
         DFBETA = dfbetas(CS_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_CarSev)))

# c) Exponential Law
CS_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_CarSev)
summary(CS_exp_lm_ols)
CS_pred_exp_lm_ols <- exp(predict(CS_exp_lm_ols, newdata = RO_Census_CarSev, 
                                  interval = "prediction", level = 0.95))
CS_exp_out_ols <- RO_Census_CarSev %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(CS_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_CarSev), 
         DFFIT = dffits(CS_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(CS_exp_lm_ols$coefficients) / nrow(RO_Census_CarSev)), 
         Rezid_Std = rstudent(CS_exp_lm_ols), Leverage = hatvalues(CS_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(CS_exp_lm_ols)), 
         DFBETA = dfbetas(CS_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_CarSev)))

# d) Lavalette Function
RO_Census_CarSev <- RO_Census_CarSev %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_CarSev) - Rank + 1))
)
CS_lav_lm_ols <- lm(log(RO_Census_CarSev$Population) ~ RO_Census_CarSev$Lav_exp)
summary(CS_lav_lm_ols)
CS_lav_kst_ols <- exp(signif(CS_lav_lm_ols$coef[[1]], 4))
CS_lav_chi_ols <- signif(CS_lav_lm_ols$coef[[2]], 4)
CS_pred_lav_lm_ols <- exp(predict(CS_lav_lm_ols, newdata = RO_Census_CarSev, 
                                  interval = "prediction", level = 0.95))
CS_lav_out_ols <- RO_Census_CarSev %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(CS_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_CarSev), 
         DFFIT = dffits(CS_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(CS_lav_lm_ols$coefficients) / nrow(RO_Census_CarSev)), 
         Rezid_Std = rstudent(CS_lav_lm_ols), Leverage = hatvalues(CS_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(CS_lav_lm_ols)), 
         DFBETA = dfbetas(CS_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_CarSev)))

# e) Data Distributions
RO_Census_CarSev %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_CarSev$Rank, 
                              Population = CS_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(CS_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(CS_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(CS_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_CarSev$Rank, 
                              Population = CS_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(CS_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(CS_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(CS_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_CarSev$Rank, 
                              Population = CS_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(CS_ZM_cst_ols, 4), "%.%", "(",
                           signif(CS_ZM_m_ols, 4), "+ x)^", signif(CS_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(summary(CS_ZM_lm_ols)$r.squared, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_CarSev$Rank, 
                              Population = CS_pred_lav_lm_ols[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(CS_lav_kst_ols, 4), "%.%", "x^",
                           -signif(CS_lav_chi_ols, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(summary(CS_lav_lm_ols)$r.squared, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on CarSev judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# Linear Regressions
grid.arrange(
