# f) Extract Outliers
CarSev_Outliers <- bind_rows(
  (CS_pw_out_ols %>% mutate(Function_Name = "Power")),
  (CS_ZM_out_ols %>% mutate(Function_Name = "Zipf-Mandelbrot")),
  (CS_exp_out_ols %>% mutate(Function_Name = "Exponential")),
  (CS_lav_out_ols %>% mutate(Function_Name = "Lavalette"))
) %>% mutate(DFBETA_intercept = round(DFBETA[,1], 8), 
             DFBETA_var_x = round(DFBETA[,2], 8)) %>% dplyr::select(-DFBETA)

CS_out <- get_outliers(CarSev_Outliers, RO_Census_CarSev)

CS_out_ols <- RO_Census_CarSev %>% inner_join(
  bind_rows(
    (CS_out$PW %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>% 
       dplyr::select(Rank) %>% distinct()),
    (CS_out$ZM %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (CS_out$LAV %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (CS_out$EXP %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct())
  ) %>% count(Rank) %>% arrange(desc(n)) %>% filter(n >= mean(n))) %>% 
  dplyr::select(-n)

# g) Extract regression metrics
CS_regmet_ols <- as.data.frame(list(Judet_Name = "CARAS-SEVERIN",
