                                                  signif(summary(CS_lav_lm_ols)$r.squared, 4)),
                                    Adj_R_Squared = c(signif(summary(CS_pw_lm_ols)$adj.r.squared, 4), 
                                                      signif(summary(CS_exp_lm_ols)$adj.r.squared, 4),
                                                      signif(summary(CS_ZM_lm_ols)$adj.r.squared, 4),
                                                      signif(summary(CS_lav_lm_ols)$adj.r.squared, 4)),
                                    AIC = c(signif(AIC(CS_pw_lm_ols), 4), signif(AIC(CS_exp_lm_ols), 4), 
                                            signif(AIC(CS_ZM_lm_ols), 4), signif(AIC(CS_lav_lm_ols), 4)),
                                    BIC = c(signif(BIC(CS_pw_lm_ols), 4), signif(BIC(CS_exp_lm_ols), 4), 
                                            signif(BIC(CS_ZM_lm_ols), 4), signif(BIC(CS_lav_lm_ols), 4)),
                                    MAE = c(signif(mean(abs((log(RO_Census_CarSev$Population) - 
                                                               (predict(CS_pw_lm_ols, newdata = RO_Census_CarSev, 
                                                                        interval = "prediction", level = 0.95))))), 4), 
                                            signif(mean(abs((log(RO_Census_CarSev$Population) - 
                                                               (predict(CS_exp_lm_ols, newdata = RO_Census_CarSev, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_CarSev$Population) - 
                                                               (predict(CS_ZM_lm_ols, newdata = RO_Census_CarSev, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_CarSev$Population) - 
                                                               (predict(CS_lav_lm_ols, newdata = RO_Census_CarSev, 
                                                                        interval = "prediction", level = 0.95))))), 4)),
                                    RMSE = c(signif(sqrt(mean(((log(RO_Census_CarSev$Population)) - 
                                                                 (predict(CS_pw_lm_ols, newdata = RO_Census_CarSev, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_CarSev$Population)) - 
                                                                 (predict(CS_exp_lm_ols, newdata = RO_Census_CarSev, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
