))

# h) Extract MAE/RMSE on head, body, tail
RO_Census_CarSev_ols <- RO_Census_CarSev %>% 
  mutate(PW_Y_Pred = (predict(CS_pw_lm_ols, newdata = RO_Census_CarSev, 
                              interval = "prediction", level = 0.95))[,1], 
         ZM_Y_Pred = (predict(CS_ZM_lm_ols, newdata = RO_Census_CarSev, 
                              interval = "prediction", level = 0.95))[,1],
         EXP_Y_Pred = (predict(CS_exp_lm_ols, newdata = RO_Census_CarSev, 
                               interval = "prediction", level = 0.95))[,1], 
         LAV_Y_Pred = (predict(CS_lav_lm_ols, newdata = RO_Census_CarSev, 
                               interval = "prediction", level = 0.95))[,1])

# Head
CS_ols_hd <- RO_Census_CarSev_ols %>% filter(Rank <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(CS_ols_hd$Population) - CS_ols_hd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(CS_ols_hd$Population) - CS_ols_hd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(CS_ols_hd$Population) - CS_ols_hd$ZM_Y_Pred))), 4),
          signif(mean(abs((log(CS_ols_hd$Population) - CS_ols_hd$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(CS_ols_hd$Population)) - CS_ols_hd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(CS_ols_hd$Population)) - CS_ols_hd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(CS_ols_hd$Population)) - CS_ols_hd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(CS_ols_hd$Population)) - CS_ols_hd$LAV_Y_Pred) ^ 2)), 4))
))

# Tail
CS_ols_tl <- RO_Census_CarSev_ols %>% arrange(desc(Rank)) %>% 
  filter(row_number() <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
