            signif(mean(abs((log(CS_ols_tl$Population) - CS_ols_tl$EXP_Y_Pred))), 4),
            signif(mean(abs((log(CS_ols_tl$Population) - CS_ols_tl$ZM_Y_Pred))), 4),
            signif(mean(abs((log(CS_ols_tl$Population) - CS_ols_tl$LAV_Y_Pred))), 4)),
    RMSE = c(signif(sqrt(mean(((log(CS_ols_tl$Population)) - CS_ols_tl$PW_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(CS_ols_tl$Population)) - CS_ols_tl$EXP_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(CS_ols_tl$Population)) - CS_ols_tl$ZM_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(CS_ols_tl$Population)) - CS_ols_tl$LAV_Y_Pred) ^ 2)), 4)),
    Data_Part = "Tail"
  )),
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(CS_ols_bd$Population) - CS_ols_bd$PW_Y_Pred))), 4), 
            signif(mean(abs((log(CS_ols_bd$Population) - CS_ols_bd$EXP_Y_Pred))), 4),
            signif(mean(abs((log(CS_ols_bd$Population) - CS_ols_bd$ZM_Y_Pred))), 4),
            signif(mean(abs((log(CS_ols_bd$Population) - CS_ols_bd$LAV_Y_Pred))), 4)),
    RMSE = c(signif(sqrt(mean(((log(CS_ols_bd$Population)) - CS_ols_bd$PW_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(CS_ols_bd$Population)) - CS_ols_bd$EXP_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(CS_ols_bd$Population)) - CS_ols_bd$ZM_Y_Pred) ^ 2)), 4),
