  ))
)) %>% mutate(Regression_Type = "OLS", Judet_Name = "CARAS-SEVERIN")

# 2. Robust

# a) Power Law
CS_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_CarSev)
summary(CS_pw_lm_rob)
CS_pred_pw_lm_rob <- exp(predict(CS_pw_lm_rob, newdata = RO_Census_CarSev, 
                                 interval = "prediction", level = 0.95))
CS_RSquared_pw_rob <- 1 - sum((log(RO_Census_CarSev$Population) - fitted(CS_pw_lm_rob))^2) / 
  sum((log(RO_Census_CarSev$Population) - mean(log(RO_Census_CarSev$Population)))^2)

# b) Zipf_Mandelbrot Law
CS_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_CarSev, "Population", "Rank")
CS_ZM_m_rob <- CS_ZM_prm_rob$m
CS_ZM_alpha_rob <- CS_ZM_prm_rob$alpha_ZM
CS_ZM_cst_rob <- CS_ZM_prm_rob$constant_ZM
CS_ZM_lm_rob <- rlm(log(RO_Census_CarSev$Population) ~ log(RO_Census_CarSev$Rank + CS_ZM_m_rob))
summary(CS_ZM_lm_rob)
CS_pred_ZM_lm_rob <- exp(predict(CS_ZM_lm_rob, newdata = RO_Census_CarSev, 
                                 interval = "prediction", level = 0.95))
CS_RSquared_ZM_rob <- 1 - sum((log(RO_Census_CarSev$Population) - fitted(CS_ZM_lm_rob))^2) / 
  sum((log(RO_Census_CarSev$Population) - mean(log(RO_Census_CarSev$Population)))^2)

# c) Exponential Law
CS_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_CarSev)
summary(CS_exp_lm_rob)
CS_pred_exp_lm_rob <- exp(predict(CS_exp_lm_rob, newdata = RO_Census_CarSev, 
                                  interval = "prediction", level = 0.95))
CS_RSquared_exp_rob <- 1 - sum((log(RO_Census_CarSev$Population) - fitted(CS_exp_lm_rob))^2) / 
  sum((log(RO_Census_CarSev$Population) - mean(log(RO_Census_CarSev$Population)))^2)

# d) Lavalette Function
RO_Census_CarSev <- RO_Census_CarSev %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_CarSev) - Rank + 1))
)
CS_lav_lm_rob <- rlm(log(RO_Census_CarSev$Population) ~ RO_Census_CarSev$Lav_exp)
summary(CS_lav_lm_rob)
CS_lav_kst_rob <- exp(signif(CS_lav_lm_rob$coef[[1]], 4))
CS_lav_chi_rob <- signif(CS_lav_lm_rob$coef[[2]], 4)
CS_pred_lav_lm_rob <- exp(predict(CS_lav_lm_rob, newdata = RO_Census_CarSev, 
                                  interval = "prediction", level = 0.95))
CS_RSquared_lav_rob <- 1 - sum((log(RO_Census_CarSev$Population) - fitted(CS_lav_lm_rob))^2) / 
  sum((log(RO_Census_CarSev$Population) - mean(log(RO_Census_CarSev$Population)))^2)

# e) Data Distributions
RO_Census_CarSev %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_CarSev$Rank, 
                              Population = CS_pred_pw_lm_rob[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(CS_pw_lm_rob$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(CS_pw_lm_rob$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(CS_RSquared_pw_rob, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_CarSev$Rank, 
                              Population = CS_pred_exp_lm_rob[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(CS_exp_lm_rob$coefficients[[1]]), 4), "%.%", 
                           signif(exp(CS_exp_lm_rob$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(CS_RSquared_exp_rob, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_CarSev$Rank, 
                              Population = CS_pred_ZM_lm_rob[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(CS_ZM_cst_rob, 4), "%.%", "(",
                           signif(CS_ZM_m_rob, 4), "+ x)^", signif(CS_ZM_alpha_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(CS_RSquared_ZM_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_CarSev$Rank, 
                              Population = CS_pred_lav_lm_rob[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(CS_lav_kst_rob, 4), "%.%", "x^",
                           -signif(CS_lav_chi_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(CS_RSquared_lav_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on CarSev judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# f) Extract regression metrics
CS_regmet_rob <- as.data.frame(list(Judet_Name = "CARAS-SEVERIN",
                                    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
                                    R_Squared = c(signif(CS_RSquared_pw_rob, 4), 
                                                  signif(CS_RSquared_exp_rob, 4),
                                                  signif(CS_RSquared_ZM_rob, 4),
                                                  signif(CS_RSquared_lav_rob, 4)),
                                    AIC = c(signif(AIC(CS_pw_lm_rob), 4), signif(AIC(CS_exp_lm_rob), 4), 
                                            signif(AIC(CS_ZM_lm_rob), 4), signif(AIC(CS_lav_lm_rob), 4)),
                                    BIC = c(signif(BIC(CS_pw_lm_rob), 4), signif(BIC(CS_exp_lm_rob), 4), 
                                            signif(BIC(CS_ZM_lm_rob), 4), signif(BIC(CS_lav_lm_rob), 4)),
                                    MAE = c(signif(mean(abs((log(RO_Census_CarSev$Population) - 
                                                               (predict(CS_pw_lm_rob, newdata = RO_Census_CarSev, 
                                                                        interval = "prediction", level = 0.95))))), 4), 
                                            signif(mean(abs((log(RO_Census_CarSev$Population) - 
                                                               (predict(CS_exp_lm_rob, newdata = RO_Census_CarSev, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_CarSev$Population) - 
                                                               (predict(CS_ZM_lm_rob, newdata = RO_Census_CarSev, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_CarSev$Population) - 
                                                               (predict(CS_lav_lm_rob, newdata = RO_Census_CarSev, 
                                                                        interval = "prediction", level = 0.95))))), 4)),
                                    RMSE = c(signif(sqrt(mean(((log(RO_Census_CarSev$Population)) - 
                                                                 (predict(CS_pw_lm_rob, newdata = RO_Census_CarSev, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_CarSev$Population)) - 
                                                                 (predict(CS_exp_lm_rob, newdata = RO_Census_CarSev, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_CarSev$Population)) - 
                                                                 (predict(CS_ZM_lm_rob, newdata = RO_Census_CarSev, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_CarSev$Population)) - 
                                                                 (predict(CS_lav_lm_rob, newdata = RO_Census_CarSev, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4))
))

# Extract weight
CS_out_weights <- bind_rows(
  (RO_Census_CarSev %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>% 
     mutate(Robust_Weight = CS_pw_lm_rob$w, Function_Name = "Power")),
  (RO_Census_CarSev %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = CS_ZM_lm_rob$w, Function_Name = "Zipf-Mandelbrot")),
  (RO_Census_CarSev %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = CS_exp_lm_rob$w, Function_Name = "Exponential")),
  (RO_Census_CarSev %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = CS_lav_lm_rob$w, Function_Name = "Lavalette"))) %>% 
  inner_join(CS_out_ols) %>% 
  dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank, Robust_Weight, Function_Name) %>%
  mutate(Judet_Name = "CARAS-SEVERIN")

# g) Extract MAE/RMSE on head, body, tail
RO_Census_CarSev_rob <- RO_Census_CarSev %>% 
  mutate(PW_Y_Pred = (predict(CS_pw_lm_rob, newdata = RO_Census_CarSev, 
                              interval = "prediction", level = 0.95))[,1], 
         ZM_Y_Pred = (predict(CS_ZM_lm_rob, newdata = RO_Census_CarSev, 
                              interval = "prediction", level = 0.95))[,1],
         EXP_Y_Pred = (predict(CS_exp_lm_rob, newdata = RO_Census_CarSev, 
                               interval = "prediction", level = 0.95))[,1], 
         LAV_Y_Pred = (predict(CS_lav_lm_rob, newdata = RO_Census_CarSev, 
                               interval = "prediction", level = 0.95))[,1])

# Head
CS_rob_hd <- RO_Census_CarSev_rob %>% filter(Rank <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(CS_rob_hd$Population) - CS_rob_hd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(CS_rob_hd$Population) - CS_rob_hd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(CS_rob_hd$Population) - CS_rob_hd$ZM_Y_Pred))), 4),
          signif(mean(abs((log(CS_rob_hd$Population) - CS_rob_hd$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(CS_rob_hd$Population)) - CS_rob_hd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(CS_rob_hd$Population)) - CS_rob_hd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(CS_rob_hd$Population)) - CS_rob_hd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(CS_rob_hd$Population)) - CS_rob_hd$LAV_Y_Pred) ^ 2)), 4))
))

# Tail
CS_rob_tl <- RO_Census_CarSev_rob %>% arrange(desc(Rank)) %>% 
  filter(row_number() <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(CS_rob_tl$Population) - CS_rob_tl$PW_Y_Pred))), 4), 
          signif(mean(abs((log(CS_rob_tl$Population) - CS_rob_tl$EXP_Y_Pred))), 4),
          signif(mean(abs((log(CS_rob_tl$Population) - CS_rob_tl$ZM_Y_Pred))), 4),
          signif(mean(abs((log(CS_rob_tl$Population) - CS_rob_tl$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(CS_rob_tl$Population)) - CS_rob_tl$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(CS_rob_tl$Population)) - CS_rob_tl$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(CS_rob_tl$Population)) - CS_rob_tl$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(CS_rob_tl$Population)) - CS_rob_tl$LAV_Y_Pred) ^ 2)), 4))
))

# Body
CS_rob_bd <- RO_Census_CarSev_rob %>% anti_join(CS_rob_hd) %>% anti_join(CS_rob_tl)

as.data.frame(list(
