  facet_wrap(~ Regression_Type) + scale_y_log10() +
  scale_color_manual(
    values = c("Power" = "#ED3F39FF", "Exponential" = "#088BBEFF", 
               "Zipf-Mandelbrot" = "#1B7837FF", "Lavalette" = "#F8A02EFF")) +
  labs(x = "Data Region", y = "RMSE (log scale)") +
  theme(plot.title = element_text(hjust = 0.5))

# MAE
CS_regg_res %>% ggplot(aes(Data_Part, MAE, color = Function_Name, 
                           group = Function_Name)) +
  geom_line(linewidth = 1) + geom_point(size = 3) + 
  facet_wrap(~ Regression_Type) + scale_y_log10() +
  scale_color_manual(
    values = c("Power" = "#ED3F39FF", "Exponential" = "#088BBEFF", 
               "Zipf-Mandelbrot" = "#1B7837FF", "Lavalette" = "#F8A02EFF")) +
  labs(x = "Data Region", y = "MAE (log scale)") +
  theme(plot.title = element_text(hjust = 0.5))

# XII. Calarasi

# 1. OLS
RO_Census_Calarasi <- RO_Census_rank %>% filter(Judet_Name == "CALARASI")
#View(RO_Census_Calarasi)

# a) Power Law
CL_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Calarasi)
summary(CL_pw_lm_ols)
CL_pred_pw_lm_ols <- exp(predict(CL_pw_lm_ols, newdata = RO_Census_Calarasi, 
                                 interval = "prediction", level = 0.95))
CL_pw_out_ols <- RO_Census_Calarasi %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(CL_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Calarasi), 
         DFFIT = dffits(CL_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(CL_pw_lm_ols$coefficients) / nrow(RO_Census_Calarasi)), 
         Rezid_Std = rstudent(CL_pw_lm_ols), Leverage = hatvalues(CL_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(CL_pw_lm_ols)), 
         DFBETA = dfbetas(CL_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Calarasi)))

# b) Zipf_Mandelbrot Law
CL_ZM_prm_ols <- get_ZM_Param("RO_Census_Calarasi", "Population", "Rank")
CL_ZM_m_ols <- CL_ZM_prm_ols$m
CL_ZM_alpha_ols <- CL_ZM_prm_ols$alpha_ZM
CL_ZM_cst_ols <- CL_ZM_prm_ols$constant_ZM
CL_ZM_lm_ols <- lm(log(RO_Census_Calarasi$Population) ~ log(RO_Census_Calarasi$Rank + CL_ZM_m_ols))
summary(CL_ZM_lm_ols)
CL_pred_ZM_lm_ols <- exp(predict(CL_ZM_lm_ols, newdata = RO_Census_Calarasi, 
                                 interval = "prediction", level = 0.95))
CL_ZM_out_ols <- RO_Census_Calarasi %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(CL_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Calarasi), 
         DFFIT = dffits(CL_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(CL_ZM_lm_ols$coefficients) / nrow(RO_Census_Calarasi)), 
         Rezid_Std = rstudent(CL_ZM_lm_ols), Leverage = hatvalues(CL_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(CL_ZM_lm_ols)), 
         DFBETA = dfbetas(CL_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Calarasi)))

# c) Exponential Law
CL_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Calarasi)
summary(CL_exp_lm_ols)
CL_pred_exp_lm_ols <- exp(predict(CL_exp_lm_ols, newdata = RO_Census_Calarasi, 
                                  interval = "prediction", level = 0.95))
CL_exp_out_ols <- RO_Census_Calarasi %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(CL_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Calarasi), 
         DFFIT = dffits(CL_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(CL_exp_lm_ols$coefficients) / nrow(RO_Census_Calarasi)), 
         Rezid_Std = rstudent(CL_exp_lm_ols), Leverage = hatvalues(CL_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(CL_exp_lm_ols)), 
         DFBETA = dfbetas(CL_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Calarasi)))

# d) Lavalette Function
RO_Census_Calarasi <- RO_Census_Calarasi %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Calarasi) - Rank + 1))
)
CL_lav_lm_ols <- lm(log(RO_Census_Calarasi$Population) ~ RO_Census_Calarasi$Lav_exp)
summary(CL_lav_lm_ols)
CL_lav_kst_ols <- exp(signif(CL_lav_lm_ols$coef[[1]], 4))
CL_lav_chi_ols <- signif(CL_lav_lm_ols$coef[[2]], 4)
CL_pred_lav_lm_ols <- exp(predict(CL_lav_lm_ols, newdata = RO_Census_Calarasi, 
                                  interval = "prediction", level = 0.95))
CL_lav_out_ols <- RO_Census_Calarasi %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(CL_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Calarasi), 
         DFFIT = dffits(CL_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(CL_lav_lm_ols$coefficients) / nrow(RO_Census_Calarasi)), 
         Rezid_Std = rstudent(CL_lav_lm_ols), Leverage = hatvalues(CL_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(CL_lav_lm_ols)), 
         DFBETA = dfbetas(CL_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Calarasi)))

# e) Data Distributions
RO_Census_Calarasi %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Calarasi$Rank, 
                              Population = CL_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(CL_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(CL_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(CL_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Calarasi$Rank, 
                              Population = CL_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(CL_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(CL_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(CL_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Calarasi$Rank, 
                              Population = CL_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(CL_ZM_cst_ols, 4), "%.%", "(",
                           signif(CL_ZM_m_ols, 4), "+ x)^", signif(CL_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(summary(CL_ZM_lm_ols)$r.squared, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Calarasi$Rank, 
                              Population = CL_pred_lav_lm_ols[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(CL_lav_kst_ols, 4), "%.%", "x^",
                           -signif(CL_lav_chi_ols, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(summary(CL_lav_lm_ols)$r.squared, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Calarasi judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# Linear Regressions
grid.arrange(
  (RO_Census_Calarasi %>%
     ggplot(aes(x = log(Rank), y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
