  ncol = 2, nrow = 2)

# f) Extract Outliers
Calarasi_Outliers <- bind_rows(
  (CL_pw_out_ols %>% mutate(Function_Name = "Power")),
  (CL_ZM_out_ols %>% mutate(Function_Name = "Zipf-Mandelbrot")),
  (CL_exp_out_ols %>% mutate(Function_Name = "Exponential")),
  (CL_lav_out_ols %>% mutate(Function_Name = "Lavalette"))
) %>% mutate(DFBETA_intercept = round(DFBETA[,1], 8), 
             DFBETA_var_x = round(DFBETA[,2], 8)) %>% dplyr::select(-DFBETA)

CL_out <- get_outliers(Calarasi_Outliers, RO_Census_Calarasi)

CL_out_ols <- RO_Census_Calarasi %>% inner_join(
  bind_rows(
    (CL_out$PW %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>% 
       dplyr::select(Rank) %>% distinct()),
    (CL_out$ZM %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (CL_out$LAV %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (CL_out$EXP %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct())
  ) %>% count(Rank) %>% arrange(desc(n)) %>% filter(n >= mean(n))) %>% 
  dplyr::select(-n)

# g) Extract regression metrics
CL_regmet_ols <- as.data.frame(list(Judet_Name = "CALARASI",
                                    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
                                    R_Squared = c(signif(summary(CL_pw_lm_ols)$r.squared, 4), 
                                                  signif(summary(CL_exp_lm_ols)$r.squared, 4),
                                                  signif(summary(CL_ZM_lm_ols)$r.squared, 4),
                                                  signif(summary(CL_lav_lm_ols)$r.squared, 4)),
                                    Adj_R_Squared = c(signif(summary(CL_pw_lm_ols)$adj.r.squared, 4), 
                                                      signif(summary(CL_exp_lm_ols)$adj.r.squared, 4),
                                                      signif(summary(CL_ZM_lm_ols)$adj.r.squared, 4),
                                                      signif(summary(CL_lav_lm_ols)$adj.r.squared, 4)),
                                    AIC = c(signif(AIC(CL_pw_lm_ols), 4), signif(AIC(CL_exp_lm_ols), 4), 
                                            signif(AIC(CL_ZM_lm_ols), 4), signif(AIC(CL_lav_lm_ols), 4)),
                                    BIC = c(signif(BIC(CL_pw_lm_ols), 4), signif(BIC(CL_exp_lm_ols), 4), 
                                            signif(BIC(CL_ZM_lm_ols), 4), signif(BIC(CL_lav_lm_ols), 4)),
                                    MAE = c(signif(mean(abs((log(RO_Census_Calarasi$Population) - 
                                                               (predict(CL_pw_lm_ols, newdata = RO_Census_Calarasi, 
                                                                        interval = "prediction", level = 0.95))))), 4), 
                                            signif(mean(abs((log(RO_Census_Calarasi$Population) - 
                                                               (predict(CL_exp_lm_ols, newdata = RO_Census_Calarasi, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Calarasi$Population) - 
                                                               (predict(CL_ZM_lm_ols, newdata = RO_Census_Calarasi, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Calarasi$Population) - 
                                                               (predict(CL_lav_lm_ols, newdata = RO_Census_Calarasi, 
                                                                        interval = "prediction", level = 0.95))))), 4)),
                                    RMSE = c(signif(sqrt(mean(((log(RO_Census_Calarasi$Population)) - 
                                                                 (predict(CL_pw_lm_ols, newdata = RO_Census_Calarasi, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Calarasi$Population)) - 
                                                                 (predict(CL_exp_lm_ols, newdata = RO_Census_Calarasi, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Calarasi$Population)) - 
                                                                 (predict(CL_ZM_lm_ols, newdata = RO_Census_Calarasi, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Calarasi$Population)) - 
                                                                 (predict(CL_lav_lm_ols, newdata = RO_Census_Calarasi, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4))
))

# h) Extract MAE/RMSE on head, body, tail
RO_Census_Calarasi_ols <- RO_Census_Calarasi %>% 
  mutate(PW_Y_Pred = (predict(CL_pw_lm_ols, newdata = RO_Census_Calarasi, 
                              interval = "prediction", level = 0.95))[,1], 
         ZM_Y_Pred = (predict(CL_ZM_lm_ols, newdata = RO_Census_Calarasi, 
                              interval = "prediction", level = 0.95))[,1],
