                               interval = "prediction", level = 0.95))[,1], 
         LAV_Y_Pred = (predict(CL_lav_lm_ols, newdata = RO_Census_Calarasi, 
                               interval = "prediction", level = 0.95))[,1])

# Head
CL_ols_hd <- RO_Census_Calarasi_ols %>% filter(Rank <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(CL_ols_hd$Population) - CL_ols_hd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(CL_ols_hd$Population) - CL_ols_hd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(CL_ols_hd$Population) - CL_ols_hd$ZM_Y_Pred))), 4),
          signif(mean(abs((log(CL_ols_hd$Population) - CL_ols_hd$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(CL_ols_hd$Population)) - CL_ols_hd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(CL_ols_hd$Population)) - CL_ols_hd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(CL_ols_hd$Population)) - CL_ols_hd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(CL_ols_hd$Population)) - CL_ols_hd$LAV_Y_Pred) ^ 2)), 4))
))

# Tail
CL_ols_tl <- RO_Census_Calarasi_ols %>% arrange(desc(Rank)) %>% 
  filter(row_number() <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
