# XIII. Cluj

# 1. OLS
RO_Census_Cluj <- RO_Census_rank %>% filter(Judet_Name == "CLUJ")
#View(RO_Census_Cluj)

# a) Power Law
CJ_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Cluj)
summary(CJ_pw_lm_ols)
CJ_pred_pw_lm_ols <- exp(predict(CJ_pw_lm_ols, newdata = RO_Census_Cluj, 
                                 interval = "prediction", level = 0.95))
CJ_pw_out_ols <- RO_Census_Cluj %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(CJ_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Cluj), 
         DFFIT = dffits(CJ_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(CJ_pw_lm_ols$coefficients) / nrow(RO_Census_Cluj)), 
         Rezid_Std = rstudent(CJ_pw_lm_ols), Leverage = hatvalues(CJ_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(CJ_pw_lm_ols)), 
         DFBETA = dfbetas(CJ_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Cluj)))

# b) Zipf_Mandelbrot Law
CJ_ZM_prm_ols <- get_ZM_Param("RO_Census_Cluj", "Population", "Rank")
CJ_ZM_m_ols <- CJ_ZM_prm_ols$m
CJ_ZM_alpha_ols <- CJ_ZM_prm_ols$alpha_ZM
CJ_ZM_cst_ols <- CJ_ZM_prm_ols$constant_ZM
CJ_ZM_lm_ols <- lm(log(RO_Census_Cluj$Population) ~ log(RO_Census_Cluj$Rank + CJ_ZM_m_ols))
summary(CJ_ZM_lm_ols)
CJ_pred_ZM_lm_ols <- exp(predict(CJ_ZM_lm_ols, newdata = RO_Census_Cluj, 
                                 interval = "prediction", level = 0.95))
CJ_ZM_out_ols <- RO_Census_Cluj %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(CJ_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Cluj), 
         DFFIT = dffits(CJ_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(CJ_ZM_lm_ols$coefficients) / nrow(RO_Census_Cluj)), 
         Rezid_Std = rstudent(CJ_ZM_lm_ols), Leverage = hatvalues(CJ_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(CJ_ZM_lm_ols)), 
         DFBETA = dfbetas(CJ_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Cluj)))

# c) Exponential Law
CJ_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Cluj)
summary(CJ_exp_lm_ols)
CJ_pred_exp_lm_ols <- exp(predict(CJ_exp_lm_ols, newdata = RO_Census_Cluj, 
                                  interval = "prediction", level = 0.95))
CJ_exp_out_ols <- RO_Census_Cluj %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(CJ_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Cluj), 
         DFFIT = dffits(CJ_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(CJ_exp_lm_ols$coefficients) / nrow(RO_Census_Cluj)), 
         Rezid_Std = rstudent(CJ_exp_lm_ols), Leverage = hatvalues(CJ_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(CJ_exp_lm_ols)), 
         DFBETA = dfbetas(CJ_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Cluj)))

# d) Lavalette Function
RO_Census_Cluj <- RO_Census_Cluj %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Cluj) - Rank + 1))
)
CJ_lav_lm_ols <- lm(log(RO_Census_Cluj$Population) ~ RO_Census_Cluj$Lav_exp)
summary(CJ_lav_lm_ols)
CJ_lav_kst_ols <- exp(signif(CJ_lav_lm_ols$coef[[1]], 4))
CJ_lav_chi_ols <- signif(CJ_lav_lm_ols$coef[[2]], 4)
CJ_pred_lav_lm_ols <- exp(predict(CJ_lav_lm_ols, newdata = RO_Census_Cluj, 
                                  interval = "prediction", level = 0.95))
CJ_lav_out_ols <- RO_Census_Cluj %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(CJ_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Cluj), 
         DFFIT = dffits(CJ_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(CJ_lav_lm_ols$coefficients) / nrow(RO_Census_Cluj)), 
         Rezid_Std = rstudent(CJ_lav_lm_ols), Leverage = hatvalues(CJ_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(CJ_lav_lm_ols)), 
         DFBETA = dfbetas(CJ_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Cluj)))

# e) Data Distributions
RO_Census_Cluj %>%
