# 2. Robust

# a) Power Law
CJ_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Cluj)
summary(CJ_pw_lm_rob)
CJ_pred_pw_lm_rob <- exp(predict(CJ_pw_lm_rob, newdata = RO_Census_Cluj, 
                                 interval = "prediction", level = 0.95))
CJ_RSquared_pw_rob <- 1 - sum((log(RO_Census_Cluj$Population) - fitted(CJ_pw_lm_rob))^2) / 
  sum((log(RO_Census_Cluj$Population) - mean(log(RO_Census_Cluj$Population)))^2)

# b) Zipf_Mandelbrot Law
CJ_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Cluj, "Population", "Rank")
CJ_ZM_m_rob <- CJ_ZM_prm_rob$m
CJ_ZM_alpha_rob <- CJ_ZM_prm_rob$alpha_ZM
CJ_ZM_cst_rob <- CJ_ZM_prm_rob$constant_ZM
CJ_ZM_lm_rob <- rlm(log(RO_Census_Cluj$Population) ~ log(RO_Census_Cluj$Rank + CJ_ZM_m_rob))
summary(CJ_ZM_lm_rob)
CJ_pred_ZM_lm_rob <- exp(predict(CJ_ZM_lm_rob, newdata = RO_Census_Cluj, 
                                 interval = "prediction", level = 0.95))
CJ_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Cluj$Population) - fitted(CJ_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Cluj$Population) - mean(log(RO_Census_Cluj$Population)))^2)

# c) Exponential Law
CJ_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Cluj)
summary(CJ_exp_lm_rob)
CJ_pred_exp_lm_rob <- exp(predict(CJ_exp_lm_rob, newdata = RO_Census_Cluj, 
                                  interval = "prediction", level = 0.95))
CJ_RSquared_exp_rob <- 1 - sum((log(RO_Census_Cluj$Population) - fitted(CJ_exp_lm_rob))^2) / 
  sum((log(RO_Census_Cluj$Population) - mean(log(RO_Census_Cluj$Population)))^2)

# d) Lavalette Function
RO_Census_Cluj <- RO_Census_Cluj %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Cluj) - Rank + 1))
)
CJ_lav_lm_rob <- rlm(log(RO_Census_Cluj$Population) ~ RO_Census_Cluj$Lav_exp)
summary(CJ_lav_lm_rob)
CJ_lav_kst_rob <- exp(signif(CJ_lav_lm_rob$coef[[1]], 4))
CJ_lav_chi_rob <- signif(CJ_lav_lm_rob$coef[[2]], 4)
CJ_pred_lav_lm_rob <- exp(predict(CJ_lav_lm_rob, newdata = RO_Census_Cluj, 
                                  interval = "prediction", level = 0.95))
CJ_RSquared_lav_rob <- 1 - sum((log(RO_Census_Cluj$Population) - fitted(CJ_lav_lm_rob))^2) / 
  sum((log(RO_Census_Cluj$Population) - mean(log(RO_Census_Cluj$Population)))^2)

# e) Data Distributions
RO_Census_Cluj %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Cluj$Rank, 
                              Population = CJ_pred_pw_lm_rob[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 30, y = 200000,
            label = paste0("y", "==", signif(exp(CJ_pw_lm_rob$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(CJ_pw_lm_rob$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 60, y = 200000,
            label = paste0("R^2 ==", signif(CJ_RSquared_pw_rob, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Cluj$Rank, 
                              Population = CJ_pred_exp_lm_rob[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 30, y = 180000,
            label = paste0("y", "==", signif(exp(CJ_exp_lm_rob$coefficients[[1]]), 4), "%.%", 
                           signif(exp(CJ_exp_lm_rob$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 60, y = 180000,
            label = paste0("R^2 ==", signif(CJ_RSquared_exp_rob, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Cluj$Rank, 
                              Population = CJ_pred_ZM_lm_rob[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 30, y = 160000,
            label = paste0("y", "==", signif(CJ_ZM_cst_rob, 4), "%.%", "(",
                           signif(CJ_ZM_m_rob, 4), "+ x)^", signif(CJ_ZM_alpha_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 60, y = 160000,
            label = paste0("R^2 ==", signif(CJ_RSquared_ZM_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Cluj$Rank, 
                              Population = CJ_pred_lav_lm_rob[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 30, y = 140000,
            label = paste0("y", "==", signif(CJ_lav_kst_rob, 4), "%.%", "x^",
                           -signif(CJ_lav_chi_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 60, y = 140000,
            label = paste0("R^2 ==", signif(CJ_RSquared_lav_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_y_continuous(labels = scales::label_number(
    big.mark = ",", decimal.mark = ".")) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Cluj judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# f) Extract regression metrics
CJ_regmet_rob <- as.data.frame(list(Judet_Name = "CLUJ",
                                    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
                                    R_Squared = c(signif(CJ_RSquared_pw_rob, 4), 
                                                  signif(CJ_RSquared_exp_rob, 4),
                                                  signif(CJ_RSquared_ZM_rob, 4),
                                                  signif(CJ_RSquared_lav_rob, 4)),
                                    AIC = c(signif(AIC(CJ_pw_lm_rob), 4), signif(AIC(CJ_exp_lm_rob), 4), 
                                            signif(AIC(CJ_ZM_lm_rob), 4), signif(AIC(CJ_lav_lm_rob), 4)),
                                    BIC = c(signif(BIC(CJ_pw_lm_rob), 4), signif(BIC(CJ_exp_lm_rob), 4), 
                                            signif(BIC(CJ_ZM_lm_rob), 4), signif(BIC(CJ_lav_lm_rob), 4)),
                                    MAE = c(signif(mean(abs((log(RO_Census_Cluj$Population) - 
                                                               (predict(CJ_pw_lm_rob, newdata = RO_Census_Cluj, 
                                                                        interval = "prediction", level = 0.95))))), 4), 
                                            signif(mean(abs((log(RO_Census_Cluj$Population) - 
                                                               (predict(CJ_exp_lm_rob, newdata = RO_Census_Cluj, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Cluj$Population) - 
                                                               (predict(CJ_ZM_lm_rob, newdata = RO_Census_Cluj, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Cluj$Population) - 
                                                               (predict(CJ_lav_lm_rob, newdata = RO_Census_Cluj, 
                                                                        interval = "prediction", level = 0.95))))), 4)),
                                    RMSE = c(signif(sqrt(mean(((log(RO_Census_Cluj$Population)) - 
                                                                 (predict(CJ_pw_lm_rob, newdata = RO_Census_Cluj, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Cluj$Population)) - 
                                                                 (predict(CJ_exp_lm_rob, newdata = RO_Census_Cluj, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Cluj$Population)) - 
                                                                 (predict(CJ_ZM_lm_rob, newdata = RO_Census_Cluj, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Cluj$Population)) - 
                                                                 (predict(CJ_lav_lm_rob, newdata = RO_Census_Cluj, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4))
))

# Extract weight
CJ_out_weights <- bind_rows(
  (RO_Census_Cluj %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>% 
     mutate(Robust_Weight = CJ_pw_lm_rob$w, Function_Name = "Power")),
  (RO_Census_Cluj %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = CJ_ZM_lm_rob$w, Function_Name = "Zipf-Mandelbrot")),
  (RO_Census_Cluj %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = CJ_exp_lm_rob$w, Function_Name = "Exponential")),
  (RO_Census_Cluj %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = CJ_lav_lm_rob$w, Function_Name = "Lavalette"))) %>% 
  inner_join(CJ_out_ols) %>% 
  dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank, Robust_Weight, Function_Name) %>%
  mutate(Judet_Name = "CLUJ")

# g) Extract MAE/RMSE on head, body, tail
RO_Census_Cluj_rob <- RO_Census_Cluj %>% 
  mutate(PW_Y_Pred = (predict(CJ_pw_lm_rob, newdata = RO_Census_Cluj, 
                              interval = "prediction", level = 0.95))[,1], 
         ZM_Y_Pred = (predict(CJ_ZM_lm_rob, newdata = RO_Census_Cluj, 
                              interval = "prediction", level = 0.95))[,1],
         EXP_Y_Pred = (predict(CJ_exp_lm_rob, newdata = RO_Census_Cluj, 
                               interval = "prediction", level = 0.95))[,1], 
         LAV_Y_Pred = (predict(CJ_lav_lm_rob, newdata = RO_Census_Cluj, 
                               interval = "prediction", level = 0.95))[,1])

# Head
CJ_rob_hd <- RO_Census_Cluj_rob %>% filter(Rank <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(CJ_rob_hd$Population) - CJ_rob_hd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(CJ_rob_hd$Population) - CJ_rob_hd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(CJ_rob_hd$Population) - CJ_rob_hd$ZM_Y_Pred))), 4),
          signif(mean(abs((log(CJ_rob_hd$Population) - CJ_rob_hd$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(CJ_rob_hd$Population)) - CJ_rob_hd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(CJ_rob_hd$Population)) - CJ_rob_hd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(CJ_rob_hd$Population)) - CJ_rob_hd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(CJ_rob_hd$Population)) - CJ_rob_hd$LAV_Y_Pred) ^ 2)), 4))
))

# Tail
CJ_rob_tl <- RO_Census_Cluj_rob %>% arrange(desc(Rank)) %>% 
  filter(row_number() <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(CJ_rob_tl$Population) - CJ_rob_tl$PW_Y_Pred))), 4), 
          signif(mean(abs((log(CJ_rob_tl$Population) - CJ_rob_tl$EXP_Y_Pred))), 4),
          signif(mean(abs((log(CJ_rob_tl$Population) - CJ_rob_tl$ZM_Y_Pred))), 4),
          signif(mean(abs((log(CJ_rob_tl$Population) - CJ_rob_tl$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(CJ_rob_tl$Population)) - CJ_rob_tl$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(CJ_rob_tl$Population)) - CJ_rob_tl$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(CJ_rob_tl$Population)) - CJ_rob_tl$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(CJ_rob_tl$Population)) - CJ_rob_tl$LAV_Y_Pred) ^ 2)), 4))
))

# Body
CJ_rob_bd <- RO_Census_Cluj_rob %>% anti_join(CJ_rob_hd) %>% anti_join(CJ_rob_tl)

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(CJ_rob_bd$Population) - CJ_rob_bd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(CJ_rob_bd$Population) - CJ_rob_bd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(CJ_rob_bd$Population) - CJ_rob_bd$ZM_Y_Pred))), 4),
          signif(mean(abs((log(CJ_rob_bd$Population) - CJ_rob_bd$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(CJ_rob_bd$Population)) - CJ_rob_bd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(CJ_rob_bd$Population)) - CJ_rob_bd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(CJ_rob_bd$Population)) - CJ_rob_bd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(CJ_rob_bd$Population)) - CJ_rob_bd$LAV_Y_Pred) ^ 2)), 4))
))

# Final
CJ_res_rob <- as.data.frame(bind_rows(
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(CJ_rob_hd$Population) - CJ_rob_hd$PW_Y_Pred))), 4), 
            signif(mean(abs((log(CJ_rob_hd$Population) - CJ_rob_hd$EXP_Y_Pred))), 4),
            signif(mean(abs((log(CJ_rob_hd$Population) - CJ_rob_hd$ZM_Y_Pred))), 4),
            signif(mean(abs((log(CJ_rob_hd$Population) - CJ_rob_hd$LAV_Y_Pred))), 4)),
    RMSE = c(signif(sqrt(mean(((log(CJ_rob_hd$Population)) - CJ_rob_hd$PW_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(CJ_rob_hd$Population)) - CJ_rob_hd$EXP_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(CJ_rob_hd$Population)) - CJ_rob_hd$ZM_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(CJ_rob_hd$Population)) - CJ_rob_hd$LAV_Y_Pred) ^ 2)), 4)),
    Data_Part = "Head"
  )),
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(CJ_rob_tl$Population) - CJ_rob_tl$PW_Y_Pred))), 4), 
            signif(mean(abs((log(CJ_rob_tl$Population) - CJ_rob_tl$EXP_Y_Pred))), 4),
            signif(mean(abs((log(CJ_rob_tl$Population) - CJ_rob_tl$ZM_Y_Pred))), 4),
            signif(mean(abs((log(CJ_rob_tl$Population) - CJ_rob_tl$LAV_Y_Pred))), 4)),
    RMSE = c(signif(sqrt(mean(((log(CJ_rob_tl$Population)) - CJ_rob_tl$PW_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(CJ_rob_tl$Population)) - CJ_rob_tl$EXP_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(CJ_rob_tl$Population)) - CJ_rob_tl$ZM_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(CJ_rob_tl$Population)) - CJ_rob_tl$LAV_Y_Pred) ^ 2)), 4)),
    Data_Part = "Tail"
  )),
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(CJ_rob_bd$Population) - CJ_rob_bd$PW_Y_Pred))), 4), 
            signif(mean(abs((log(CJ_rob_bd$Population) - CJ_rob_bd$EXP_Y_Pred))), 4),
            signif(mean(abs((log(CJ_rob_bd$Population) - CJ_rob_bd$ZM_Y_Pred))), 4),
            signif(mean(abs((log(CJ_rob_bd$Population) - CJ_rob_bd$LAV_Y_Pred))), 4)),
    RMSE = c(signif(sqrt(mean(((log(CJ_rob_bd$Population)) - CJ_rob_bd$PW_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(CJ_rob_bd$Population)) - CJ_rob_bd$EXP_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(CJ_rob_bd$Population)) - CJ_rob_bd$ZM_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(CJ_rob_bd$Population)) - CJ_rob_bd$LAV_Y_Pred) ^ 2)), 4)),
    Data_Part = "Body"
  )),
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(RO_Census_Cluj$Population) - 
                               (predict(CJ_pw_lm_rob, newdata = RO_Census_Cluj, 
                                        interval = "prediction", level = 0.95))))), 4), 
            signif(mean(abs((log(RO_Census_Cluj$Population) - 
                               (predict(CJ_exp_lm_rob, newdata = RO_Census_Cluj, 
                                        interval = "prediction", level = 0.95))))), 4),
            signif(mean(abs((log(RO_Census_Cluj$Population) - 
                               (predict(CJ_ZM_lm_rob, newdata = RO_Census_Cluj, 
                                        interval = "prediction", level = 0.95))))), 4),
            signif(mean(abs((log(RO_Census_Cluj$Population) - 
                               (predict(CJ_lav_lm_rob, newdata = RO_Census_Cluj, 
                                        interval = "prediction", level = 0.95))))), 4)),
    RMSE = c(signif(sqrt(mean(((log(RO_Census_Cluj$Population)) - 
                                 (predict(CJ_pw_lm_rob, newdata = RO_Census_Cluj, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Cluj$Population)) - 
                                 (predict(CJ_exp_lm_rob, newdata = RO_Census_Cluj, 
