# XIV. Constanta

# 1. OLS
RO_Census_Constanta <- RO_Census_rank %>% filter(Judet_Name == "CONSTANTA")
#View(RO_Census_Constanta)

# a) Power Law
CT_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Constanta)
summary(CT_pw_lm_ols)
CT_pred_pw_lm_ols <- exp(predict(CT_pw_lm_ols, newdata = RO_Census_Constanta, 
                                 interval = "prediction", level = 0.95))
CT_pw_out_ols <- RO_Census_Constanta %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(CT_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Constanta), 
         DFFIT = dffits(CT_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(CT_pw_lm_ols$coefficients) / nrow(RO_Census_Constanta)), 
         Rezid_Std = rstudent(CT_pw_lm_ols), Leverage = hatvalues(CT_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(CT_pw_lm_ols)), 
         DFBETA = dfbetas(CT_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Constanta)))

# b) Zipf_Mandelbrot Law
CT_ZM_prm_ols <- get_ZM_Param("RO_Census_Constanta", "Population", "Rank")
CT_ZM_m_ols <- CT_ZM_prm_ols$m
CT_ZM_alpha_ols <- CT_ZM_prm_ols$alpha_ZM
CT_ZM_cst_ols <- CT_ZM_prm_ols$constant_ZM
CT_ZM_lm_ols <- lm(log(RO_Census_Constanta$Population) ~ log(RO_Census_Constanta$Rank + CT_ZM_m_ols))
summary(CT_ZM_lm_ols)
CT_pred_ZM_lm_ols <- exp(predict(CT_ZM_lm_ols, newdata = RO_Census_Constanta, 
                                 interval = "prediction", level = 0.95))
CT_ZM_out_ols <- RO_Census_Constanta %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(CT_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Constanta), 
         DFFIT = dffits(CT_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(CT_ZM_lm_ols$coefficients) / nrow(RO_Census_Constanta)), 
         Rezid_Std = rstudent(CT_ZM_lm_ols), Leverage = hatvalues(CT_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(CT_ZM_lm_ols)), 
         DFBETA = dfbetas(CT_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Constanta)))

# c) Exponential Law
CT_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Constanta)
summary(CT_exp_lm_ols)
CT_pred_exp_lm_ols <- exp(predict(CT_exp_lm_ols, newdata = RO_Census_Constanta, 
                                  interval = "prediction", level = 0.95))
CT_exp_out_ols <- RO_Census_Constanta %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(CT_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Constanta), 
         DFFIT = dffits(CT_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(CT_exp_lm_ols$coefficients) / nrow(RO_Census_Constanta)), 
         Rezid_Std = rstudent(CT_exp_lm_ols), Leverage = hatvalues(CT_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(CT_exp_lm_ols)), 
         DFBETA = dfbetas(CT_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Constanta)))

# d) Lavalette Function
RO_Census_Constanta <- RO_Census_Constanta %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Constanta) - Rank + 1))
)
CT_lav_lm_ols <- lm(log(RO_Census_Constanta$Population) ~ RO_Census_Constanta$Lav_exp)
summary(CT_lav_lm_ols)
CT_lav_kst_ols <- exp(signif(CT_lav_lm_ols$coef[[1]], 4))
CT_lav_chi_ols <- signif(CT_lav_lm_ols$coef[[2]], 4)
CT_pred_lav_lm_ols <- exp(predict(CT_lav_lm_ols, newdata = RO_Census_Constanta, 
                                  interval = "prediction", level = 0.95))
CT_lav_out_ols <- RO_Census_Constanta %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(CT_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Constanta), 
         DFFIT = dffits(CT_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(CT_lav_lm_ols$coefficients) / nrow(RO_Census_Constanta)), 
         Rezid_Std = rstudent(CT_lav_lm_ols), Leverage = hatvalues(CT_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(CT_lav_lm_ols)), 
         DFBETA = dfbetas(CT_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Constanta)))

