# 2. Robust

# a) Power Law
CT_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Constanta)
summary(CT_pw_lm_rob)
CT_pred_pw_lm_rob <- exp(predict(CT_pw_lm_rob, newdata = RO_Census_Constanta, 
                                 interval = "prediction", level = 0.95))
CT_RSquared_pw_rob <- 1 - sum((log(RO_Census_Constanta$Population) - fitted(CT_pw_lm_rob))^2) / 
  sum((log(RO_Census_Constanta$Population) - mean(log(RO_Census_Constanta$Population)))^2)

# b) Zipf_Mandelbrot Law
CT_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Constanta, "Population", "Rank")
CT_ZM_m_rob <- CT_ZM_prm_rob$m
CT_ZM_alpha_rob <- CT_ZM_prm_rob$alpha_ZM
CT_ZM_cst_rob <- CT_ZM_prm_rob$constant_ZM
CT_ZM_lm_rob <- rlm(log(RO_Census_Constanta$Population) ~ log(RO_Census_Constanta$Rank + CT_ZM_m_rob))
summary(CT_ZM_lm_rob)
CT_pred_ZM_lm_rob <- exp(predict(CT_ZM_lm_rob, newdata = RO_Census_Constanta, 
                                 interval = "prediction", level = 0.95))
CT_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Constanta$Population) - fitted(CT_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Constanta$Population) - mean(log(RO_Census_Constanta$Population)))^2)

# c) Exponential Law
CT_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Constanta)
summary(CT_exp_lm_rob)
CT_pred_exp_lm_rob <- exp(predict(CT_exp_lm_rob, newdata = RO_Census_Constanta, 
                                  interval = "prediction", level = 0.95))
CT_RSquared_exp_rob <- 1 - sum((log(RO_Census_Constanta$Population) - fitted(CT_exp_lm_rob))^2) / 
  sum((log(RO_Census_Constanta$Population) - mean(log(RO_Census_Constanta$Population)))^2)

# d) Lavalette Function
RO_Census_Constanta <- RO_Census_Constanta %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Constanta) - Rank + 1))
)
CT_lav_lm_rob <- rlm(log(RO_Census_Constanta$Population) ~ RO_Census_Constanta$Lav_exp)
summary(CT_lav_lm_rob)
CT_lav_kst_rob <- exp(signif(CT_lav_lm_rob$coef[[1]], 4))
CT_lav_chi_rob <- signif(CT_lav_lm_rob$coef[[2]], 4)
CT_pred_lav_lm_rob <- exp(predict(CT_lav_lm_rob, newdata = RO_Census_Constanta, 
                                  interval = "prediction", level = 0.95))
CT_RSquared_lav_rob <- 1 - sum((log(RO_Census_Constanta$Population) - fitted(CT_lav_lm_rob))^2) / 
  sum((log(RO_Census_Constanta$Population) - mean(log(RO_Census_Constanta$Population)))^2)

