# 1. OLS
RO_Census_Covasna <- RO_Census_rank %>% filter(Judet_Name == "COVASNA")
#View(RO_Census_Covasna)

# a) Power Law
CV_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Covasna)
summary(CV_pw_lm_ols)
CV_pred_pw_lm_ols <- exp(predict(CV_pw_lm_ols, newdata = RO_Census_Covasna, 
                                 interval = "prediction", level = 0.95))
CV_pw_out_ols <- RO_Census_Covasna %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(CV_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Covasna), 
         DFFIT = dffits(CV_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(CV_pw_lm_ols$coefficients) / nrow(RO_Census_Covasna)), 
         Rezid_Std = rstudent(CV_pw_lm_ols), Leverage = hatvalues(CV_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(CV_pw_lm_ols)), 
         DFBETA = dfbetas(CV_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Covasna)))

# b) Zipf_Mandelbrot Law
