         Rezid_Std = rstudent(CV_ZM_lm_ols), Leverage = hatvalues(CV_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(CV_ZM_lm_ols)), 
         DFBETA = dfbetas(CV_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Covasna)))

# c) Exponential Law
