  mutate(Cooks_Dist = cooks.distance(CV_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Covasna), 
         DFFIT = dffits(CV_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(CV_lav_lm_ols$coefficients) / nrow(RO_Census_Covasna)), 
         Rezid_Std = rstudent(CV_lav_lm_ols), Leverage = hatvalues(CV_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(CV_lav_lm_ols)), 
