# 2. Robust

# a) Power Law
CV_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Covasna)
summary(CV_pw_lm_rob)
CV_pred_pw_lm_rob <- exp(predict(CV_pw_lm_rob, newdata = RO_Census_Covasna, 
                                 interval = "prediction", level = 0.95))
CV_RSquared_pw_rob <- 1 - sum((log(RO_Census_Covasna$Population) - fitted(CV_pw_lm_rob))^2) / 
  sum((log(RO_Census_Covasna$Population) - mean(log(RO_Census_Covasna$Population)))^2)

# b) Zipf_Mandelbrot Law
CV_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Covasna, "Population", "Rank")
CV_ZM_m_rob <- CV_ZM_prm_rob$m
CV_ZM_alpha_rob <- CV_ZM_prm_rob$alpha_ZM
CV_ZM_cst_rob <- CV_ZM_prm_rob$constant_ZM
CV_ZM_lm_rob <- rlm(log(RO_Census_Covasna$Population) ~ log(RO_Census_Covasna$Rank + CV_ZM_m_rob))
summary(CV_ZM_lm_rob)
CV_pred_ZM_lm_rob <- exp(predict(CV_ZM_lm_rob, newdata = RO_Census_Covasna, 
                                 interval = "prediction", level = 0.95))
CV_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Covasna$Population) - fitted(CV_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Covasna$Population) - mean(log(RO_Census_Covasna$Population)))^2)

# c) Exponential Law
CV_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Covasna)
summary(CV_exp_lm_rob)
CV_pred_exp_lm_rob <- exp(predict(CV_exp_lm_rob, newdata = RO_Census_Covasna, 
                                  interval = "prediction", level = 0.95))
CV_RSquared_exp_rob <- 1 - sum((log(RO_Census_Covasna$Population) - fitted(CV_exp_lm_rob))^2) / 
  sum((log(RO_Census_Covasna$Population) - mean(log(RO_Census_Covasna$Population)))^2)

# d) Lavalette Function
RO_Census_Covasna <- RO_Census_Covasna %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Covasna) - Rank + 1))
)
CV_lav_lm_rob <- rlm(log(RO_Census_Covasna$Population) ~ RO_Census_Covasna$Lav_exp)
summary(CV_lav_lm_rob)
CV_lav_kst_rob <- exp(signif(CV_lav_lm_rob$coef[[1]], 4))
CV_lav_chi_rob <- signif(CV_lav_lm_rob$coef[[2]], 4)
CV_pred_lav_lm_rob <- exp(predict(CV_lav_lm_rob, newdata = RO_Census_Covasna, 
                                  interval = "prediction", level = 0.95))
CV_RSquared_lav_rob <- 1 - sum((log(RO_Census_Covasna$Population) - fitted(CV_lav_lm_rob))^2) / 
  sum((log(RO_Census_Covasna$Population) - mean(log(RO_Census_Covasna$Population)))^2)

# e) Data Distributions
RO_Census_Covasna %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Covasna$Rank, 
                              Population = CV_pred_pw_lm_rob[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(CV_pw_lm_rob$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(CV_pw_lm_rob$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(CV_RSquared_pw_rob, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Covasna$Rank, 
                              Population = CV_pred_exp_lm_rob[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(CV_exp_lm_rob$coefficients[[1]]), 4), "%.%", 
                           signif(exp(CV_exp_lm_rob$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(CV_RSquared_exp_rob, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Covasna$Rank, 
                              Population = CV_pred_ZM_lm_rob[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(CV_ZM_cst_rob, 4), "%.%", "(",
                           signif(CV_ZM_m_rob, 4), "+ x)^", signif(CV_ZM_alpha_rob, 4)),
