# XVI. Dambovita

# 1. OLS
RO_Census_Dambovita <- RO_Census_rank %>% filter(Judet_Name == "DAMBOVITA")
#View(RO_Census_Dambovita)

# a) Power Law
DB_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Dambovita)
summary(DB_pw_lm_ols)
DB_pred_pw_lm_ols <- exp(predict(DB_pw_lm_ols, newdata = RO_Census_Dambovita, 
                                 interval = "prediction", level = 0.95))
DB_pw_out_ols <- RO_Census_Dambovita %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(DB_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Dambovita), 
         DFFIT = dffits(DB_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(DB_pw_lm_ols$coefficients) / nrow(RO_Census_Dambovita)), 
         Rezid_Std = rstudent(DB_pw_lm_ols), Leverage = hatvalues(DB_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(DB_pw_lm_ols)), 
         DFBETA = dfbetas(DB_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Dambovita)))

# b) Zipf_Mandelbrot Law
DB_ZM_prm_ols <- get_ZM_Param("RO_Census_Dambovita", "Population", "Rank")
DB_ZM_m_ols <- DB_ZM_prm_ols$m
DB_ZM_alpha_ols <- DB_ZM_prm_ols$alpha_ZM
DB_ZM_cst_ols <- DB_ZM_prm_ols$constant_ZM
DB_ZM_lm_ols <- lm(log(RO_Census_Dambovita$Population) ~ log(RO_Census_Dambovita$Rank + DB_ZM_m_ols))
summary(DB_ZM_lm_ols)
DB_pred_ZM_lm_ols <- exp(predict(DB_ZM_lm_ols, newdata = RO_Census_Dambovita, 
                                 interval = "prediction", level = 0.95))
DB_ZM_out_ols <- RO_Census_Dambovita %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(DB_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Dambovita), 
         DFFIT = dffits(DB_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(DB_ZM_lm_ols$coefficients) / nrow(RO_Census_Dambovita)), 
         Rezid_Std = rstudent(DB_ZM_lm_ols), Leverage = hatvalues(DB_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(DB_ZM_lm_ols)), 
         DFBETA = dfbetas(DB_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Dambovita)))

# c) Exponential Law
DB_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Dambovita)
summary(DB_exp_lm_ols)
DB_pred_exp_lm_ols <- exp(predict(DB_exp_lm_ols, newdata = RO_Census_Dambovita, 
                                  interval = "prediction", level = 0.95))
DB_exp_out_ols <- RO_Census_Dambovita %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(DB_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Dambovita), 
         DFFIT = dffits(DB_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(DB_exp_lm_ols$coefficients) / nrow(RO_Census_Dambovita)), 
         Rezid_Std = rstudent(DB_exp_lm_ols), Leverage = hatvalues(DB_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(DB_exp_lm_ols)), 
         DFBETA = dfbetas(DB_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Dambovita)))

# d) Lavalette Function
RO_Census_Dambovita <- RO_Census_Dambovita %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Dambovita) - Rank + 1))
)
DB_lav_lm_ols <- lm(log(RO_Census_Dambovita$Population) ~ RO_Census_Dambovita$Lav_exp)
summary(DB_lav_lm_ols)
DB_lav_kst_ols <- exp(signif(DB_lav_lm_ols$coef[[1]], 4))
DB_lav_chi_ols <- signif(DB_lav_lm_ols$coef[[2]], 4)
DB_pred_lav_lm_ols <- exp(predict(DB_lav_lm_ols, newdata = RO_Census_Dambovita, 
                                  interval = "prediction", level = 0.95))
DB_lav_out_ols <- RO_Census_Dambovita %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(DB_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Dambovita), 
         DFFIT = dffits(DB_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(DB_lav_lm_ols$coefficients) / nrow(RO_Census_Dambovita)), 
         Rezid_Std = rstudent(DB_lav_lm_ols), Leverage = hatvalues(DB_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(DB_lav_lm_ols)), 
         DFBETA = dfbetas(DB_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Dambovita)))

# e) Data Distributions
RO_Census_Dambovita %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Dambovita$Rank, 
                              Population = DB_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(DB_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(DB_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(DB_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Dambovita$Rank, 
                              Population = DB_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(DB_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(DB_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
