# 2. Robust

# a) Power Law
DB_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Dambovita)
summary(DB_pw_lm_rob)
DB_pred_pw_lm_rob <- exp(predict(DB_pw_lm_rob, newdata = RO_Census_Dambovita, 
                                 interval = "prediction", level = 0.95))
DB_RSquared_pw_rob <- 1 - sum((log(RO_Census_Dambovita$Population) - fitted(DB_pw_lm_rob))^2) / 
  sum((log(RO_Census_Dambovita$Population) - mean(log(RO_Census_Dambovita$Population)))^2)

# b) Zipf_Mandelbrot Law
DB_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Dambovita, "Population", "Rank")
DB_ZM_m_rob <- DB_ZM_prm_rob$m
DB_ZM_alpha_rob <- DB_ZM_prm_rob$alpha_ZM
DB_ZM_cst_rob <- DB_ZM_prm_rob$constant_ZM
DB_ZM_lm_rob <- rlm(log(RO_Census_Dambovita$Population) ~ log(RO_Census_Dambovita$Rank + DB_ZM_m_rob))
summary(DB_ZM_lm_rob)
DB_pred_ZM_lm_rob <- exp(predict(DB_ZM_lm_rob, newdata = RO_Census_Dambovita, 
                                 interval = "prediction", level = 0.95))
DB_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Dambovita$Population) - fitted(DB_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Dambovita$Population) - mean(log(RO_Census_Dambovita$Population)))^2)

# c) Exponential Law
DB_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Dambovita)
summary(DB_exp_lm_rob)
DB_pred_exp_lm_rob <- exp(predict(DB_exp_lm_rob, newdata = RO_Census_Dambovita, 
                                  interval = "prediction", level = 0.95))
DB_RSquared_exp_rob <- 1 - sum((log(RO_Census_Dambovita$Population) - fitted(DB_exp_lm_rob))^2) / 
  sum((log(RO_Census_Dambovita$Population) - mean(log(RO_Census_Dambovita$Population)))^2)

# d) Lavalette Function
RO_Census_Dambovita <- RO_Census_Dambovita %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Dambovita) - Rank + 1))
)
DB_lav_lm_rob <- rlm(log(RO_Census_Dambovita$Population) ~ RO_Census_Dambovita$Lav_exp)
summary(DB_lav_lm_rob)
DB_lav_kst_rob <- exp(signif(DB_lav_lm_rob$coef[[1]], 4))
DB_lav_chi_rob <- signif(DB_lav_lm_rob$coef[[2]], 4)
DB_pred_lav_lm_rob <- exp(predict(DB_lav_lm_rob, newdata = RO_Census_Dambovita, 
                                  interval = "prediction", level = 0.95))
DB_RSquared_lav_rob <- 1 - sum((log(RO_Census_Dambovita$Population) - fitted(DB_lav_lm_rob))^2) / 
  sum((log(RO_Census_Dambovita$Population) - mean(log(RO_Census_Dambovita$Population)))^2)

# e) Data Distributions
RO_Census_Dambovita %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
