  (RO_Census_Dambovita %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = DB_ZM_lm_rob$w, Function_Name = "Zipf-Mandelbrot")),
  (RO_Census_Dambovita %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
