# XVII. Dolj

# 1. OLS
RO_Census_Dolj <- RO_Census_rank %>% filter(Judet_Name == "DOLJ")
#View(RO_Census_Dolj)

# a) Power Law
DJ_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Dolj)
summary(DJ_pw_lm_ols)
DJ_pred_pw_lm_ols <- exp(predict(DJ_pw_lm_ols, newdata = RO_Census_Dolj, 
                                 interval = "prediction", level = 0.95))
DJ_pw_out_ols <- RO_Census_Dolj %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(DJ_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Dolj), 
         DFFIT = dffits(DJ_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(DJ_pw_lm_ols$coefficients) / nrow(RO_Census_Dolj)), 
         Rezid_Std = rstudent(DJ_pw_lm_ols), Leverage = hatvalues(DJ_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(DJ_pw_lm_ols)), 
         DFBETA = dfbetas(DJ_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Dolj)))

# b) Zipf_Mandelbrot Law
DJ_ZM_prm_ols <- get_ZM_Param("RO_Census_Dolj", "Population", "Rank")
DJ_ZM_m_ols <- DJ_ZM_prm_ols$m
DJ_ZM_alpha_ols <- DJ_ZM_prm_ols$alpha_ZM
DJ_ZM_cst_ols <- DJ_ZM_prm_ols$constant_ZM
DJ_ZM_lm_ols <- lm(log(RO_Census_Dolj$Population) ~ log(RO_Census_Dolj$Rank + DJ_ZM_m_ols))
summary(DJ_ZM_lm_ols)
DJ_pred_ZM_lm_ols <- exp(predict(DJ_ZM_lm_ols, newdata = RO_Census_Dolj, 
                                 interval = "prediction", level = 0.95))
DJ_ZM_out_ols <- RO_Census_Dolj %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(DJ_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Dolj), 
         DFFIT = dffits(DJ_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(DJ_ZM_lm_ols$coefficients) / nrow(RO_Census_Dolj)), 
         Rezid_Std = rstudent(DJ_ZM_lm_ols), Leverage = hatvalues(DJ_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(DJ_ZM_lm_ols)), 
         DFBETA = dfbetas(DJ_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Dolj)))

# c) Exponential Law
DJ_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Dolj)
summary(DJ_exp_lm_ols)
DJ_pred_exp_lm_ols <- exp(predict(DJ_exp_lm_ols, newdata = RO_Census_Dolj, 
                                  interval = "prediction", level = 0.95))
DJ_exp_out_ols <- RO_Census_Dolj %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(DJ_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Dolj), 
         DFFIT = dffits(DJ_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(DJ_exp_lm_ols$coefficients) / nrow(RO_Census_Dolj)), 
         Rezid_Std = rstudent(DJ_exp_lm_ols), Leverage = hatvalues(DJ_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(DJ_exp_lm_ols)), 
         DFBETA = dfbetas(DJ_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Dolj)))

# d) Lavalette Function
RO_Census_Dolj <- RO_Census_Dolj %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Dolj) - Rank + 1))
)
DJ_lav_lm_ols <- lm(log(RO_Census_Dolj$Population) ~ RO_Census_Dolj$Lav_exp)
summary(DJ_lav_lm_ols)
DJ_lav_kst_ols <- exp(signif(DJ_lav_lm_ols$coef[[1]], 4))
DJ_lav_chi_ols <- signif(DJ_lav_lm_ols$coef[[2]], 4)
DJ_pred_lav_lm_ols <- exp(predict(DJ_lav_lm_ols, newdata = RO_Census_Dolj, 
                                  interval = "prediction", level = 0.95))
DJ_lav_out_ols <- RO_Census_Dolj %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(DJ_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Dolj), 
         DFFIT = dffits(DJ_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(DJ_lav_lm_ols$coefficients) / nrow(RO_Census_Dolj)), 
         Rezid_Std = rstudent(DJ_lav_lm_ols), Leverage = hatvalues(DJ_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(DJ_lav_lm_ols)), 
         DFBETA = dfbetas(DJ_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Dolj)))

# e) Data Distributions
RO_Census_Dolj %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Dolj$Rank, 
