# 2. Robust

# a) Power Law
DJ_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Dolj)
summary(DJ_pw_lm_rob)
DJ_pred_pw_lm_rob <- exp(predict(DJ_pw_lm_rob, newdata = RO_Census_Dolj, 
                                 interval = "prediction", level = 0.95))
DJ_RSquared_pw_rob <- 1 - sum((log(RO_Census_Dolj$Population) - fitted(DJ_pw_lm_rob))^2) / 
  sum((log(RO_Census_Dolj$Population) - mean(log(RO_Census_Dolj$Population)))^2)

# b) Zipf_Mandelbrot Law
DJ_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Dolj, "Population", "Rank")
DJ_ZM_m_rob <- DJ_ZM_prm_rob$m
DJ_ZM_alpha_rob <- DJ_ZM_prm_rob$alpha_ZM
DJ_ZM_cst_rob <- DJ_ZM_prm_rob$constant_ZM
DJ_ZM_lm_rob <- rlm(log(RO_Census_Dolj$Population) ~ log(RO_Census_Dolj$Rank + DJ_ZM_m_rob))
summary(DJ_ZM_lm_rob)
DJ_pred_ZM_lm_rob <- exp(predict(DJ_ZM_lm_rob, newdata = RO_Census_Dolj, 
                                 interval = "prediction", level = 0.95))
DJ_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Dolj$Population) - fitted(DJ_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Dolj$Population) - mean(log(RO_Census_Dolj$Population)))^2)

# c) Exponential Law
DJ_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Dolj)
summary(DJ_exp_lm_rob)
DJ_pred_exp_lm_rob <- exp(predict(DJ_exp_lm_rob, newdata = RO_Census_Dolj, 
                                  interval = "prediction", level = 0.95))
DJ_RSquared_exp_rob <- 1 - sum((log(RO_Census_Dolj$Population) - fitted(DJ_exp_lm_rob))^2) / 
  sum((log(RO_Census_Dolj$Population) - mean(log(RO_Census_Dolj$Population)))^2)

# d) Lavalette Function
RO_Census_Dolj <- RO_Census_Dolj %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Dolj) - Rank + 1))
)
DJ_lav_lm_rob <- rlm(log(RO_Census_Dolj$Population) ~ RO_Census_Dolj$Lav_exp)
summary(DJ_lav_lm_rob)
DJ_lav_kst_rob <- exp(signif(DJ_lav_lm_rob$coef[[1]], 4))
DJ_lav_chi_rob <- signif(DJ_lav_lm_rob$coef[[2]], 4)
DJ_pred_lav_lm_rob <- exp(predict(DJ_lav_lm_rob, newdata = RO_Census_Dolj, 
                                  interval = "prediction", level = 0.95))
DJ_RSquared_lav_rob <- 1 - sum((log(RO_Census_Dolj$Population) - fitted(DJ_lav_lm_rob))^2) / 
  sum((log(RO_Census_Dolj$Population) - mean(log(RO_Census_Dolj$Population)))^2)

# e) Data Distributions
RO_Census_Dolj %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Dolj$Rank, 
