# XVIII. Galati

# 1. OLS
RO_Census_Galati <- RO_Census_rank %>% filter(Judet_Name == "GALATI")
#View(RO_Census_Galati)

# a) Power Law
GL_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Galati)
summary(GL_pw_lm_ols)
GL_pred_pw_lm_ols <- exp(predict(GL_pw_lm_ols, newdata = RO_Census_Galati, 
                                 interval = "prediction", level = 0.95))
GL_pw_out_ols <- RO_Census_Galati %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(GL_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Galati), 
         DFFIT = dffits(GL_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(GL_pw_lm_ols$coefficients) / nrow(RO_Census_Galati)), 
         Rezid_Std = rstudent(GL_pw_lm_ols), Leverage = hatvalues(GL_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(GL_pw_lm_ols)), 
         DFBETA = dfbetas(GL_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Galati)))

# b) Zipf_Mandelbrot Law
GL_ZM_prm_ols <- get_ZM_Param("RO_Census_Galati", "Population", "Rank")
GL_ZM_m_ols <- GL_ZM_prm_ols$m
GL_ZM_alpha_ols <- GL_ZM_prm_ols$alpha_ZM
GL_ZM_cst_ols <- GL_ZM_prm_ols$constant_ZM
GL_ZM_lm_ols <- lm(log(RO_Census_Galati$Population) ~ log(RO_Census_Galati$Rank + GL_ZM_m_ols))
summary(GL_ZM_lm_ols)
GL_pred_ZM_lm_ols <- exp(predict(GL_ZM_lm_ols, newdata = RO_Census_Galati, 
                                 interval = "prediction", level = 0.95))
GL_ZM_out_ols <- RO_Census_Galati %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(GL_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Galati), 
         DFFIT = dffits(GL_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(GL_ZM_lm_ols$coefficients) / nrow(RO_Census_Galati)), 
         Rezid_Std = rstudent(GL_ZM_lm_ols), Leverage = hatvalues(GL_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(GL_ZM_lm_ols)), 
         DFBETA = dfbetas(GL_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Galati)))

# c) Exponential Law
GL_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Galati)
summary(GL_exp_lm_ols)
GL_pred_exp_lm_ols <- exp(predict(GL_exp_lm_ols, newdata = RO_Census_Galati, 
                                  interval = "prediction", level = 0.95))
GL_exp_out_ols <- RO_Census_Galati %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(GL_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Galati), 
         DFFIT = dffits(GL_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(GL_exp_lm_ols$coefficients) / nrow(RO_Census_Galati)), 
         Rezid_Std = rstudent(GL_exp_lm_ols), Leverage = hatvalues(GL_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(GL_exp_lm_ols)), 
         DFBETA = dfbetas(GL_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Galati)))

# d) Lavalette Function
RO_Census_Galati <- RO_Census_Galati %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Galati) - Rank + 1))
)
GL_lav_lm_ols <- lm(log(RO_Census_Galati$Population) ~ RO_Census_Galati$Lav_exp)
summary(GL_lav_lm_ols)
GL_lav_kst_ols <- exp(signif(GL_lav_lm_ols$coef[[1]], 4))
GL_lav_chi_ols <- signif(GL_lav_lm_ols$coef[[2]], 4)
GL_pred_lav_lm_ols <- exp(predict(GL_lav_lm_ols, newdata = RO_Census_Galati, 
                                  interval = "prediction", level = 0.95))
GL_lav_out_ols <- RO_Census_Galati %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(GL_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Galati), 
         DFFIT = dffits(GL_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(GL_lav_lm_ols$coefficients) / nrow(RO_Census_Galati)), 
         Rezid_Std = rstudent(GL_lav_lm_ols), Leverage = hatvalues(GL_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(GL_lav_lm_ols)), 
         DFBETA = dfbetas(GL_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Galati)))

# e) Data Distributions
RO_Census_Galati %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Galati$Rank, 
                              Population = GL_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(GL_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(GL_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(GL_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Galati$Rank, 
                              Population = GL_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(GL_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(GL_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(GL_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Galati$Rank, 
                              Population = GL_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(GL_ZM_cst_ols, 4), "%.%", "(",
                           signif(GL_ZM_m_ols, 4), "+ x)^", signif(GL_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(summary(GL_ZM_lm_ols)$r.squared, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Galati$Rank, 
                              Population = GL_pred_lav_lm_ols[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(GL_lav_kst_ols, 4), "%.%", "x^",
                           -signif(GL_lav_chi_ols, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(summary(GL_lav_lm_ols)$r.squared, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Galati judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# Linear Regressions
grid.arrange(
