# f) Extract Outliers
Galati_Outliers <- bind_rows(
  (GL_pw_out_ols %>% mutate(Function_Name = "Power")),
  (GL_ZM_out_ols %>% mutate(Function_Name = "Zipf-Mandelbrot")),
  (GL_exp_out_ols %>% mutate(Function_Name = "Exponential")),
  (GL_lav_out_ols %>% mutate(Function_Name = "Lavalette"))
) %>% mutate(DFBETA_intercept = round(DFBETA[,1], 8), 
             DFBETA_var_x = round(DFBETA[,2], 8)) %>% dplyr::select(-DFBETA)

GL_out <- get_outliers(Galati_Outliers, RO_Census_Galati)

GL_out_ols <- RO_Census_Galati %>% inner_join(
  bind_rows(
    (GL_out$PW %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>% 
       dplyr::select(Rank) %>% distinct()),
    (GL_out$ZM %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (GL_out$LAV %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (GL_out$EXP %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct())
  ) %>% count(Rank) %>% arrange(desc(n)) %>% filter(n >= mean(n))) %>% 
  dplyr::select(-n)

# g) Extract regression metrics
GL_regmet_ols <- as.data.frame(list(Judet_Name = "GALATI",
