  mutate(Judet_Name = "GALATI")

# g) Extract MAE/RMSE on head, body, tail
RO_Census_Galati_rob <- RO_Census_Galati %>% 
  mutate(PW_Y_Pred = (predict(GL_pw_lm_rob, newdata = RO_Census_Galati, 
                              interval = "prediction", level = 0.95))[,1], 
         ZM_Y_Pred = (predict(GL_ZM_lm_rob, newdata = RO_Census_Galati, 
                              interval = "prediction", level = 0.95))[,1],
         EXP_Y_Pred = (predict(GL_exp_lm_rob, newdata = RO_Census_Galati, 
                               interval = "prediction", level = 0.95))[,1], 
         LAV_Y_Pred = (predict(GL_lav_lm_rob, newdata = RO_Census_Galati, 
                               interval = "prediction", level = 0.95))[,1])

# Head
GL_rob_hd <- RO_Census_Galati_rob %>% filter(Rank <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(GL_rob_hd$Population) - GL_rob_hd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(GL_rob_hd$Population) - GL_rob_hd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(GL_rob_hd$Population) - GL_rob_hd$ZM_Y_Pred))), 4),
          signif(mean(abs((log(GL_rob_hd$Population) - GL_rob_hd$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(GL_rob_hd$Population)) - GL_rob_hd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(GL_rob_hd$Population)) - GL_rob_hd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(GL_rob_hd$Population)) - GL_rob_hd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(GL_rob_hd$Population)) - GL_rob_hd$LAV_Y_Pred) ^ 2)), 4))
))

# Tail
GL_rob_tl <- RO_Census_Galati_rob %>% arrange(desc(Rank)) %>% 
  filter(row_number() <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(GL_rob_tl$Population) - GL_rob_tl$PW_Y_Pred))), 4), 
          signif(mean(abs((log(GL_rob_tl$Population) - GL_rob_tl$EXP_Y_Pred))), 4),
          signif(mean(abs((log(GL_rob_tl$Population) - GL_rob_tl$ZM_Y_Pred))), 4),
          signif(mean(abs((log(GL_rob_tl$Population) - GL_rob_tl$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(GL_rob_tl$Population)) - GL_rob_tl$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(GL_rob_tl$Population)) - GL_rob_tl$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(GL_rob_tl$Population)) - GL_rob_tl$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(GL_rob_tl$Population)) - GL_rob_tl$LAV_Y_Pred) ^ 2)), 4))
))

# Body
GL_rob_bd <- RO_Census_Galati_rob %>% anti_join(GL_rob_hd) %>% anti_join(GL_rob_tl)

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(GL_rob_bd$Population) - GL_rob_bd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(GL_rob_bd$Population) - GL_rob_bd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(GL_rob_bd$Population) - GL_rob_bd$ZM_Y_Pred))), 4),
          signif(mean(abs((log(GL_rob_bd$Population) - GL_rob_bd$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(GL_rob_bd$Population)) - GL_rob_bd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(GL_rob_bd$Population)) - GL_rob_bd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(GL_rob_bd$Population)) - GL_rob_bd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(GL_rob_bd$Population)) - GL_rob_bd$LAV_Y_Pred) ^ 2)), 4))
))

# Final
GL_res_rob <- as.data.frame(bind_rows(
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(GL_rob_hd$Population) - GL_rob_hd$PW_Y_Pred))), 4), 
            signif(mean(abs((log(GL_rob_hd$Population) - GL_rob_hd$EXP_Y_Pred))), 4),
            signif(mean(abs((log(GL_rob_hd$Population) - GL_rob_hd$ZM_Y_Pred))), 4),
            signif(mean(abs((log(GL_rob_hd$Population) - GL_rob_hd$LAV_Y_Pred))), 4)),
    RMSE = c(signif(sqrt(mean(((log(GL_rob_hd$Population)) - GL_rob_hd$PW_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(GL_rob_hd$Population)) - GL_rob_hd$EXP_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(GL_rob_hd$Population)) - GL_rob_hd$ZM_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(GL_rob_hd$Population)) - GL_rob_hd$LAV_Y_Pred) ^ 2)), 4)),
    Data_Part = "Head"
  )),
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(GL_rob_tl$Population) - GL_rob_tl$PW_Y_Pred))), 4), 
            signif(mean(abs((log(GL_rob_tl$Population) - GL_rob_tl$EXP_Y_Pred))), 4),
            signif(mean(abs((log(GL_rob_tl$Population) - GL_rob_tl$ZM_Y_Pred))), 4),
            signif(mean(abs((log(GL_rob_tl$Population) - GL_rob_tl$LAV_Y_Pred))), 4)),
    RMSE = c(signif(sqrt(mean(((log(GL_rob_tl$Population)) - GL_rob_tl$PW_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(GL_rob_tl$Population)) - GL_rob_tl$EXP_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(GL_rob_tl$Population)) - GL_rob_tl$ZM_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(GL_rob_tl$Population)) - GL_rob_tl$LAV_Y_Pred) ^ 2)), 4)),
    Data_Part = "Tail"
  )),
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(GL_rob_bd$Population) - GL_rob_bd$PW_Y_Pred))), 4), 
            signif(mean(abs((log(GL_rob_bd$Population) - GL_rob_bd$EXP_Y_Pred))), 4),
