    RMSE = c(signif(sqrt(mean(((log(GL_rob_bd$Population)) - GL_rob_bd$PW_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(GL_rob_bd$Population)) - GL_rob_bd$EXP_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(GL_rob_bd$Population)) - GL_rob_bd$ZM_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(GL_rob_bd$Population)) - GL_rob_bd$LAV_Y_Pred) ^ 2)), 4)),
    Data_Part = "Body"
  )),
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(RO_Census_Galati$Population) - 
                               (predict(GL_pw_lm_rob, newdata = RO_Census_Galati, 
                                        interval = "prediction", level = 0.95))))), 4), 
            signif(mean(abs((log(RO_Census_Galati$Population) - 
                               (predict(GL_exp_lm_rob, newdata = RO_Census_Galati, 
                                        interval = "prediction", level = 0.95))))), 4),
            signif(mean(abs((log(RO_Census_Galati$Population) - 
                               (predict(GL_ZM_lm_rob, newdata = RO_Census_Galati, 
                                        interval = "prediction", level = 0.95))))), 4),
            signif(mean(abs((log(RO_Census_Galati$Population) - 
                               (predict(GL_lav_lm_rob, newdata = RO_Census_Galati, 
                                        interval = "prediction", level = 0.95))))), 4)),
    RMSE = c(signif(sqrt(mean(((log(RO_Census_Galati$Population)) - 
                                 (predict(GL_pw_lm_rob, newdata = RO_Census_Galati, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Galati$Population)) - 
                                 (predict(GL_exp_lm_rob, newdata = RO_Census_Galati, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Galati$Population)) - 
                                 (predict(GL_ZM_lm_rob, newdata = RO_Census_Galati, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Galati$Population)) - 
                                 (predict(GL_lav_lm_rob, newdata = RO_Census_Galati, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4)),
    Data_Part = "Full"
  ))
)) %>% mutate(Regression_Type = "Robust", Judet_Name = "GALATI")

