# XIX. Giurgiu

# 1. OLS
RO_Census_Giurgiu <- RO_Census_rank %>% filter(Judet_Name == "GIURGIU")
#View(RO_Census_Giurgiu)

# a) Power Law
GR_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Giurgiu)
summary(GR_pw_lm_ols)
GR_pred_pw_lm_ols <- exp(predict(GR_pw_lm_ols, newdata = RO_Census_Giurgiu, 
                                 interval = "prediction", level = 0.95))
GR_pw_out_ols <- RO_Census_Giurgiu %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(GR_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Giurgiu), 
         DFFIT = dffits(GR_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(GR_pw_lm_ols$coefficients) / nrow(RO_Census_Giurgiu)), 
         Rezid_Std = rstudent(GR_pw_lm_ols), Leverage = hatvalues(GR_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(GR_pw_lm_ols)), 
         DFBETA = dfbetas(GR_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Giurgiu)))

# b) Zipf_Mandelbrot Law
GR_ZM_prm_ols <- get_ZM_Param("RO_Census_Giurgiu", "Population", "Rank")
GR_ZM_m_ols <- GR_ZM_prm_ols$m
GR_ZM_alpha_ols <- GR_ZM_prm_ols$alpha_ZM
GR_ZM_cst_ols <- GR_ZM_prm_ols$constant_ZM
GR_ZM_lm_ols <- lm(log(RO_Census_Giurgiu$Population) ~ log(RO_Census_Giurgiu$Rank + GR_ZM_m_ols))
summary(GR_ZM_lm_ols)
GR_pred_ZM_lm_ols <- exp(predict(GR_ZM_lm_ols, newdata = RO_Census_Giurgiu, 
                                 interval = "prediction", level = 0.95))
GR_ZM_out_ols <- RO_Census_Giurgiu %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(GR_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Giurgiu), 
         DFFIT = dffits(GR_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(GR_ZM_lm_ols$coefficients) / nrow(RO_Census_Giurgiu)), 
         Rezid_Std = rstudent(GR_ZM_lm_ols), Leverage = hatvalues(GR_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(GR_ZM_lm_ols)), 
         DFBETA = dfbetas(GR_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Giurgiu)))

# c) Exponential Law
GR_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Giurgiu)
summary(GR_exp_lm_ols)
GR_pred_exp_lm_ols <- exp(predict(GR_exp_lm_ols, newdata = RO_Census_Giurgiu, 
                                  interval = "prediction", level = 0.95))
GR_exp_out_ols <- RO_Census_Giurgiu %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(GR_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Giurgiu), 
         DFFIT = dffits(GR_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(GR_exp_lm_ols$coefficients) / nrow(RO_Census_Giurgiu)), 
         Rezid_Std = rstudent(GR_exp_lm_ols), Leverage = hatvalues(GR_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(GR_exp_lm_ols)), 
         DFBETA = dfbetas(GR_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Giurgiu)))

# d) Lavalette Function
RO_Census_Giurgiu <- RO_Census_Giurgiu %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Giurgiu) - Rank + 1))
)
GR_lav_lm_ols <- lm(log(RO_Census_Giurgiu$Population) ~ RO_Census_Giurgiu$Lav_exp)
summary(GR_lav_lm_ols)
GR_lav_kst_ols <- exp(signif(GR_lav_lm_ols$coef[[1]], 4))
GR_lav_chi_ols <- signif(GR_lav_lm_ols$coef[[2]], 4)
GR_pred_lav_lm_ols <- exp(predict(GR_lav_lm_ols, newdata = RO_Census_Giurgiu, 
                                  interval = "prediction", level = 0.95))
GR_lav_out_ols <- RO_Census_Giurgiu %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(GR_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Giurgiu), 
         DFFIT = dffits(GR_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(GR_lav_lm_ols$coefficients) / nrow(RO_Census_Giurgiu)), 
         Rezid_Std = rstudent(GR_lav_lm_ols), Leverage = hatvalues(GR_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(GR_lav_lm_ols)), 
         DFBETA = dfbetas(GR_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Giurgiu)))

# e) Data Distributions
RO_Census_Giurgiu %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Giurgiu$Rank, 
                              Population = GR_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(GR_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(GR_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(GR_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Giurgiu$Rank, 
                              Population = GR_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(GR_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(GR_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(GR_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Giurgiu$Rank, 
                              Population = GR_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(GR_ZM_cst_ols, 4), "%.%", "(",
                           signif(GR_ZM_m_ols, 4), "+ x)^", signif(GR_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(summary(GR_ZM_lm_ols)$r.squared, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Giurgiu$Rank, 
                              Population = GR_pred_lav_lm_ols[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(GR_lav_kst_ols, 4), "%.%", "x^",
                           -signif(GR_lav_chi_ols, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(summary(GR_lav_lm_ols)$r.squared, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Giurgiu judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# Linear Regressions
grid.arrange(
  (RO_Census_Giurgiu %>%
     ggplot(aes(x = log(Rank), y = log(Population))) +
