     theme(plot.title = element_text(hjust = 0.5))
  ),
  ncol = 2, nrow = 2)

# f) Extract Outliers
Giurgiu_Outliers <- bind_rows(
  (GR_pw_out_ols %>% mutate(Function_Name = "Power")),
  (GR_ZM_out_ols %>% mutate(Function_Name = "Zipf-Mandelbrot")),
  (GR_exp_out_ols %>% mutate(Function_Name = "Exponential")),
  (GR_lav_out_ols %>% mutate(Function_Name = "Lavalette"))
) %>% mutate(DFBETA_intercept = round(DFBETA[,1], 8), 
             DFBETA_var_x = round(DFBETA[,2], 8)) %>% dplyr::select(-DFBETA)

GR_out <- get_outliers(Giurgiu_Outliers, RO_Census_Giurgiu)

GR_out_ols <- RO_Census_Giurgiu %>% inner_join(
  bind_rows(
    (GR_out$PW %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>% 
       dplyr::select(Rank) %>% distinct()),
    (GR_out$ZM %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (GR_out$LAV %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (GR_out$EXP %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct())
  ) %>% count(Rank) %>% arrange(desc(n)) %>% filter(n == max(n))) %>% 
  dplyr::select(-n)

# g) Extract regression metrics
GR_regmet_ols <- as.data.frame(list(Judet_Name = "GIURGIU",
                                    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
                                    R_Squared = c(signif(summary(GR_pw_lm_ols)$r.squared, 4), 
                                                  signif(summary(GR_exp_lm_ols)$r.squared, 4),
                                                  signif(summary(GR_ZM_lm_ols)$r.squared, 4),
                                                  signif(summary(GR_lav_lm_ols)$r.squared, 4)),
                                    Adj_R_Squared = c(signif(summary(GR_pw_lm_ols)$adj.r.squared, 4), 
                                                      signif(summary(GR_exp_lm_ols)$adj.r.squared, 4),
                                                      signif(summary(GR_ZM_lm_ols)$adj.r.squared, 4),
                                                      signif(summary(GR_lav_lm_ols)$adj.r.squared, 4)),
                                    AIC = c(signif(AIC(GR_pw_lm_ols), 4), signif(AIC(GR_exp_lm_ols), 4), 
