# XX. Gorj

# 1. OLS
RO_Census_Gorj <- RO_Census_rank %>% filter(Judet_Name == "GORJ")
#View(RO_Census_Gorj)

# a) Power Law
GJ_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Gorj)
summary(GJ_pw_lm_ols)
GJ_pred_pw_lm_ols <- exp(predict(GJ_pw_lm_ols, newdata = RO_Census_Gorj, 
                                 interval = "prediction", level = 0.95))
GJ_pw_out_ols <- RO_Census_Gorj %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(GJ_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Gorj), 
         DFFIT = dffits(GJ_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(GJ_pw_lm_ols$coefficients) / nrow(RO_Census_Gorj)), 
         Rezid_Std = rstudent(GJ_pw_lm_ols), Leverage = hatvalues(GJ_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(GJ_pw_lm_ols)), 
         DFBETA = dfbetas(GJ_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Gorj)))

# b) Zipf_Mandelbrot Law
GJ_ZM_prm_ols <- get_ZM_Param("RO_Census_Gorj", "Population", "Rank")
GJ_ZM_m_ols <- GJ_ZM_prm_ols$m
GJ_ZM_alpha_ols <- GJ_ZM_prm_ols$alpha_ZM
GJ_ZM_cst_ols <- GJ_ZM_prm_ols$constant_ZM
GJ_ZM_lm_ols <- lm(log(RO_Census_Gorj$Population) ~ log(RO_Census_Gorj$Rank + GJ_ZM_m_ols))
summary(GJ_ZM_lm_ols)
GJ_pred_ZM_lm_ols <- exp(predict(GJ_ZM_lm_ols, newdata = RO_Census_Gorj, 
                                 interval = "prediction", level = 0.95))
GJ_ZM_out_ols <- RO_Census_Gorj %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(GJ_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Gorj), 
         DFFIT = dffits(GJ_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(GJ_ZM_lm_ols$coefficients) / nrow(RO_Census_Gorj)), 
         Rezid_Std = rstudent(GJ_ZM_lm_ols), Leverage = hatvalues(GJ_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(GJ_ZM_lm_ols)), 
         DFBETA = dfbetas(GJ_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Gorj)))

# c) Exponential Law
GJ_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Gorj)
summary(GJ_exp_lm_ols)
GJ_pred_exp_lm_ols <- exp(predict(GJ_exp_lm_ols, newdata = RO_Census_Gorj, 
                                  interval = "prediction", level = 0.95))
GJ_exp_out_ols <- RO_Census_Gorj %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(GJ_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Gorj), 
         DFFIT = dffits(GJ_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(GJ_exp_lm_ols$coefficients) / nrow(RO_Census_Gorj)), 
         Rezid_Std = rstudent(GJ_exp_lm_ols), Leverage = hatvalues(GJ_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(GJ_exp_lm_ols)), 
         DFBETA = dfbetas(GJ_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Gorj)))

# d) Lavalette Function
RO_Census_Gorj <- RO_Census_Gorj %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Gorj) - Rank + 1))
)
GJ_lav_lm_ols <- lm(log(RO_Census_Gorj$Population) ~ RO_Census_Gorj$Lav_exp)
summary(GJ_lav_lm_ols)
GJ_lav_kst_ols <- exp(signif(GJ_lav_lm_ols$coef[[1]], 4))
GJ_lav_chi_ols <- signif(GJ_lav_lm_ols$coef[[2]], 4)
GJ_pred_lav_lm_ols <- exp(predict(GJ_lav_lm_ols, newdata = RO_Census_Gorj, 
                                  interval = "prediction", level = 0.95))
GJ_lav_out_ols <- RO_Census_Gorj %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(GJ_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Gorj), 
         DFFIT = dffits(GJ_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(GJ_lav_lm_ols$coefficients) / nrow(RO_Census_Gorj)), 
         Rezid_Std = rstudent(GJ_lav_lm_ols), Leverage = hatvalues(GJ_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(GJ_lav_lm_ols)), 
         DFBETA = dfbetas(GJ_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Gorj)))

# e) Data Distributions
RO_Census_Gorj %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Gorj$Rank, 
                              Population = GJ_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(GJ_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(GJ_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(GJ_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Gorj$Rank, 
                              Population = GJ_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(GJ_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(GJ_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(GJ_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Gorj$Rank, 
                              Population = GJ_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(GJ_ZM_cst_ols, 4), "%.%", "(",
                           signif(GJ_ZM_m_ols, 4), "+ x)^", signif(GJ_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(summary(GJ_ZM_lm_ols)$r.squared, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Gorj$Rank, 
                              Population = GJ_pred_lav_lm_ols[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(GJ_lav_kst_ols, 4), "%.%", "x^",
                           -signif(GJ_lav_chi_ols, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(summary(GJ_lav_lm_ols)$r.squared, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Gorj judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# Linear Regressions
grid.arrange(
