# f) Extract Outliers
Gorj_Outliers <- bind_rows(
  (GJ_pw_out_ols %>% mutate(Function_Name = "Power")),
  (GJ_ZM_out_ols %>% mutate(Function_Name = "Zipf-Mandelbrot")),
  (GJ_exp_out_ols %>% mutate(Function_Name = "Exponential")),
  (GJ_lav_out_ols %>% mutate(Function_Name = "Lavalette"))
) %>% mutate(DFBETA_intercept = round(DFBETA[,1], 8), 
             DFBETA_var_x = round(DFBETA[,2], 8)) %>% dplyr::select(-DFBETA)

GJ_out <- get_outliers(Gorj_Outliers, RO_Census_Gorj)

GJ_out_ols <- RO_Census_Gorj %>% inner_join(
  bind_rows(
    (GJ_out$PW %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>% 
       dplyr::select(Rank) %>% distinct()),
    (GJ_out$ZM %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (GJ_out$LAV %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (GJ_out$EXP %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct())
  ) %>% count(Rank) %>% arrange(desc(n)) %>% filter(n >= mean(n))) %>% 
  dplyr::select(-n)

