                                            signif(BIC(GJ_ZM_lm_ols), 4), signif(BIC(GJ_lav_lm_ols), 4)),
                                    MAE = c(signif(mean(abs((log(RO_Census_Gorj$Population) - 
                                                               (predict(GJ_pw_lm_ols, newdata = RO_Census_Gorj, 
                                                                        interval = "prediction", level = 0.95))))), 4), 
                                            signif(mean(abs((log(RO_Census_Gorj$Population) - 
                                                               (predict(GJ_exp_lm_ols, newdata = RO_Census_Gorj, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Gorj$Population) - 
                                                               (predict(GJ_ZM_lm_ols, newdata = RO_Census_Gorj, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Gorj$Population) - 
                                                               (predict(GJ_lav_lm_ols, newdata = RO_Census_Gorj, 
                                                                        interval = "prediction", level = 0.95))))), 4)),
                                    RMSE = c(signif(sqrt(mean(((log(RO_Census_Gorj$Population)) - 
                                                                 (predict(GJ_pw_lm_ols, newdata = RO_Census_Gorj, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Gorj$Population)) - 
                                                                 (predict(GJ_exp_lm_ols, newdata = RO_Census_Gorj, 
