GJ_rob_bd <- RO_Census_Gorj_rob %>% anti_join(GJ_rob_hd) %>% anti_join(GJ_rob_tl)

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(GJ_rob_bd$Population) - GJ_rob_bd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(GJ_rob_bd$Population) - GJ_rob_bd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(GJ_rob_bd$Population) - GJ_rob_bd$ZM_Y_Pred))), 4),
          signif(mean(abs((log(GJ_rob_bd$Population) - GJ_rob_bd$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(GJ_rob_bd$Population)) - GJ_rob_bd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(GJ_rob_bd$Population)) - GJ_rob_bd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(GJ_rob_bd$Population)) - GJ_rob_bd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(GJ_rob_bd$Population)) - GJ_rob_bd$LAV_Y_Pred) ^ 2)), 4))
))

