# XXI. Harghita

# 1. OLS
RO_Census_Harghita <- RO_Census_rank %>% filter(Judet_Name == "HARGHITA")
#View(RO_Census_Harghita)

# a) Power Law
HR_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Harghita)
summary(HR_pw_lm_ols)
HR_pred_pw_lm_ols <- exp(predict(HR_pw_lm_ols, newdata = RO_Census_Harghita, 
                                 interval = "prediction", level = 0.95))
HR_pw_out_ols <- RO_Census_Harghita %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(HR_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Harghita), 
         DFFIT = dffits(HR_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(HR_pw_lm_ols$coefficients) / nrow(RO_Census_Harghita)), 
         Rezid_Std = rstudent(HR_pw_lm_ols), Leverage = hatvalues(HR_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(HR_pw_lm_ols)), 
         DFBETA = dfbetas(HR_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Harghita)))

# b) Zipf_Mandelbrot Law
HR_ZM_prm_ols <- get_ZM_Param("RO_Census_Harghita", "Population", "Rank")
HR_ZM_m_ols <- HR_ZM_prm_ols$m
HR_ZM_alpha_ols <- HR_ZM_prm_ols$alpha_ZM
HR_ZM_cst_ols <- HR_ZM_prm_ols$constant_ZM
HR_ZM_lm_ols <- lm(log(RO_Census_Harghita$Population) ~ log(RO_Census_Harghita$Rank + HR_ZM_m_ols))
summary(HR_ZM_lm_ols)
HR_pred_ZM_lm_ols <- exp(predict(HR_ZM_lm_ols, newdata = RO_Census_Harghita, 
                                 interval = "prediction", level = 0.95))
HR_ZM_out_ols <- RO_Census_Harghita %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(HR_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Harghita), 
         DFFIT = dffits(HR_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(HR_ZM_lm_ols$coefficients) / nrow(RO_Census_Harghita)), 
         Rezid_Std = rstudent(HR_ZM_lm_ols), Leverage = hatvalues(HR_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(HR_ZM_lm_ols)), 
         DFBETA = dfbetas(HR_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Harghita)))

# c) Exponential Law
HR_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Harghita)
summary(HR_exp_lm_ols)
HR_pred_exp_lm_ols <- exp(predict(HR_exp_lm_ols, newdata = RO_Census_Harghita, 
                                  interval = "prediction", level = 0.95))
HR_exp_out_ols <- RO_Census_Harghita %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(HR_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Harghita), 
         DFFIT = dffits(HR_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(HR_exp_lm_ols$coefficients) / nrow(RO_Census_Harghita)), 
         Rezid_Std = rstudent(HR_exp_lm_ols), Leverage = hatvalues(HR_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(HR_exp_lm_ols)), 
         DFBETA = dfbetas(HR_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Harghita)))

# d) Lavalette Function
RO_Census_Harghita <- RO_Census_Harghita %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Harghita) - Rank + 1))
)
HR_lav_lm_ols <- lm(log(RO_Census_Harghita$Population) ~ RO_Census_Harghita$Lav_exp)
summary(HR_lav_lm_ols)
HR_lav_kst_ols <- exp(signif(HR_lav_lm_ols$coef[[1]], 4))
HR_lav_chi_ols <- signif(HR_lav_lm_ols$coef[[2]], 4)
HR_pred_lav_lm_ols <- exp(predict(HR_lav_lm_ols, newdata = RO_Census_Harghita, 
                                  interval = "prediction", level = 0.95))
HR_lav_out_ols <- RO_Census_Harghita %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(HR_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Harghita), 
         DFFIT = dffits(HR_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(HR_lav_lm_ols$coefficients) / nrow(RO_Census_Harghita)), 
         Rezid_Std = rstudent(HR_lav_lm_ols), Leverage = hatvalues(HR_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(HR_lav_lm_ols)), 
         DFBETA = dfbetas(HR_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Harghita)))

# e) Data Distributions
RO_Census_Harghita %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Harghita$Rank, 
                              Population = HR_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(HR_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(HR_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(HR_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Harghita$Rank, 
                              Population = HR_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(HR_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(HR_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(HR_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Harghita$Rank, 
                              Population = HR_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(HR_ZM_cst_ols, 4), "%.%", "(",
                           signif(HR_ZM_m_ols, 4), "+ x)^", signif(HR_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(summary(HR_ZM_lm_ols)$r.squared, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Harghita$Rank, 
                              Population = HR_pred_lav_lm_ols[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(HR_lav_kst_ols, 4), "%.%", "x^",
                           -signif(HR_lav_chi_ols, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(summary(HR_lav_lm_ols)$r.squared, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Harghita judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# Linear Regressions
grid.arrange(
  (RO_Census_Harghita %>%
     ggplot(aes(x = log(Rank), y = log(Population))) +
