  ncol = 2, nrow = 2)

# f) Extract Outliers
Harghita_Outliers <- bind_rows(
  (HR_pw_out_ols %>% mutate(Function_Name = "Power")),
  (HR_ZM_out_ols %>% mutate(Function_Name = "Zipf-Mandelbrot")),
  (HR_exp_out_ols %>% mutate(Function_Name = "Exponential")),
  (HR_lav_out_ols %>% mutate(Function_Name = "Lavalette"))
) %>% mutate(DFBETA_intercept = round(DFBETA[,1], 8), 
             DFBETA_var_x = round(DFBETA[,2], 8)) %>% dplyr::select(-DFBETA)

HR_out <- get_outliers(Harghita_Outliers, RO_Census_Harghita)

HR_out_ols <- RO_Census_Harghita %>% inner_join(
  bind_rows(
    (HR_out$PW %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>% 
       dplyr::select(Rank) %>% distinct()),
    (HR_out$ZM %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (HR_out$LAV %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (HR_out$EXP %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct())
  ) %>% count(Rank) %>% arrange(desc(n)) %>% filter(n >= mean(n))) %>% 
  dplyr::select(-n)

# g) Extract regression metrics
