                                            signif(AIC(HR_ZM_lm_ols), 4), signif(AIC(HR_lav_lm_ols), 4)),
                                    BIC = c(signif(BIC(HR_pw_lm_ols), 4), signif(BIC(HR_exp_lm_ols), 4), 
                                            signif(BIC(HR_ZM_lm_ols), 4), signif(BIC(HR_lav_lm_ols), 4)),
                                    MAE = c(signif(mean(abs((log(RO_Census_Harghita$Population) - 
                                                               (predict(HR_pw_lm_ols, newdata = RO_Census_Harghita, 
                                                                        interval = "prediction", level = 0.95))))), 4), 
                                            signif(mean(abs((log(RO_Census_Harghita$Population) - 
                                                               (predict(HR_exp_lm_ols, newdata = RO_Census_Harghita, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Harghita$Population) - 
                                                               (predict(HR_ZM_lm_ols, newdata = RO_Census_Harghita, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Harghita$Population) - 
                                                               (predict(HR_lav_lm_ols, newdata = RO_Census_Harghita, 
                                                                        interval = "prediction", level = 0.95))))), 4)),
                                    RMSE = c(signif(sqrt(mean(((log(RO_Census_Harghita$Population)) - 
                                                                 (predict(HR_pw_lm_ols, newdata = RO_Census_Harghita, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Harghita$Population)) - 
