# 2. Robust

# a) Power Law
HR_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Harghita)
summary(HR_pw_lm_rob)
HR_pred_pw_lm_rob <- exp(predict(HR_pw_lm_rob, newdata = RO_Census_Harghita, 
                                 interval = "prediction", level = 0.95))
HR_RSquared_pw_rob <- 1 - sum((log(RO_Census_Harghita$Population) - fitted(HR_pw_lm_rob))^2) / 
  sum((log(RO_Census_Harghita$Population) - mean(log(RO_Census_Harghita$Population)))^2)

# b) Zipf_Mandelbrot Law
HR_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Harghita, "Population", "Rank")
HR_ZM_m_rob <- HR_ZM_prm_rob$m
HR_ZM_alpha_rob <- HR_ZM_prm_rob$alpha_ZM
HR_ZM_cst_rob <- HR_ZM_prm_rob$constant_ZM
HR_ZM_lm_rob <- rlm(log(RO_Census_Harghita$Population) ~ log(RO_Census_Harghita$Rank + HR_ZM_m_rob))
summary(HR_ZM_lm_rob)
HR_pred_ZM_lm_rob <- exp(predict(HR_ZM_lm_rob, newdata = RO_Census_Harghita, 
                                 interval = "prediction", level = 0.95))
HR_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Harghita$Population) - fitted(HR_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Harghita$Population) - mean(log(RO_Census_Harghita$Population)))^2)

# c) Exponential Law
HR_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Harghita)
summary(HR_exp_lm_rob)
HR_pred_exp_lm_rob <- exp(predict(HR_exp_lm_rob, newdata = RO_Census_Harghita, 
                                  interval = "prediction", level = 0.95))
HR_RSquared_exp_rob <- 1 - sum((log(RO_Census_Harghita$Population) - fitted(HR_exp_lm_rob))^2) / 
  sum((log(RO_Census_Harghita$Population) - mean(log(RO_Census_Harghita$Population)))^2)

# d) Lavalette Function
RO_Census_Harghita <- RO_Census_Harghita %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Harghita) - Rank + 1))
)
HR_lav_lm_rob <- rlm(log(RO_Census_Harghita$Population) ~ RO_Census_Harghita$Lav_exp)
summary(HR_lav_lm_rob)
HR_lav_kst_rob <- exp(signif(HR_lav_lm_rob$coef[[1]], 4))
HR_lav_chi_rob <- signif(HR_lav_lm_rob$coef[[2]], 4)
HR_pred_lav_lm_rob <- exp(predict(HR_lav_lm_rob, newdata = RO_Census_Harghita, 
                                  interval = "prediction", level = 0.95))
HR_RSquared_lav_rob <- 1 - sum((log(RO_Census_Harghita$Population) - fitted(HR_lav_lm_rob))^2) / 
  sum((log(RO_Census_Harghita$Population) - mean(log(RO_Census_Harghita$Population)))^2)

# e) Data Distributions
RO_Census_Harghita %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Harghita$Rank, 
                              Population = HR_pred_pw_lm_rob[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(HR_pw_lm_rob$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(HR_pw_lm_rob$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(HR_RSquared_pw_rob, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Harghita$Rank, 
                              Population = HR_pred_exp_lm_rob[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(HR_exp_lm_rob$coefficients[[1]]), 4), "%.%", 
                           signif(exp(HR_exp_lm_rob$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(HR_RSquared_exp_rob, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Harghita$Rank, 
                              Population = HR_pred_ZM_lm_rob[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(HR_ZM_cst_rob, 4), "%.%", "(",
                           signif(HR_ZM_m_rob, 4), "+ x)^", signif(HR_ZM_alpha_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(HR_RSquared_ZM_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Harghita$Rank, 
                              Population = HR_pred_lav_lm_rob[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(HR_lav_kst_rob, 4), "%.%", "x^",
                           -signif(HR_lav_chi_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(HR_RSquared_lav_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Harghita judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# f) Extract regression metrics
HR_regmet_rob <- as.data.frame(list(Judet_Name = "HARGHITA",
