# XXII. Hunedoara

# 1. OLS
RO_Census_Hunedoara <- RO_Census_rank %>% filter(Judet_Name == "HUNEDOARA")
#View(RO_Census_Hunedoara)

# a) Power Law
HD_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Hunedoara)
summary(HD_pw_lm_ols)
HD_pred_pw_lm_ols <- exp(predict(HD_pw_lm_ols, newdata = RO_Census_Hunedoara, 
                                 interval = "prediction", level = 0.95))
HD_pw_out_ols <- RO_Census_Hunedoara %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(HD_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Hunedoara), 
         DFFIT = dffits(HD_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(HD_pw_lm_ols$coefficients) / nrow(RO_Census_Hunedoara)), 
         Rezid_Std = rstudent(HD_pw_lm_ols), Leverage = hatvalues(HD_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(HD_pw_lm_ols)), 
         DFBETA = dfbetas(HD_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Hunedoara)))

# b) Zipf_Mandelbrot Law
HD_ZM_prm_ols <- get_ZM_Param("RO_Census_Hunedoara", "Population", "Rank")
HD_ZM_m_ols <- HD_ZM_prm_ols$m
HD_ZM_alpha_ols <- HD_ZM_prm_ols$alpha_ZM
HD_ZM_cst_ols <- HD_ZM_prm_ols$constant_ZM
HD_ZM_lm_ols <- lm(log(RO_Census_Hunedoara$Population) ~ log(RO_Census_Hunedoara$Rank + HD_ZM_m_ols))
summary(HD_ZM_lm_ols)
HD_pred_ZM_lm_ols <- exp(predict(HD_ZM_lm_ols, newdata = RO_Census_Hunedoara, 
                                 interval = "prediction", level = 0.95))
HD_ZM_out_ols <- RO_Census_Hunedoara %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(HD_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Hunedoara), 
         DFFIT = dffits(HD_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(HD_ZM_lm_ols$coefficients) / nrow(RO_Census_Hunedoara)), 
         Rezid_Std = rstudent(HD_ZM_lm_ols), Leverage = hatvalues(HD_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(HD_ZM_lm_ols)), 
         DFBETA = dfbetas(HD_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Hunedoara)))

# c) Exponential Law
HD_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Hunedoara)
summary(HD_exp_lm_ols)
HD_pred_exp_lm_ols <- exp(predict(HD_exp_lm_ols, newdata = RO_Census_Hunedoara, 
                                  interval = "prediction", level = 0.95))
HD_exp_out_ols <- RO_Census_Hunedoara %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(HD_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Hunedoara), 
         DFFIT = dffits(HD_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(HD_exp_lm_ols$coefficients) / nrow(RO_Census_Hunedoara)), 
         Rezid_Std = rstudent(HD_exp_lm_ols), Leverage = hatvalues(HD_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(HD_exp_lm_ols)), 
         DFBETA = dfbetas(HD_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Hunedoara)))

# d) Lavalette Function
RO_Census_Hunedoara <- RO_Census_Hunedoara %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Hunedoara) - Rank + 1))
)
HD_lav_lm_ols <- lm(log(RO_Census_Hunedoara$Population) ~ RO_Census_Hunedoara$Lav_exp)
summary(HD_lav_lm_ols)
HD_lav_kst_ols <- exp(signif(HD_lav_lm_ols$coef[[1]], 4))
HD_lav_chi_ols <- signif(HD_lav_lm_ols$coef[[2]], 4)
HD_pred_lav_lm_ols <- exp(predict(HD_lav_lm_ols, newdata = RO_Census_Hunedoara, 
                                  interval = "prediction", level = 0.95))
HD_lav_out_ols <- RO_Census_Hunedoara %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(HD_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Hunedoara), 
         DFFIT = dffits(HD_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(HD_lav_lm_ols$coefficients) / nrow(RO_Census_Hunedoara)), 
         Rezid_Std = rstudent(HD_lav_lm_ols), Leverage = hatvalues(HD_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(HD_lav_lm_ols)), 
         DFBETA = dfbetas(HD_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Hunedoara)))

# e) Data Distributions
RO_Census_Hunedoara %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Hunedoara$Rank, 
                              Population = HD_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(HD_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(HD_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(HD_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Hunedoara$Rank, 
                              Population = HD_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(HD_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(HD_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(HD_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Hunedoara$Rank, 
                              Population = HD_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(HD_ZM_cst_ols, 4), "%.%", "(",
                           signif(HD_ZM_m_ols, 4), "+ x)^", signif(HD_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(summary(HD_ZM_lm_ols)$r.squared, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Hunedoara$Rank, 
                              Population = HD_pred_lav_lm_ols[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(HD_lav_kst_ols, 4), "%.%", "x^",
                           -signif(HD_lav_chi_ols, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(summary(HD_lav_lm_ols)$r.squared, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Hunedoara judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# Linear Regressions
grid.arrange(
  (RO_Census_Hunedoara %>%
     ggplot(aes(x = log(Rank), y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = "#ED3F39FF") +
     labs(x = "Rank", y = "Population") +
     ggtitle("Power Linear Regression on Hunedoara judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  (RO_Census_Hunedoara %>%
     ggplot(aes(x = Rank, y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = "#088BBEFF") +
     labs(x = "Rank", y = "Population") +
     ggtitle("Exponential Linear Regression on Hunedoara judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  (RO_Census_Hunedoara %>%
     ggplot(aes(x = log(Rank + HD_ZM_m_ols), y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = '#1B7837FF') +
     labs(x = "Rank", y = "Population") +
