                                            signif(BIC(HD_ZM_lm_ols), 4), signif(BIC(HD_lav_lm_ols), 4)),
                                    MAE = c(signif(mean(abs((log(RO_Census_Hunedoara$Population) - 
                                                               (predict(HD_pw_lm_ols, newdata = RO_Census_Hunedoara, 
                                                                        interval = "prediction", level = 0.95))))), 4), 
