as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(HD_ols_hd$Population) - HD_ols_hd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(HD_ols_hd$Population) - HD_ols_hd$EXP_Y_Pred))), 4),
