  RMSE = c(signif(sqrt(mean(((log(HD_ols_hd$Population)) - HD_ols_hd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(HD_ols_hd$Population)) - HD_ols_hd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(HD_ols_hd$Population)) - HD_ols_hd$ZM_Y_Pred) ^ 2)), 4),
