# 2. Robust

# a) Power Law
HD_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Hunedoara)
summary(HD_pw_lm_rob)
HD_pred_pw_lm_rob <- exp(predict(HD_pw_lm_rob, newdata = RO_Census_Hunedoara, 
                                 interval = "prediction", level = 0.95))
HD_RSquared_pw_rob <- 1 - sum((log(RO_Census_Hunedoara$Population) - fitted(HD_pw_lm_rob))^2) / 
  sum((log(RO_Census_Hunedoara$Population) - mean(log(RO_Census_Hunedoara$Population)))^2)

# b) Zipf_Mandelbrot Law
HD_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Hunedoara, "Population", "Rank")
HD_ZM_m_rob <- HD_ZM_prm_rob$m
HD_ZM_alpha_rob <- HD_ZM_prm_rob$alpha_ZM
HD_ZM_cst_rob <- HD_ZM_prm_rob$constant_ZM
HD_ZM_lm_rob <- rlm(log(RO_Census_Hunedoara$Population) ~ log(RO_Census_Hunedoara$Rank + HD_ZM_m_rob))
summary(HD_ZM_lm_rob)
HD_pred_ZM_lm_rob <- exp(predict(HD_ZM_lm_rob, newdata = RO_Census_Hunedoara, 
                                 interval = "prediction", level = 0.95))
HD_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Hunedoara$Population) - fitted(HD_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Hunedoara$Population) - mean(log(RO_Census_Hunedoara$Population)))^2)

# c) Exponential Law
HD_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Hunedoara)
summary(HD_exp_lm_rob)
HD_pred_exp_lm_rob <- exp(predict(HD_exp_lm_rob, newdata = RO_Census_Hunedoara, 
                                  interval = "prediction", level = 0.95))
HD_RSquared_exp_rob <- 1 - sum((log(RO_Census_Hunedoara$Population) - fitted(HD_exp_lm_rob))^2) / 
  sum((log(RO_Census_Hunedoara$Population) - mean(log(RO_Census_Hunedoara$Population)))^2)

# d) Lavalette Function
RO_Census_Hunedoara <- RO_Census_Hunedoara %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Hunedoara) - Rank + 1))
)
HD_lav_lm_rob <- rlm(log(RO_Census_Hunedoara$Population) ~ RO_Census_Hunedoara$Lav_exp)
summary(HD_lav_lm_rob)
HD_lav_kst_rob <- exp(signif(HD_lav_lm_rob$coef[[1]], 4))
HD_lav_chi_rob <- signif(HD_lav_lm_rob$coef[[2]], 4)
HD_pred_lav_lm_rob <- exp(predict(HD_lav_lm_rob, newdata = RO_Census_Hunedoara, 
                                  interval = "prediction", level = 0.95))
HD_RSquared_lav_rob <- 1 - sum((log(RO_Census_Hunedoara$Population) - fitted(HD_lav_lm_rob))^2) / 
  sum((log(RO_Census_Hunedoara$Population) - mean(log(RO_Census_Hunedoara$Population)))^2)

# e) Data Distributions
RO_Census_Hunedoara %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Hunedoara$Rank, 
                              Population = HD_pred_pw_lm_rob[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(HD_pw_lm_rob$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(HD_pw_lm_rob$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(HD_RSquared_pw_rob, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Hunedoara$Rank, 
                              Population = HD_pred_exp_lm_rob[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(HD_exp_lm_rob$coefficients[[1]]), 4), "%.%", 
                           signif(exp(HD_exp_lm_rob$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(HD_RSquared_exp_rob, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Hunedoara$Rank, 
                              Population = HD_pred_ZM_lm_rob[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(HD_ZM_cst_rob, 4), "%.%", "(",
                           signif(HD_ZM_m_rob, 4), "+ x)^", signif(HD_ZM_alpha_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(HD_RSquared_ZM_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Hunedoara$Rank, 
                              Population = HD_pred_lav_lm_rob[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(HD_lav_kst_rob, 4), "%.%", "x^",
                           -signif(HD_lav_chi_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(HD_RSquared_lav_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Hunedoara judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# f) Extract regression metrics
