             signif(sqrt(mean(((log(HD_rob_tl$Population)) - HD_rob_tl$EXP_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(HD_rob_tl$Population)) - HD_rob_tl$ZM_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(HD_rob_tl$Population)) - HD_rob_tl$LAV_Y_Pred) ^ 2)), 4)),
    Data_Part = "Tail"
  )),
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(HD_rob_bd$Population) - HD_rob_bd$PW_Y_Pred))), 4), 
            signif(mean(abs((log(HD_rob_bd$Population) - HD_rob_bd$EXP_Y_Pred))), 4),
            signif(mean(abs((log(HD_rob_bd$Population) - HD_rob_bd$ZM_Y_Pred))), 4),
            signif(mean(abs((log(HD_rob_bd$Population) - HD_rob_bd$LAV_Y_Pred))), 4)),
    RMSE = c(signif(sqrt(mean(((log(HD_rob_bd$Population)) - HD_rob_bd$PW_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(HD_rob_bd$Population)) - HD_rob_bd$EXP_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(HD_rob_bd$Population)) - HD_rob_bd$ZM_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(HD_rob_bd$Population)) - HD_rob_bd$LAV_Y_Pred) ^ 2)), 4)),
    Data_Part = "Body"
  )),
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(RO_Census_Hunedoara$Population) - 
                               (predict(HD_pw_lm_rob, newdata = RO_Census_Hunedoara, 
                                        interval = "prediction", level = 0.95))))), 4), 
            signif(mean(abs((log(RO_Census_Hunedoara$Population) - 
                               (predict(HD_exp_lm_rob, newdata = RO_Census_Hunedoara, 
                                        interval = "prediction", level = 0.95))))), 4),
            signif(mean(abs((log(RO_Census_Hunedoara$Population) - 
                               (predict(HD_ZM_lm_rob, newdata = RO_Census_Hunedoara, 
                                        interval = "prediction", level = 0.95))))), 4),
            signif(mean(abs((log(RO_Census_Hunedoara$Population) - 
                               (predict(HD_lav_lm_rob, newdata = RO_Census_Hunedoara, 
                                        interval = "prediction", level = 0.95))))), 4)),
    RMSE = c(signif(sqrt(mean(((log(RO_Census_Hunedoara$Population)) - 
                                 (predict(HD_pw_lm_rob, newdata = RO_Census_Hunedoara, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Hunedoara$Population)) - 
                                 (predict(HD_exp_lm_rob, newdata = RO_Census_Hunedoara, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Hunedoara$Population)) - 
                                 (predict(HD_ZM_lm_rob, newdata = RO_Census_Hunedoara, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Hunedoara$Population)) - 
                                 (predict(HD_lav_lm_rob, newdata = RO_Census_Hunedoara, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4)),
    Data_Part = "Full"
  ))
)) %>% mutate(Regression_Type = "Robust", Judet_Name = "HUNEDOARA")

# 3. Compare OLS with Robust
HD_regg_res <- bind_rows(HD_res_ols, HD_res_rob)

# RMSE
HD_regg_res %>% ggplot(aes(Data_Part, RMSE, color = Function_Name, 
