# XXIII. Ialomita

# 1. OLS
RO_Census_Ialomita <- RO_Census_rank %>% filter(Judet_Name == "IALOMITA")
#View(RO_Census_Ialomita)

# a) Power Law
IL_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Ialomita)
summary(IL_pw_lm_ols)
IL_pred_pw_lm_ols <- exp(predict(IL_pw_lm_ols, newdata = RO_Census_Ialomita, 
                                 interval = "prediction", level = 0.95))
IL_pw_out_ols <- RO_Census_Ialomita %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(IL_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Ialomita), 
         DFFIT = dffits(IL_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(IL_pw_lm_ols$coefficients) / nrow(RO_Census_Ialomita)), 
         Rezid_Std = rstudent(IL_pw_lm_ols), Leverage = hatvalues(IL_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(IL_pw_lm_ols)), 
         DFBETA = dfbetas(IL_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Ialomita)))

# b) Zipf_Mandelbrot Law
IL_ZM_prm_ols <- get_ZM_Param("RO_Census_Ialomita", "Population", "Rank")
IL_ZM_m_ols <- IL_ZM_prm_ols$m
IL_ZM_alpha_ols <- IL_ZM_prm_ols$alpha_ZM
IL_ZM_cst_ols <- IL_ZM_prm_ols$constant_ZM
IL_ZM_lm_ols <- lm(log(RO_Census_Ialomita$Population) ~ log(RO_Census_Ialomita$Rank + IL_ZM_m_ols))
summary(IL_ZM_lm_ols)
IL_pred_ZM_lm_ols <- exp(predict(IL_ZM_lm_ols, newdata = RO_Census_Ialomita, 
                                 interval = "prediction", level = 0.95))
IL_ZM_out_ols <- RO_Census_Ialomita %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(IL_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Ialomita), 
         DFFIT = dffits(IL_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(IL_ZM_lm_ols$coefficients) / nrow(RO_Census_Ialomita)), 
         Rezid_Std = rstudent(IL_ZM_lm_ols), Leverage = hatvalues(IL_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(IL_ZM_lm_ols)), 
         DFBETA = dfbetas(IL_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Ialomita)))

# c) Exponential Law
IL_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Ialomita)
summary(IL_exp_lm_ols)
IL_pred_exp_lm_ols <- exp(predict(IL_exp_lm_ols, newdata = RO_Census_Ialomita, 
                                  interval = "prediction", level = 0.95))
IL_exp_out_ols <- RO_Census_Ialomita %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(IL_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Ialomita), 
         DFFIT = dffits(IL_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(IL_exp_lm_ols$coefficients) / nrow(RO_Census_Ialomita)), 
         Rezid_Std = rstudent(IL_exp_lm_ols), Leverage = hatvalues(IL_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(IL_exp_lm_ols)), 
         DFBETA = dfbetas(IL_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Ialomita)))

# d) Lavalette Function
RO_Census_Ialomita <- RO_Census_Ialomita %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Ialomita) - Rank + 1))
)
IL_lav_lm_ols <- lm(log(RO_Census_Ialomita$Population) ~ RO_Census_Ialomita$Lav_exp)
summary(IL_lav_lm_ols)
IL_lav_kst_ols <- exp(signif(IL_lav_lm_ols$coef[[1]], 4))
IL_lav_chi_ols <- signif(IL_lav_lm_ols$coef[[2]], 4)
IL_pred_lav_lm_ols <- exp(predict(IL_lav_lm_ols, newdata = RO_Census_Ialomita, 
                                  interval = "prediction", level = 0.95))
IL_lav_out_ols <- RO_Census_Ialomita %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(IL_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Ialomita), 
         DFFIT = dffits(IL_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(IL_lav_lm_ols$coefficients) / nrow(RO_Census_Ialomita)), 
         Rezid_Std = rstudent(IL_lav_lm_ols), Leverage = hatvalues(IL_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(IL_lav_lm_ols)), 
         DFBETA = dfbetas(IL_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Ialomita)))

# e) Data Distributions
RO_Census_Ialomita %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Ialomita$Rank, 
                              Population = IL_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(IL_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(IL_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(IL_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Ialomita$Rank, 
                              Population = IL_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(IL_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(IL_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(IL_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Ialomita$Rank, 
                              Population = IL_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(IL_ZM_cst_ols, 4), "%.%", "(",
                           signif(IL_ZM_m_ols, 4), "+ x)^", signif(IL_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(summary(IL_ZM_lm_ols)$r.squared, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Ialomita$Rank, 
                              Population = IL_pred_lav_lm_ols[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(IL_lav_kst_ols, 4), "%.%", "x^",
                           -signif(IL_lav_chi_ols, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(summary(IL_lav_lm_ols)$r.squared, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Ialomita judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# Linear Regressions
grid.arrange(
  (RO_Census_Ialomita %>%
     ggplot(aes(x = log(Rank), y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = "#ED3F39FF") +
     labs(x = "Rank", y = "Population") +
     ggtitle("Power Linear Regression on Ialomita judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  (RO_Census_Ialomita %>%
     ggplot(aes(x = Rank, y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = "#088BBEFF") +
     labs(x = "Rank", y = "Population") +
     ggtitle("Exponential Linear Regression on Ialomita judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  (RO_Census_Ialomita %>%
     ggplot(aes(x = log(Rank + IL_ZM_m_ols), y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = '#1B7837FF') +
     labs(x = "Rank", y = "Population") +
     ggtitle("Zipf-Mandelbrot Linear Regression on Ialomita judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  (RO_Census_Ialomita %>%
     ggplot(aes(x = Lav_exp, y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = '#F8A02EFF') +
     labs(x = "Rank", y = "Population") +
     ggtitle("Lavalette Linear Regression on Ialomita judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  ncol = 2, nrow = 2)

# f) Extract Outliers
Ialomita_Outliers <- bind_rows(
  (IL_pw_out_ols %>% mutate(Function_Name = "Power")),
  (IL_ZM_out_ols %>% mutate(Function_Name = "Zipf-Mandelbrot")),
  (IL_exp_out_ols %>% mutate(Function_Name = "Exponential")),
  (IL_lav_out_ols %>% mutate(Function_Name = "Lavalette"))
) %>% mutate(DFBETA_intercept = round(DFBETA[,1], 8), 
             DFBETA_var_x = round(DFBETA[,2], 8)) %>% dplyr::select(-DFBETA)

IL_out <- get_outliers(Ialomita_Outliers, RO_Census_Ialomita)

IL_out_ols <- RO_Census_Ialomita %>% inner_join(
  bind_rows(
    (IL_out$PW %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>% 
       dplyr::select(Rank) %>% distinct()),
    (IL_out$ZM %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (IL_out$LAV %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (IL_out$EXP %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct())
  ) %>% count(Rank) %>% arrange(desc(n)) %>% filter(n >= mean(n))) %>% 
  dplyr::select(-n)

# g) Extract regression metrics
IL_regmet_ols <- as.data.frame(list(Judet_Name = "IALOMITA",
                                    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
                                    R_Squared = c(signif(summary(IL_pw_lm_ols)$r.squared, 4), 
                                                  signif(summary(IL_exp_lm_ols)$r.squared, 4),
                                                  signif(summary(IL_ZM_lm_ols)$r.squared, 4),
                                                  signif(summary(IL_lav_lm_ols)$r.squared, 4)),
                                    Adj_R_Squared = c(signif(summary(IL_pw_lm_ols)$adj.r.squared, 4), 
                                                      signif(summary(IL_exp_lm_ols)$adj.r.squared, 4),
                                                      signif(summary(IL_ZM_lm_ols)$adj.r.squared, 4),
                                                      signif(summary(IL_lav_lm_ols)$adj.r.squared, 4)),
                                    AIC = c(signif(AIC(IL_pw_lm_ols), 4), signif(AIC(IL_exp_lm_ols), 4), 
                                            signif(AIC(IL_ZM_lm_ols), 4), signif(AIC(IL_lav_lm_ols), 4)),
                                    BIC = c(signif(BIC(IL_pw_lm_ols), 4), signif(BIC(IL_exp_lm_ols), 4), 
                                            signif(BIC(IL_ZM_lm_ols), 4), signif(BIC(IL_lav_lm_ols), 4)),
                                    MAE = c(signif(mean(abs((log(RO_Census_Ialomita$Population) - 
                                                               (predict(IL_pw_lm_ols, newdata = RO_Census_Ialomita, 
                                                                        interval = "prediction", level = 0.95))))), 4), 
                                            signif(mean(abs((log(RO_Census_Ialomita$Population) - 
                                                               (predict(IL_exp_lm_ols, newdata = RO_Census_Ialomita, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Ialomita$Population) - 
                                                               (predict(IL_ZM_lm_ols, newdata = RO_Census_Ialomita, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Ialomita$Population) - 
                                                               (predict(IL_lav_lm_ols, newdata = RO_Census_Ialomita, 
                                                                        interval = "prediction", level = 0.95))))), 4)),
                                    RMSE = c(signif(sqrt(mean(((log(RO_Census_Ialomita$Population)) - 
                                                                 (predict(IL_pw_lm_ols, newdata = RO_Census_Ialomita, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Ialomita$Population)) - 
                                                                 (predict(IL_exp_lm_ols, newdata = RO_Census_Ialomita, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Ialomita$Population)) - 
                                                                 (predict(IL_ZM_lm_ols, newdata = RO_Census_Ialomita, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Ialomita$Population)) - 
                                                                 (predict(IL_lav_lm_ols, newdata = RO_Census_Ialomita, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4))
))

# h) Extract MAE/RMSE on head, body, tail
RO_Census_Ialomita_ols <- RO_Census_Ialomita %>% 
  mutate(PW_Y_Pred = (predict(IL_pw_lm_ols, newdata = RO_Census_Ialomita, 
                              interval = "prediction", level = 0.95))[,1], 
         ZM_Y_Pred = (predict(IL_ZM_lm_ols, newdata = RO_Census_Ialomita, 
                              interval = "prediction", level = 0.95))[,1],
         EXP_Y_Pred = (predict(IL_exp_lm_ols, newdata = RO_Census_Ialomita, 
                               interval = "prediction", level = 0.95))[,1], 
         LAV_Y_Pred = (predict(IL_lav_lm_ols, newdata = RO_Census_Ialomita, 
                               interval = "prediction", level = 0.95))[,1])

# Head
IL_ols_hd <- RO_Census_Ialomita_ols %>% filter(Rank <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(IL_ols_hd$Population) - IL_ols_hd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(IL_ols_hd$Population) - IL_ols_hd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(IL_ols_hd$Population) - IL_ols_hd$ZM_Y_Pred))), 4),
          signif(mean(abs((log(IL_ols_hd$Population) - IL_ols_hd$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(IL_ols_hd$Population)) - IL_ols_hd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(IL_ols_hd$Population)) - IL_ols_hd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(IL_ols_hd$Population)) - IL_ols_hd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(IL_ols_hd$Population)) - IL_ols_hd$LAV_Y_Pred) ^ 2)), 4))
))

# Tail
IL_ols_tl <- RO_Census_Ialomita_ols %>% arrange(desc(Rank)) %>% 
  filter(row_number() <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(IL_ols_tl$Population) - IL_ols_tl$PW_Y_Pred))), 4), 
          signif(mean(abs((log(IL_ols_tl$Population) - IL_ols_tl$EXP_Y_Pred))), 4),
          signif(mean(abs((log(IL_ols_tl$Population) - IL_ols_tl$ZM_Y_Pred))), 4),
          signif(mean(abs((log(IL_ols_tl$Population) - IL_ols_tl$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(IL_ols_tl$Population)) - IL_ols_tl$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(IL_ols_tl$Population)) - IL_ols_tl$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(IL_ols_tl$Population)) - IL_ols_tl$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(IL_ols_tl$Population)) - IL_ols_tl$LAV_Y_Pred) ^ 2)), 4))
))

# Body
IL_ols_bd <- RO_Census_Ialomita_ols %>% anti_join(IL_ols_hd) %>% anti_join(IL_ols_tl)

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(IL_ols_bd$Population) - IL_ols_bd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(IL_ols_bd$Population) - IL_ols_bd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(IL_ols_bd$Population) - IL_ols_bd$ZM_Y_Pred))), 4),
