# 2. Robust

# a) Power Law
IL_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Ialomita)
summary(IL_pw_lm_rob)
IL_pred_pw_lm_rob <- exp(predict(IL_pw_lm_rob, newdata = RO_Census_Ialomita, 
                                 interval = "prediction", level = 0.95))
IL_RSquared_pw_rob <- 1 - sum((log(RO_Census_Ialomita$Population) - fitted(IL_pw_lm_rob))^2) / 
  sum((log(RO_Census_Ialomita$Population) - mean(log(RO_Census_Ialomita$Population)))^2)

# b) Zipf_Mandelbrot Law
IL_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Ialomita, "Population", "Rank")
IL_ZM_m_rob <- IL_ZM_prm_rob$m
IL_ZM_alpha_rob <- IL_ZM_prm_rob$alpha_ZM
IL_ZM_cst_rob <- IL_ZM_prm_rob$constant_ZM
IL_ZM_lm_rob <- rlm(log(RO_Census_Ialomita$Population) ~ log(RO_Census_Ialomita$Rank + IL_ZM_m_rob))
summary(IL_ZM_lm_rob)
IL_pred_ZM_lm_rob <- exp(predict(IL_ZM_lm_rob, newdata = RO_Census_Ialomita, 
                                 interval = "prediction", level = 0.95))
IL_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Ialomita$Population) - fitted(IL_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Ialomita$Population) - mean(log(RO_Census_Ialomita$Population)))^2)

# c) Exponential Law
IL_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Ialomita)
summary(IL_exp_lm_rob)
IL_pred_exp_lm_rob <- exp(predict(IL_exp_lm_rob, newdata = RO_Census_Ialomita, 
                                  interval = "prediction", level = 0.95))
IL_RSquared_exp_rob <- 1 - sum((log(RO_Census_Ialomita$Population) - fitted(IL_exp_lm_rob))^2) / 
  sum((log(RO_Census_Ialomita$Population) - mean(log(RO_Census_Ialomita$Population)))^2)

# d) Lavalette Function
RO_Census_Ialomita <- RO_Census_Ialomita %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Ialomita) - Rank + 1))
)
IL_lav_lm_rob <- rlm(log(RO_Census_Ialomita$Population) ~ RO_Census_Ialomita$Lav_exp)
summary(IL_lav_lm_rob)
IL_lav_kst_rob <- exp(signif(IL_lav_lm_rob$coef[[1]], 4))
IL_lav_chi_rob <- signif(IL_lav_lm_rob$coef[[2]], 4)
IL_pred_lav_lm_rob <- exp(predict(IL_lav_lm_rob, newdata = RO_Census_Ialomita, 
                                  interval = "prediction", level = 0.95))
IL_RSquared_lav_rob <- 1 - sum((log(RO_Census_Ialomita$Population) - fitted(IL_lav_lm_rob))^2) / 
  sum((log(RO_Census_Ialomita$Population) - mean(log(RO_Census_Ialomita$Population)))^2)

# e) Data Distributions
RO_Census_Ialomita %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Ialomita$Rank, 
                              Population = IL_pred_pw_lm_rob[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(IL_pw_lm_rob$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(IL_pw_lm_rob$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(IL_RSquared_pw_rob, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Ialomita$Rank, 
                              Population = IL_pred_exp_lm_rob[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(IL_exp_lm_rob$coefficients[[1]]), 4), "%.%", 
                           signif(exp(IL_exp_lm_rob$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(IL_RSquared_exp_rob, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Ialomita$Rank, 
                              Population = IL_pred_ZM_lm_rob[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(IL_ZM_cst_rob, 4), "%.%", "(",
                           signif(IL_ZM_m_rob, 4), "+ x)^", signif(IL_ZM_alpha_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(IL_RSquared_ZM_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Ialomita$Rank, 
                              Population = IL_pred_lav_lm_rob[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(IL_lav_kst_rob, 4), "%.%", "x^",
                           -signif(IL_lav_chi_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(IL_RSquared_lav_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Ialomita judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# f) Extract regression metrics
IL_regmet_rob <- as.data.frame(list(Judet_Name = "IALOMITA",
