# Extract weight
IL_out_weights <- bind_rows(
  (RO_Census_Ialomita %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>% 
     mutate(Robust_Weight = IL_pw_lm_rob$w, Function_Name = "Power")),
  (RO_Census_Ialomita %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = IL_ZM_lm_rob$w, Function_Name = "Zipf-Mandelbrot")),
  (RO_Census_Ialomita %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = IL_exp_lm_rob$w, Function_Name = "Exponential")),
