    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(RO_Census_Ialomita$Population) - 
                               (predict(IL_pw_lm_rob, newdata = RO_Census_Ialomita, 
                                        interval = "prediction", level = 0.95))))), 4), 
            signif(mean(abs((log(RO_Census_Ialomita$Population) - 
                               (predict(IL_exp_lm_rob, newdata = RO_Census_Ialomita, 
                                        interval = "prediction", level = 0.95))))), 4),
            signif(mean(abs((log(RO_Census_Ialomita$Population) - 
                               (predict(IL_ZM_lm_rob, newdata = RO_Census_Ialomita, 
                                        interval = "prediction", level = 0.95))))), 4),
            signif(mean(abs((log(RO_Census_Ialomita$Population) - 
                               (predict(IL_lav_lm_rob, newdata = RO_Census_Ialomita, 
                                        interval = "prediction", level = 0.95))))), 4)),
    RMSE = c(signif(sqrt(mean(((log(RO_Census_Ialomita$Population)) - 
                                 (predict(IL_pw_lm_rob, newdata = RO_Census_Ialomita, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Ialomita$Population)) - 
                                 (predict(IL_exp_lm_rob, newdata = RO_Census_Ialomita, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Ialomita$Population)) - 
                                 (predict(IL_ZM_lm_rob, newdata = RO_Census_Ialomita, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Ialomita$Population)) - 
                                 (predict(IL_lav_lm_rob, newdata = RO_Census_Ialomita, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4)),
    Data_Part = "Full"
  ))
)) %>% mutate(Regression_Type = "Robust", Judet_Name = "IALOMITA")

# 3. Compare OLS with Robust
IL_regg_res <- bind_rows(IL_res_ols, IL_res_rob)

# RMSE
IL_regg_res %>% ggplot(aes(Data_Part, RMSE, color = Function_Name, 
