# XXIV. Iasi

# 1. OLS
RO_Census_Iasi <- RO_Census_rank %>% filter(Judet_Name == "IASI")
#View(RO_Census_Iasi)

# a) Power Law
IS_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Iasi)
summary(IS_pw_lm_ols)
IS_pred_pw_lm_ols <- exp(predict(IS_pw_lm_ols, newdata = RO_Census_Iasi, 
                                 interval = "prediction", level = 0.95))
IS_pw_out_ols <- RO_Census_Iasi %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(IS_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Iasi), 
         DFFIT = dffits(IS_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(IS_pw_lm_ols$coefficients) / nrow(RO_Census_Iasi)), 
         Rezid_Std = rstudent(IS_pw_lm_ols), Leverage = hatvalues(IS_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(IS_pw_lm_ols)), 
         DFBETA = dfbetas(IS_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Iasi)))

# b) Zipf_Mandelbrot Law
IS_ZM_prm_ols <- get_ZM_Param("RO_Census_Iasi", "Population", "Rank")
IS_ZM_m_ols <- IS_ZM_prm_ols$m
IS_ZM_alpha_ols <- IS_ZM_prm_ols$alpha_ZM
IS_ZM_cst_ols <- IS_ZM_prm_ols$constant_ZM
IS_ZM_lm_ols <- lm(log(RO_Census_Iasi$Population) ~ log(RO_Census_Iasi$Rank + IS_ZM_m_ols))
summary(IS_ZM_lm_ols)
IS_pred_ZM_lm_ols <- exp(predict(IS_ZM_lm_ols, newdata = RO_Census_Iasi, 
                                 interval = "prediction", level = 0.95))
IS_ZM_out_ols <- RO_Census_Iasi %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(IS_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Iasi), 
         DFFIT = dffits(IS_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(IS_ZM_lm_ols$coefficients) / nrow(RO_Census_Iasi)), 
         Rezid_Std = rstudent(IS_ZM_lm_ols), Leverage = hatvalues(IS_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(IS_ZM_lm_ols)), 
         DFBETA = dfbetas(IS_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Iasi)))

# c) Exponential Law
IS_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Iasi)
summary(IS_exp_lm_ols)
IS_pred_exp_lm_ols <- exp(predict(IS_exp_lm_ols, newdata = RO_Census_Iasi, 
                                  interval = "prediction", level = 0.95))
IS_exp_out_ols <- RO_Census_Iasi %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(IS_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Iasi), 
         DFFIT = dffits(IS_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(IS_exp_lm_ols$coefficients) / nrow(RO_Census_Iasi)), 
         Rezid_Std = rstudent(IS_exp_lm_ols), Leverage = hatvalues(IS_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(IS_exp_lm_ols)), 
         DFBETA = dfbetas(IS_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Iasi)))

# d) Lavalette Function
RO_Census_Iasi <- RO_Census_Iasi %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Iasi) - Rank + 1))
)
IS_lav_lm_ols <- lm(log(RO_Census_Iasi$Population) ~ RO_Census_Iasi$Lav_exp)
summary(IS_lav_lm_ols)
IS_lav_kst_ols <- exp(signif(IS_lav_lm_ols$coef[[1]], 4))
IS_lav_chi_ols <- signif(IS_lav_lm_ols$coef[[2]], 4)
IS_pred_lav_lm_ols <- exp(predict(IS_lav_lm_ols, newdata = RO_Census_Iasi, 
                                  interval = "prediction", level = 0.95))
IS_lav_out_ols <- RO_Census_Iasi %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(IS_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Iasi), 
         DFFIT = dffits(IS_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(IS_lav_lm_ols$coefficients) / nrow(RO_Census_Iasi)), 
         Rezid_Std = rstudent(IS_lav_lm_ols), Leverage = hatvalues(IS_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(IS_lav_lm_ols)), 
         DFBETA = dfbetas(IS_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Iasi)))

# e) Data Distributions
RO_Census_Iasi %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Iasi$Rank, 
                              Population = IS_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(IS_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(IS_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(IS_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Iasi$Rank, 
                              Population = IS_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(IS_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(IS_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(IS_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Iasi$Rank, 
                              Population = IS_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(IS_ZM_cst_ols, 4), "%.%", "(",
                           signif(IS_ZM_m_ols, 4), "+ x)^", signif(IS_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(summary(IS_ZM_lm_ols)$r.squared, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Iasi$Rank, 
                              Population = IS_pred_lav_lm_ols[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(IS_lav_kst_ols, 4), "%.%", "x^",
                           -signif(IS_lav_chi_ols, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(summary(IS_lav_lm_ols)$r.squared, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Iasi judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# Linear Regressions
grid.arrange(
