# f) Extract Outliers
Iasi_Outliers <- bind_rows(
  (IS_pw_out_ols %>% mutate(Function_Name = "Power")),
  (IS_ZM_out_ols %>% mutate(Function_Name = "Zipf-Mandelbrot")),
  (IS_exp_out_ols %>% mutate(Function_Name = "Exponential")),
  (IS_lav_out_ols %>% mutate(Function_Name = "Lavalette"))
