           signif(sqrt(mean(((log(IS_ols_tl$Population)) - IS_ols_tl$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(IS_ols_tl$Population)) - IS_ols_tl$LAV_Y_Pred) ^ 2)), 4))
))

# Body
IS_ols_bd <- RO_Census_Iasi_ols %>% anti_join(IS_ols_hd) %>% anti_join(IS_ols_tl)

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
