           signif(sqrt(mean(((log(IS_ols_bd$Population)) - IS_ols_bd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(IS_ols_bd$Population)) - IS_ols_bd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(IS_ols_bd$Population)) - IS_ols_bd$LAV_Y_Pred) ^ 2)), 4))
))

# Final
IS_res_ols <- as.data.frame(bind_rows(
