  )),
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(IS_ols_bd$Population) - IS_ols_bd$PW_Y_Pred))), 4), 
            signif(mean(abs((log(IS_ols_bd$Population) - IS_ols_bd$EXP_Y_Pred))), 4),
            signif(mean(abs((log(IS_ols_bd$Population) - IS_ols_bd$ZM_Y_Pred))), 4),
            signif(mean(abs((log(IS_ols_bd$Population) - IS_ols_bd$LAV_Y_Pred))), 4)),
