                               (predict(IS_pw_lm_ols, newdata = RO_Census_Iasi, 
                                        interval = "prediction", level = 0.95))))), 4), 
            signif(mean(abs((log(RO_Census_Iasi$Population) - 
                               (predict(IS_exp_lm_ols, newdata = RO_Census_Iasi, 
                                        interval = "prediction", level = 0.95))))), 4),
            signif(mean(abs((log(RO_Census_Iasi$Population) - 
                               (predict(IS_ZM_lm_ols, newdata = RO_Census_Iasi, 
