# 2. Robust

# a) Power Law
IS_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Iasi)
summary(IS_pw_lm_rob)
IS_pred_pw_lm_rob <- exp(predict(IS_pw_lm_rob, newdata = RO_Census_Iasi, 
                                 interval = "prediction", level = 0.95))
IS_RSquared_pw_rob <- 1 - sum((log(RO_Census_Iasi$Population) - fitted(IS_pw_lm_rob))^2) / 
  sum((log(RO_Census_Iasi$Population) - mean(log(RO_Census_Iasi$Population)))^2)

# b) Zipf_Mandelbrot Law
IS_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Iasi, "Population", "Rank")
IS_ZM_m_rob <- IS_ZM_prm_rob$m
IS_ZM_alpha_rob <- IS_ZM_prm_rob$alpha_ZM
IS_ZM_cst_rob <- IS_ZM_prm_rob$constant_ZM
IS_ZM_lm_rob <- rlm(log(RO_Census_Iasi$Population) ~ log(RO_Census_Iasi$Rank + IS_ZM_m_rob))
summary(IS_ZM_lm_rob)
IS_pred_ZM_lm_rob <- exp(predict(IS_ZM_lm_rob, newdata = RO_Census_Iasi, 
                                 interval = "prediction", level = 0.95))
IS_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Iasi$Population) - fitted(IS_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Iasi$Population) - mean(log(RO_Census_Iasi$Population)))^2)

# c) Exponential Law
IS_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Iasi)
summary(IS_exp_lm_rob)
IS_pred_exp_lm_rob <- exp(predict(IS_exp_lm_rob, newdata = RO_Census_Iasi, 
                                  interval = "prediction", level = 0.95))
IS_RSquared_exp_rob <- 1 - sum((log(RO_Census_Iasi$Population) - fitted(IS_exp_lm_rob))^2) / 
  sum((log(RO_Census_Iasi$Population) - mean(log(RO_Census_Iasi$Population)))^2)

# d) Lavalette Function
RO_Census_Iasi <- RO_Census_Iasi %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Iasi) - Rank + 1))
)
IS_lav_lm_rob <- rlm(log(RO_Census_Iasi$Population) ~ RO_Census_Iasi$Lav_exp)
summary(IS_lav_lm_rob)
IS_lav_kst_rob <- exp(signif(IS_lav_lm_rob$coef[[1]], 4))
IS_lav_chi_rob <- signif(IS_lav_lm_rob$coef[[2]], 4)
IS_pred_lav_lm_rob <- exp(predict(IS_lav_lm_rob, newdata = RO_Census_Iasi, 
                                  interval = "prediction", level = 0.95))
IS_RSquared_lav_rob <- 1 - sum((log(RO_Census_Iasi$Population) - fitted(IS_lav_lm_rob))^2) / 
  sum((log(RO_Census_Iasi$Population) - mean(log(RO_Census_Iasi$Population)))^2)

# e) Data Distributions
RO_Census_Iasi %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Iasi$Rank, 
                              Population = IS_pred_pw_lm_rob[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(IS_pw_lm_rob$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(IS_pw_lm_rob$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(IS_RSquared_pw_rob, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Iasi$Rank, 
                              Population = IS_pred_exp_lm_rob[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(IS_exp_lm_rob$coefficients[[1]]), 4), "%.%", 
                           signif(exp(IS_exp_lm_rob$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(IS_RSquared_exp_rob, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Iasi$Rank, 
                              Population = IS_pred_ZM_lm_rob[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(IS_ZM_cst_rob, 4), "%.%", "(",
                           signif(IS_ZM_m_rob, 4), "+ x)^", signif(IS_ZM_alpha_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(IS_RSquared_ZM_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Iasi$Rank, 
                              Population = IS_pred_lav_lm_rob[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(IS_lav_kst_rob, 4), "%.%", "x^",
                           -signif(IS_lav_chi_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(IS_RSquared_lav_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Iasi judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# f) Extract regression metrics
IS_regmet_rob <- as.data.frame(list(Judet_Name = "IASI",
                                    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
                                    R_Squared = c(signif(IS_RSquared_pw_rob, 4), 
                                                  signif(IS_RSquared_exp_rob, 4),
                                                  signif(IS_RSquared_ZM_rob, 4),
                                                  signif(IS_RSquared_lav_rob, 4)),
                                    AIC = c(signif(AIC(IS_pw_lm_rob), 4), signif(AIC(IS_exp_lm_rob), 4), 
                                            signif(AIC(IS_ZM_lm_rob), 4), signif(AIC(IS_lav_lm_rob), 4)),
                                    BIC = c(signif(BIC(IS_pw_lm_rob), 4), signif(BIC(IS_exp_lm_rob), 4), 
                                            signif(BIC(IS_ZM_lm_rob), 4), signif(BIC(IS_lav_lm_rob), 4)),
                                    MAE = c(signif(mean(abs((log(RO_Census_Iasi$Population) - 
                                                               (predict(IS_pw_lm_rob, newdata = RO_Census_Iasi, 
                                                                        interval = "prediction", level = 0.95))))), 4), 
                                            signif(mean(abs((log(RO_Census_Iasi$Population) - 
                                                               (predict(IS_exp_lm_rob, newdata = RO_Census_Iasi, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Iasi$Population) - 
                                                               (predict(IS_ZM_lm_rob, newdata = RO_Census_Iasi, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Iasi$Population) - 
                                                               (predict(IS_lav_lm_rob, newdata = RO_Census_Iasi, 
                                                                        interval = "prediction", level = 0.95))))), 4)),
                                    RMSE = c(signif(sqrt(mean(((log(RO_Census_Iasi$Population)) - 
                                                                 (predict(IS_pw_lm_rob, newdata = RO_Census_Iasi, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Iasi$Population)) - 
                                                                 (predict(IS_exp_lm_rob, newdata = RO_Census_Iasi, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Iasi$Population)) - 
                                                                 (predict(IS_ZM_lm_rob, newdata = RO_Census_Iasi, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Iasi$Population)) - 
                                                                 (predict(IS_lav_lm_rob, newdata = RO_Census_Iasi, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4))
))

# Extract weight
IS_out_weights <- bind_rows(
  (RO_Census_Iasi %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>% 
     mutate(Robust_Weight = IS_pw_lm_rob$w, Function_Name = "Power")),
  (RO_Census_Iasi %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = IS_ZM_lm_rob$w, Function_Name = "Zipf-Mandelbrot")),
  (RO_Census_Iasi %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = IS_exp_lm_rob$w, Function_Name = "Exponential")),
  (RO_Census_Iasi %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = IS_lav_lm_rob$w, Function_Name = "Lavalette"))) %>% 
  inner_join(IS_out_ols) %>% 
  dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank, Robust_Weight, Function_Name) %>%
  mutate(Judet_Name = "IASI")

# g) Extract MAE/RMSE on head, body, tail
RO_Census_Iasi_rob <- RO_Census_Iasi %>% 
  mutate(PW_Y_Pred = (predict(IS_pw_lm_rob, newdata = RO_Census_Iasi, 
                              interval = "prediction", level = 0.95))[,1], 
         ZM_Y_Pred = (predict(IS_ZM_lm_rob, newdata = RO_Census_Iasi, 
                              interval = "prediction", level = 0.95))[,1],
         EXP_Y_Pred = (predict(IS_exp_lm_rob, newdata = RO_Census_Iasi, 
                               interval = "prediction", level = 0.95))[,1], 
         LAV_Y_Pred = (predict(IS_lav_lm_rob, newdata = RO_Census_Iasi, 
                               interval = "prediction", level = 0.95))[,1])

# Head
IS_rob_hd <- RO_Census_Iasi_rob %>% filter(Rank <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(IS_rob_hd$Population) - IS_rob_hd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(IS_rob_hd$Population) - IS_rob_hd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(IS_rob_hd$Population) - IS_rob_hd$ZM_Y_Pred))), 4),
          signif(mean(abs((log(IS_rob_hd$Population) - IS_rob_hd$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(IS_rob_hd$Population)) - IS_rob_hd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(IS_rob_hd$Population)) - IS_rob_hd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(IS_rob_hd$Population)) - IS_rob_hd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(IS_rob_hd$Population)) - IS_rob_hd$LAV_Y_Pred) ^ 2)), 4))
))

# Tail
IS_rob_tl <- RO_Census_Iasi_rob %>% arrange(desc(Rank)) %>% 
  filter(row_number() <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(IS_rob_tl$Population) - IS_rob_tl$PW_Y_Pred))), 4), 
          signif(mean(abs((log(IS_rob_tl$Population) - IS_rob_tl$EXP_Y_Pred))), 4),
          signif(mean(abs((log(IS_rob_tl$Population) - IS_rob_tl$ZM_Y_Pred))), 4),
          signif(mean(abs((log(IS_rob_tl$Population) - IS_rob_tl$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(IS_rob_tl$Population)) - IS_rob_tl$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(IS_rob_tl$Population)) - IS_rob_tl$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(IS_rob_tl$Population)) - IS_rob_tl$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(IS_rob_tl$Population)) - IS_rob_tl$LAV_Y_Pred) ^ 2)), 4))
))

# Body
IS_rob_bd <- RO_Census_Iasi_rob %>% anti_join(IS_rob_hd) %>% anti_join(IS_rob_tl)

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(IS_rob_bd$Population) - IS_rob_bd$PW_Y_Pred))), 4), 
