    values = c("Power" = "#ED3F39FF", "Exponential" = "#088BBEFF", 
               "Zipf-Mandelbrot" = "#1B7837FF", "Lavalette" = "#F8A02EFF")) +
  labs(x = "Data Region", y = "RMSE (log scale)") +
  theme(plot.title = element_text(hjust = 0.5))

# MAE
IS_regg_res %>% ggplot(aes(Data_Part, MAE, color = Function_Name, 
                           group = Function_Name)) +
  geom_line(linewidth = 1) + geom_point(size = 3) + 
  facet_wrap(~ Regression_Type) + scale_y_log10() +
  scale_color_manual(
    values = c("Power" = "#ED3F39FF", "Exponential" = "#088BBEFF", 
               "Zipf-Mandelbrot" = "#1B7837FF", "Lavalette" = "#F8A02EFF")) +
  labs(x = "Data Region", y = "MAE (log scale)") +
  theme(plot.title = element_text(hjust = 0.5))

# XXV. Ilfov

# 1. OLS
RO_Census_Ilfov <- RO_Census_rank %>% filter(Judet_Name == "ILFOV")
#View(RO_Census_Ilfov)

# a) Power Law
IF_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Ilfov)
summary(IF_pw_lm_ols)
IF_pred_pw_lm_ols <- exp(predict(IF_pw_lm_ols, newdata = RO_Census_Ilfov, 
                                 interval = "prediction", level = 0.95))
IF_pw_out_ols <- RO_Census_Ilfov %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(IF_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Ilfov), 
         DFFIT = dffits(IF_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(IF_pw_lm_ols$coefficients) / nrow(RO_Census_Ilfov)), 
         Rezid_Std = rstudent(IF_pw_lm_ols), Leverage = hatvalues(IF_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(IF_pw_lm_ols)), 
         DFBETA = dfbetas(IF_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Ilfov)))

# b) Zipf_Mandelbrot Law
IF_ZM_prm_ols <- get_ZM_Param("RO_Census_Ilfov", "Population", "Rank")
IF_ZM_m_ols <- IF_ZM_prm_ols$m
IF_ZM_alpha_ols <- IF_ZM_prm_ols$alpha_ZM
IF_ZM_cst_ols <- IF_ZM_prm_ols$constant_ZM
IF_ZM_lm_ols <- lm(log(RO_Census_Ilfov$Population) ~ log(RO_Census_Ilfov$Rank + IF_ZM_m_ols))
summary(IF_ZM_lm_ols)
IF_pred_ZM_lm_ols <- exp(predict(IF_ZM_lm_ols, newdata = RO_Census_Ilfov, 
                                 interval = "prediction", level = 0.95))
IF_ZM_out_ols <- RO_Census_Ilfov %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(IF_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Ilfov), 
         DFFIT = dffits(IF_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(IF_ZM_lm_ols$coefficients) / nrow(RO_Census_Ilfov)), 
         Rezid_Std = rstudent(IF_ZM_lm_ols), Leverage = hatvalues(IF_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(IF_ZM_lm_ols)), 
         DFBETA = dfbetas(IF_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Ilfov)))

# c) Exponential Law
IF_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Ilfov)
summary(IF_exp_lm_ols)
IF_pred_exp_lm_ols <- exp(predict(IF_exp_lm_ols, newdata = RO_Census_Ilfov, 
                                  interval = "prediction", level = 0.95))
IF_exp_out_ols <- RO_Census_Ilfov %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(IF_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Ilfov), 
         DFFIT = dffits(IF_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(IF_exp_lm_ols$coefficients) / nrow(RO_Census_Ilfov)), 
         Rezid_Std = rstudent(IF_exp_lm_ols), Leverage = hatvalues(IF_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(IF_exp_lm_ols)), 
         DFBETA = dfbetas(IF_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Ilfov)))

# d) Lavalette Function
RO_Census_Ilfov <- RO_Census_Ilfov %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Ilfov) - Rank + 1))
)
IF_lav_lm_ols <- lm(log(RO_Census_Ilfov$Population) ~ RO_Census_Ilfov$Lav_exp)
summary(IF_lav_lm_ols)
IF_lav_kst_ols <- exp(signif(IF_lav_lm_ols$coef[[1]], 4))
IF_lav_chi_ols <- signif(IF_lav_lm_ols$coef[[2]], 4)
IF_pred_lav_lm_ols <- exp(predict(IF_lav_lm_ols, newdata = RO_Census_Ilfov, 
                                  interval = "prediction", level = 0.95))
IF_lav_out_ols <- RO_Census_Ilfov %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(IF_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Ilfov), 
         DFFIT = dffits(IF_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(IF_lav_lm_ols$coefficients) / nrow(RO_Census_Ilfov)), 
         Rezid_Std = rstudent(IF_lav_lm_ols), Leverage = hatvalues(IF_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(IF_lav_lm_ols)), 
         DFBETA = dfbetas(IF_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Ilfov)))

# e) Data Distributions
RO_Census_Ilfov %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Ilfov$Rank, 
                              Population = IF_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(IF_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(IF_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(IF_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Ilfov$Rank, 
                              Population = IF_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(IF_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(IF_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(IF_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Ilfov$Rank, 
                              Population = IF_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(IF_ZM_cst_ols, 4), "%.%", "(",
                           signif(IF_ZM_m_ols, 4), "+ x)^", signif(IF_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(summary(IF_ZM_lm_ols)$r.squared, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Ilfov$Rank, 
                              Population = IF_pred_lav_lm_ols[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(IF_lav_kst_ols, 4), "%.%", "x^",
                           -signif(IF_lav_chi_ols, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(summary(IF_lav_lm_ols)$r.squared, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Ilfov judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# Linear Regressions
grid.arrange(
  (RO_Census_Ilfov %>%
     ggplot(aes(x = log(Rank), y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = "#ED3F39FF") +
     labs(x = "Rank", y = "Population") +
     ggtitle("Power Linear Regression on Ilfov judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  (RO_Census_Ilfov %>%
     ggplot(aes(x = Rank, y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = "#088BBEFF") +
     labs(x = "Rank", y = "Population") +
     ggtitle("Exponential Linear Regression on Ilfov judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  (RO_Census_Ilfov %>%
     ggplot(aes(x = log(Rank + IF_ZM_m_ols), y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = '#1B7837FF') +
     labs(x = "Rank", y = "Population") +
     ggtitle("Zipf-Mandelbrot Linear Regression on Ilfov judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  (RO_Census_Ilfov %>%
     ggplot(aes(x = Lav_exp, y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = '#F8A02EFF') +
     labs(x = "Rank", y = "Population") +
     ggtitle("Lavalette Linear Regression on Ilfov judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  ncol = 2, nrow = 2)

# f) Extract Outliers
Ilfov_Outliers <- bind_rows(
  (IF_pw_out_ols %>% mutate(Function_Name = "Power")),
  (IF_ZM_out_ols %>% mutate(Function_Name = "Zipf-Mandelbrot")),
  (IF_exp_out_ols %>% mutate(Function_Name = "Exponential")),
  (IF_lav_out_ols %>% mutate(Function_Name = "Lavalette"))
) %>% mutate(DFBETA_intercept = round(DFBETA[,1], 8), 
             DFBETA_var_x = round(DFBETA[,2], 8)) %>% dplyr::select(-DFBETA)

IF_out <- get_outliers(Ilfov_Outliers, RO_Census_Ilfov)

IF_out_ols <- RO_Census_Ilfov %>% inner_join(
  bind_rows(
    (IF_out$PW %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>% 
       dplyr::select(Rank) %>% distinct()),
    (IF_out$ZM %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (IF_out$LAV %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (IF_out$EXP %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct())
  ) %>% count(Rank) %>% arrange(desc(n)) %>% filter(n >= mean(n))) %>% 
  dplyr::select(-n)

# g) Extract regression metrics
IF_regmet_ols <- as.data.frame(list(Judet_Name = "ILFOV",
                                    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
                                    R_Squared = c(signif(summary(IF_pw_lm_ols)$r.squared, 4), 
                                                  signif(summary(IF_exp_lm_ols)$r.squared, 4),
                                                  signif(summary(IF_ZM_lm_ols)$r.squared, 4),
                                                  signif(summary(IF_lav_lm_ols)$r.squared, 4)),
                                    Adj_R_Squared = c(signif(summary(IF_pw_lm_ols)$adj.r.squared, 4), 
                                                      signif(summary(IF_exp_lm_ols)$adj.r.squared, 4),
                                                      signif(summary(IF_ZM_lm_ols)$adj.r.squared, 4),
                                                      signif(summary(IF_lav_lm_ols)$adj.r.squared, 4)),
                                    AIC = c(signif(AIC(IF_pw_lm_ols), 4), signif(AIC(IF_exp_lm_ols), 4), 
                                            signif(AIC(IF_ZM_lm_ols), 4), signif(AIC(IF_lav_lm_ols), 4)),
                                    BIC = c(signif(BIC(IF_pw_lm_ols), 4), signif(BIC(IF_exp_lm_ols), 4), 
                                            signif(BIC(IF_ZM_lm_ols), 4), signif(BIC(IF_lav_lm_ols), 4)),
                                    MAE = c(signif(mean(abs((log(RO_Census_Ilfov$Population) - 
                                                               (predict(IF_pw_lm_ols, newdata = RO_Census_Ilfov, 
                                                                        interval = "prediction", level = 0.95))))), 4), 
                                            signif(mean(abs((log(RO_Census_Ilfov$Population) - 
                                                               (predict(IF_exp_lm_ols, newdata = RO_Census_Ilfov, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Ilfov$Population) - 
                                                               (predict(IF_ZM_lm_ols, newdata = RO_Census_Ilfov, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Ilfov$Population) - 
                                                               (predict(IF_lav_lm_ols, newdata = RO_Census_Ilfov, 
                                                                        interval = "prediction", level = 0.95))))), 4)),
                                    RMSE = c(signif(sqrt(mean(((log(RO_Census_Ilfov$Population)) - 
                                                                 (predict(IF_pw_lm_ols, newdata = RO_Census_Ilfov, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Ilfov$Population)) - 
                                                                 (predict(IF_exp_lm_ols, newdata = RO_Census_Ilfov, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Ilfov$Population)) - 
                                                                 (predict(IF_ZM_lm_ols, newdata = RO_Census_Ilfov, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Ilfov$Population)) - 
                                                                 (predict(IF_lav_lm_ols, newdata = RO_Census_Ilfov, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4))
))

# h) Extract MAE/RMSE on head, body, tail
RO_Census_Ilfov_ols <- RO_Census_Ilfov %>% 
  mutate(PW_Y_Pred = (predict(IF_pw_lm_ols, newdata = RO_Census_Ilfov, 
                              interval = "prediction", level = 0.95))[,1], 
         ZM_Y_Pred = (predict(IF_ZM_lm_ols, newdata = RO_Census_Ilfov, 
                              interval = "prediction", level = 0.95))[,1],
         EXP_Y_Pred = (predict(IF_exp_lm_ols, newdata = RO_Census_Ilfov, 
                               interval = "prediction", level = 0.95))[,1], 
         LAV_Y_Pred = (predict(IF_lav_lm_ols, newdata = RO_Census_Ilfov, 
                               interval = "prediction", level = 0.95))[,1])

# Head
IF_ols_hd <- RO_Census_Ilfov_ols %>% filter(Rank <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(IF_ols_hd$Population) - IF_ols_hd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(IF_ols_hd$Population) - IF_ols_hd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(IF_ols_hd$Population) - IF_ols_hd$ZM_Y_Pred))), 4),
          signif(mean(abs((log(IF_ols_hd$Population) - IF_ols_hd$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(IF_ols_hd$Population)) - IF_ols_hd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(IF_ols_hd$Population)) - IF_ols_hd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(IF_ols_hd$Population)) - IF_ols_hd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(IF_ols_hd$Population)) - IF_ols_hd$LAV_Y_Pred) ^ 2)), 4))
))

# Tail
IF_ols_tl <- RO_Census_Ilfov_ols %>% arrange(desc(Rank)) %>% 
  filter(row_number() <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(IF_ols_tl$Population) - IF_ols_tl$PW_Y_Pred))), 4), 
          signif(mean(abs((log(IF_ols_tl$Population) - IF_ols_tl$EXP_Y_Pred))), 4),
          signif(mean(abs((log(IF_ols_tl$Population) - IF_ols_tl$ZM_Y_Pred))), 4),
          signif(mean(abs((log(IF_ols_tl$Population) - IF_ols_tl$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(IF_ols_tl$Population)) - IF_ols_tl$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(IF_ols_tl$Population)) - IF_ols_tl$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(IF_ols_tl$Population)) - IF_ols_tl$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(IF_ols_tl$Population)) - IF_ols_tl$LAV_Y_Pred) ^ 2)), 4))
))

# Body
IF_ols_bd <- RO_Census_Ilfov_ols %>% anti_join(IF_ols_hd) %>% anti_join(IF_ols_tl)

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
