            signif(mean(abs((log(IF_ols_bd$Population) - IF_ols_bd$EXP_Y_Pred))), 4),
            signif(mean(abs((log(IF_ols_bd$Population) - IF_ols_bd$ZM_Y_Pred))), 4),
            signif(mean(abs((log(IF_ols_bd$Population) - IF_ols_bd$LAV_Y_Pred))), 4)),
    RMSE = c(signif(sqrt(mean(((log(IF_ols_bd$Population)) - IF_ols_bd$PW_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(IF_ols_bd$Population)) - IF_ols_bd$EXP_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(IF_ols_bd$Population)) - IF_ols_bd$ZM_Y_Pred) ^ 2)), 4),
             signif(sqrt(mean(((log(IF_ols_bd$Population)) - IF_ols_bd$LAV_Y_Pred) ^ 2)), 4)),
    Data_Part = "Body"
  )),
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(RO_Census_Ilfov$Population) - 
