                                        interval = "prediction", level = 0.95))))), 4), 
            signif(mean(abs((log(RO_Census_Ilfov$Population) - 
                               (predict(IF_exp_lm_ols, newdata = RO_Census_Ilfov, 
                                        interval = "prediction", level = 0.95))))), 4),
            signif(mean(abs((log(RO_Census_Ilfov$Population) - 
                               (predict(IF_ZM_lm_ols, newdata = RO_Census_Ilfov, 
                                        interval = "prediction", level = 0.95))))), 4),
            signif(mean(abs((log(RO_Census_Ilfov$Population) - 
                               (predict(IF_lav_lm_ols, newdata = RO_Census_Ilfov, 
                                        interval = "prediction", level = 0.95))))), 4)),
    RMSE = c(signif(sqrt(mean(((log(RO_Census_Ilfov$Population)) - 
                                 (predict(IF_pw_lm_ols, newdata = RO_Census_Ilfov, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Ilfov$Population)) - 
                                 (predict(IF_exp_lm_ols, newdata = RO_Census_Ilfov, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Ilfov$Population)) - 
                                 (predict(IF_ZM_lm_ols, newdata = RO_Census_Ilfov, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Ilfov$Population)) - 
                                 (predict(IF_lav_lm_ols, newdata = RO_Census_Ilfov, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4)),
    Data_Part = "Full"
  ))
)) %>% mutate(Regression_Type = "OLS", Judet_Name = "ILFOV")

# 2. Robust

# a) Power Law
IF_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Ilfov)
summary(IF_pw_lm_rob)
IF_pred_pw_lm_rob <- exp(predict(IF_pw_lm_rob, newdata = RO_Census_Ilfov, 
                                 interval = "prediction", level = 0.95))
IF_RSquared_pw_rob <- 1 - sum((log(RO_Census_Ilfov$Population) - fitted(IF_pw_lm_rob))^2) / 
  sum((log(RO_Census_Ilfov$Population) - mean(log(RO_Census_Ilfov$Population)))^2)

# b) Zipf_Mandelbrot Law
IF_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Ilfov, "Population", "Rank")
IF_ZM_m_rob <- IF_ZM_prm_rob$m
IF_ZM_alpha_rob <- IF_ZM_prm_rob$alpha_ZM
IF_ZM_cst_rob <- IF_ZM_prm_rob$constant_ZM
IF_ZM_lm_rob <- rlm(log(RO_Census_Ilfov$Population) ~ log(RO_Census_Ilfov$Rank + IF_ZM_m_rob))
summary(IF_ZM_lm_rob)
IF_pred_ZM_lm_rob <- exp(predict(IF_ZM_lm_rob, newdata = RO_Census_Ilfov, 
                                 interval = "prediction", level = 0.95))
IF_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Ilfov$Population) - fitted(IF_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Ilfov$Population) - mean(log(RO_Census_Ilfov$Population)))^2)

# c) Exponential Law
IF_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Ilfov)
summary(IF_exp_lm_rob)
IF_pred_exp_lm_rob <- exp(predict(IF_exp_lm_rob, newdata = RO_Census_Ilfov, 
                                  interval = "prediction", level = 0.95))
IF_RSquared_exp_rob <- 1 - sum((log(RO_Census_Ilfov$Population) - fitted(IF_exp_lm_rob))^2) / 
  sum((log(RO_Census_Ilfov$Population) - mean(log(RO_Census_Ilfov$Population)))^2)

# d) Lavalette Function
RO_Census_Ilfov <- RO_Census_Ilfov %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Ilfov) - Rank + 1))
)
IF_lav_lm_rob <- rlm(log(RO_Census_Ilfov$Population) ~ RO_Census_Ilfov$Lav_exp)
summary(IF_lav_lm_rob)
IF_lav_kst_rob <- exp(signif(IF_lav_lm_rob$coef[[1]], 4))
IF_lav_chi_rob <- signif(IF_lav_lm_rob$coef[[2]], 4)
IF_pred_lav_lm_rob <- exp(predict(IF_lav_lm_rob, newdata = RO_Census_Ilfov, 
                                  interval = "prediction", level = 0.95))
IF_RSquared_lav_rob <- 1 - sum((log(RO_Census_Ilfov$Population) - fitted(IF_lav_lm_rob))^2) / 
  sum((log(RO_Census_Ilfov$Population) - mean(log(RO_Census_Ilfov$Population)))^2)

# e) Data Distributions
RO_Census_Ilfov %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Ilfov$Rank, 
                              Population = IF_pred_pw_lm_rob[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(IF_pw_lm_rob$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(IF_pw_lm_rob$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(IF_RSquared_pw_rob, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Ilfov$Rank, 
                              Population = IF_pred_exp_lm_rob[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(IF_exp_lm_rob$coefficients[[1]]), 4), "%.%", 
                           signif(exp(IF_exp_lm_rob$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(IF_RSquared_exp_rob, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Ilfov$Rank, 
                              Population = IF_pred_ZM_lm_rob[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(IF_ZM_cst_rob, 4), "%.%", "(",
                           signif(IF_ZM_m_rob, 4), "+ x)^", signif(IF_ZM_alpha_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(IF_RSquared_ZM_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Ilfov$Rank, 
                              Population = IF_pred_lav_lm_rob[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(IF_lav_kst_rob, 4), "%.%", "x^",
                           -signif(IF_lav_chi_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(IF_RSquared_lav_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Ilfov judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# f) Extract regression metrics
IF_regmet_rob <- as.data.frame(list(Judet_Name = "ILFOV",
                                    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
