# XXVI. Maramures

# 1. OLS
RO_Census_Maramures <- RO_Census_rank %>% filter(Judet_Name == "MARAMURES")
#View(RO_Census_Maramures)

# a) Power Law
MM_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Maramures)
summary(MM_pw_lm_ols)
MM_pred_pw_lm_ols <- exp(predict(MM_pw_lm_ols, newdata = RO_Census_Maramures, 
                                 interval = "prediction", level = 0.95))
MM_pw_out_ols <- RO_Census_Maramures %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(MM_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Maramures), 
         DFFIT = dffits(MM_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(MM_pw_lm_ols$coefficients) / nrow(RO_Census_Maramures)), 
         Rezid_Std = rstudent(MM_pw_lm_ols), Leverage = hatvalues(MM_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(MM_pw_lm_ols)), 
         DFBETA = dfbetas(MM_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Maramures)))

# b) Zipf_Mandelbrot Law
MM_ZM_prm_ols <- get_ZM_Param("RO_Census_Maramures", "Population", "Rank")
MM_ZM_m_ols <- MM_ZM_prm_ols$m
MM_ZM_alpha_ols <- MM_ZM_prm_ols$alpha_ZM
MM_ZM_cst_ols <- MM_ZM_prm_ols$constant_ZM
MM_ZM_lm_ols <- lm(log(RO_Census_Maramures$Population) ~ log(RO_Census_Maramures$Rank + MM_ZM_m_ols))
summary(MM_ZM_lm_ols)
MM_pred_ZM_lm_ols <- exp(predict(MM_ZM_lm_ols, newdata = RO_Census_Maramures, 
                                 interval = "prediction", level = 0.95))
MM_ZM_out_ols <- RO_Census_Maramures %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(MM_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Maramures), 
         DFFIT = dffits(MM_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(MM_ZM_lm_ols$coefficients) / nrow(RO_Census_Maramures)), 
         Rezid_Std = rstudent(MM_ZM_lm_ols), Leverage = hatvalues(MM_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(MM_ZM_lm_ols)), 
         DFBETA = dfbetas(MM_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Maramures)))

# c) Exponential Law
MM_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Maramures)
summary(MM_exp_lm_ols)
MM_pred_exp_lm_ols <- exp(predict(MM_exp_lm_ols, newdata = RO_Census_Maramures, 
                                  interval = "prediction", level = 0.95))
MM_exp_out_ols <- RO_Census_Maramures %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(MM_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Maramures), 
         DFFIT = dffits(MM_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(MM_exp_lm_ols$coefficients) / nrow(RO_Census_Maramures)), 
         Rezid_Std = rstudent(MM_exp_lm_ols), Leverage = hatvalues(MM_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(MM_exp_lm_ols)), 
         DFBETA = dfbetas(MM_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Maramures)))

# d) Lavalette Function
RO_Census_Maramures <- RO_Census_Maramures %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Maramures) - Rank + 1))
)
MM_lav_lm_ols <- lm(log(RO_Census_Maramures$Population) ~ RO_Census_Maramures$Lav_exp)
summary(MM_lav_lm_ols)
MM_lav_kst_ols <- exp(signif(MM_lav_lm_ols$coef[[1]], 4))
MM_lav_chi_ols <- signif(MM_lav_lm_ols$coef[[2]], 4)
MM_pred_lav_lm_ols <- exp(predict(MM_lav_lm_ols, newdata = RO_Census_Maramures, 
                                  interval = "prediction", level = 0.95))
MM_lav_out_ols <- RO_Census_Maramures %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(MM_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Maramures), 
         DFFIT = dffits(MM_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(MM_lav_lm_ols$coefficients) / nrow(RO_Census_Maramures)), 
         Rezid_Std = rstudent(MM_lav_lm_ols), Leverage = hatvalues(MM_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(MM_lav_lm_ols)), 
         DFBETA = dfbetas(MM_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Maramures)))

# e) Data Distributions
RO_Census_Maramures %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Maramures$Rank, 
                              Population = MM_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(MM_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(MM_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(MM_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Maramures$Rank, 
                              Population = MM_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(MM_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(MM_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(MM_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Maramures$Rank, 
                              Population = MM_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(MM_ZM_cst_ols, 4), "%.%", "(",
                           signif(MM_ZM_m_ols, 4), "+ x)^", signif(MM_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(summary(MM_ZM_lm_ols)$r.squared, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Maramures$Rank, 
                              Population = MM_pred_lav_lm_ols[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(MM_lav_kst_ols, 4), "%.%", "x^",
                           -signif(MM_lav_chi_ols, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(summary(MM_lav_lm_ols)$r.squared, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Maramures judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# Linear Regressions
