# f) Extract Outliers
Maramures_Outliers <- bind_rows(
  (MM_pw_out_ols %>% mutate(Function_Name = "Power")),
  (MM_ZM_out_ols %>% mutate(Function_Name = "Zipf-Mandelbrot")),
  (MM_exp_out_ols %>% mutate(Function_Name = "Exponential")),
  (MM_lav_out_ols %>% mutate(Function_Name = "Lavalette"))
) %>% mutate(DFBETA_intercept = round(DFBETA[,1], 8), 
             DFBETA_var_x = round(DFBETA[,2], 8)) %>% dplyr::select(-DFBETA)

MM_out <- get_outliers(Maramures_Outliers, RO_Census_Maramures)

MM_out_ols <- RO_Census_Maramures %>% inner_join(
  bind_rows(
    (MM_out$PW %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>% 
       dplyr::select(Rank) %>% distinct()),
    (MM_out$ZM %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (MM_out$LAV %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (MM_out$EXP %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct())
  ) %>% count(Rank) %>% arrange(desc(n)) %>% filter(n >= mean(n))) %>% 
  dplyr::select(-n)

