                                            signif(BIC(MM_ZM_lm_ols), 4), signif(BIC(MM_lav_lm_ols), 4)),
                                    MAE = c(signif(mean(abs((log(RO_Census_Maramures$Population) - 
                                                               (predict(MM_pw_lm_ols, newdata = RO_Census_Maramures, 
                                                                        interval = "prediction", level = 0.95))))), 4), 
                                            signif(mean(abs((log(RO_Census_Maramures$Population) - 
                                                               (predict(MM_exp_lm_ols, newdata = RO_Census_Maramures, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Maramures$Population) - 
                                                               (predict(MM_ZM_lm_ols, newdata = RO_Census_Maramures, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Maramures$Population) - 
                                                               (predict(MM_lav_lm_ols, newdata = RO_Census_Maramures, 
                                                                        interval = "prediction", level = 0.95))))), 4)),
                                    RMSE = c(signif(sqrt(mean(((log(RO_Census_Maramures$Population)) - 
                                                                 (predict(MM_pw_lm_ols, newdata = RO_Census_Maramures, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Maramures$Population)) - 
                                                                 (predict(MM_exp_lm_ols, newdata = RO_Census_Maramures, 
