                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4))
))

# h) Extract MAE/RMSE on head, body, tail
RO_Census_Maramures_ols <- RO_Census_Maramures %>% 
  mutate(PW_Y_Pred = (predict(MM_pw_lm_ols, newdata = RO_Census_Maramures, 
                              interval = "prediction", level = 0.95))[,1], 
         ZM_Y_Pred = (predict(MM_ZM_lm_ols, newdata = RO_Census_Maramures, 
                              interval = "prediction", level = 0.95))[,1],
         EXP_Y_Pred = (predict(MM_exp_lm_ols, newdata = RO_Census_Maramures, 
                               interval = "prediction", level = 0.95))[,1], 
         LAV_Y_Pred = (predict(MM_lav_lm_ols, newdata = RO_Census_Maramures, 
                               interval = "prediction", level = 0.95))[,1])

# Head
MM_ols_hd <- RO_Census_Maramures_ols %>% filter(Rank <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(MM_ols_hd$Population) - MM_ols_hd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(MM_ols_hd$Population) - MM_ols_hd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(MM_ols_hd$Population) - MM_ols_hd$ZM_Y_Pred))), 4),
          signif(mean(abs((log(MM_ols_hd$Population) - MM_ols_hd$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(MM_ols_hd$Population)) - MM_ols_hd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(MM_ols_hd$Population)) - MM_ols_hd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(MM_ols_hd$Population)) - MM_ols_hd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(MM_ols_hd$Population)) - MM_ols_hd$LAV_Y_Pred) ^ 2)), 4))
))

# Tail
MM_ols_tl <- RO_Census_Maramures_ols %>% arrange(desc(Rank)) %>% 
  filter(row_number() <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(MM_ols_tl$Population) - MM_ols_tl$PW_Y_Pred))), 4), 
          signif(mean(abs((log(MM_ols_tl$Population) - MM_ols_tl$EXP_Y_Pred))), 4),
          signif(mean(abs((log(MM_ols_tl$Population) - MM_ols_tl$ZM_Y_Pred))), 4),
          signif(mean(abs((log(MM_ols_tl$Population) - MM_ols_tl$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(MM_ols_tl$Population)) - MM_ols_tl$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(MM_ols_tl$Population)) - MM_ols_tl$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(MM_ols_tl$Population)) - MM_ols_tl$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(MM_ols_tl$Population)) - MM_ols_tl$LAV_Y_Pred) ^ 2)), 4))
))

# Body
MM_ols_bd <- RO_Census_Maramures_ols %>% anti_join(MM_ols_hd) %>% anti_join(MM_ols_tl)

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(MM_ols_bd$Population) - MM_ols_bd$PW_Y_Pred))), 4), 
