  RMSE = c(signif(sqrt(mean(((log(MM_ols_bd$Population)) - MM_ols_bd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(MM_ols_bd$Population)) - MM_ols_bd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(MM_ols_bd$Population)) - MM_ols_bd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(MM_ols_bd$Population)) - MM_ols_bd$LAV_Y_Pred) ^ 2)), 4))
))

