# 2. Robust

# a) Power Law
MM_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Maramures)
summary(MM_pw_lm_rob)
MM_pred_pw_lm_rob <- exp(predict(MM_pw_lm_rob, newdata = RO_Census_Maramures, 
                                 interval = "prediction", level = 0.95))
MM_RSquared_pw_rob <- 1 - sum((log(RO_Census_Maramures$Population) - fitted(MM_pw_lm_rob))^2) / 
  sum((log(RO_Census_Maramures$Population) - mean(log(RO_Census_Maramures$Population)))^2)

# b) Zipf_Mandelbrot Law
MM_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Maramures, "Population", "Rank")
MM_ZM_m_rob <- MM_ZM_prm_rob$m
MM_ZM_alpha_rob <- MM_ZM_prm_rob$alpha_ZM
MM_ZM_cst_rob <- MM_ZM_prm_rob$constant_ZM
MM_ZM_lm_rob <- rlm(log(RO_Census_Maramures$Population) ~ log(RO_Census_Maramures$Rank + MM_ZM_m_rob))
summary(MM_ZM_lm_rob)
MM_pred_ZM_lm_rob <- exp(predict(MM_ZM_lm_rob, newdata = RO_Census_Maramures, 
                                 interval = "prediction", level = 0.95))
MM_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Maramures$Population) - fitted(MM_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Maramures$Population) - mean(log(RO_Census_Maramures$Population)))^2)

# c) Exponential Law
MM_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Maramures)
summary(MM_exp_lm_rob)
MM_pred_exp_lm_rob <- exp(predict(MM_exp_lm_rob, newdata = RO_Census_Maramures, 
                                  interval = "prediction", level = 0.95))
MM_RSquared_exp_rob <- 1 - sum((log(RO_Census_Maramures$Population) - fitted(MM_exp_lm_rob))^2) / 
  sum((log(RO_Census_Maramures$Population) - mean(log(RO_Census_Maramures$Population)))^2)

# d) Lavalette Function
RO_Census_Maramures <- RO_Census_Maramures %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Maramures) - Rank + 1))
)
MM_lav_lm_rob <- rlm(log(RO_Census_Maramures$Population) ~ RO_Census_Maramures$Lav_exp)
summary(MM_lav_lm_rob)
MM_lav_kst_rob <- exp(signif(MM_lav_lm_rob$coef[[1]], 4))
MM_lav_chi_rob <- signif(MM_lav_lm_rob$coef[[2]], 4)
MM_pred_lav_lm_rob <- exp(predict(MM_lav_lm_rob, newdata = RO_Census_Maramures, 
                                  interval = "prediction", level = 0.95))
MM_RSquared_lav_rob <- 1 - sum((log(RO_Census_Maramures$Population) - fitted(MM_lav_lm_rob))^2) / 
  sum((log(RO_Census_Maramures$Population) - mean(log(RO_Census_Maramures$Population)))^2)

# e) Data Distributions
RO_Census_Maramures %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Maramures$Rank, 
                              Population = MM_pred_pw_lm_rob[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(MM_pw_lm_rob$coefficients[[1]]), 4), "%.%", 
