# XXVII. Mehedinti

# 1. OLS
RO_Census_Mehedinti <- RO_Census_rank %>% filter(Judet_Name == "MEHEDINTI")
#View(RO_Census_Mehedinti)

# a) Power Law
MH_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Mehedinti)
summary(MH_pw_lm_ols)
MH_pred_pw_lm_ols <- exp(predict(MH_pw_lm_ols, newdata = RO_Census_Mehedinti, 
                                 interval = "prediction", level = 0.95))
MH_pw_out_ols <- RO_Census_Mehedinti %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(MH_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Mehedinti), 
         DFFIT = dffits(MH_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(MH_pw_lm_ols$coefficients) / nrow(RO_Census_Mehedinti)), 
         Rezid_Std = rstudent(MH_pw_lm_ols), Leverage = hatvalues(MH_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(MH_pw_lm_ols)), 
         DFBETA = dfbetas(MH_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Mehedinti)))

# b) Zipf_Mandelbrot Law
MH_ZM_prm_ols <- get_ZM_Param("RO_Census_Mehedinti", "Population", "Rank")
MH_ZM_m_ols <- MH_ZM_prm_ols$m
MH_ZM_alpha_ols <- MH_ZM_prm_ols$alpha_ZM
MH_ZM_cst_ols <- MH_ZM_prm_ols$constant_ZM
MH_ZM_lm_ols <- lm(log(RO_Census_Mehedinti$Population) ~ log(RO_Census_Mehedinti$Rank + MH_ZM_m_ols))
summary(MH_ZM_lm_ols)
MH_pred_ZM_lm_ols <- exp(predict(MH_ZM_lm_ols, newdata = RO_Census_Mehedinti, 
                                 interval = "prediction", level = 0.95))
MH_ZM_out_ols <- RO_Census_Mehedinti %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(MH_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Mehedinti), 
         DFFIT = dffits(MH_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(MH_ZM_lm_ols$coefficients) / nrow(RO_Census_Mehedinti)), 
         Rezid_Std = rstudent(MH_ZM_lm_ols), Leverage = hatvalues(MH_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(MH_ZM_lm_ols)), 
         DFBETA = dfbetas(MH_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Mehedinti)))

# c) Exponential Law
MH_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Mehedinti)
summary(MH_exp_lm_ols)
MH_pred_exp_lm_ols <- exp(predict(MH_exp_lm_ols, newdata = RO_Census_Mehedinti, 
                                  interval = "prediction", level = 0.95))
MH_exp_out_ols <- RO_Census_Mehedinti %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(MH_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Mehedinti), 
         DFFIT = dffits(MH_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(MH_exp_lm_ols$coefficients) / nrow(RO_Census_Mehedinti)), 
         Rezid_Std = rstudent(MH_exp_lm_ols), Leverage = hatvalues(MH_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(MH_exp_lm_ols)), 
         DFBETA = dfbetas(MH_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Mehedinti)))

# d) Lavalette Function
RO_Census_Mehedinti <- RO_Census_Mehedinti %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Mehedinti) - Rank + 1))
)
MH_lav_lm_ols <- lm(log(RO_Census_Mehedinti$Population) ~ RO_Census_Mehedinti$Lav_exp)
summary(MH_lav_lm_ols)
MH_lav_kst_ols <- exp(signif(MH_lav_lm_ols$coef[[1]], 4))
MH_lav_chi_ols <- signif(MH_lav_lm_ols$coef[[2]], 4)
MH_pred_lav_lm_ols <- exp(predict(MH_lav_lm_ols, newdata = RO_Census_Mehedinti, 
                                  interval = "prediction", level = 0.95))
MH_lav_out_ols <- RO_Census_Mehedinti %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(MH_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Mehedinti), 
         DFFIT = dffits(MH_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(MH_lav_lm_ols$coefficients) / nrow(RO_Census_Mehedinti)), 
         Rezid_Std = rstudent(MH_lav_lm_ols), Leverage = hatvalues(MH_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(MH_lav_lm_ols)), 
         DFBETA = dfbetas(MH_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Mehedinti)))

