# 2. Robust

# a) Power Law
MH_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Mehedinti)
summary(MH_pw_lm_rob)
MH_pred_pw_lm_rob <- exp(predict(MH_pw_lm_rob, newdata = RO_Census_Mehedinti, 
                                 interval = "prediction", level = 0.95))
MH_RSquared_pw_rob <- 1 - sum((log(RO_Census_Mehedinti$Population) - fitted(MH_pw_lm_rob))^2) / 
  sum((log(RO_Census_Mehedinti$Population) - mean(log(RO_Census_Mehedinti$Population)))^2)

# b) Zipf_Mandelbrot Law
MH_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Mehedinti, "Population", "Rank")
MH_ZM_m_rob <- MH_ZM_prm_rob$m
MH_ZM_alpha_rob <- MH_ZM_prm_rob$alpha_ZM
MH_ZM_cst_rob <- MH_ZM_prm_rob$constant_ZM
MH_ZM_lm_rob <- rlm(log(RO_Census_Mehedinti$Population) ~ log(RO_Census_Mehedinti$Rank + MH_ZM_m_rob))
summary(MH_ZM_lm_rob)
MH_pred_ZM_lm_rob <- exp(predict(MH_ZM_lm_rob, newdata = RO_Census_Mehedinti, 
                                 interval = "prediction", level = 0.95))
MH_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Mehedinti$Population) - fitted(MH_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Mehedinti$Population) - mean(log(RO_Census_Mehedinti$Population)))^2)

# c) Exponential Law
MH_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Mehedinti)
summary(MH_exp_lm_rob)
MH_pred_exp_lm_rob <- exp(predict(MH_exp_lm_rob, newdata = RO_Census_Mehedinti, 
                                  interval = "prediction", level = 0.95))
MH_RSquared_exp_rob <- 1 - sum((log(RO_Census_Mehedinti$Population) - fitted(MH_exp_lm_rob))^2) / 
  sum((log(RO_Census_Mehedinti$Population) - mean(log(RO_Census_Mehedinti$Population)))^2)

# d) Lavalette Function
RO_Census_Mehedinti <- RO_Census_Mehedinti %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Mehedinti) - Rank + 1))
)
MH_lav_lm_rob <- rlm(log(RO_Census_Mehedinti$Population) ~ RO_Census_Mehedinti$Lav_exp)
summary(MH_lav_lm_rob)
MH_lav_kst_rob <- exp(signif(MH_lav_lm_rob$coef[[1]], 4))
MH_lav_chi_rob <- signif(MH_lav_lm_rob$coef[[2]], 4)
MH_pred_lav_lm_rob <- exp(predict(MH_lav_lm_rob, newdata = RO_Census_Mehedinti, 
                                  interval = "prediction", level = 0.95))
MH_RSquared_lav_rob <- 1 - sum((log(RO_Census_Mehedinti$Population) - fitted(MH_lav_lm_rob))^2) / 
  sum((log(RO_Census_Mehedinti$Population) - mean(log(RO_Census_Mehedinti$Population)))^2)

