# XXVIII. Mures

# 1. OLS
RO_Census_Mures <- RO_Census_rank %>% filter(Judet_Name == "MURES")
#View(RO_Census_Mures)

# a) Power Law
MS_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Mures)
summary(MS_pw_lm_ols)
MS_pred_pw_lm_ols <- exp(predict(MS_pw_lm_ols, newdata = RO_Census_Mures, 
                                 interval = "prediction", level = 0.95))
MS_pw_out_ols <- RO_Census_Mures %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(MS_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Mures), 
         DFFIT = dffits(MS_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(MS_pw_lm_ols$coefficients) / nrow(RO_Census_Mures)), 
         Rezid_Std = rstudent(MS_pw_lm_ols), Leverage = hatvalues(MS_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(MS_pw_lm_ols)), 
         DFBETA = dfbetas(MS_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Mures)))

# b) Zipf_Mandelbrot Law
MS_ZM_prm_ols <- get_ZM_Param("RO_Census_Mures", "Population", "Rank")
MS_ZM_m_ols <- MS_ZM_prm_ols$m
MS_ZM_alpha_ols <- MS_ZM_prm_ols$alpha_ZM
MS_ZM_cst_ols <- MS_ZM_prm_ols$constant_ZM
MS_ZM_lm_ols <- lm(log(RO_Census_Mures$Population) ~ log(RO_Census_Mures$Rank + MS_ZM_m_ols))
summary(MS_ZM_lm_ols)
MS_pred_ZM_lm_ols <- exp(predict(MS_ZM_lm_ols, newdata = RO_Census_Mures, 
                                 interval = "prediction", level = 0.95))
MS_ZM_out_ols <- RO_Census_Mures %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(MS_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Mures), 
         DFFIT = dffits(MS_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(MS_ZM_lm_ols$coefficients) / nrow(RO_Census_Mures)), 
         Rezid_Std = rstudent(MS_ZM_lm_ols), Leverage = hatvalues(MS_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(MS_ZM_lm_ols)), 
         DFBETA = dfbetas(MS_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Mures)))

# c) Exponential Law
MS_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Mures)
summary(MS_exp_lm_ols)
MS_pred_exp_lm_ols <- exp(predict(MS_exp_lm_ols, newdata = RO_Census_Mures, 
                                  interval = "prediction", level = 0.95))
MS_exp_out_ols <- RO_Census_Mures %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(MS_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Mures), 
         DFFIT = dffits(MS_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(MS_exp_lm_ols$coefficients) / nrow(RO_Census_Mures)), 
         Rezid_Std = rstudent(MS_exp_lm_ols), Leverage = hatvalues(MS_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(MS_exp_lm_ols)), 
         DFBETA = dfbetas(MS_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Mures)))

# d) Lavalette Function
RO_Census_Mures <- RO_Census_Mures %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Mures) - Rank + 1))
)
MS_lav_lm_ols <- lm(log(RO_Census_Mures$Population) ~ RO_Census_Mures$Lav_exp)
summary(MS_lav_lm_ols)
MS_lav_kst_ols <- exp(signif(MS_lav_lm_ols$coef[[1]], 4))
MS_lav_chi_ols <- signif(MS_lav_lm_ols$coef[[2]], 4)
MS_pred_lav_lm_ols <- exp(predict(MS_lav_lm_ols, newdata = RO_Census_Mures, 
                                  interval = "prediction", level = 0.95))
MS_lav_out_ols <- RO_Census_Mures %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(MS_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Mures), 
         DFFIT = dffits(MS_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(MS_lav_lm_ols$coefficients) / nrow(RO_Census_Mures)), 
         Rezid_Std = rstudent(MS_lav_lm_ols), Leverage = hatvalues(MS_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(MS_lav_lm_ols)), 
         DFBETA = dfbetas(MS_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Mures)))

