# 2. Robust

# a) Power Law
MS_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Mures)
summary(MS_pw_lm_rob)
MS_pred_pw_lm_rob <- exp(predict(MS_pw_lm_rob, newdata = RO_Census_Mures, 
                                 interval = "prediction", level = 0.95))
MS_RSquared_pw_rob <- 1 - sum((log(RO_Census_Mures$Population) - fitted(MS_pw_lm_rob))^2) / 
  sum((log(RO_Census_Mures$Population) - mean(log(RO_Census_Mures$Population)))^2)

# b) Zipf_Mandelbrot Law
MS_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Mures, "Population", "Rank")
MS_ZM_m_rob <- MS_ZM_prm_rob$m
MS_ZM_alpha_rob <- MS_ZM_prm_rob$alpha_ZM
MS_ZM_cst_rob <- MS_ZM_prm_rob$constant_ZM
MS_ZM_lm_rob <- rlm(log(RO_Census_Mures$Population) ~ log(RO_Census_Mures$Rank + MS_ZM_m_rob))
summary(MS_ZM_lm_rob)
MS_pred_ZM_lm_rob <- exp(predict(MS_ZM_lm_rob, newdata = RO_Census_Mures, 
                                 interval = "prediction", level = 0.95))
MS_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Mures$Population) - fitted(MS_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Mures$Population) - mean(log(RO_Census_Mures$Population)))^2)

# c) Exponential Law
MS_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Mures)
summary(MS_exp_lm_rob)
MS_pred_exp_lm_rob <- exp(predict(MS_exp_lm_rob, newdata = RO_Census_Mures, 
                                  interval = "prediction", level = 0.95))
MS_RSquared_exp_rob <- 1 - sum((log(RO_Census_Mures$Population) - fitted(MS_exp_lm_rob))^2) / 
  sum((log(RO_Census_Mures$Population) - mean(log(RO_Census_Mures$Population)))^2)

# d) Lavalette Function
RO_Census_Mures <- RO_Census_Mures %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Mures) - Rank + 1))
)
MS_lav_lm_rob <- rlm(log(RO_Census_Mures$Population) ~ RO_Census_Mures$Lav_exp)
summary(MS_lav_lm_rob)
MS_lav_kst_rob <- exp(signif(MS_lav_lm_rob$coef[[1]], 4))
MS_lav_chi_rob <- signif(MS_lav_lm_rob$coef[[2]], 4)
MS_pred_lav_lm_rob <- exp(predict(MS_lav_lm_rob, newdata = RO_Census_Mures, 
                                  interval = "prediction", level = 0.95))
MS_RSquared_lav_rob <- 1 - sum((log(RO_Census_Mures$Population) - fitted(MS_lav_lm_rob))^2) / 
  sum((log(RO_Census_Mures$Population) - mean(log(RO_Census_Mures$Population)))^2)

# e) Data Distributions
RO_Census_Mures %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Mures$Rank, 
                              Population = MS_pred_pw_lm_rob[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(MS_pw_lm_rob$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(MS_pw_lm_rob$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(MS_RSquared_pw_rob, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Mures$Rank, 
                              Population = MS_pred_exp_lm_rob[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(MS_exp_lm_rob$coefficients[[1]]), 4), "%.%", 
                           signif(exp(MS_exp_lm_rob$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(MS_RSquared_exp_rob, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Mures$Rank, 
                              Population = MS_pred_ZM_lm_rob[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(MS_ZM_cst_rob, 4), "%.%", "(",
                           signif(MS_ZM_m_rob, 4), "+ x)^", signif(MS_ZM_alpha_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(MS_RSquared_ZM_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Mures$Rank, 
                              Population = MS_pred_lav_lm_rob[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(MS_lav_kst_rob, 4), "%.%", "x^",
                           -signif(MS_lav_chi_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(MS_RSquared_lav_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Mures judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# f) Extract regression metrics
MS_regmet_rob <- as.data.frame(list(Judet_Name = "MURES",
                                    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
                                    R_Squared = c(signif(MS_RSquared_pw_rob, 4), 
