                                    BIC = c(signif(BIC(MS_pw_lm_rob), 4), signif(BIC(MS_exp_lm_rob), 4), 
                                            signif(BIC(MS_ZM_lm_rob), 4), signif(BIC(MS_lav_lm_rob), 4)),
                                    MAE = c(signif(mean(abs((log(RO_Census_Mures$Population) - 
                                                               (predict(MS_pw_lm_rob, newdata = RO_Census_Mures, 
                                                                        interval = "prediction", level = 0.95))))), 4), 
