# XXIX. Neamt

# 1. OLS
RO_Census_Neamt <- RO_Census_rank %>% filter(Judet_Name == "NEAMT")
#View(RO_Census_Neamt)

# a) Power Law
NT_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Neamt)
summary(NT_pw_lm_ols)
NT_pred_pw_lm_ols <- exp(predict(NT_pw_lm_ols, newdata = RO_Census_Neamt, 
                                 interval = "prediction", level = 0.95))
NT_pw_out_ols <- RO_Census_Neamt %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(NT_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Neamt), 
         DFFIT = dffits(NT_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(NT_pw_lm_ols$coefficients) / nrow(RO_Census_Neamt)), 
         Rezid_Std = rstudent(NT_pw_lm_ols), Leverage = hatvalues(NT_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(NT_pw_lm_ols)), 
         DFBETA = dfbetas(NT_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Neamt)))

# b) Zipf_Mandelbrot Law
NT_ZM_prm_ols <- get_ZM_Param("RO_Census_Neamt", "Population", "Rank")
NT_ZM_m_ols <- NT_ZM_prm_ols$m
NT_ZM_alpha_ols <- NT_ZM_prm_ols$alpha_ZM
NT_ZM_cst_ols <- NT_ZM_prm_ols$constant_ZM
NT_ZM_lm_ols <- lm(log(RO_Census_Neamt$Population) ~ log(RO_Census_Neamt$Rank + NT_ZM_m_ols))
summary(NT_ZM_lm_ols)
NT_pred_ZM_lm_ols <- exp(predict(NT_ZM_lm_ols, newdata = RO_Census_Neamt, 
                                 interval = "prediction", level = 0.95))
NT_ZM_out_ols <- RO_Census_Neamt %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(NT_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Neamt), 
         DFFIT = dffits(NT_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(NT_ZM_lm_ols$coefficients) / nrow(RO_Census_Neamt)), 
         Rezid_Std = rstudent(NT_ZM_lm_ols), Leverage = hatvalues(NT_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(NT_ZM_lm_ols)), 
         DFBETA = dfbetas(NT_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Neamt)))

# c) Exponential Law
NT_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Neamt)
summary(NT_exp_lm_ols)
NT_pred_exp_lm_ols <- exp(predict(NT_exp_lm_ols, newdata = RO_Census_Neamt, 
                                  interval = "prediction", level = 0.95))
NT_exp_out_ols <- RO_Census_Neamt %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(NT_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Neamt), 
         DFFIT = dffits(NT_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(NT_exp_lm_ols$coefficients) / nrow(RO_Census_Neamt)), 
         Rezid_Std = rstudent(NT_exp_lm_ols), Leverage = hatvalues(NT_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(NT_exp_lm_ols)), 
         DFBETA = dfbetas(NT_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Neamt)))

# d) Lavalette Function
RO_Census_Neamt <- RO_Census_Neamt %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Neamt) - Rank + 1))
)
NT_lav_lm_ols <- lm(log(RO_Census_Neamt$Population) ~ RO_Census_Neamt$Lav_exp)
summary(NT_lav_lm_ols)
NT_lav_kst_ols <- exp(signif(NT_lav_lm_ols$coef[[1]], 4))
NT_lav_chi_ols <- signif(NT_lav_lm_ols$coef[[2]], 4)
NT_pred_lav_lm_ols <- exp(predict(NT_lav_lm_ols, newdata = RO_Census_Neamt, 
                                  interval = "prediction", level = 0.95))
NT_lav_out_ols <- RO_Census_Neamt %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(NT_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Neamt), 
         DFFIT = dffits(NT_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(NT_lav_lm_ols$coefficients) / nrow(RO_Census_Neamt)), 
         Rezid_Std = rstudent(NT_lav_lm_ols), Leverage = hatvalues(NT_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(NT_lav_lm_ols)), 
         DFBETA = dfbetas(NT_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Neamt)))

# e) Data Distributions
RO_Census_Neamt %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Neamt$Rank, 
