# f) Extract Outliers
Neamt_Outliers <- bind_rows(
  (NT_pw_out_ols %>% mutate(Function_Name = "Power")),
  (NT_ZM_out_ols %>% mutate(Function_Name = "Zipf-Mandelbrot")),
  (NT_exp_out_ols %>% mutate(Function_Name = "Exponential")),
  (NT_lav_out_ols %>% mutate(Function_Name = "Lavalette"))
