# 2. Robust

# a) Power Law
NT_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Neamt)
summary(NT_pw_lm_rob)
NT_pred_pw_lm_rob <- exp(predict(NT_pw_lm_rob, newdata = RO_Census_Neamt, 
                                 interval = "prediction", level = 0.95))
NT_RSquared_pw_rob <- 1 - sum((log(RO_Census_Neamt$Population) - fitted(NT_pw_lm_rob))^2) / 
  sum((log(RO_Census_Neamt$Population) - mean(log(RO_Census_Neamt$Population)))^2)

# b) Zipf_Mandelbrot Law
NT_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Neamt, "Population", "Rank")
NT_ZM_m_rob <- NT_ZM_prm_rob$m
NT_ZM_alpha_rob <- NT_ZM_prm_rob$alpha_ZM
NT_ZM_cst_rob <- NT_ZM_prm_rob$constant_ZM
NT_ZM_lm_rob <- rlm(log(RO_Census_Neamt$Population) ~ log(RO_Census_Neamt$Rank + NT_ZM_m_rob))
summary(NT_ZM_lm_rob)
NT_pred_ZM_lm_rob <- exp(predict(NT_ZM_lm_rob, newdata = RO_Census_Neamt, 
                                 interval = "prediction", level = 0.95))
NT_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Neamt$Population) - fitted(NT_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Neamt$Population) - mean(log(RO_Census_Neamt$Population)))^2)

# c) Exponential Law
NT_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Neamt)
summary(NT_exp_lm_rob)
NT_pred_exp_lm_rob <- exp(predict(NT_exp_lm_rob, newdata = RO_Census_Neamt, 
                                  interval = "prediction", level = 0.95))
NT_RSquared_exp_rob <- 1 - sum((log(RO_Census_Neamt$Population) - fitted(NT_exp_lm_rob))^2) / 
  sum((log(RO_Census_Neamt$Population) - mean(log(RO_Census_Neamt$Population)))^2)

# d) Lavalette Function
RO_Census_Neamt <- RO_Census_Neamt %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Neamt) - Rank + 1))
)
NT_lav_lm_rob <- rlm(log(RO_Census_Neamt$Population) ~ RO_Census_Neamt$Lav_exp)
summary(NT_lav_lm_rob)
NT_lav_kst_rob <- exp(signif(NT_lav_lm_rob$coef[[1]], 4))
NT_lav_chi_rob <- signif(NT_lav_lm_rob$coef[[2]], 4)
NT_pred_lav_lm_rob <- exp(predict(NT_lav_lm_rob, newdata = RO_Census_Neamt, 
                                  interval = "prediction", level = 0.95))
NT_RSquared_lav_rob <- 1 - sum((log(RO_Census_Neamt$Population) - fitted(NT_lav_lm_rob))^2) / 
  sum((log(RO_Census_Neamt$Population) - mean(log(RO_Census_Neamt$Population)))^2)

# e) Data Distributions
RO_Census_Neamt %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Neamt$Rank, 
                              Population = NT_pred_pw_lm_rob[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(NT_pw_lm_rob$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(NT_pw_lm_rob$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(NT_RSquared_pw_rob, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Neamt$Rank, 
                              Population = NT_pred_exp_lm_rob[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(NT_exp_lm_rob$coefficients[[1]]), 4), "%.%", 
                           signif(exp(NT_exp_lm_rob$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(NT_RSquared_exp_rob, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Neamt$Rank, 
                              Population = NT_pred_ZM_lm_rob[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(NT_ZM_cst_rob, 4), "%.%", "(",
                           signif(NT_ZM_m_rob, 4), "+ x)^", signif(NT_ZM_alpha_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(NT_RSquared_ZM_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Neamt$Rank, 
                              Population = NT_pred_lav_lm_rob[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(NT_lav_kst_rob, 4), "%.%", "x^",
                           -signif(NT_lav_chi_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(NT_RSquared_lav_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Neamt judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# f) Extract regression metrics
NT_regmet_rob <- as.data.frame(list(Judet_Name = "NEAMT",
                                    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
                                    R_Squared = c(signif(NT_RSquared_pw_rob, 4), 
                                                  signif(NT_RSquared_exp_rob, 4),
                                                  signif(NT_RSquared_ZM_rob, 4),
                                                  signif(NT_RSquared_lav_rob, 4)),
                                    AIC = c(signif(AIC(NT_pw_lm_rob), 4), signif(AIC(NT_exp_lm_rob), 4), 
                                            signif(AIC(NT_ZM_lm_rob), 4), signif(AIC(NT_lav_lm_rob), 4)),
                                    BIC = c(signif(BIC(NT_pw_lm_rob), 4), signif(BIC(NT_exp_lm_rob), 4), 
                                            signif(BIC(NT_ZM_lm_rob), 4), signif(BIC(NT_lav_lm_rob), 4)),
                                    MAE = c(signif(mean(abs((log(RO_Census_Neamt$Population) - 
                                                               (predict(NT_pw_lm_rob, newdata = RO_Census_Neamt, 
                                                                        interval = "prediction", level = 0.95))))), 4), 
                                            signif(mean(abs((log(RO_Census_Neamt$Population) - 
                                                               (predict(NT_exp_lm_rob, newdata = RO_Census_Neamt, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Neamt$Population) - 
                                                               (predict(NT_ZM_lm_rob, newdata = RO_Census_Neamt, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Neamt$Population) - 
                                                               (predict(NT_lav_lm_rob, newdata = RO_Census_Neamt, 
                                                                        interval = "prediction", level = 0.95))))), 4)),
                                    RMSE = c(signif(sqrt(mean(((log(RO_Census_Neamt$Population)) - 
                                                                 (predict(NT_pw_lm_rob, newdata = RO_Census_Neamt, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Neamt$Population)) - 
                                                                 (predict(NT_exp_lm_rob, newdata = RO_Census_Neamt, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Neamt$Population)) - 
                                                                 (predict(NT_ZM_lm_rob, newdata = RO_Census_Neamt, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
