))

# Extract weight
NT_out_weights <- bind_rows(
  (RO_Census_Neamt %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>% 
     mutate(Robust_Weight = NT_pw_lm_rob$w, Function_Name = "Power")),
  (RO_Census_Neamt %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = NT_ZM_lm_rob$w, Function_Name = "Zipf-Mandelbrot")),
  (RO_Census_Neamt %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = NT_exp_lm_rob$w, Function_Name = "Exponential")),
  (RO_Census_Neamt %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = NT_lav_lm_rob$w, Function_Name = "Lavalette"))) %>% 
  inner_join(NT_out_ols) %>% 
  dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank, Robust_Weight, Function_Name) %>%
  mutate(Judet_Name = "NEAMT")

# g) Extract MAE/RMSE on head, body, tail
RO_Census_Neamt_rob <- RO_Census_Neamt %>% 
  mutate(PW_Y_Pred = (predict(NT_pw_lm_rob, newdata = RO_Census_Neamt, 
                              interval = "prediction", level = 0.95))[,1], 
         ZM_Y_Pred = (predict(NT_ZM_lm_rob, newdata = RO_Census_Neamt, 
                              interval = "prediction", level = 0.95))[,1],
         EXP_Y_Pred = (predict(NT_exp_lm_rob, newdata = RO_Census_Neamt, 
                               interval = "prediction", level = 0.95))[,1], 
         LAV_Y_Pred = (predict(NT_lav_lm_rob, newdata = RO_Census_Neamt, 
                               interval = "prediction", level = 0.95))[,1])

# Head
NT_rob_hd <- RO_Census_Neamt_rob %>% filter(Rank <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(NT_rob_hd$Population) - NT_rob_hd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(NT_rob_hd$Population) - NT_rob_hd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(NT_rob_hd$Population) - NT_rob_hd$ZM_Y_Pred))), 4),
          signif(mean(abs((log(NT_rob_hd$Population) - NT_rob_hd$LAV_Y_Pred))), 4)),
