           signif(sqrt(mean(((log(NT_rob_tl$Population)) - NT_rob_tl$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(NT_rob_tl$Population)) - NT_rob_tl$LAV_Y_Pred) ^ 2)), 4))
))

# Body
NT_rob_bd <- RO_Census_Neamt_rob %>% anti_join(NT_rob_hd) %>% anti_join(NT_rob_tl)

as.data.frame(list(
