# XXX. Olt

# 1. OLS
RO_Census_Olt <- RO_Census_rank %>% filter(Judet_Name == "OLT")
#View(RO_Census_Olt)

# a) Power Law
OT_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Olt)
summary(OT_pw_lm_ols)
OT_pred_pw_lm_ols <- exp(predict(OT_pw_lm_ols, newdata = RO_Census_Olt, 
                                 interval = "prediction", level = 0.95))
OT_pw_out_ols <- RO_Census_Olt %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(OT_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Olt), 
         DFFIT = dffits(OT_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(OT_pw_lm_ols$coefficients) / nrow(RO_Census_Olt)), 
         Rezid_Std = rstudent(OT_pw_lm_ols), Leverage = hatvalues(OT_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(OT_pw_lm_ols)), 
         DFBETA = dfbetas(OT_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Olt)))

# b) Zipf_Mandelbrot Law
OT_ZM_prm_ols <- get_ZM_Param("RO_Census_Olt", "Population", "Rank")
OT_ZM_m_ols <- OT_ZM_prm_ols$m
OT_ZM_alpha_ols <- OT_ZM_prm_ols$alpha_ZM
OT_ZM_cst_ols <- OT_ZM_prm_ols$constant_ZM
OT_ZM_lm_ols <- lm(log(RO_Census_Olt$Population) ~ log(RO_Census_Olt$Rank + OT_ZM_m_ols))
summary(OT_ZM_lm_ols)
OT_pred_ZM_lm_ols <- exp(predict(OT_ZM_lm_ols, newdata = RO_Census_Olt, 
                                 interval = "prediction", level = 0.95))
OT_ZM_out_ols <- RO_Census_Olt %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(OT_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Olt), 
         DFFIT = dffits(OT_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(OT_ZM_lm_ols$coefficients) / nrow(RO_Census_Olt)), 
         Rezid_Std = rstudent(OT_ZM_lm_ols), Leverage = hatvalues(OT_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(OT_ZM_lm_ols)), 
         DFBETA = dfbetas(OT_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Olt)))

# c) Exponential Law
OT_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Olt)
summary(OT_exp_lm_ols)
OT_pred_exp_lm_ols <- exp(predict(OT_exp_lm_ols, newdata = RO_Census_Olt, 
                                  interval = "prediction", level = 0.95))
OT_exp_out_ols <- RO_Census_Olt %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(OT_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Olt), 
         DFFIT = dffits(OT_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(OT_exp_lm_ols$coefficients) / nrow(RO_Census_Olt)), 
         Rezid_Std = rstudent(OT_exp_lm_ols), Leverage = hatvalues(OT_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(OT_exp_lm_ols)), 
         DFBETA = dfbetas(OT_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Olt)))

# d) Lavalette Function
RO_Census_Olt <- RO_Census_Olt %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Olt) - Rank + 1))
)
OT_lav_lm_ols <- lm(log(RO_Census_Olt$Population) ~ RO_Census_Olt$Lav_exp)
summary(OT_lav_lm_ols)
OT_lav_kst_ols <- exp(signif(OT_lav_lm_ols$coef[[1]], 4))
OT_lav_chi_ols <- signif(OT_lav_lm_ols$coef[[2]], 4)
OT_pred_lav_lm_ols <- exp(predict(OT_lav_lm_ols, newdata = RO_Census_Olt, 
                                  interval = "prediction", level = 0.95))
OT_lav_out_ols <- RO_Census_Olt %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(OT_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Olt), 
         DFFIT = dffits(OT_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(OT_lav_lm_ols$coefficients) / nrow(RO_Census_Olt)), 
         Rezid_Std = rstudent(OT_lav_lm_ols), Leverage = hatvalues(OT_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(OT_lav_lm_ols)), 
         DFBETA = dfbetas(OT_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Olt)))

# e) Data Distributions
RO_Census_Olt %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Olt$Rank, 
                              Population = OT_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(OT_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(OT_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(OT_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Olt$Rank, 
                              Population = OT_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(OT_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(OT_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(OT_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Olt$Rank, 
                              Population = OT_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(OT_ZM_cst_ols, 4), "%.%", "(",
                           signif(OT_ZM_m_ols, 4), "+ x)^", signif(OT_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(summary(OT_ZM_lm_ols)$r.squared, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Olt$Rank, 
                              Population = OT_pred_lav_lm_ols[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(OT_lav_kst_ols, 4), "%.%", "x^",
                           -signif(OT_lav_chi_ols, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(summary(OT_lav_lm_ols)$r.squared, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Olt judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# Linear Regressions
