# f) Extract Outliers
Olt_Outliers <- bind_rows(
  (OT_pw_out_ols %>% mutate(Function_Name = "Power")),
  (OT_ZM_out_ols %>% mutate(Function_Name = "Zipf-Mandelbrot")),
  (OT_exp_out_ols %>% mutate(Function_Name = "Exponential")),
  (OT_lav_out_ols %>% mutate(Function_Name = "Lavalette"))
) %>% mutate(DFBETA_intercept = round(DFBETA[,1], 8), 
             DFBETA_var_x = round(DFBETA[,2], 8)) %>% dplyr::select(-DFBETA)

OT_out <- get_outliers(Olt_Outliers, RO_Census_Olt)

OT_out_ols <- RO_Census_Olt %>% inner_join(
  bind_rows(
    (OT_out$PW %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>% 
       dplyr::select(Rank) %>% distinct()),
    (OT_out$ZM %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (OT_out$LAV %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (OT_out$EXP %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct())
  ) %>% count(Rank) %>% arrange(desc(n)) %>% filter(n >= mean(n))) %>% 
  dplyr::select(-n)

