  (RO_Census_Olt %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>% 
     mutate(Robust_Weight = OT_pw_lm_rob$w, Function_Name = "Power")),
  (RO_Census_Olt %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = OT_ZM_lm_rob$w, Function_Name = "Zipf-Mandelbrot")),
  (RO_Census_Olt %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = OT_exp_lm_rob$w, Function_Name = "Exponential")),
  (RO_Census_Olt %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = OT_lav_lm_rob$w, Function_Name = "Lavalette"))) %>% 
  inner_join(OT_out_ols) %>% 
  dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank, Robust_Weight, Function_Name) %>%
  mutate(Judet_Name = "OLT")

# g) Extract MAE/RMSE on head, body, tail
RO_Census_Olt_rob <- RO_Census_Olt %>% 
  mutate(PW_Y_Pred = (predict(OT_pw_lm_rob, newdata = RO_Census_Olt, 
                              interval = "prediction", level = 0.95))[,1], 
         ZM_Y_Pred = (predict(OT_ZM_lm_rob, newdata = RO_Census_Olt, 
                              interval = "prediction", level = 0.95))[,1],
         EXP_Y_Pred = (predict(OT_exp_lm_rob, newdata = RO_Census_Olt, 
                               interval = "prediction", level = 0.95))[,1], 
         LAV_Y_Pred = (predict(OT_lav_lm_rob, newdata = RO_Census_Olt, 
                               interval = "prediction", level = 0.95))[,1])

# Head
OT_rob_hd <- RO_Census_Olt_rob %>% filter(Rank <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(OT_rob_hd$Population) - OT_rob_hd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(OT_rob_hd$Population) - OT_rob_hd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(OT_rob_hd$Population) - OT_rob_hd$ZM_Y_Pred))), 4),
          signif(mean(abs((log(OT_rob_hd$Population) - OT_rob_hd$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(OT_rob_hd$Population)) - OT_rob_hd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(OT_rob_hd$Population)) - OT_rob_hd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(OT_rob_hd$Population)) - OT_rob_hd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(OT_rob_hd$Population)) - OT_rob_hd$LAV_Y_Pred) ^ 2)), 4))
))

# Tail
OT_rob_tl <- RO_Census_Olt_rob %>% arrange(desc(Rank)) %>% 
  filter(row_number() <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(OT_rob_tl$Population) - OT_rob_tl$PW_Y_Pred))), 4), 
          signif(mean(abs((log(OT_rob_tl$Population) - OT_rob_tl$EXP_Y_Pred))), 4),
          signif(mean(abs((log(OT_rob_tl$Population) - OT_rob_tl$ZM_Y_Pred))), 4),
          signif(mean(abs((log(OT_rob_tl$Population) - OT_rob_tl$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(OT_rob_tl$Population)) - OT_rob_tl$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(OT_rob_tl$Population)) - OT_rob_tl$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(OT_rob_tl$Population)) - OT_rob_tl$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(OT_rob_tl$Population)) - OT_rob_tl$LAV_Y_Pred) ^ 2)), 4))
))

# Body
OT_rob_bd <- RO_Census_Olt_rob %>% anti_join(OT_rob_hd) %>% anti_join(OT_rob_tl)

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(OT_rob_bd$Population) - OT_rob_bd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(OT_rob_bd$Population) - OT_rob_bd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(OT_rob_bd$Population) - OT_rob_bd$ZM_Y_Pred))), 4),
          signif(mean(abs((log(OT_rob_bd$Population) - OT_rob_bd$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(OT_rob_bd$Population)) - OT_rob_bd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(OT_rob_bd$Population)) - OT_rob_bd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(OT_rob_bd$Population)) - OT_rob_bd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(OT_rob_bd$Population)) - OT_rob_bd$LAV_Y_Pred) ^ 2)), 4))
))

# Final
OT_res_rob <- as.data.frame(bind_rows(
  as.data.frame(list(
    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
    MAE = c(signif(mean(abs((log(OT_rob_hd$Population) - OT_rob_hd$PW_Y_Pred))), 4), 
            signif(mean(abs((log(OT_rob_hd$Population) - OT_rob_hd$EXP_Y_Pred))), 4),
            signif(mean(abs((log(OT_rob_hd$Population) - OT_rob_hd$ZM_Y_Pred))), 4),
            signif(mean(abs((log(OT_rob_hd$Population) - OT_rob_hd$LAV_Y_Pred))), 4)),
