    MAE = c(signif(mean(abs((log(RO_Census_Olt$Population) - 
                               (predict(OT_pw_lm_rob, newdata = RO_Census_Olt, 
                                        interval = "prediction", level = 0.95))))), 4), 
            signif(mean(abs((log(RO_Census_Olt$Population) - 
                               (predict(OT_exp_lm_rob, newdata = RO_Census_Olt, 
