# XXXI. Prahova

# 1. OLS
RO_Census_Prahova <- RO_Census_rank %>% filter(Judet_Name == "PRAHOVA")
#View(RO_Census_Prahova)

# a) Power Law
PH_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Prahova)
summary(PH_pw_lm_ols)
PH_pred_pw_lm_ols <- exp(predict(PH_pw_lm_ols, newdata = RO_Census_Prahova, 
                                 interval = "prediction", level = 0.95))
PH_pw_out_ols <- RO_Census_Prahova %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(PH_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Prahova), 
         DFFIT = dffits(PH_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(PH_pw_lm_ols$coefficients) / nrow(RO_Census_Prahova)), 
         Rezid_Std = rstudent(PH_pw_lm_ols), Leverage = hatvalues(PH_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(PH_pw_lm_ols)), 
         DFBETA = dfbetas(PH_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Prahova)))

# b) Zipf_Mandelbrot Law
PH_ZM_prm_ols <- get_ZM_Param("RO_Census_Prahova", "Population", "Rank")
PH_ZM_m_ols <- PH_ZM_prm_ols$m
PH_ZM_alpha_ols <- PH_ZM_prm_ols$alpha_ZM
PH_ZM_cst_ols <- PH_ZM_prm_ols$constant_ZM
PH_ZM_lm_ols <- lm(log(RO_Census_Prahova$Population) ~ log(RO_Census_Prahova$Rank + PH_ZM_m_ols))
summary(PH_ZM_lm_ols)
PH_pred_ZM_lm_ols <- exp(predict(PH_ZM_lm_ols, newdata = RO_Census_Prahova, 
                                 interval = "prediction", level = 0.95))
PH_ZM_out_ols <- RO_Census_Prahova %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(PH_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Prahova), 
         DFFIT = dffits(PH_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(PH_ZM_lm_ols$coefficients) / nrow(RO_Census_Prahova)), 
         Rezid_Std = rstudent(PH_ZM_lm_ols), Leverage = hatvalues(PH_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(PH_ZM_lm_ols)), 
         DFBETA = dfbetas(PH_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Prahova)))

# c) Exponential Law
PH_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Prahova)
summary(PH_exp_lm_ols)
PH_pred_exp_lm_ols <- exp(predict(PH_exp_lm_ols, newdata = RO_Census_Prahova, 
                                  interval = "prediction", level = 0.95))
PH_exp_out_ols <- RO_Census_Prahova %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(PH_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Prahova), 
         DFFIT = dffits(PH_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(PH_exp_lm_ols$coefficients) / nrow(RO_Census_Prahova)), 
         Rezid_Std = rstudent(PH_exp_lm_ols), Leverage = hatvalues(PH_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(PH_exp_lm_ols)), 
         DFBETA = dfbetas(PH_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Prahova)))

# d) Lavalette Function
RO_Census_Prahova <- RO_Census_Prahova %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Prahova) - Rank + 1))
)
PH_lav_lm_ols <- lm(log(RO_Census_Prahova$Population) ~ RO_Census_Prahova$Lav_exp)
summary(PH_lav_lm_ols)
PH_lav_kst_ols <- exp(signif(PH_lav_lm_ols$coef[[1]], 4))
PH_lav_chi_ols <- signif(PH_lav_lm_ols$coef[[2]], 4)
PH_pred_lav_lm_ols <- exp(predict(PH_lav_lm_ols, newdata = RO_Census_Prahova, 
                                  interval = "prediction", level = 0.95))
PH_lav_out_ols <- RO_Census_Prahova %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(PH_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Prahova), 
         DFFIT = dffits(PH_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(PH_lav_lm_ols$coefficients) / nrow(RO_Census_Prahova)), 
         Rezid_Std = rstudent(PH_lav_lm_ols), Leverage = hatvalues(PH_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(PH_lav_lm_ols)), 
         DFBETA = dfbetas(PH_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Prahova)))

# e) Data Distributions
RO_Census_Prahova %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Prahova$Rank, 
                              Population = PH_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(PH_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(PH_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(PH_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Prahova$Rank, 
                              Population = PH_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(PH_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(PH_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(PH_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Prahova$Rank, 
                              Population = PH_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(PH_ZM_cst_ols, 4), "%.%", "(",
                           signif(PH_ZM_m_ols, 4), "+ x)^", signif(PH_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(summary(PH_ZM_lm_ols)$r.squared, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Prahova$Rank, 
                              Population = PH_pred_lav_lm_ols[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(PH_lav_kst_ols, 4), "%.%", "x^",
                           -signif(PH_lav_chi_ols, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(summary(PH_lav_lm_ols)$r.squared, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Prahova judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# Linear Regressions
grid.arrange(
  (RO_Census_Prahova %>%
     ggplot(aes(x = log(Rank), y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = "#ED3F39FF") +
     labs(x = "Rank", y = "Population") +
     ggtitle("Power Linear Regression on Prahova judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  (RO_Census_Prahova %>%
     ggplot(aes(x = Rank, y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = "#088BBEFF") +
     labs(x = "Rank", y = "Population") +
     ggtitle("Exponential Linear Regression on Prahova judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  (RO_Census_Prahova %>%
     ggplot(aes(x = log(Rank + PH_ZM_m_ols), y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = '#1B7837FF') +
     labs(x = "Rank", y = "Population") +
     ggtitle("Zipf-Mandelbrot Linear Regression on Prahova judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  (RO_Census_Prahova %>%
     ggplot(aes(x = Lav_exp, y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = '#F8A02EFF') +
