     ggtitle("Lavalette Linear Regression on Prahova judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  ncol = 2, nrow = 2)

# f) Extract Outliers
Prahova_Outliers <- bind_rows(
  (PH_pw_out_ols %>% mutate(Function_Name = "Power")),
  (PH_ZM_out_ols %>% mutate(Function_Name = "Zipf-Mandelbrot")),
  (PH_exp_out_ols %>% mutate(Function_Name = "Exponential")),
  (PH_lav_out_ols %>% mutate(Function_Name = "Lavalette"))
) %>% mutate(DFBETA_intercept = round(DFBETA[,1], 8), 
             DFBETA_var_x = round(DFBETA[,2], 8)) %>% dplyr::select(-DFBETA)

PH_out <- get_outliers(Prahova_Outliers, RO_Census_Prahova)

PH_out_ols <- RO_Census_Prahova %>% inner_join(
  bind_rows(
    (PH_out$PW %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>% 
       dplyr::select(Rank) %>% distinct()),
    (PH_out$ZM %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (PH_out$LAV %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (PH_out$EXP %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct())
  ) %>% count(Rank) %>% arrange(desc(n)) %>% filter(n >= mean(n))) %>% 
  dplyr::select(-n)

# g) Extract regression metrics
PH_regmet_ols <- as.data.frame(list(Judet_Name = "PRAHOVA",
                                    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
                                    R_Squared = c(signif(summary(PH_pw_lm_ols)$r.squared, 4), 
