          signif(mean(abs((log(PH_rob_hd$Population) - PH_rob_hd$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(PH_rob_hd$Population)) - PH_rob_hd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(PH_rob_hd$Population)) - PH_rob_hd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(PH_rob_hd$Population)) - PH_rob_hd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(PH_rob_hd$Population)) - PH_rob_hd$LAV_Y_Pred) ^ 2)), 4))
))

# Tail
PH_rob_tl <- RO_Census_Prahova_rob %>% arrange(desc(Rank)) %>% 
  filter(row_number() <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(PH_rob_tl$Population) - PH_rob_tl$PW_Y_Pred))), 4), 
          signif(mean(abs((log(PH_rob_tl$Population) - PH_rob_tl$EXP_Y_Pred))), 4),
          signif(mean(abs((log(PH_rob_tl$Population) - PH_rob_tl$ZM_Y_Pred))), 4),
          signif(mean(abs((log(PH_rob_tl$Population) - PH_rob_tl$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(PH_rob_tl$Population)) - PH_rob_tl$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(PH_rob_tl$Population)) - PH_rob_tl$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(PH_rob_tl$Population)) - PH_rob_tl$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(PH_rob_tl$Population)) - PH_rob_tl$LAV_Y_Pred) ^ 2)), 4))
))

# Body
PH_rob_bd <- RO_Census_Prahova_rob %>% anti_join(PH_rob_hd) %>% anti_join(PH_rob_tl)

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
