  RMSE = c(signif(sqrt(mean(((log(PH_rob_bd$Population)) - PH_rob_bd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(PH_rob_bd$Population)) - PH_rob_bd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(PH_rob_bd$Population)) - PH_rob_bd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(PH_rob_bd$Population)) - PH_rob_bd$LAV_Y_Pred) ^ 2)), 4))
))

