# XXXII. Satu Mare

# 1. OLS
RO_Census_SatuMare <- RO_Census_rank %>% filter(Judet_Name == "SATU MARE")
#View(RO_Census_SatuMare)

# a) Power Law
SM_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_SatuMare)
summary(SM_pw_lm_ols)
SM_pred_pw_lm_ols <- exp(predict(SM_pw_lm_ols, newdata = RO_Census_SatuMare, 
                                 interval = "prediction", level = 0.95))
SM_pw_out_ols <- RO_Census_SatuMare %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(SM_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_SatuMare), 
         DFFIT = dffits(SM_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(SM_pw_lm_ols$coefficients) / nrow(RO_Census_SatuMare)), 
         Rezid_Std = rstudent(SM_pw_lm_ols), Leverage = hatvalues(SM_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(SM_pw_lm_ols)), 
         DFBETA = dfbetas(SM_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_SatuMare)))

# b) Zipf_Mandelbrot Law
SM_ZM_prm_ols <- get_ZM_Param("RO_Census_SatuMare", "Population", "Rank")
SM_ZM_m_ols <- SM_ZM_prm_ols$m
SM_ZM_alpha_ols <- SM_ZM_prm_ols$alpha_ZM
SM_ZM_cst_ols <- SM_ZM_prm_ols$constant_ZM
SM_ZM_lm_ols <- lm(log(RO_Census_SatuMare$Population) ~ log(RO_Census_SatuMare$Rank + SM_ZM_m_ols))
summary(SM_ZM_lm_ols)
SM_pred_ZM_lm_ols <- exp(predict(SM_ZM_lm_ols, newdata = RO_Census_SatuMare, 
                                 interval = "prediction", level = 0.95))
SM_ZM_out_ols <- RO_Census_SatuMare %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(SM_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_SatuMare), 
         DFFIT = dffits(SM_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(SM_ZM_lm_ols$coefficients) / nrow(RO_Census_SatuMare)), 
         Rezid_Std = rstudent(SM_ZM_lm_ols), Leverage = hatvalues(SM_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(SM_ZM_lm_ols)), 
         DFBETA = dfbetas(SM_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_SatuMare)))

# c) Exponential Law
SM_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_SatuMare)
summary(SM_exp_lm_ols)
SM_pred_exp_lm_ols <- exp(predict(SM_exp_lm_ols, newdata = RO_Census_SatuMare, 
                                  interval = "prediction", level = 0.95))
SM_exp_out_ols <- RO_Census_SatuMare %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(SM_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_SatuMare), 
         DFFIT = dffits(SM_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(SM_exp_lm_ols$coefficients) / nrow(RO_Census_SatuMare)), 
         Rezid_Std = rstudent(SM_exp_lm_ols), Leverage = hatvalues(SM_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(SM_exp_lm_ols)), 
         DFBETA = dfbetas(SM_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_SatuMare)))

# d) Lavalette Function
RO_Census_SatuMare <- RO_Census_SatuMare %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_SatuMare) - Rank + 1))
)
SM_lav_lm_ols <- lm(log(RO_Census_SatuMare$Population) ~ RO_Census_SatuMare$Lav_exp)
summary(SM_lav_lm_ols)
SM_lav_kst_ols <- exp(signif(SM_lav_lm_ols$coef[[1]], 4))
SM_lav_chi_ols <- signif(SM_lav_lm_ols$coef[[2]], 4)
SM_pred_lav_lm_ols <- exp(predict(SM_lav_lm_ols, newdata = RO_Census_SatuMare, 
                                  interval = "prediction", level = 0.95))
SM_lav_out_ols <- RO_Census_SatuMare %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(SM_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_SatuMare), 
         DFFIT = dffits(SM_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(SM_lav_lm_ols$coefficients) / nrow(RO_Census_SatuMare)), 
         Rezid_Std = rstudent(SM_lav_lm_ols), Leverage = hatvalues(SM_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(SM_lav_lm_ols)), 
         DFBETA = dfbetas(SM_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_SatuMare)))

# e) Data Distributions
RO_Census_SatuMare %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_SatuMare$Rank, 
                              Population = SM_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(SM_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(SM_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(SM_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_SatuMare$Rank, 
                              Population = SM_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(SM_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(SM_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(SM_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_SatuMare$Rank, 
                              Population = SM_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(SM_ZM_cst_ols, 4), "%.%", "(",
                           signif(SM_ZM_m_ols, 4), "+ x)^", signif(SM_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(summary(SM_ZM_lm_ols)$r.squared, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_SatuMare$Rank, 
                              Population = SM_pred_lav_lm_ols[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(SM_lav_kst_ols, 4), "%.%", "x^",
                           -signif(SM_lav_chi_ols, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(summary(SM_lav_lm_ols)$r.squared, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on SatuMare judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# Linear Regressions
grid.arrange(
  (RO_Census_SatuMare %>%
     ggplot(aes(x = log(Rank), y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
     geom_smooth(method = "lm", se = FALSE, color = "#ED3F39FF") +
     labs(x = "Rank", y = "Population") +
