     labs(x = "Rank", y = "Population") +
     ggtitle("Lavalette Linear Regression on SatuMare judet") +
     theme(plot.title = element_text(hjust = 0.5))
  ),
  ncol = 2, nrow = 2)

# f) Extract Outliers
SatuMare_Outliers <- bind_rows(
  (SM_pw_out_ols %>% mutate(Function_Name = "Power")),
  (SM_ZM_out_ols %>% mutate(Function_Name = "Zipf-Mandelbrot")),
  (SM_exp_out_ols %>% mutate(Function_Name = "Exponential")),
  (SM_lav_out_ols %>% mutate(Function_Name = "Lavalette"))
) %>% mutate(DFBETA_intercept = round(DFBETA[,1], 8), 
             DFBETA_var_x = round(DFBETA[,2], 8)) %>% dplyr::select(-DFBETA)

SM_out <- get_outliers(SatuMare_Outliers, RO_Census_SatuMare)

SM_out_ols <- RO_Census_SatuMare %>% inner_join(
  bind_rows(
    (SM_out$PW %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>% 
       dplyr::select(Rank) %>% distinct()),
    (SM_out$ZM %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (SM_out$LAV %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (SM_out$EXP %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct())
  ) %>% count(Rank) %>% arrange(desc(n)) %>% filter(n == max(n))) %>% 
  dplyr::select(-n)

# g) Extract regression metrics
SM_regmet_ols <- as.data.frame(list(Judet_Name = "SATU MARE",
                                    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
                                    R_Squared = c(signif(summary(SM_pw_lm_ols)$r.squared, 4), 
                                                  signif(summary(SM_exp_lm_ols)$r.squared, 4),
                                                  signif(summary(SM_ZM_lm_ols)$r.squared, 4),
                                                  signif(summary(SM_lav_lm_ols)$r.squared, 4)),
                                    Adj_R_Squared = c(signif(summary(SM_pw_lm_ols)$adj.r.squared, 4), 
                                                      signif(summary(SM_exp_lm_ols)$adj.r.squared, 4),
                                                      signif(summary(SM_ZM_lm_ols)$adj.r.squared, 4),
                                                      signif(summary(SM_lav_lm_ols)$adj.r.squared, 4)),
                                    AIC = c(signif(AIC(SM_pw_lm_ols), 4), signif(AIC(SM_exp_lm_ols), 4), 
                                            signif(AIC(SM_ZM_lm_ols), 4), signif(AIC(SM_lav_lm_ols), 4)),
                                    BIC = c(signif(BIC(SM_pw_lm_ols), 4), signif(BIC(SM_exp_lm_ols), 4), 
                                            signif(BIC(SM_ZM_lm_ols), 4), signif(BIC(SM_lav_lm_ols), 4)),
                                    MAE = c(signif(mean(abs((log(RO_Census_SatuMare$Population) - 
                                                               (predict(SM_pw_lm_ols, newdata = RO_Census_SatuMare, 
                                                                        interval = "prediction", level = 0.95))))), 4), 
                                            signif(mean(abs((log(RO_Census_SatuMare$Population) - 
                                                               (predict(SM_exp_lm_ols, newdata = RO_Census_SatuMare, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_SatuMare$Population) - 
                                                               (predict(SM_ZM_lm_ols, newdata = RO_Census_SatuMare, 
                                                                        interval = "prediction", level = 0.95))))), 4),
