# XXXIII. Salaj

# 1. OLS
RO_Census_Salaj <- RO_Census_rank %>% filter(Judet_Name == "SALAJ")
#View(RO_Census_Salaj)

# a) Power Law
SJ_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Salaj)
summary(SJ_pw_lm_ols)
SJ_pred_pw_lm_ols <- exp(predict(SJ_pw_lm_ols, newdata = RO_Census_Salaj, 
                                 interval = "prediction", level = 0.95))
SJ_pw_out_ols <- RO_Census_Salaj %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(SJ_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Salaj), 
         DFFIT = dffits(SJ_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(SJ_pw_lm_ols$coefficients) / nrow(RO_Census_Salaj)), 
         Rezid_Std = rstudent(SJ_pw_lm_ols), Leverage = hatvalues(SJ_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(SJ_pw_lm_ols)), 
         DFBETA = dfbetas(SJ_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Salaj)))

# b) Zipf_Mandelbrot Law
SJ_ZM_prm_ols <- get_ZM_Param("RO_Census_Salaj", "Population", "Rank")
SJ_ZM_m_ols <- SJ_ZM_prm_ols$m
SJ_ZM_alpha_ols <- SJ_ZM_prm_ols$alpha_ZM
SJ_ZM_cst_ols <- SJ_ZM_prm_ols$constant_ZM
SJ_ZM_lm_ols <- lm(log(RO_Census_Salaj$Population) ~ log(RO_Census_Salaj$Rank + SJ_ZM_m_ols))
summary(SJ_ZM_lm_ols)
SJ_pred_ZM_lm_ols <- exp(predict(SJ_ZM_lm_ols, newdata = RO_Census_Salaj, 
                                 interval = "prediction", level = 0.95))
SJ_ZM_out_ols <- RO_Census_Salaj %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(SJ_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Salaj), 
         DFFIT = dffits(SJ_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(SJ_ZM_lm_ols$coefficients) / nrow(RO_Census_Salaj)), 
         Rezid_Std = rstudent(SJ_ZM_lm_ols), Leverage = hatvalues(SJ_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(SJ_ZM_lm_ols)), 
         DFBETA = dfbetas(SJ_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Salaj)))

# c) Exponential Law
SJ_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Salaj)
summary(SJ_exp_lm_ols)
SJ_pred_exp_lm_ols <- exp(predict(SJ_exp_lm_ols, newdata = RO_Census_Salaj, 
                                  interval = "prediction", level = 0.95))
SJ_exp_out_ols <- RO_Census_Salaj %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(SJ_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Salaj), 
         DFFIT = dffits(SJ_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(SJ_exp_lm_ols$coefficients) / nrow(RO_Census_Salaj)), 
         Rezid_Std = rstudent(SJ_exp_lm_ols), Leverage = hatvalues(SJ_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(SJ_exp_lm_ols)), 
         DFBETA = dfbetas(SJ_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Salaj)))

# d) Lavalette Function
RO_Census_Salaj <- RO_Census_Salaj %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Salaj) - Rank + 1))
)
SJ_lav_lm_ols <- lm(log(RO_Census_Salaj$Population) ~ RO_Census_Salaj$Lav_exp)
summary(SJ_lav_lm_ols)
SJ_lav_kst_ols <- exp(signif(SJ_lav_lm_ols$coef[[1]], 4))
SJ_lav_chi_ols <- signif(SJ_lav_lm_ols$coef[[2]], 4)
SJ_pred_lav_lm_ols <- exp(predict(SJ_lav_lm_ols, newdata = RO_Census_Salaj, 
                                  interval = "prediction", level = 0.95))
SJ_lav_out_ols <- RO_Census_Salaj %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(SJ_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Salaj), 
         DFFIT = dffits(SJ_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(SJ_lav_lm_ols$coefficients) / nrow(RO_Census_Salaj)), 
         Rezid_Std = rstudent(SJ_lav_lm_ols), Leverage = hatvalues(SJ_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(SJ_lav_lm_ols)), 
         DFBETA = dfbetas(SJ_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Salaj)))

# e) Data Distributions
RO_Census_Salaj %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Salaj$Rank, 
                              Population = SJ_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(SJ_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(SJ_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(SJ_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Salaj$Rank, 
                              Population = SJ_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(SJ_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(SJ_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(SJ_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Salaj$Rank, 
                              Population = SJ_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(SJ_ZM_cst_ols, 4), "%.%", "(",
                           signif(SJ_ZM_m_ols, 4), "+ x)^", signif(SJ_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(summary(SJ_ZM_lm_ols)$r.squared, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Salaj$Rank, 
                              Population = SJ_pred_lav_lm_ols[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(SJ_lav_kst_ols, 4), "%.%", "x^",
                           -signif(SJ_lav_chi_ols, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(summary(SJ_lav_lm_ols)$r.squared, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Salaj judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# Linear Regressions
grid.arrange(
