# f) Extract Outliers
Salaj_Outliers <- bind_rows(
  (SJ_pw_out_ols %>% mutate(Function_Name = "Power")),
  (SJ_ZM_out_ols %>% mutate(Function_Name = "Zipf-Mandelbrot")),
  (SJ_exp_out_ols %>% mutate(Function_Name = "Exponential")),
  (SJ_lav_out_ols %>% mutate(Function_Name = "Lavalette"))
) %>% mutate(DFBETA_intercept = round(DFBETA[,1], 8), 
             DFBETA_var_x = round(DFBETA[,2], 8)) %>% dplyr::select(-DFBETA)

SJ_out <- get_outliers(Salaj_Outliers, RO_Census_Salaj)

