# XXXIV. Sibiu

# 1. OLS
RO_Census_Sibiu <- RO_Census_rank %>% filter(Judet_Name == "SIBIU")
#View(RO_Census_Sibiu)

# a) Power Law
SB_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Sibiu)
summary(SB_pw_lm_ols)
SB_pred_pw_lm_ols <- exp(predict(SB_pw_lm_ols, newdata = RO_Census_Sibiu, 
                                 interval = "prediction", level = 0.95))
SB_pw_out_ols <- RO_Census_Sibiu %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(SB_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Sibiu), 
         DFFIT = dffits(SB_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(SB_pw_lm_ols$coefficients) / nrow(RO_Census_Sibiu)), 
         Rezid_Std = rstudent(SB_pw_lm_ols), Leverage = hatvalues(SB_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(SB_pw_lm_ols)), 
         DFBETA = dfbetas(SB_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Sibiu)))

# b) Zipf_Mandelbrot Law
SB_ZM_prm_ols <- get_ZM_Param("RO_Census_Sibiu", "Population", "Rank")
SB_ZM_m_ols <- SB_ZM_prm_ols$m
SB_ZM_alpha_ols <- SB_ZM_prm_ols$alpha_ZM
SB_ZM_cst_ols <- SB_ZM_prm_ols$constant_ZM
SB_ZM_lm_ols <- lm(log(RO_Census_Sibiu$Population) ~ log(RO_Census_Sibiu$Rank + SB_ZM_m_ols))
summary(SB_ZM_lm_ols)
SB_pred_ZM_lm_ols <- exp(predict(SB_ZM_lm_ols, newdata = RO_Census_Sibiu, 
                                 interval = "prediction", level = 0.95))
SB_ZM_out_ols <- RO_Census_Sibiu %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(SB_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Sibiu), 
         DFFIT = dffits(SB_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(SB_ZM_lm_ols$coefficients) / nrow(RO_Census_Sibiu)), 
         Rezid_Std = rstudent(SB_ZM_lm_ols), Leverage = hatvalues(SB_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(SB_ZM_lm_ols)), 
         DFBETA = dfbetas(SB_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Sibiu)))

# c) Exponential Law
SB_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Sibiu)
summary(SB_exp_lm_ols)
SB_pred_exp_lm_ols <- exp(predict(SB_exp_lm_ols, newdata = RO_Census_Sibiu, 
                                  interval = "prediction", level = 0.95))
SB_exp_out_ols <- RO_Census_Sibiu %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(SB_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Sibiu), 
         DFFIT = dffits(SB_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(SB_exp_lm_ols$coefficients) / nrow(RO_Census_Sibiu)), 
         Rezid_Std = rstudent(SB_exp_lm_ols), Leverage = hatvalues(SB_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(SB_exp_lm_ols)), 
         DFBETA = dfbetas(SB_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Sibiu)))

# d) Lavalette Function
RO_Census_Sibiu <- RO_Census_Sibiu %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Sibiu) - Rank + 1))
)
SB_lav_lm_ols <- lm(log(RO_Census_Sibiu$Population) ~ RO_Census_Sibiu$Lav_exp)
summary(SB_lav_lm_ols)
SB_lav_kst_ols <- exp(signif(SB_lav_lm_ols$coef[[1]], 4))
SB_lav_chi_ols <- signif(SB_lav_lm_ols$coef[[2]], 4)
SB_pred_lav_lm_ols <- exp(predict(SB_lav_lm_ols, newdata = RO_Census_Sibiu, 
                                  interval = "prediction", level = 0.95))
SB_lav_out_ols <- RO_Census_Sibiu %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(SB_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Sibiu), 
         DFFIT = dffits(SB_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(SB_lav_lm_ols$coefficients) / nrow(RO_Census_Sibiu)), 
         Rezid_Std = rstudent(SB_lav_lm_ols), Leverage = hatvalues(SB_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(SB_lav_lm_ols)), 
         DFBETA = dfbetas(SB_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Sibiu)))

# e) Data Distributions
RO_Census_Sibiu %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Sibiu$Rank, 
                              Population = SB_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(SB_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(SB_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(SB_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Sibiu$Rank, 
                              Population = SB_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(SB_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(SB_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(SB_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Sibiu$Rank, 
                              Population = SB_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(SB_ZM_cst_ols, 4), "%.%", "(",
                           signif(SB_ZM_m_ols, 4), "+ x)^", signif(SB_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(summary(SB_ZM_lm_ols)$r.squared, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Sibiu$Rank, 
                              Population = SB_pred_lav_lm_ols[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(SB_lav_kst_ols, 4), "%.%", "x^",
                           -signif(SB_lav_chi_ols, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(summary(SB_lav_lm_ols)$r.squared, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Sibiu judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# Linear Regressions
grid.arrange(
  (RO_Census_Sibiu %>%
     ggplot(aes(x = log(Rank), y = log(Population))) +
