# f) Extract Outliers
Sibiu_Outliers <- bind_rows(
  (SB_pw_out_ols %>% mutate(Function_Name = "Power")),
  (SB_ZM_out_ols %>% mutate(Function_Name = "Zipf-Mandelbrot")),
  (SB_exp_out_ols %>% mutate(Function_Name = "Exponential")),
  (SB_lav_out_ols %>% mutate(Function_Name = "Lavalette"))
) %>% mutate(DFBETA_intercept = round(DFBETA[,1], 8), 
             DFBETA_var_x = round(DFBETA[,2], 8)) %>% dplyr::select(-DFBETA)

SB_out <- get_outliers(Sibiu_Outliers, RO_Census_Sibiu)

SB_out_ols <- RO_Census_Sibiu %>% inner_join(
  bind_rows(
    (SB_out$PW %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>% 
       dplyr::select(Rank) %>% distinct()),
    (SB_out$ZM %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (SB_out$LAV %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (SB_out$EXP %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct())
  ) %>% count(Rank) %>% arrange(desc(n)) %>% filter(n >= mean(n))) %>% 
  dplyr::select(-n)

