# XXXV. Suceava

# 1. OLS
RO_Census_Suceava <- RO_Census_rank %>% filter(Judet_Name == "SUCEAVA")
#View(RO_Census_Suceava)

# a) Power Law
SV_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Suceava)
summary(SV_pw_lm_ols)
SV_pred_pw_lm_ols <- exp(predict(SV_pw_lm_ols, newdata = RO_Census_Suceava, 
                                 interval = "prediction", level = 0.95))
SV_pw_out_ols <- RO_Census_Suceava %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(SV_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Suceava), 
         DFFIT = dffits(SV_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(SV_pw_lm_ols$coefficients) / nrow(RO_Census_Suceava)), 
         Rezid_Std = rstudent(SV_pw_lm_ols), Leverage = hatvalues(SV_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(SV_pw_lm_ols)), 
         DFBETA = dfbetas(SV_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Suceava)))

# b) Zipf_Mandelbrot Law
SV_ZM_prm_ols <- get_ZM_Param("RO_Census_Suceava", "Population", "Rank")
SV_ZM_m_ols <- SV_ZM_prm_ols$m
SV_ZM_alpha_ols <- SV_ZM_prm_ols$alpha_ZM
SV_ZM_cst_ols <- SV_ZM_prm_ols$constant_ZM
SV_ZM_lm_ols <- lm(log(RO_Census_Suceava$Population) ~ log(RO_Census_Suceava$Rank + SV_ZM_m_ols))
summary(SV_ZM_lm_ols)
SV_pred_ZM_lm_ols <- exp(predict(SV_ZM_lm_ols, newdata = RO_Census_Suceava, 
                                 interval = "prediction", level = 0.95))
SV_ZM_out_ols <- RO_Census_Suceava %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(SV_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Suceava), 
         DFFIT = dffits(SV_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(SV_ZM_lm_ols$coefficients) / nrow(RO_Census_Suceava)), 
         Rezid_Std = rstudent(SV_ZM_lm_ols), Leverage = hatvalues(SV_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(SV_ZM_lm_ols)), 
         DFBETA = dfbetas(SV_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Suceava)))

# c) Exponential Law
SV_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Suceava)
summary(SV_exp_lm_ols)
SV_pred_exp_lm_ols <- exp(predict(SV_exp_lm_ols, newdata = RO_Census_Suceava, 
                                  interval = "prediction", level = 0.95))
SV_exp_out_ols <- RO_Census_Suceava %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(SV_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Suceava), 
         DFFIT = dffits(SV_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(SV_exp_lm_ols$coefficients) / nrow(RO_Census_Suceava)), 
         Rezid_Std = rstudent(SV_exp_lm_ols), Leverage = hatvalues(SV_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(SV_exp_lm_ols)), 
         DFBETA = dfbetas(SV_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Suceava)))

# d) Lavalette Function
RO_Census_Suceava <- RO_Census_Suceava %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Suceava) - Rank + 1))
)
SV_lav_lm_ols <- lm(log(RO_Census_Suceava$Population) ~ RO_Census_Suceava$Lav_exp)
summary(SV_lav_lm_ols)
SV_lav_kst_ols <- exp(signif(SV_lav_lm_ols$coef[[1]], 4))
SV_lav_chi_ols <- signif(SV_lav_lm_ols$coef[[2]], 4)
SV_pred_lav_lm_ols <- exp(predict(SV_lav_lm_ols, newdata = RO_Census_Suceava, 
                                  interval = "prediction", level = 0.95))
SV_lav_out_ols <- RO_Census_Suceava %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(SV_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Suceava), 
         DFFIT = dffits(SV_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(SV_lav_lm_ols$coefficients) / nrow(RO_Census_Suceava)), 
         Rezid_Std = rstudent(SV_lav_lm_ols), Leverage = hatvalues(SV_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(SV_lav_lm_ols)), 
         DFBETA = dfbetas(SV_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Suceava)))

# e) Data Distributions
RO_Census_Suceava %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Suceava$Rank, 
                              Population = SV_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(SV_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(SV_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(SV_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Suceava$Rank, 
                              Population = SV_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(SV_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(SV_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(SV_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Suceava$Rank, 
                              Population = SV_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(SV_ZM_cst_ols, 4), "%.%", "(",
                           signif(SV_ZM_m_ols, 4), "+ x)^", signif(SV_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(summary(SV_ZM_lm_ols)$r.squared, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Suceava$Rank, 
                              Population = SV_pred_lav_lm_ols[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(SV_lav_kst_ols, 4), "%.%", "x^",
                           -signif(SV_lav_chi_ols, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(summary(SV_lav_lm_ols)$r.squared, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Suceava judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# Linear Regressions
grid.arrange(
  (RO_Census_Suceava %>%
     ggplot(aes(x = log(Rank), y = log(Population))) +
