  ncol = 2, nrow = 2)

# f) Extract Outliers
Suceava_Outliers <- bind_rows(
  (SV_pw_out_ols %>% mutate(Function_Name = "Power")),
  (SV_ZM_out_ols %>% mutate(Function_Name = "Zipf-Mandelbrot")),
  (SV_exp_out_ols %>% mutate(Function_Name = "Exponential")),
  (SV_lav_out_ols %>% mutate(Function_Name = "Lavalette"))
) %>% mutate(DFBETA_intercept = round(DFBETA[,1], 8), 
             DFBETA_var_x = round(DFBETA[,2], 8)) %>% dplyr::select(-DFBETA)

SV_out <- get_outliers(Suceava_Outliers, RO_Census_Suceava)

SV_out_ols <- RO_Census_Suceava %>% inner_join(
  bind_rows(
    (SV_out$PW %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>% 
       dplyr::select(Rank) %>% distinct()),
    (SV_out$ZM %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (SV_out$LAV %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (SV_out$EXP %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct())
  ) %>% count(Rank) %>% arrange(desc(n)) %>% filter(n >= mean(n))) %>% 
  dplyr::select(-n)

# g) Extract regression metrics
