                                            signif(BIC(SV_ZM_lm_ols), 4), signif(BIC(SV_lav_lm_ols), 4)),
                                    MAE = c(signif(mean(abs((log(RO_Census_Suceava$Population) - 
                                                               (predict(SV_pw_lm_ols, newdata = RO_Census_Suceava, 
                                                                        interval = "prediction", level = 0.95))))), 4), 
