# h) Extract MAE/RMSE on head, body, tail
RO_Census_Suceava_ols <- RO_Census_Suceava %>% 
  mutate(PW_Y_Pred = (predict(SV_pw_lm_ols, newdata = RO_Census_Suceava, 
                              interval = "prediction", level = 0.95))[,1], 
         ZM_Y_Pred = (predict(SV_ZM_lm_ols, newdata = RO_Census_Suceava, 
                              interval = "prediction", level = 0.95))[,1],
         EXP_Y_Pred = (predict(SV_exp_lm_ols, newdata = RO_Census_Suceava, 
                               interval = "prediction", level = 0.95))[,1], 
         LAV_Y_Pred = (predict(SV_lav_lm_ols, newdata = RO_Census_Suceava, 
                               interval = "prediction", level = 0.95))[,1])

# Head
SV_ols_hd <- RO_Census_Suceava_ols %>% filter(Rank <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(SV_ols_hd$Population) - SV_ols_hd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(SV_ols_hd$Population) - SV_ols_hd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(SV_ols_hd$Population) - SV_ols_hd$ZM_Y_Pred))), 4),
          signif(mean(abs((log(SV_ols_hd$Population) - SV_ols_hd$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(SV_ols_hd$Population)) - SV_ols_hd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(SV_ols_hd$Population)) - SV_ols_hd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(SV_ols_hd$Population)) - SV_ols_hd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(SV_ols_hd$Population)) - SV_ols_hd$LAV_Y_Pred) ^ 2)), 4))
))

# Tail
SV_ols_tl <- RO_Census_Suceava_ols %>% arrange(desc(Rank)) %>% 
  filter(row_number() <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(SV_ols_tl$Population) - SV_ols_tl$PW_Y_Pred))), 4), 
          signif(mean(abs((log(SV_ols_tl$Population) - SV_ols_tl$EXP_Y_Pred))), 4),
