  RMSE = c(signif(sqrt(mean(((log(SV_ols_tl$Population)) - SV_ols_tl$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(SV_ols_tl$Population)) - SV_ols_tl$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(SV_ols_tl$Population)) - SV_ols_tl$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(SV_ols_tl$Population)) - SV_ols_tl$LAV_Y_Pred) ^ 2)), 4))
))

# Body
SV_ols_bd <- RO_Census_Suceava_ols %>% anti_join(SV_ols_hd) %>% anti_join(SV_ols_tl)

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(SV_ols_bd$Population) - SV_ols_bd$PW_Y_Pred))), 4), 
