# 2. Robust

# a) Power Law
SV_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Suceava)
summary(SV_pw_lm_rob)
SV_pred_pw_lm_rob <- exp(predict(SV_pw_lm_rob, newdata = RO_Census_Suceava, 
                                 interval = "prediction", level = 0.95))
SV_RSquared_pw_rob <- 1 - sum((log(RO_Census_Suceava$Population) - fitted(SV_pw_lm_rob))^2) / 
  sum((log(RO_Census_Suceava$Population) - mean(log(RO_Census_Suceava$Population)))^2)

# b) Zipf_Mandelbrot Law
SV_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Suceava, "Population", "Rank")
SV_ZM_m_rob <- SV_ZM_prm_rob$m
SV_ZM_alpha_rob <- SV_ZM_prm_rob$alpha_ZM
SV_ZM_cst_rob <- SV_ZM_prm_rob$constant_ZM
SV_ZM_lm_rob <- rlm(log(RO_Census_Suceava$Population) ~ log(RO_Census_Suceava$Rank + SV_ZM_m_rob))
summary(SV_ZM_lm_rob)
SV_pred_ZM_lm_rob <- exp(predict(SV_ZM_lm_rob, newdata = RO_Census_Suceava, 
                                 interval = "prediction", level = 0.95))
SV_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Suceava$Population) - fitted(SV_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Suceava$Population) - mean(log(RO_Census_Suceava$Population)))^2)

# c) Exponential Law
SV_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Suceava)
summary(SV_exp_lm_rob)
SV_pred_exp_lm_rob <- exp(predict(SV_exp_lm_rob, newdata = RO_Census_Suceava, 
                                  interval = "prediction", level = 0.95))
SV_RSquared_exp_rob <- 1 - sum((log(RO_Census_Suceava$Population) - fitted(SV_exp_lm_rob))^2) / 
  sum((log(RO_Census_Suceava$Population) - mean(log(RO_Census_Suceava$Population)))^2)

# d) Lavalette Function
RO_Census_Suceava <- RO_Census_Suceava %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Suceava) - Rank + 1))
)
SV_lav_lm_rob <- rlm(log(RO_Census_Suceava$Population) ~ RO_Census_Suceava$Lav_exp)
summary(SV_lav_lm_rob)
SV_lav_kst_rob <- exp(signif(SV_lav_lm_rob$coef[[1]], 4))
SV_lav_chi_rob <- signif(SV_lav_lm_rob$coef[[2]], 4)
SV_pred_lav_lm_rob <- exp(predict(SV_lav_lm_rob, newdata = RO_Census_Suceava, 
                                  interval = "prediction", level = 0.95))
SV_RSquared_lav_rob <- 1 - sum((log(RO_Census_Suceava$Population) - fitted(SV_lav_lm_rob))^2) / 
  sum((log(RO_Census_Suceava$Population) - mean(log(RO_Census_Suceava$Population)))^2)

# e) Data Distributions
RO_Census_Suceava %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Suceava$Rank, 
                              Population = SV_pred_pw_lm_rob[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 45, y = 70000,
            label = paste0("y", "==", signif(exp(SV_pw_lm_rob$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(SV_pw_lm_rob$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 75, y = 70000,
            label = paste0("R^2 ==", signif(SV_RSquared_pw_rob, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Suceava$Rank, 
                              Population = SV_pred_exp_lm_rob[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 45, y = 60000,
            label = paste0("y", "==", signif(exp(SV_exp_lm_rob$coefficients[[1]]), 4), "%.%", 
                           signif(exp(SV_exp_lm_rob$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 75, y = 60000,
            label = paste0("R^2 ==", signif(SV_RSquared_exp_rob, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Suceava$Rank, 
                              Population = SV_pred_ZM_lm_rob[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 45, y = 50000,
            label = paste0("y", "==", signif(SV_ZM_cst_rob, 4), "%.%", "(",
                           signif(SV_ZM_m_rob, 4), "+ x)^", signif(SV_ZM_alpha_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 75, y = 50000,
            label = paste0("R^2 ==", signif(SV_RSquared_ZM_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Suceava$Rank, 
                              Population = SV_pred_lav_lm_rob[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 45, y = 40000,
            label = paste0("y", "==", signif(SV_lav_kst_rob, 4), "%.%", "x^",
                           -signif(SV_lav_chi_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 75, y = 40000,
            label = paste0("R^2 ==", signif(SV_RSquared_lav_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_y_continuous(labels = scales::label_number(
    big.mark = ",", decimal.mark = ".")) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Suceava judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# f) Extract regression metrics
SV_regmet_rob <- as.data.frame(list(Judet_Name = "SUCEAVA",
