    MAE = c(signif(mean(abs((log(RO_Census_Suceava$Population) - 
                               (predict(SV_pw_lm_rob, newdata = RO_Census_Suceava, 
                                        interval = "prediction", level = 0.95))))), 4), 
            signif(mean(abs((log(RO_Census_Suceava$Population) - 
                               (predict(SV_exp_lm_rob, newdata = RO_Census_Suceava, 
                                        interval = "prediction", level = 0.95))))), 4),
            signif(mean(abs((log(RO_Census_Suceava$Population) - 
                               (predict(SV_ZM_lm_rob, newdata = RO_Census_Suceava, 
                                        interval = "prediction", level = 0.95))))), 4),
            signif(mean(abs((log(RO_Census_Suceava$Population) - 
                               (predict(SV_lav_lm_rob, newdata = RO_Census_Suceava, 
                                        interval = "prediction", level = 0.95))))), 4)),
    RMSE = c(signif(sqrt(mean(((log(RO_Census_Suceava$Population)) - 
                                 (predict(SV_pw_lm_rob, newdata = RO_Census_Suceava, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Suceava$Population)) - 
                                 (predict(SV_exp_lm_rob, newdata = RO_Census_Suceava, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Suceava$Population)) - 
                                 (predict(SV_ZM_lm_rob, newdata = RO_Census_Suceava, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Suceava$Population)) - 
                                 (predict(SV_lav_lm_rob, newdata = RO_Census_Suceava, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4)),
    Data_Part = "Full"
  ))
)) %>% mutate(Regression_Type = "Robust", Judet_Name = "SUCEAVA")

