# XXXVI. Teleorman

# 1. OLS
RO_Census_Teleorman <- RO_Census_rank %>% filter(Judet_Name == "TELEORMAN")
#View(RO_Census_Teleorman)

# a) Power Law
TR_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Teleorman)
summary(TR_pw_lm_ols)
TR_pred_pw_lm_ols <- exp(predict(TR_pw_lm_ols, newdata = RO_Census_Teleorman, 
                                 interval = "prediction", level = 0.95))
TR_pw_out_ols <- RO_Census_Teleorman %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(TR_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Teleorman), 
         DFFIT = dffits(TR_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(TR_pw_lm_ols$coefficients) / nrow(RO_Census_Teleorman)), 
         Rezid_Std = rstudent(TR_pw_lm_ols), Leverage = hatvalues(TR_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(TR_pw_lm_ols)), 
         DFBETA = dfbetas(TR_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Teleorman)))

# b) Zipf_Mandelbrot Law
TR_ZM_prm_ols <- get_ZM_Param("RO_Census_Teleorman", "Population", "Rank")
TR_ZM_m_ols <- TR_ZM_prm_ols$m
TR_ZM_alpha_ols <- TR_ZM_prm_ols$alpha_ZM
TR_ZM_cst_ols <- TR_ZM_prm_ols$constant_ZM
TR_ZM_lm_ols <- lm(log(RO_Census_Teleorman$Population) ~ log(RO_Census_Teleorman$Rank + TR_ZM_m_ols))
summary(TR_ZM_lm_ols)
TR_pred_ZM_lm_ols <- exp(predict(TR_ZM_lm_ols, newdata = RO_Census_Teleorman, 
                                 interval = "prediction", level = 0.95))
TR_ZM_out_ols <- RO_Census_Teleorman %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(TR_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Teleorman), 
         DFFIT = dffits(TR_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(TR_ZM_lm_ols$coefficients) / nrow(RO_Census_Teleorman)), 
         Rezid_Std = rstudent(TR_ZM_lm_ols), Leverage = hatvalues(TR_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(TR_ZM_lm_ols)), 
         DFBETA = dfbetas(TR_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Teleorman)))

# c) Exponential Law
TR_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Teleorman)
summary(TR_exp_lm_ols)
TR_pred_exp_lm_ols <- exp(predict(TR_exp_lm_ols, newdata = RO_Census_Teleorman, 
                                  interval = "prediction", level = 0.95))
TR_exp_out_ols <- RO_Census_Teleorman %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(TR_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Teleorman), 
         DFFIT = dffits(TR_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(TR_exp_lm_ols$coefficients) / nrow(RO_Census_Teleorman)), 
         Rezid_Std = rstudent(TR_exp_lm_ols), Leverage = hatvalues(TR_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(TR_exp_lm_ols)), 
         DFBETA = dfbetas(TR_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Teleorman)))

# d) Lavalette Function
RO_Census_Teleorman <- RO_Census_Teleorman %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Teleorman) - Rank + 1))
)
TR_lav_lm_ols <- lm(log(RO_Census_Teleorman$Population) ~ RO_Census_Teleorman$Lav_exp)
summary(TR_lav_lm_ols)
TR_lav_kst_ols <- exp(signif(TR_lav_lm_ols$coef[[1]], 4))
TR_lav_chi_ols <- signif(TR_lav_lm_ols$coef[[2]], 4)
TR_pred_lav_lm_ols <- exp(predict(TR_lav_lm_ols, newdata = RO_Census_Teleorman, 
                                  interval = "prediction", level = 0.95))
TR_lav_out_ols <- RO_Census_Teleorman %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(TR_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Teleorman), 
         DFFIT = dffits(TR_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(TR_lav_lm_ols$coefficients) / nrow(RO_Census_Teleorman)), 
         Rezid_Std = rstudent(TR_lav_lm_ols), Leverage = hatvalues(TR_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(TR_lav_lm_ols)), 
         DFBETA = dfbetas(TR_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Teleorman)))

# e) Data Distributions
RO_Census_Teleorman %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Teleorman$Rank, 
                              Population = TR_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(TR_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(TR_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(TR_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Teleorman$Rank, 
                              Population = TR_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(TR_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(TR_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(TR_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Teleorman$Rank, 
                              Population = TR_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(TR_ZM_cst_ols, 4), "%.%", "(",
                           signif(TR_ZM_m_ols, 4), "+ x)^", signif(TR_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(summary(TR_ZM_lm_ols)$r.squared, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Teleorman$Rank, 
                              Population = TR_pred_lav_lm_ols[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(TR_lav_kst_ols, 4), "%.%", "x^",
                           -signif(TR_lav_chi_ols, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(summary(TR_lav_lm_ols)$r.squared, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Teleorman judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# Linear Regressions
grid.arrange(
