# h) Extract MAE/RMSE on head, body, tail
RO_Census_Teleorman_ols <- RO_Census_Teleorman %>% 
  mutate(PW_Y_Pred = (predict(TR_pw_lm_ols, newdata = RO_Census_Teleorman, 
