    MAE = c(signif(mean(abs((log(TR_ols_bd$Population) - TR_ols_bd$PW_Y_Pred))), 4), 
            signif(mean(abs((log(TR_ols_bd$Population) - TR_ols_bd$EXP_Y_Pred))), 4),
            signif(mean(abs((log(TR_ols_bd$Population) - TR_ols_bd$ZM_Y_Pred))), 4),
