# 2. Robust

# a) Power Law
TR_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Teleorman)
summary(TR_pw_lm_rob)
TR_pred_pw_lm_rob <- exp(predict(TR_pw_lm_rob, newdata = RO_Census_Teleorman, 
                                 interval = "prediction", level = 0.95))
TR_RSquared_pw_rob <- 1 - sum((log(RO_Census_Teleorman$Population) - fitted(TR_pw_lm_rob))^2) / 
  sum((log(RO_Census_Teleorman$Population) - mean(log(RO_Census_Teleorman$Population)))^2)

# b) Zipf_Mandelbrot Law
TR_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Teleorman, "Population", "Rank")
TR_ZM_m_rob <- TR_ZM_prm_rob$m
TR_ZM_alpha_rob <- TR_ZM_prm_rob$alpha_ZM
TR_ZM_cst_rob <- TR_ZM_prm_rob$constant_ZM
TR_ZM_lm_rob <- rlm(log(RO_Census_Teleorman$Population) ~ log(RO_Census_Teleorman$Rank + TR_ZM_m_rob))
summary(TR_ZM_lm_rob)
TR_pred_ZM_lm_rob <- exp(predict(TR_ZM_lm_rob, newdata = RO_Census_Teleorman, 
                                 interval = "prediction", level = 0.95))
TR_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Teleorman$Population) - fitted(TR_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Teleorman$Population) - mean(log(RO_Census_Teleorman$Population)))^2)

# c) Exponential Law
TR_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Teleorman)
summary(TR_exp_lm_rob)
TR_pred_exp_lm_rob <- exp(predict(TR_exp_lm_rob, newdata = RO_Census_Teleorman, 
                                  interval = "prediction", level = 0.95))
TR_RSquared_exp_rob <- 1 - sum((log(RO_Census_Teleorman$Population) - fitted(TR_exp_lm_rob))^2) / 
  sum((log(RO_Census_Teleorman$Population) - mean(log(RO_Census_Teleorman$Population)))^2)

# d) Lavalette Function
RO_Census_Teleorman <- RO_Census_Teleorman %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Teleorman) - Rank + 1))
)
TR_lav_lm_rob <- rlm(log(RO_Census_Teleorman$Population) ~ RO_Census_Teleorman$Lav_exp)
summary(TR_lav_lm_rob)
TR_lav_kst_rob <- exp(signif(TR_lav_lm_rob$coef[[1]], 4))
TR_lav_chi_rob <- signif(TR_lav_lm_rob$coef[[2]], 4)
TR_pred_lav_lm_rob <- exp(predict(TR_lav_lm_rob, newdata = RO_Census_Teleorman, 
                                  interval = "prediction", level = 0.95))
TR_RSquared_lav_rob <- 1 - sum((log(RO_Census_Teleorman$Population) - fitted(TR_lav_lm_rob))^2) / 
  sum((log(RO_Census_Teleorman$Population) - mean(log(RO_Census_Teleorman$Population)))^2)

# e) Data Distributions
RO_Census_Teleorman %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Teleorman$Rank, 
                              Population = TR_pred_pw_lm_rob[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(TR_pw_lm_rob$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(TR_pw_lm_rob$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(TR_RSquared_pw_rob, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Teleorman$Rank, 
                              Population = TR_pred_exp_lm_rob[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(TR_exp_lm_rob$coefficients[[1]]), 4), "%.%", 
                           signif(exp(TR_exp_lm_rob$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(TR_RSquared_exp_rob, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Teleorman$Rank, 
                              Population = TR_pred_ZM_lm_rob[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(TR_ZM_cst_rob, 4), "%.%", "(",
                           signif(TR_ZM_m_rob, 4), "+ x)^", signif(TR_ZM_alpha_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(TR_RSquared_ZM_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Teleorman$Rank, 
                              Population = TR_pred_lav_lm_rob[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(TR_lav_kst_rob, 4), "%.%", "x^",
                           -signif(TR_lav_chi_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(TR_RSquared_lav_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Teleorman judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# f) Extract regression metrics
TR_regmet_rob <- as.data.frame(list(Judet_Name = "TELEORMAN",
                                    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
                                    R_Squared = c(signif(TR_RSquared_pw_rob, 4), 
