                                    BIC = c(signif(BIC(TR_pw_lm_rob), 4), signif(BIC(TR_exp_lm_rob), 4), 
                                            signif(BIC(TR_ZM_lm_rob), 4), signif(BIC(TR_lav_lm_rob), 4)),
                                    MAE = c(signif(mean(abs((log(RO_Census_Teleorman$Population) - 
                                                               (predict(TR_pw_lm_rob, newdata = RO_Census_Teleorman, 
                                                                        interval = "prediction", level = 0.95))))), 4), 
                                            signif(mean(abs((log(RO_Census_Teleorman$Population) - 
                                                               (predict(TR_exp_lm_rob, newdata = RO_Census_Teleorman, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Teleorman$Population) - 
                                                               (predict(TR_ZM_lm_rob, newdata = RO_Census_Teleorman, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Teleorman$Population) - 
                                                               (predict(TR_lav_lm_rob, newdata = RO_Census_Teleorman, 
                                                                        interval = "prediction", level = 0.95))))), 4)),
                                    RMSE = c(signif(sqrt(mean(((log(RO_Census_Teleorman$Population)) - 
                                                                 (predict(TR_pw_lm_rob, newdata = RO_Census_Teleorman, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Teleorman$Population)) - 
                                                                 (predict(TR_exp_lm_rob, newdata = RO_Census_Teleorman, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Teleorman$Population)) - 
