))

# Extract weight
TR_out_weights <- bind_rows(
  (RO_Census_Teleorman %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>% 
     mutate(Robust_Weight = TR_pw_lm_rob$w, Function_Name = "Power")),
  (RO_Census_Teleorman %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = TR_ZM_lm_rob$w, Function_Name = "Zipf-Mandelbrot")),
  (RO_Census_Teleorman %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = TR_exp_lm_rob$w, Function_Name = "Exponential")),
