  mutate(Judet_Name = "TELEORMAN")

# g) Extract MAE/RMSE on head, body, tail
RO_Census_Teleorman_rob <- RO_Census_Teleorman %>% 
  mutate(PW_Y_Pred = (predict(TR_pw_lm_rob, newdata = RO_Census_Teleorman, 
                              interval = "prediction", level = 0.95))[,1], 
