           signif(sqrt(mean(((log(TR_rob_hd$Population)) - TR_rob_hd$LAV_Y_Pred) ^ 2)), 4))
))

# Tail
TR_rob_tl <- RO_Census_Teleorman_rob %>% arrange(desc(Rank)) %>% 
  filter(row_number() <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(TR_rob_tl$Population) - TR_rob_tl$PW_Y_Pred))), 4), 
          signif(mean(abs((log(TR_rob_tl$Population) - TR_rob_tl$EXP_Y_Pred))), 4),
