  theme(plot.title = element_text(hjust = 0.5))

# MAE
TR_regg_res %>% ggplot(aes(Data_Part, MAE, color = Function_Name, 
                           group = Function_Name)) +
  geom_line(linewidth = 1) + geom_point(size = 3) + 
  facet_wrap(~ Regression_Type) + scale_y_log10() +
  scale_color_manual(
    values = c("Power" = "#ED3F39FF", "Exponential" = "#088BBEFF", 
               "Zipf-Mandelbrot" = "#1B7837FF", "Lavalette" = "#F8A02EFF")) +
  labs(x = "Data Region", y = "MAE (log scale)") +
  theme(plot.title = element_text(hjust = 0.5))

# XXXVII. Timis

# 1. OLS
RO_Census_Timis <- RO_Census_rank %>% filter(Judet_Name == "TIMIS")
#View(RO_Census_Timis)

# a) Power Law
TM_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Timis)
summary(TM_pw_lm_ols)
TM_pred_pw_lm_ols <- exp(predict(TM_pw_lm_ols, newdata = RO_Census_Timis, 
                                 interval = "prediction", level = 0.95))
TM_pw_out_ols <- RO_Census_Timis %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(TM_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Timis), 
         DFFIT = dffits(TM_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(TM_pw_lm_ols$coefficients) / nrow(RO_Census_Timis)), 
         Rezid_Std = rstudent(TM_pw_lm_ols), Leverage = hatvalues(TM_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(TM_pw_lm_ols)), 
         DFBETA = dfbetas(TM_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Timis)))

# b) Zipf_Mandelbrot Law
TM_ZM_prm_ols <- get_ZM_Param("RO_Census_Timis", "Population", "Rank")
TM_ZM_m_ols <- TM_ZM_prm_ols$m
TM_ZM_alpha_ols <- TM_ZM_prm_ols$alpha_ZM
TM_ZM_cst_ols <- TM_ZM_prm_ols$constant_ZM
TM_ZM_lm_ols <- lm(log(RO_Census_Timis$Population) ~ log(RO_Census_Timis$Rank + TM_ZM_m_ols))
summary(TM_ZM_lm_ols)
TM_pred_ZM_lm_ols <- exp(predict(TM_ZM_lm_ols, newdata = RO_Census_Timis, 
                                 interval = "prediction", level = 0.95))
TM_ZM_out_ols <- RO_Census_Timis %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(TM_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Timis), 
         DFFIT = dffits(TM_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(TM_ZM_lm_ols$coefficients) / nrow(RO_Census_Timis)), 
         Rezid_Std = rstudent(TM_ZM_lm_ols), Leverage = hatvalues(TM_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(TM_ZM_lm_ols)), 
         DFBETA = dfbetas(TM_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Timis)))

# c) Exponential Law
TM_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Timis)
summary(TM_exp_lm_ols)
TM_pred_exp_lm_ols <- exp(predict(TM_exp_lm_ols, newdata = RO_Census_Timis, 
                                  interval = "prediction", level = 0.95))
TM_exp_out_ols <- RO_Census_Timis %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(TM_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Timis), 
         DFFIT = dffits(TM_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(TM_exp_lm_ols$coefficients) / nrow(RO_Census_Timis)), 
         Rezid_Std = rstudent(TM_exp_lm_ols), Leverage = hatvalues(TM_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(TM_exp_lm_ols)), 
         DFBETA = dfbetas(TM_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Timis)))

# d) Lavalette Function
RO_Census_Timis <- RO_Census_Timis %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Timis) - Rank + 1))
)
TM_lav_lm_ols <- lm(log(RO_Census_Timis$Population) ~ RO_Census_Timis$Lav_exp)
summary(TM_lav_lm_ols)
TM_lav_kst_ols <- exp(signif(TM_lav_lm_ols$coef[[1]], 4))
TM_lav_chi_ols <- signif(TM_lav_lm_ols$coef[[2]], 4)
TM_pred_lav_lm_ols <- exp(predict(TM_lav_lm_ols, newdata = RO_Census_Timis, 
                                  interval = "prediction", level = 0.95))
TM_lav_out_ols <- RO_Census_Timis %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(TM_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Timis), 
         DFFIT = dffits(TM_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(TM_lav_lm_ols$coefficients) / nrow(RO_Census_Timis)), 
         Rezid_Std = rstudent(TM_lav_lm_ols), Leverage = hatvalues(TM_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(TM_lav_lm_ols)), 
         DFBETA = dfbetas(TM_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Timis)))

# e) Data Distributions
RO_Census_Timis %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Timis$Rank, 
                              Population = TM_pred_pw_lm_ols[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(TM_pw_lm_ols$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(TM_pw_lm_ols$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(summary(TM_pw_lm_ols)$r.squared, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Timis$Rank, 
                              Population = TM_pred_exp_lm_ols[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(TM_exp_lm_ols$coefficients[[1]]), 4), "%.%", 
                           signif(exp(TM_exp_lm_ols$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(summary(TM_exp_lm_ols)$r.squared, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Timis$Rank, 
                              Population = TM_pred_ZM_lm_ols[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(TM_ZM_cst_ols, 4), "%.%", "(",
                           signif(TM_ZM_m_ols, 4), "+ x)^", signif(TM_ZM_alpha_ols, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(summary(TM_ZM_lm_ols)$r.squared, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Timis$Rank, 
                              Population = TM_pred_lav_lm_ols[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(TM_lav_kst_ols, 4), "%.%", "x^",
                           -signif(TM_lav_chi_ols, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(summary(TM_lav_lm_ols)$r.squared, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Timis judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# Linear Regressions
grid.arrange(
  (RO_Census_Timis %>%
     ggplot(aes(x = log(Rank), y = log(Population))) +
     geom_point(alpha = 0.8, show.legend = FALSE) +
