  ),
  ncol = 2, nrow = 2)

# f) Extract Outliers
Timis_Outliers <- bind_rows(
  (TM_pw_out_ols %>% mutate(Function_Name = "Power")),
  (TM_ZM_out_ols %>% mutate(Function_Name = "Zipf-Mandelbrot")),
  (TM_exp_out_ols %>% mutate(Function_Name = "Exponential")),
  (TM_lav_out_ols %>% mutate(Function_Name = "Lavalette"))
) %>% mutate(DFBETA_intercept = round(DFBETA[,1], 8), 
             DFBETA_var_x = round(DFBETA[,2], 8)) %>% dplyr::select(-DFBETA)

TM_out <- get_outliers(Timis_Outliers, RO_Census_Timis)

TM_out_ols <- RO_Census_Timis %>% inner_join(
  bind_rows(
    (TM_out$PW %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>% 
       dplyr::select(Rank) %>% distinct()),
    (TM_out$ZM %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (TM_out$LAV %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct()),
    (TM_out$EXP %>% filter(
      !Out_Method %in% c("Leverage", "DFBETA_intercept", "DFBETA_var_x")) %>%
       dplyr::select(Rank) %>% distinct())
  ) %>% count(Rank) %>% arrange(desc(n)) %>% filter(n >= mean(n))) %>% 
  dplyr::select(-n)

# g) Extract regression metrics
TM_regmet_ols <- as.data.frame(list(Judet_Name = "TIMIS",
                                    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
                                    R_Squared = c(signif(summary(TM_pw_lm_ols)$r.squared, 4), 
                                                  signif(summary(TM_exp_lm_ols)$r.squared, 4),
                                                  signif(summary(TM_ZM_lm_ols)$r.squared, 4),
                                                  signif(summary(TM_lav_lm_ols)$r.squared, 4)),
                                    Adj_R_Squared = c(signif(summary(TM_pw_lm_ols)$adj.r.squared, 4), 
                                                      signif(summary(TM_exp_lm_ols)$adj.r.squared, 4),
                                                      signif(summary(TM_ZM_lm_ols)$adj.r.squared, 4),
                                                      signif(summary(TM_lav_lm_ols)$adj.r.squared, 4)),
                                    AIC = c(signif(AIC(TM_pw_lm_ols), 4), signif(AIC(TM_exp_lm_ols), 4), 
                                            signif(AIC(TM_ZM_lm_ols), 4), signif(AIC(TM_lav_lm_ols), 4)),
                                    BIC = c(signif(BIC(TM_pw_lm_ols), 4), signif(BIC(TM_exp_lm_ols), 4), 
                                            signif(BIC(TM_ZM_lm_ols), 4), signif(BIC(TM_lav_lm_ols), 4)),
                                    MAE = c(signif(mean(abs((log(RO_Census_Timis$Population) - 
                                                               (predict(TM_pw_lm_ols, newdata = RO_Census_Timis, 
                                                                        interval = "prediction", level = 0.95))))), 4), 
                                            signif(mean(abs((log(RO_Census_Timis$Population) - 
                                                               (predict(TM_exp_lm_ols, newdata = RO_Census_Timis, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Timis$Population) - 
                                                               (predict(TM_ZM_lm_ols, newdata = RO_Census_Timis, 
                                                                        interval = "prediction", level = 0.95))))), 4),
                                            signif(mean(abs((log(RO_Census_Timis$Population) - 
                                                               (predict(TM_lav_lm_ols, newdata = RO_Census_Timis, 
                                                                        interval = "prediction", level = 0.95))))), 4)),
                                    RMSE = c(signif(sqrt(mean(((log(RO_Census_Timis$Population)) - 
                                                                 (predict(TM_pw_lm_ols, newdata = RO_Census_Timis, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Timis$Population)) - 
                                                                 (predict(TM_exp_lm_ols, newdata = RO_Census_Timis, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
