         LAV_Y_Pred = (predict(TM_lav_lm_ols, newdata = RO_Census_Timis, 
                               interval = "prediction", level = 0.95))[,1])

# Head
TM_ols_hd <- RO_Census_Timis_ols %>% filter(Rank <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(TM_ols_hd$Population) - TM_ols_hd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(TM_ols_hd$Population) - TM_ols_hd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(TM_ols_hd$Population) - TM_ols_hd$ZM_Y_Pred))), 4),
          signif(mean(abs((log(TM_ols_hd$Population) - TM_ols_hd$LAV_Y_Pred))), 4)),
