                               (predict(TM_ZM_lm_ols, newdata = RO_Census_Timis, 
                                        interval = "prediction", level = 0.95))))), 4),
            signif(mean(abs((log(RO_Census_Timis$Population) - 
                               (predict(TM_lav_lm_ols, newdata = RO_Census_Timis, 
                                        interval = "prediction", level = 0.95))))), 4)),
    RMSE = c(signif(sqrt(mean(((log(RO_Census_Timis$Population)) - 
                                 (predict(TM_pw_lm_ols, newdata = RO_Census_Timis, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Timis$Population)) - 
                                 (predict(TM_exp_lm_ols, newdata = RO_Census_Timis, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Timis$Population)) - 
                                 (predict(TM_ZM_lm_ols, newdata = RO_Census_Timis, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
             signif(sqrt(mean(((log(RO_Census_Timis$Population)) - 
                                 (predict(TM_lav_lm_ols, newdata = RO_Census_Timis, 
                                          interval = "prediction", level = 0.95))) ^ 2)), 4)),
    Data_Part = "Full"
  ))
)) %>% mutate(Regression_Type = "OLS", Judet_Name = "TIMIS")

# 2. Robust

# a) Power Law
TM_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Timis)
summary(TM_pw_lm_rob)
TM_pred_pw_lm_rob <- exp(predict(TM_pw_lm_rob, newdata = RO_Census_Timis, 
                                 interval = "prediction", level = 0.95))
TM_RSquared_pw_rob <- 1 - sum((log(RO_Census_Timis$Population) - fitted(TM_pw_lm_rob))^2) / 
  sum((log(RO_Census_Timis$Population) - mean(log(RO_Census_Timis$Population)))^2)

# b) Zipf_Mandelbrot Law
TM_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Timis, "Population", "Rank")
TM_ZM_m_rob <- TM_ZM_prm_rob$m
TM_ZM_alpha_rob <- TM_ZM_prm_rob$alpha_ZM
TM_ZM_cst_rob <- TM_ZM_prm_rob$constant_ZM
TM_ZM_lm_rob <- rlm(log(RO_Census_Timis$Population) ~ log(RO_Census_Timis$Rank + TM_ZM_m_rob))
summary(TM_ZM_lm_rob)
TM_pred_ZM_lm_rob <- exp(predict(TM_ZM_lm_rob, newdata = RO_Census_Timis, 
                                 interval = "prediction", level = 0.95))
TM_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Timis$Population) - fitted(TM_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Timis$Population) - mean(log(RO_Census_Timis$Population)))^2)

# c) Exponential Law
TM_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Timis)
summary(TM_exp_lm_rob)
TM_pred_exp_lm_rob <- exp(predict(TM_exp_lm_rob, newdata = RO_Census_Timis, 
                                  interval = "prediction", level = 0.95))
TM_RSquared_exp_rob <- 1 - sum((log(RO_Census_Timis$Population) - fitted(TM_exp_lm_rob))^2) / 
  sum((log(RO_Census_Timis$Population) - mean(log(RO_Census_Timis$Population)))^2)

# d) Lavalette Function
RO_Census_Timis <- RO_Census_Timis %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Timis) - Rank + 1))
)
TM_lav_lm_rob <- rlm(log(RO_Census_Timis$Population) ~ RO_Census_Timis$Lav_exp)
summary(TM_lav_lm_rob)
TM_lav_kst_rob <- exp(signif(TM_lav_lm_rob$coef[[1]], 4))
TM_lav_chi_rob <- signif(TM_lav_lm_rob$coef[[2]], 4)
TM_pred_lav_lm_rob <- exp(predict(TM_lav_lm_rob, newdata = RO_Census_Timis, 
                                  interval = "prediction", level = 0.95))
TM_RSquared_lav_rob <- 1 - sum((log(RO_Census_Timis$Population) - fitted(TM_lav_lm_rob))^2) / 
  sum((log(RO_Census_Timis$Population) - mean(log(RO_Census_Timis$Population)))^2)

# e) Data Distributions
RO_Census_Timis %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Timis$Rank, 
                              Population = TM_pred_pw_lm_rob[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(TM_pw_lm_rob$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(TM_pw_lm_rob$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(TM_RSquared_pw_rob, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Timis$Rank, 
                              Population = TM_pred_exp_lm_rob[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(TM_exp_lm_rob$coefficients[[1]]), 4), "%.%", 
                           signif(exp(TM_exp_lm_rob$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(TM_RSquared_exp_rob, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Timis$Rank, 
                              Population = TM_pred_ZM_lm_rob[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(TM_ZM_cst_rob, 4), "%.%", "(",
                           signif(TM_ZM_m_rob, 4), "+ x)^", signif(TM_ZM_alpha_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(TM_RSquared_ZM_rob, 4)),
