# XXXVIII. Tulcea

# 1. OLS
RO_Census_Tulcea <- RO_Census_rank %>% filter(Judet_Name == "TULCEA")
#View(RO_Census_Tulcea)

# a) Power Law
TL_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Tulcea)
summary(TL_pw_lm_ols)
TL_pred_pw_lm_ols <- exp(predict(TL_pw_lm_ols, newdata = RO_Census_Tulcea, 
                                 interval = "prediction", level = 0.95))
TL_pw_out_ols <- RO_Census_Tulcea %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(TL_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Tulcea), 
         DFFIT = dffits(TL_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(TL_pw_lm_ols$coefficients) / nrow(RO_Census_Tulcea)), 
         Rezid_Std = rstudent(TL_pw_lm_ols), Leverage = hatvalues(TL_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(TL_pw_lm_ols)), 
         DFBETA = dfbetas(TL_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Tulcea)))

# b) Zipf_Mandelbrot Law
TL_ZM_prm_ols <- get_ZM_Param("RO_Census_Tulcea", "Population", "Rank")
TL_ZM_m_ols <- TL_ZM_prm_ols$m
TL_ZM_alpha_ols <- TL_ZM_prm_ols$alpha_ZM
TL_ZM_cst_ols <- TL_ZM_prm_ols$constant_ZM
TL_ZM_lm_ols <- lm(log(RO_Census_Tulcea$Population) ~ log(RO_Census_Tulcea$Rank + TL_ZM_m_ols))
summary(TL_ZM_lm_ols)
TL_pred_ZM_lm_ols <- exp(predict(TL_ZM_lm_ols, newdata = RO_Census_Tulcea, 
                                 interval = "prediction", level = 0.95))
TL_ZM_out_ols <- RO_Census_Tulcea %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(TL_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Tulcea), 
         DFFIT = dffits(TL_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(TL_ZM_lm_ols$coefficients) / nrow(RO_Census_Tulcea)), 
         Rezid_Std = rstudent(TL_ZM_lm_ols), Leverage = hatvalues(TL_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(TL_ZM_lm_ols)), 
         DFBETA = dfbetas(TL_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Tulcea)))

# c) Exponential Law
TL_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Tulcea)
summary(TL_exp_lm_ols)
TL_pred_exp_lm_ols <- exp(predict(TL_exp_lm_ols, newdata = RO_Census_Tulcea, 
                                  interval = "prediction", level = 0.95))
TL_exp_out_ols <- RO_Census_Tulcea %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(TL_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Tulcea), 
         DFFIT = dffits(TL_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(TL_exp_lm_ols$coefficients) / nrow(RO_Census_Tulcea)), 
         Rezid_Std = rstudent(TL_exp_lm_ols), Leverage = hatvalues(TL_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(TL_exp_lm_ols)), 
         DFBETA = dfbetas(TL_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Tulcea)))

# d) Lavalette Function
RO_Census_Tulcea <- RO_Census_Tulcea %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Tulcea) - Rank + 1))
)
TL_lav_lm_ols <- lm(log(RO_Census_Tulcea$Population) ~ RO_Census_Tulcea$Lav_exp)
summary(TL_lav_lm_ols)
TL_lav_kst_ols <- exp(signif(TL_lav_lm_ols$coef[[1]], 4))
TL_lav_chi_ols <- signif(TL_lav_lm_ols$coef[[2]], 4)
TL_pred_lav_lm_ols <- exp(predict(TL_lav_lm_ols, newdata = RO_Census_Tulcea, 
                                  interval = "prediction", level = 0.95))
TL_lav_out_ols <- RO_Census_Tulcea %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(TL_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Tulcea), 
         DFFIT = dffits(TL_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(TL_lav_lm_ols$coefficients) / nrow(RO_Census_Tulcea)), 
         Rezid_Std = rstudent(TL_lav_lm_ols), Leverage = hatvalues(TL_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(TL_lav_lm_ols)), 
         DFBETA = dfbetas(TL_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Tulcea)))

