# 2. Robust

# a) Power Law
TL_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Tulcea)
summary(TL_pw_lm_rob)
TL_pred_pw_lm_rob <- exp(predict(TL_pw_lm_rob, newdata = RO_Census_Tulcea, 
                                 interval = "prediction", level = 0.95))
TL_RSquared_pw_rob <- 1 - sum((log(RO_Census_Tulcea$Population) - fitted(TL_pw_lm_rob))^2) / 
  sum((log(RO_Census_Tulcea$Population) - mean(log(RO_Census_Tulcea$Population)))^2)

# b) Zipf_Mandelbrot Law
TL_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Tulcea, "Population", "Rank")
TL_ZM_m_rob <- TL_ZM_prm_rob$m
TL_ZM_alpha_rob <- TL_ZM_prm_rob$alpha_ZM
TL_ZM_cst_rob <- TL_ZM_prm_rob$constant_ZM
TL_ZM_lm_rob <- rlm(log(RO_Census_Tulcea$Population) ~ log(RO_Census_Tulcea$Rank + TL_ZM_m_rob))
summary(TL_ZM_lm_rob)
TL_pred_ZM_lm_rob <- exp(predict(TL_ZM_lm_rob, newdata = RO_Census_Tulcea, 
                                 interval = "prediction", level = 0.95))
TL_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Tulcea$Population) - fitted(TL_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Tulcea$Population) - mean(log(RO_Census_Tulcea$Population)))^2)

# c) Exponential Law
TL_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Tulcea)
summary(TL_exp_lm_rob)
TL_pred_exp_lm_rob <- exp(predict(TL_exp_lm_rob, newdata = RO_Census_Tulcea, 
                                  interval = "prediction", level = 0.95))
TL_RSquared_exp_rob <- 1 - sum((log(RO_Census_Tulcea$Population) - fitted(TL_exp_lm_rob))^2) / 
  sum((log(RO_Census_Tulcea$Population) - mean(log(RO_Census_Tulcea$Population)))^2)

# d) Lavalette Function
RO_Census_Tulcea <- RO_Census_Tulcea %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Tulcea) - Rank + 1))
)
TL_lav_lm_rob <- rlm(log(RO_Census_Tulcea$Population) ~ RO_Census_Tulcea$Lav_exp)
summary(TL_lav_lm_rob)
TL_lav_kst_rob <- exp(signif(TL_lav_lm_rob$coef[[1]], 4))
TL_lav_chi_rob <- signif(TL_lav_lm_rob$coef[[2]], 4)
TL_pred_lav_lm_rob <- exp(predict(TL_lav_lm_rob, newdata = RO_Census_Tulcea, 
                                  interval = "prediction", level = 0.95))
TL_RSquared_lav_rob <- 1 - sum((log(RO_Census_Tulcea$Population) - fitted(TL_lav_lm_rob))^2) / 
  sum((log(RO_Census_Tulcea$Population) - mean(log(RO_Census_Tulcea$Population)))^2)

# e) Data Distributions
RO_Census_Tulcea %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Tulcea$Rank, 
                              Population = TL_pred_pw_lm_rob[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(TL_pw_lm_rob$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(TL_pw_lm_rob$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(TL_RSquared_pw_rob, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Tulcea$Rank, 
                              Population = TL_pred_exp_lm_rob[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(TL_exp_lm_rob$coefficients[[1]]), 4), "%.%", 
                           signif(exp(TL_exp_lm_rob$coefficients[[2]]), 4), "^x"),
            color = '#088BBEFF', parse = TRUE) +
  geom_text(x = 57, y = 0.18,
            label = paste0("R^2 ==", signif(TL_RSquared_exp_rob, 4)),
            color = '#088BBEFF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Tulcea$Rank, 
                              Population = TL_pred_ZM_lm_rob[,1]), 
            aes(color = "Zipf-Mandelbrot Law"), linetype = "longdash", linewidth=1.1) +
  geom_text(x = 40, y = 0.16,
            label = paste0("y", "==", signif(TL_ZM_cst_rob, 4), "%.%", "(",
                           signif(TL_ZM_m_rob, 4), "+ x)^", signif(TL_ZM_alpha_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_text(x = 57, y = 0.16,
            label = paste0("R^2 ==", signif(TL_RSquared_ZM_rob, 4)),
            color = '#1B7837FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Tulcea$Rank, 
                              Population = TL_pred_lav_lm_rob[,1]), 
            aes(color = "Lavalette Function"), linetype = "dashed", linewidth=1.1) +
  geom_text(x = 40, y = 0.14,
            label = paste0("y", "==", signif(TL_lav_kst_rob, 4), "%.%", "x^",
                           -signif(TL_lav_chi_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  geom_text(x = 57, y = 0.14,
            label = paste0("R^2 ==", signif(TL_RSquared_lav_rob, 4)),
            color = '#F8A02EFF', parse = TRUE) +
  scale_color_manual(values = c("Power Law" = "#ED3F39FF", 
                                "Exponential Law" = "#088BBEFF", 
                                "Zipf-Mandelbrot Law" = "#1B7837FF",
                                "Lavalette Function" = "#F8A02EFF")) +
  labs(x = "Rank", y = "Population", color = "Legend") +
  #ggtitle("Data Distribution on Tulcea judet (With Outliers)") +
  theme(plot.title = element_text(hjust = 0.5))

# f) Extract regression metrics
TL_regmet_rob <- as.data.frame(list(Judet_Name = "TULCEA",
                                    Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
                                    R_Squared = c(signif(TL_RSquared_pw_rob, 4), 
