                                    RMSE = c(signif(sqrt(mean(((log(RO_Census_Tulcea$Population)) - 
                                                                 (predict(TL_pw_lm_rob, newdata = RO_Census_Tulcea, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Tulcea$Population)) - 
                                                                 (predict(TL_exp_lm_rob, newdata = RO_Census_Tulcea, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
                                             signif(sqrt(mean(((log(RO_Census_Tulcea$Population)) - 
                                                                 (predict(TL_ZM_lm_rob, newdata = RO_Census_Tulcea, 
                                                                          interval = "prediction", level = 0.95))) ^ 2)), 4),
