# Extract weight
TL_out_weights <- bind_rows(
  (RO_Census_Tulcea %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>% 
     mutate(Robust_Weight = TL_pw_lm_rob$w, Function_Name = "Power")),
  (RO_Census_Tulcea %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = TL_ZM_lm_rob$w, Function_Name = "Zipf-Mandelbrot")),
  (RO_Census_Tulcea %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = TL_exp_lm_rob$w, Function_Name = "Exponential")),
  (RO_Census_Tulcea %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = TL_lav_lm_rob$w, Function_Name = "Lavalette"))) %>% 
  inner_join(TL_out_ols) %>% 
  dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank, Robust_Weight, Function_Name) %>%
  mutate(Judet_Name = "TULCEA")

# g) Extract MAE/RMSE on head, body, tail
RO_Census_Tulcea_rob <- RO_Census_Tulcea %>% 
  mutate(PW_Y_Pred = (predict(TL_pw_lm_rob, newdata = RO_Census_Tulcea, 
                              interval = "prediction", level = 0.95))[,1], 
         ZM_Y_Pred = (predict(TL_ZM_lm_rob, newdata = RO_Census_Tulcea, 
                              interval = "prediction", level = 0.95))[,1],
         EXP_Y_Pred = (predict(TL_exp_lm_rob, newdata = RO_Census_Tulcea, 
                               interval = "prediction", level = 0.95))[,1], 
         LAV_Y_Pred = (predict(TL_lav_lm_rob, newdata = RO_Census_Tulcea, 
                               interval = "prediction", level = 0.95))[,1])

# Head
TL_rob_hd <- RO_Census_Tulcea_rob %>% filter(Rank <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(TL_rob_hd$Population) - TL_rob_hd$PW_Y_Pred))), 4), 
          signif(mean(abs((log(TL_rob_hd$Population) - TL_rob_hd$EXP_Y_Pred))), 4),
          signif(mean(abs((log(TL_rob_hd$Population) - TL_rob_hd$ZM_Y_Pred))), 4),
          signif(mean(abs((log(TL_rob_hd$Population) - TL_rob_hd$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(TL_rob_hd$Population)) - TL_rob_hd$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(TL_rob_hd$Population)) - TL_rob_hd$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(TL_rob_hd$Population)) - TL_rob_hd$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(TL_rob_hd$Population)) - TL_rob_hd$LAV_Y_Pred) ^ 2)), 4))
))

# Tail
TL_rob_tl <- RO_Census_Tulcea_rob %>% arrange(desc(Rank)) %>% 
  filter(row_number() <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(TL_rob_tl$Population) - TL_rob_tl$PW_Y_Pred))), 4), 
