          signif(mean(abs((log(TL_rob_tl$Population) - TL_rob_tl$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(TL_rob_tl$Population)) - TL_rob_tl$PW_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(TL_rob_tl$Population)) - TL_rob_tl$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(TL_rob_tl$Population)) - TL_rob_tl$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(TL_rob_tl$Population)) - TL_rob_tl$LAV_Y_Pred) ^ 2)), 4))
))

# Body
TL_rob_bd <- RO_Census_Tulcea_rob %>% anti_join(TL_rob_hd) %>% anti_join(TL_rob_tl)

