# XXXIX. Vaslui

# 1. OLS
RO_Census_Vaslui <- RO_Census_rank %>% filter(Judet_Name == "VASLUI")
#View(RO_Census_Vaslui)

# a) Power Law
VS_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Vaslui)
summary(VS_pw_lm_ols)
VS_pred_pw_lm_ols <- exp(predict(VS_pw_lm_ols, newdata = RO_Census_Vaslui, 
                                 interval = "prediction", level = 0.95))
VS_pw_out_ols <- RO_Census_Vaslui %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(VS_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Vaslui), 
         DFFIT = dffits(VS_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(VS_pw_lm_ols$coefficients) / nrow(RO_Census_Vaslui)), 
         Rezid_Std = rstudent(VS_pw_lm_ols), Leverage = hatvalues(VS_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(VS_pw_lm_ols)), 
         DFBETA = dfbetas(VS_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Vaslui)))

# b) Zipf_Mandelbrot Law
VS_ZM_prm_ols <- get_ZM_Param("RO_Census_Vaslui", "Population", "Rank")
VS_ZM_m_ols <- VS_ZM_prm_ols$m
VS_ZM_alpha_ols <- VS_ZM_prm_ols$alpha_ZM
VS_ZM_cst_ols <- VS_ZM_prm_ols$constant_ZM
VS_ZM_lm_ols <- lm(log(RO_Census_Vaslui$Population) ~ log(RO_Census_Vaslui$Rank + VS_ZM_m_ols))
summary(VS_ZM_lm_ols)
VS_pred_ZM_lm_ols <- exp(predict(VS_ZM_lm_ols, newdata = RO_Census_Vaslui, 
                                 interval = "prediction", level = 0.95))
VS_ZM_out_ols <- RO_Census_Vaslui %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(VS_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Vaslui), 
         DFFIT = dffits(VS_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(VS_ZM_lm_ols$coefficients) / nrow(RO_Census_Vaslui)), 
         Rezid_Std = rstudent(VS_ZM_lm_ols), Leverage = hatvalues(VS_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(VS_ZM_lm_ols)), 
         DFBETA = dfbetas(VS_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Vaslui)))

# c) Exponential Law
VS_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Vaslui)
summary(VS_exp_lm_ols)
VS_pred_exp_lm_ols <- exp(predict(VS_exp_lm_ols, newdata = RO_Census_Vaslui, 
                                  interval = "prediction", level = 0.95))
VS_exp_out_ols <- RO_Census_Vaslui %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(VS_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Vaslui), 
         DFFIT = dffits(VS_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(VS_exp_lm_ols$coefficients) / nrow(RO_Census_Vaslui)), 
         Rezid_Std = rstudent(VS_exp_lm_ols), Leverage = hatvalues(VS_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(VS_exp_lm_ols)), 
         DFBETA = dfbetas(VS_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Vaslui)))

# d) Lavalette Function
RO_Census_Vaslui <- RO_Census_Vaslui %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Vaslui) - Rank + 1))
)
VS_lav_lm_ols <- lm(log(RO_Census_Vaslui$Population) ~ RO_Census_Vaslui$Lav_exp)
summary(VS_lav_lm_ols)
VS_lav_kst_ols <- exp(signif(VS_lav_lm_ols$coef[[1]], 4))
VS_lav_chi_ols <- signif(VS_lav_lm_ols$coef[[2]], 4)
VS_pred_lav_lm_ols <- exp(predict(VS_lav_lm_ols, newdata = RO_Census_Vaslui, 
                                  interval = "prediction", level = 0.95))
VS_lav_out_ols <- RO_Census_Vaslui %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(VS_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Vaslui), 
         DFFIT = dffits(VS_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(VS_lav_lm_ols$coefficients) / nrow(RO_Census_Vaslui)), 
         Rezid_Std = rstudent(VS_lav_lm_ols), Leverage = hatvalues(VS_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(VS_lav_lm_ols)), 
         DFBETA = dfbetas(VS_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Vaslui)))

