  (RO_Census_Vaslui %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = VS_ZM_lm_rob$w, Function_Name = "Zipf-Mandelbrot")),
  (RO_Census_Vaslui %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = VS_exp_lm_rob$w, Function_Name = "Exponential")),
