# g) Extract MAE/RMSE on head, body, tail
RO_Census_Vaslui_rob <- RO_Census_Vaslui %>% 
  mutate(PW_Y_Pred = (predict(VS_pw_lm_rob, newdata = RO_Census_Vaslui, 
                              interval = "prediction", level = 0.95))[,1], 
