                              interval = "prediction", level = 0.95))[,1],
         EXP_Y_Pred = (predict(VS_exp_lm_rob, newdata = RO_Census_Vaslui, 
                               interval = "prediction", level = 0.95))[,1], 
         LAV_Y_Pred = (predict(VS_lav_lm_rob, newdata = RO_Census_Vaslui, 
                               interval = "prediction", level = 0.95))[,1])

# Head
VS_rob_hd <- RO_Census_Vaslui_rob %>% filter(Rank <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(VS_rob_hd$Population) - VS_rob_hd$PW_Y_Pred))), 4), 
