          signif(mean(abs((log(VS_rob_hd$Population) - VS_rob_hd$ZM_Y_Pred))), 4),
          signif(mean(abs((log(VS_rob_hd$Population) - VS_rob_hd$LAV_Y_Pred))), 4)),
  RMSE = c(signif(sqrt(mean(((log(VS_rob_hd$Population)) - VS_rob_hd$PW_Y_Pred) ^ 2)), 4),
