           signif(sqrt(mean(((log(VS_rob_tl$Population)) - VS_rob_tl$EXP_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(VS_rob_tl$Population)) - VS_rob_tl$ZM_Y_Pred) ^ 2)), 4),
           signif(sqrt(mean(((log(VS_rob_tl$Population)) - VS_rob_tl$LAV_Y_Pred) ^ 2)), 4))
