# XL. Valcea

# 1. OLS
RO_Census_Valcea <- RO_Census_rank %>% filter(Judet_Name == "VALCEA")
#View(RO_Census_Valcea)

# a) Power Law
VL_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Valcea)
summary(VL_pw_lm_ols)
VL_pred_pw_lm_ols <- exp(predict(VL_pw_lm_ols, newdata = RO_Census_Valcea, 
                                 interval = "prediction", level = 0.95))
VL_pw_out_ols <- RO_Census_Valcea %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(VL_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Valcea), 
         DFFIT = dffits(VL_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(VL_pw_lm_ols$coefficients) / nrow(RO_Census_Valcea)), 
         Rezid_Std = rstudent(VL_pw_lm_ols), Leverage = hatvalues(VL_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(VL_pw_lm_ols)), 
         DFBETA = dfbetas(VL_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Valcea)))

# b) Zipf_Mandelbrot Law
VL_ZM_prm_ols <- get_ZM_Param("RO_Census_Valcea", "Population", "Rank")
VL_ZM_m_ols <- VL_ZM_prm_ols$m
VL_ZM_alpha_ols <- VL_ZM_prm_ols$alpha_ZM
VL_ZM_cst_ols <- VL_ZM_prm_ols$constant_ZM
VL_ZM_lm_ols <- lm(log(RO_Census_Valcea$Population) ~ log(RO_Census_Valcea$Rank + VL_ZM_m_ols))
summary(VL_ZM_lm_ols)
VL_pred_ZM_lm_ols <- exp(predict(VL_ZM_lm_ols, newdata = RO_Census_Valcea, 
                                 interval = "prediction", level = 0.95))
VL_ZM_out_ols <- RO_Census_Valcea %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(VL_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Valcea), 
         DFFIT = dffits(VL_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(VL_ZM_lm_ols$coefficients) / nrow(RO_Census_Valcea)), 
         Rezid_Std = rstudent(VL_ZM_lm_ols), Leverage = hatvalues(VL_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(VL_ZM_lm_ols)), 
         DFBETA = dfbetas(VL_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Valcea)))

# c) Exponential Law
VL_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Valcea)
summary(VL_exp_lm_ols)
VL_pred_exp_lm_ols <- exp(predict(VL_exp_lm_ols, newdata = RO_Census_Valcea, 
                                  interval = "prediction", level = 0.95))
VL_exp_out_ols <- RO_Census_Valcea %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(VL_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Valcea), 
         DFFIT = dffits(VL_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(VL_exp_lm_ols$coefficients) / nrow(RO_Census_Valcea)), 
         Rezid_Std = rstudent(VL_exp_lm_ols), Leverage = hatvalues(VL_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(VL_exp_lm_ols)), 
         DFBETA = dfbetas(VL_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Valcea)))

# d) Lavalette Function
RO_Census_Valcea <- RO_Census_Valcea %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Valcea) - Rank + 1))
)
VL_lav_lm_ols <- lm(log(RO_Census_Valcea$Population) ~ RO_Census_Valcea$Lav_exp)
summary(VL_lav_lm_ols)
VL_lav_kst_ols <- exp(signif(VL_lav_lm_ols$coef[[1]], 4))
VL_lav_chi_ols <- signif(VL_lav_lm_ols$coef[[2]], 4)
VL_pred_lav_lm_ols <- exp(predict(VL_lav_lm_ols, newdata = RO_Census_Valcea, 
                                  interval = "prediction", level = 0.95))
VL_lav_out_ols <- RO_Census_Valcea %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(VL_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Valcea), 
         DFFIT = dffits(VL_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(VL_lav_lm_ols$coefficients) / nrow(RO_Census_Valcea)), 
         Rezid_Std = rstudent(VL_lav_lm_ols), Leverage = hatvalues(VL_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(VL_lav_lm_ols)), 
