# 2. Robust

# a) Power Law
VL_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Valcea)
summary(VL_pw_lm_rob)
VL_pred_pw_lm_rob <- exp(predict(VL_pw_lm_rob, newdata = RO_Census_Valcea, 
                                 interval = "prediction", level = 0.95))
VL_RSquared_pw_rob <- 1 - sum((log(RO_Census_Valcea$Population) - fitted(VL_pw_lm_rob))^2) / 
  sum((log(RO_Census_Valcea$Population) - mean(log(RO_Census_Valcea$Population)))^2)

# b) Zipf_Mandelbrot Law
VL_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Valcea, "Population", "Rank")
VL_ZM_m_rob <- VL_ZM_prm_rob$m
VL_ZM_alpha_rob <- VL_ZM_prm_rob$alpha_ZM
VL_ZM_cst_rob <- VL_ZM_prm_rob$constant_ZM
VL_ZM_lm_rob <- rlm(log(RO_Census_Valcea$Population) ~ log(RO_Census_Valcea$Rank + VL_ZM_m_rob))
summary(VL_ZM_lm_rob)
VL_pred_ZM_lm_rob <- exp(predict(VL_ZM_lm_rob, newdata = RO_Census_Valcea, 
                                 interval = "prediction", level = 0.95))
VL_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Valcea$Population) - fitted(VL_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Valcea$Population) - mean(log(RO_Census_Valcea$Population)))^2)

# c) Exponential Law
VL_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Valcea)
summary(VL_exp_lm_rob)
VL_pred_exp_lm_rob <- exp(predict(VL_exp_lm_rob, newdata = RO_Census_Valcea, 
                                  interval = "prediction", level = 0.95))
VL_RSquared_exp_rob <- 1 - sum((log(RO_Census_Valcea$Population) - fitted(VL_exp_lm_rob))^2) / 
  sum((log(RO_Census_Valcea$Population) - mean(log(RO_Census_Valcea$Population)))^2)

# d) Lavalette Function
RO_Census_Valcea <- RO_Census_Valcea %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Valcea) - Rank + 1))
)
VL_lav_lm_rob <- rlm(log(RO_Census_Valcea$Population) ~ RO_Census_Valcea$Lav_exp)
summary(VL_lav_lm_rob)
VL_lav_kst_rob <- exp(signif(VL_lav_lm_rob$coef[[1]], 4))
VL_lav_chi_rob <- signif(VL_lav_lm_rob$coef[[2]], 4)
VL_pred_lav_lm_rob <- exp(predict(VL_lav_lm_rob, newdata = RO_Census_Valcea, 
                                  interval = "prediction", level = 0.95))
VL_RSquared_lav_rob <- 1 - sum((log(RO_Census_Valcea$Population) - fitted(VL_lav_lm_rob))^2) / 
  sum((log(RO_Census_Valcea$Population) - mean(log(RO_Census_Valcea$Population)))^2)

# e) Data Distributions
RO_Census_Valcea %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
  geom_line(data = data.frame(Rank = RO_Census_Valcea$Rank, 
                              Population = VL_pred_pw_lm_rob[,1]), 
            aes(color = "Power Law"), linetype = "solid", linewidth=0.9) +
  geom_text(x = 40, y = 0.20,
            label = paste0("y", "==", signif(exp(VL_pw_lm_rob$coefficients[[1]]), 4), "%.%", 
                           "x^", signif(VL_pw_lm_rob$coefficients[[2]], 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_text(x = 57, y = 0.20,
            label = paste0("R^2 ==", signif(VL_RSquared_pw_rob, 4)),
            color = '#ED3F39FF', parse = TRUE) +
  geom_line(data = data.frame(Rank = RO_Census_Valcea$Rank, 
                              Population = VL_pred_exp_lm_rob[,1]), 
            aes(color = "Exponential Law"), linetype = "twodash", linewidth=1.2) +
  geom_text(x = 40, y = 0.18,
            label = paste0("y", "==", signif(exp(VL_exp_lm_rob$coefficients[[1]]), 4), "%.%", 
