# XLI. Vrancea

# 1. OLS
RO_Census_Vrancea <- RO_Census_rank %>% filter(Judet_Name == "VRANCEA")
#View(RO_Census_Vrancea)

# a) Power Law
VN_pw_lm_ols <- lm(log(Population) ~ log(Rank), data = RO_Census_Vrancea)
summary(VN_pw_lm_ols)
VN_pred_pw_lm_ols <- exp(predict(VN_pw_lm_ols, newdata = RO_Census_Vrancea, 
                                 interval = "prediction", level = 0.95))
VN_pw_out_ols <- RO_Census_Vrancea %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(VN_pw_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Vrancea), 
         DFFIT = dffits(VN_pw_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(VN_pw_lm_ols$coefficients) / nrow(RO_Census_Vrancea)), 
         Rezid_Std = rstudent(VN_pw_lm_ols), Leverage = hatvalues(VN_pw_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(VN_pw_lm_ols)), 
         DFBETA = dfbetas(VN_pw_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Vrancea)))

# b) Zipf_Mandelbrot Law
VN_ZM_prm_ols <- get_ZM_Param("RO_Census_Vrancea", "Population", "Rank")
VN_ZM_m_ols <- VN_ZM_prm_ols$m
VN_ZM_alpha_ols <- VN_ZM_prm_ols$alpha_ZM
VN_ZM_cst_ols <- VN_ZM_prm_ols$constant_ZM
VN_ZM_lm_ols <- lm(log(RO_Census_Vrancea$Population) ~ log(RO_Census_Vrancea$Rank + VN_ZM_m_ols))
summary(VN_ZM_lm_ols)
VN_pred_ZM_lm_ols <- exp(predict(VN_ZM_lm_ols, newdata = RO_Census_Vrancea, 
                                 interval = "prediction", level = 0.95))
VN_ZM_out_ols <- RO_Census_Vrancea %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(VN_ZM_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Vrancea), 
         DFFIT = dffits(VN_ZM_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(VN_ZM_lm_ols$coefficients) / nrow(RO_Census_Vrancea)), 
         Rezid_Std = rstudent(VN_ZM_lm_ols), Leverage = hatvalues(VN_ZM_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(VN_ZM_lm_ols)), 
         DFBETA = dfbetas(VN_ZM_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Vrancea)))

# c) Exponential Law
VN_exp_lm_ols <- lm(log(Population) ~ Rank, RO_Census_Vrancea)
summary(VN_exp_lm_ols)
VN_pred_exp_lm_ols <- exp(predict(VN_exp_lm_ols, newdata = RO_Census_Vrancea, 
                                  interval = "prediction", level = 0.95))
VN_exp_out_ols <- RO_Census_Vrancea %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(VN_exp_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Vrancea), 
         DFFIT = dffits(VN_exp_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(VN_exp_lm_ols$coefficients) / nrow(RO_Census_Vrancea)), 
         Rezid_Std = rstudent(VN_exp_lm_ols), Leverage = hatvalues(VN_exp_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(VN_exp_lm_ols)), 
         DFBETA = dfbetas(VN_exp_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Vrancea)))

# d) Lavalette Function
RO_Census_Vrancea <- RO_Census_Vrancea %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Vrancea) - Rank + 1))
)
VN_lav_lm_ols <- lm(log(RO_Census_Vrancea$Population) ~ RO_Census_Vrancea$Lav_exp)
summary(VN_lav_lm_ols)
VN_lav_kst_ols <- exp(signif(VN_lav_lm_ols$coef[[1]], 4))
VN_lav_chi_ols <- signif(VN_lav_lm_ols$coef[[2]], 4)
VN_pred_lav_lm_ols <- exp(predict(VN_lav_lm_ols, newdata = RO_Census_Vrancea, 
                                  interval = "prediction", level = 0.95))
VN_lav_out_ols <- RO_Census_Vrancea %>% dplyr::select(Unit_Name, Unit_Type, Environment, Judet_Name) %>%
  mutate(Cooks_Dist = cooks.distance(VN_lav_lm_ols), Cooks_Dist_Trsh = 4/nrow(RO_Census_Vrancea), 
         DFFIT = dffits(VN_lav_lm_ols), 
         DFFIT_Trsh = 2 * sqrt(length(VN_lav_lm_ols$coefficients) / nrow(RO_Census_Vrancea)), 
         Rezid_Std = rstudent(VN_lav_lm_ols), Leverage = hatvalues(VN_lav_lm_ols), 
         Lev_Trsh = 2 * mean(hatvalues(VN_lav_lm_ols)), 
         DFBETA = dfbetas(VN_lav_lm_ols), DFBETA_Trsh = 2 / sqrt(nrow(RO_Census_Vrancea)))

