# 2. Robust

# a) Power Law
VN_pw_lm_rob <- rlm(log(Population) ~ log(Rank), data = RO_Census_Vrancea)
summary(VN_pw_lm_rob)
VN_pred_pw_lm_rob <- exp(predict(VN_pw_lm_rob, newdata = RO_Census_Vrancea, 
                                 interval = "prediction", level = 0.95))
VN_RSquared_pw_rob <- 1 - sum((log(RO_Census_Vrancea$Population) - fitted(VN_pw_lm_rob))^2) / 
  sum((log(RO_Census_Vrancea$Population) - mean(log(RO_Census_Vrancea$Population)))^2)

# b) Zipf_Mandelbrot Law
VN_ZM_prm_rob <- get_ZM_Param_rob(RO_Census_Vrancea, "Population", "Rank")
VN_ZM_m_rob <- VN_ZM_prm_rob$m
VN_ZM_alpha_rob <- VN_ZM_prm_rob$alpha_ZM
VN_ZM_cst_rob <- VN_ZM_prm_rob$constant_ZM
VN_ZM_lm_rob <- rlm(log(RO_Census_Vrancea$Population) ~ log(RO_Census_Vrancea$Rank + VN_ZM_m_rob))
summary(VN_ZM_lm_rob)
VN_pred_ZM_lm_rob <- exp(predict(VN_ZM_lm_rob, newdata = RO_Census_Vrancea, 
                                 interval = "prediction", level = 0.95))
VN_RSquared_ZM_rob <- 1 - sum((log(RO_Census_Vrancea$Population) - fitted(VN_ZM_lm_rob))^2) / 
  sum((log(RO_Census_Vrancea$Population) - mean(log(RO_Census_Vrancea$Population)))^2)

# c) Exponential Law
VN_exp_lm_rob <- rlm(log(Population) ~ Rank, RO_Census_Vrancea)
summary(VN_exp_lm_rob)
VN_pred_exp_lm_rob <- exp(predict(VN_exp_lm_rob, newdata = RO_Census_Vrancea, 
                                  interval = "prediction", level = 0.95))
VN_RSquared_exp_rob <- 1 - sum((log(RO_Census_Vrancea$Population) - fitted(VN_exp_lm_rob))^2) / 
  sum((log(RO_Census_Vrancea$Population) - mean(log(RO_Census_Vrancea$Population)))^2)

# d) Lavalette Function
RO_Census_Vrancea <- RO_Census_Vrancea %>% mutate(
  Lav_exp = (log(Rank) - log(nrow(RO_Census_Vrancea) - Rank + 1))
)
VN_lav_lm_rob <- rlm(log(RO_Census_Vrancea$Population) ~ RO_Census_Vrancea$Lav_exp)
summary(VN_lav_lm_rob)
VN_lav_kst_rob <- exp(signif(VN_lav_lm_rob$coef[[1]], 4))
VN_lav_chi_rob <- signif(VN_lav_lm_rob$coef[[2]], 4)
VN_pred_lav_lm_rob <- exp(predict(VN_lav_lm_rob, newdata = RO_Census_Vrancea, 
                                  interval = "prediction", level = 0.95))
VN_RSquared_lav_rob <- 1 - sum((log(RO_Census_Vrancea$Population) - fitted(VN_lav_lm_rob))^2) / 
  sum((log(RO_Census_Vrancea$Population) - mean(log(RO_Census_Vrancea$Population)))^2)

# e) Data Distributions
RO_Census_Vrancea %>%
  ggplot(aes(x = Rank, y = Population)) +
  geom_point(alpha = 0.8, size = 2, show.legend = FALSE) +
