))

# Extract weight
VN_out_weights <- bind_rows(
  (RO_Census_Vrancea %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>% 
     mutate(Robust_Weight = VN_pw_lm_rob$w, Function_Name = "Power")),
  (RO_Census_Vrancea %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = VN_ZM_lm_rob$w, Function_Name = "Zipf-Mandelbrot")),
  (RO_Census_Vrancea %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
     mutate(Robust_Weight = VN_exp_lm_rob$w, Function_Name = "Exponential")),
  (RO_Census_Vrancea %>% dplyr::select(Unit_Name, Unit_Type, Judet_Name, Rank) %>%
