# g) Extract MAE/RMSE on head, body, tail
RO_Census_Vrancea_rob <- RO_Census_Vrancea %>% 
  mutate(PW_Y_Pred = (predict(VN_pw_lm_rob, newdata = RO_Census_Vrancea, 
