# Head
VN_rob_hd <- RO_Census_Vrancea_rob %>% filter(Rank <= ceiling(max(Rank) * 0.10))

as.data.frame(list(
  Function_Name = c("Power", "Exponential", "Zipf-Mandelbrot", "Lavalette"),
  MAE = c(signif(mean(abs((log(VN_rob_hd$Population) - VN_rob_hd$PW_Y_Pred))), 4), 
