# Import calculated metrics
RO_Census_OLS <- read_excel("./RO_Census_Robust_Analysis_popsize.xlsx", sheet = 1)
  
RO_Census_ROB <- read_excel("./RO_Census_Robust_Analysis_popsize.xlsx", sheet = 2)
  
RO_Census_out_w <- read_excel("./RO_Census_Robust_Analysis_popsize.xlsx", sheet = 3)
  
RO_Census_all_regg_res <- read_excel("./RO_Census_Robust_Analysis_popsize.xlsx", sheet = 4)

# I. Determine best data distributions on OLS
RO_Census_best_OLS <- RO_Census_OLS %>% group_by(Judet_Name) %>%
  mutate(rank_R2   = min_rank(desc(R_Squared)), rank_MAE  = min_rank(MAE),
         rank_RMSE = min_rank(RMSE), rank_AIC  = min_rank(AIC), 
         rank_BIC  = min_rank(BIC), rank_sum = rank_R2 + rank_MAE + rank_RMSE +
           rank_AIC + rank_BIC) %>% arrange(Judet_Name, rank_sum) %>% slice(1) %>%
  ungroup() %>% dplyr::select(-c(rank_R2, rank_MAE, rank_RMSE, rank_AIC, rank_BIC, rank_sum))

RO_Census_best_OLS %>% group_by(Function_Name) %>% count() %>% rename("Count" = "n") %>% 
  mutate(Percent = (Count/nrow(RO_Census_best_OLS) * 100))

# II. Determine best data distributions on Robust
RO_Census_best_Rob <- RO_Census_ROB %>% group_by(Judet_Name) %>%
  mutate(rank_R2   = min_rank(desc(R_Squared)), rank_MAE  = min_rank(MAE),
         rank_RMSE = min_rank(RMSE), rank_AIC  = min_rank(AIC), 
         rank_BIC  = min_rank(BIC), rank_sum = rank_R2 + rank_MAE + rank_RMSE +
           rank_AIC + rank_BIC) %>% arrange(Judet_Name, rank_sum) %>% slice(1) %>%
  ungroup() %>% dplyr::select(-c(rank_R2, rank_MAE, rank_RMSE, rank_AIC, rank_BIC, rank_sum))

RO_Census_best_Rob %>% group_by(Function_Name) %>% count() %>% rename("Count" = "n") %>% 
  mutate(Percent = (Count/nrow(RO_Census_best_Rob) * 100))

# III. Classification of robust weights
RO_Census_cnt_w <- RO_Census_out_w %>% 
  mutate(Weight_Type = case_when(
    round(Robust_Weight, 1) <= 0.1 ~ "Extreme Outlier",
    round(Robust_Weight, 1) >= 0.9 ~ "Fit Point",
    TRUE ~ "Transition Point")) %>% group_by(Judet_Name, Function_Name, Weight_Type) %>%
  count() %>% rename("Count" = "n")

RO_Census_cnt_w %>% group_by(Judet_Name, Function_Name) %>%
  filter(Weight_Type == "Fit Point", 
         Count >= max(Count[Weight_Type %in% 
                              c("Extreme Outlier", "Transition Point")],
      na.rm = TRUE)) %>% ungroup() %>% #dplyr::select(Judet_Name, Function_Name) %>%
  inner_join(RO_Census_best_Rob %>% dplyr::select(Judet_Name, Function_Name))

# IV. Determine best data distributions by segments on OLS
RO_Census_bestpart_OLS <- RO_Census_all_regg_res %>% 
  filter(Regression_Type == "OLS") %>% group_by(Judet_Name, Data_Part) %>% 
  mutate(rank_RMSE = min_rank(RMSE), rank_MAE = min_rank(MAE), 
         rank_sum = rank_MAE + rank_RMSE) %>% 
  arrange(Judet_Name, Data_Part, rank_sum) %>% slice(1) %>% ungroup() %>% 
  dplyr::select(Judet_Name, Function_Name, MAE, RMSE, Data_Part)

RO_Census_bestpart_OLS %>% filter(Data_Part != 'Full') %>% 
  group_by(Function_Name, Data_Part) %>% count() %>% rename("Count" = "n") %>%
  mutate(Percent = (Count/nrow(RO_Census_bestpart_OLS %>% 
                                 dplyr::select(Judet_Name) %>% distinct()) * 100)) %>%
  arrange(Data_Part)

# V. Determine best data distributions by segments on Robust
RO_Census_bestpart_Rob <- RO_Census_all_regg_res %>% 
  filter(Regression_Type == "Robust") %>% group_by(Judet_Name, Data_Part) %>% 
  mutate(rank_RMSE = min_rank(RMSE), rank_MAE = min_rank(MAE), 
         rank_sum = rank_MAE + rank_RMSE) %>% 
  arrange(Judet_Name, Data_Part, rank_sum) %>% slice(1) %>% ungroup() %>% 
  dplyr::select(Judet_Name, Function_Name, MAE, RMSE, Data_Part)

RO_Census_bestpart_Rob %>% filter(Data_Part != 'Full') %>% 
  group_by(Function_Name, Data_Part) %>% count() %>% rename("Count" = "n") %>%
  mutate(Percent = (Count/nrow(RO_Census_bestpart_Rob %>% 
                                 dplyr::select(Judet_Name) %>% distinct()) * 100)) %>%
  arrange(Data_Part)

# VI. Get the final result
RO_Census_final <- bind_rows(
  (RO_Census_best_OLS %>% dplyr::select(-Adj_R_Squared) %>% 
     mutate(Regression_Type = "OLS")),
  (RO_Census_best_Rob %>% mutate(Regression_Type = "Robust"))
) %>% arrange(Judet_Name) %>% relocate(Regression_Type, .after = Function_Name)

